export type TransactionType = 'income' | 'expense';

export interface Transaction {
  id: string;
  description: string;
  amount: number;
  type: TransactionType;
  category: string;
  date: string;
}

export interface Summary {
  balance: number;
  income: number;
  expenses: number;
}

export interface CategoryBudget {
  name: string;
  limit: number;
}

import React from 'react';

export const CATEGORIES = {
  expense: [
    'Food & Drinks',
    'Rent & Bills',
    'Transport',
    'Shopping',
    'Entertainment',
    'Health',
    'Others'
  ],
  income: [
    'Salary',
    'Freelance',
    'Investments',
    'Gifts',
    'Others'
  ]
};

export const COLORS = {
  income: '#10b981', // emerald-500
  expense: '#ef4444', // red-500
  neutral: '#6b7280', // gray-500
};

import { GoogleGenAI, Type } from "@google/genai";
import { Transaction } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const getFinancialInsights = async (transactions: Transaction[]) => {
  if (transactions.length === 0) return "Add some transactions to get AI insights!";

  const summary = transactions.map(t => ({
    type: t.type,
    amount: t.amount,
    category: t.category,
    description: t.description
  }));

  const prompt = `Based on the following list of transactions, provide a brief, professional, and actionable financial insight in Portuguese. 
  Focus on identifying patterns, suggesting potential savings, and offering a quick tip.
  Transactions: ${JSON.stringify(summary)}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction: "You are a helpful, minimalist financial advisor. Your advice should be concise and direct.",
        temperature: 0.7,
      },
    });

    return response.text || "Could not generate insights at this moment.";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Erro ao carregar insights financeiros via IA.";
  }
};

import { useState, useEffect, useCallback } from 'react';
import { Transaction, Summary } from '../types';

export const useFinanceData = () => {
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const saved = localStorage.getItem('finance_flow_data');
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => {
    localStorage.setItem('finance_flow_data', JSON.stringify(transactions));
  }, [transactions]);

  const addTransaction = useCallback((transaction: Omit<Transaction, 'id' | 'date'>) => {
    const newTransaction: Transaction = {
      ...transaction,
      id: crypto.randomUUID(),
      date: new Date().toISOString(),
    };
    setTransactions(prev => [newTransaction, ...prev]);
  }, []);

  const deleteTransaction = useCallback((id: string) => {
    setTransactions(prev => prev.filter(t => t.id !== id));
  }, []);

  const getSummary = (): Summary => {
    return transactions.reduce((acc, t) => {
      if (t.type === 'income') {
        acc.income += t.amount;
        acc.balance += t.amount;
      } else {
        acc.expenses += t.amount;
        acc.balance -= t.amount;
      }
      return acc;
    }, { balance: 0, income: 0, expenses: 0 });
  };

  return {
    transactions,
    addTransaction,
    deleteTransaction,
    summary: getSummary(),
  };
};

