import React, { useState, useEffect } from 'react';
import { TransactionType, UserCategories } from '../types';

interface TransactionFormProps {
  onAdd: (data: { description: string; amount: number; type: TransactionType; category: string }) => void;
  categories: UserCategories;
  onCancel?: () => void;
  initialType?: TransactionType;
}

const TransactionForm: React.FC<TransactionFormProps> = ({ onAdd, categories, onCancel, initialType = 'expense' }) => {
  const [description, setDescription] = useState('');
  const [amount, setAmount] = useState('');
  const [type, setType] = useState<TransactionType>(initialType);
  const [category, setCategory] = useState('');
  const [success, setSuccess] = useState(false);

  useEffect(() => {
    setType(initialType);
    setCategory(categories[initialType][0] || '');
  }, [initialType, categories]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!description || !amount) return;

    onAdd({
      description,
      amount: parseFloat(amount),
      type,
      category: category || 'Outros',
    });

    setDescription('');
    setAmount('');
    setSuccess(true);
    setTimeout(() => {
      setSuccess(false);
      if (onCancel) onCancel();
    }, 1000);
  };

  const handleTypeChange = (newType: TransactionType) => {
    setType(newType);
    setCategory(categories[newType][0] || '');
  };

  return (
    <div className="bg-white p-6 rounded-2xl shadow-xl border border-gray-100 w-full max-w-md mx-auto animate-in fade-in zoom-in duration-200">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-lg font-bold text-gray-900">Novo Registro</h2>
        {onCancel && (
          <button onClick={onCancel} className="p-1 text-gray-400 hover:text-gray-600">
            <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M18 6 6 18"/><path d="m6 6 12 12"/></svg>
          </button>
        )}
      </div>

      <form onSubmit={handleSubmit} className="space-y-4">
        <div className="flex gap-1 p-1 bg-gray-50 rounded-lg border border-gray-100">
          {(['expense', 'income'] as const).map((t) => (
            <button
              key={t}
              type="button"
              onClick={() => handleTypeChange(t)}
              className={`flex-1 py-1.5 rounded-md text-[10px] font-bold transition-all ${
                type === t ? 'bg-white shadow-sm text-gray-900' : 'text-gray-400 hover:text-gray-600'
              }`}
            >
              {t === 'expense' ? 'DESPESA' : 'RECEITA'}
            </button>
          ))}
        </div>

        <div className="space-y-3">
          <div>
            <label className="block text-[9px] font-bold text-gray-400 uppercase tracking-wider mb-1">Descrição</label>
            <input
              type="text"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              className="w-full px-3 py-2 bg-gray-50 border-none rounded-lg focus:ring-2 focus:ring-blue-500/10 text-sm outline-none"
              required
            />
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-[9px] font-bold text-gray-400 uppercase tracking-wider mb-1">Valor</label>
              <input
                type="number"
                value={amount}
                onChange={(e) => setAmount(e.target.value)}
                placeholder="0.00"
                step="0.01"
                className="w-full px-3 py-2 bg-gray-50 border-none rounded-lg focus:ring-2 focus:ring-blue-500/10 text-sm font-bold outline-none"
                required
              />
            </div>
            <div>
              <label className="block text-[9px] font-bold text-gray-400 uppercase tracking-wider mb-1">Categoria</label>
              <select
                value={category}
                onChange={(e) => setCategory(e.target.value)}
                className="w-full px-3 py-2 bg-gray-50 border-none rounded-lg text-sm outline-none"
              >
                {categories[type].map(cat => (
                  <option key={cat} value={cat}>{cat}</option>
                ))}
                {categories[type].length === 0 && <option value="">Nenhuma categoria</option>}
              </select>
            </div>
          </div>
        </div>

        <button
          type="submit"
          disabled={success}
          className={`w-full py-3 rounded-lg font-bold text-white text-xs transition-all ${
            success ? 'bg-emerald-500' : type === 'expense' ? 'bg-gray-900 hover:bg-black' : 'bg-emerald-600 hover:bg-emerald-700'
          }`}
        >
          {success ? 'Concluído' : 'Adicionar'}
        </button>
      </form>
    </div>
  );
};

