import { useState, useEffect, useCallback } from 'react';
import { Transaction, Summary, UserCategories } from '../types';

const DEFAULT_CATEGORIES: UserCategories = {
  expense: ['Alimentação', 'Moradia', 'Transporte', 'Lazer', 'Saúde', 'Outros'],
  income: ['Salário', 'Freelance', 'Investimentos', 'Presentes', 'Outros']
};

export const useFinanceData = () => {
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const saved = localStorage.getItem('finance_pro_data');
    return saved ? JSON.parse(saved) : [];
  });

  const [categories, setCategories] = useState<UserCategories>(() => {
    const saved = localStorage.getItem('finance_pro_categories');
    return saved ? JSON.parse(saved) : DEFAULT_CATEGORIES;
  });

  useEffect(() => {
    localStorage.setItem('finance_pro_data', JSON.stringify(transactions));
  }, [transactions]);

  useEffect(() => {
    localStorage.setItem('finance_pro_categories', JSON.stringify(categories));
  }, [categories]);

  const addTransaction = useCallback((transaction: Omit<Transaction, 'id'>) => {
    const newTransaction: Transaction = {
      ...transaction,
      id: crypto.randomUUID(),
      date: transaction.date || new Date().toISOString(),
    };
    setTransactions(prev => [newTransaction, ...prev]);
  }, []);

  const deleteTransaction = useCallback((id: string) => {
    setTransactions(prev => prev.filter(t => t.id !== id));
  }, []);

  const addCategory = useCallback((type: 'income' | 'expense', name: string) => {
    setCategories(prev => ({
      ...prev,
      [type]: [...new Set([...prev[type], name])]
    }));
  }, []);

  const deleteCategory = useCallback((type: 'income' | 'expense', name: string) => {
    setCategories(prev => ({
      ...prev,
      [type]: prev[type].filter(cat => cat !== name)
    }));
  }, []);

  const getSummary = (): Summary => {
    return transactions.reduce((acc, t) => {
      if (t.type === 'income') {
        acc.income += t.amount;
        acc.balance += t.amount;
      } else {
        acc.expenses += t.amount;
        acc.balance -= t.amount;
      }
      return acc;
    }, { balance: 0, income: 0, expenses: 0 });
  };

  return {
    transactions,
    categories,
    addTransaction,
    deleteTransaction,
    addCategory,
    deleteCategory,
    summary: getSummary(),
  };
};

import React, { useState, useEffect } from 'react';
import { TransactionType, UserCategories } from '../types';

interface TransactionFormProps {
  onAdd: (data: { description: string; amount: number; type: TransactionType; category: string; date: string }) => void;
  categories: UserCategories;
  onCancel?: () => void;
  initialType?: TransactionType;
}

const TransactionForm: React.FC<TransactionFormProps> = ({ onAdd, categories, onCancel, initialType = 'expense' }) => {
  const [description, setDescription] = useState('');
  const [amount, setAmount] = useState('');
  const [type, setType] = useState<TransactionType>(initialType);
  const [category, setCategory] = useState('');
  const [installments, setInstallments] = useState(1);
  const [success, setSuccess] = useState(false);

  useEffect(() => {
    setType(initialType);
    setCategory(categories[initialType][0] || '');
  }, [initialType, categories]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!description || !amount) return;

    const totalAmount = parseFloat(amount);
    const numInstallments = type === 'expense' ? installments : 1;
    const amountPerInstallment = totalAmount / numInstallments;

    for (let i = 0; i < numInstallments; i++) {
      const date = new Date();
      date.setMonth(date.getMonth() + i);

      const installmentLabel = numInstallments > 1 ? ` (${i + 1}/${numInstallments})` : '';

      onAdd({
        description: description + installmentLabel,
        amount: amountPerInstallment,
        type,
        category: category || 'Outros',
        date: date.toISOString()
      });
    }

    setDescription('');
    setAmount('');
    setInstallments(1);
    setSuccess(true);
    setTimeout(() => {
      setSuccess(false);
      if (onCancel) onCancel();
    }, 1000);
  };

  const handleTypeChange = (newType: TransactionType) => {
    setType(newType);
    setCategory(categories[newType][0] || '');
    if (newType === 'income') setInstallments(1);
  };

  return (
    <div className="bg-white p-6 rounded-2xl shadow-xl border border-gray-100 w-full max-w-md mx-auto animate-in fade-in zoom-in duration-200">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-lg font-bold text-gray-900">Novo Registro</h2>
        {onCancel && (
          <button onClick={onCancel} className="p-1 text-gray-400 hover:text-gray-600">
            <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M18 6 6 18"/><path d="m6 6 12 12"/></svg>
          </button>
        )}
      </div>

      <form onSubmit={handleSubmit} className="space-y-4">
        <div className="flex gap-1 p-1 bg-gray-50 rounded-lg border border-gray-100">
          {(['expense', 'income'] as const).map((t) => (
            <button
              key={t}
              type="button"
              onClick={() => handleTypeChange(t)}
              className={`flex-1 py-1.5 rounded-md text-[10px] font-bold transition-all ${
                type === t ? 'bg-white shadow-sm text-gray-900' : 'text-gray-400 hover:text-gray-600'
              }`}
            >
              {t === 'expense' ? 'DESPESA' : 'RECEITA'}
            </button>
          ))}
        </div>

        <div className="space-y-3">
          <div>
            <label className="block text-[9px] font-bold text-gray-400 uppercase tracking-wider mb-1">Descrição</label>
            <input
              type="text"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              className="w-full px-3 py-2 bg-gray-50 border-none rounded-lg focus:ring-2 focus:ring-blue-500/10 text-sm outline-none"
              required
            />
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-[9px] font-bold text-gray-400 uppercase tracking-wider mb-1">Valor Total</label>
              <input
                type="number"
                value={amount}
                onChange={(e) => setAmount(e.target.value)}
                placeholder="0.00"
                step="0.01"
                className="w-full px-3 py-2 bg-gray-50 border-none rounded-lg focus:ring-2 focus:ring-blue-500/10 text-sm font-bold outline-none"
                required
              />
            </div>
            <div>
              <label className="block text-[9px] font-bold text-gray-400 uppercase tracking-wider mb-1">Categoria</label>
              <select
                value={category}
                onChange={(e) => setCategory(e.target.value)}
                className="w-full px-3 py-2 bg-gray-50 border-none rounded-lg text-sm outline-none"
              >
                {categories[type].map(cat => (
                  <option key={cat} value={cat}>{cat}</option>
                ))}
                {categories[type].length === 0 && <option value="">Nenhuma categoria</option>}
              </select>
            </div>
          </div>

          {type === 'expense' && (
            <div>
              <label className="block text-[9px] font-bold text-gray-400 uppercase tracking-wider mb-1">Parcelas (Mensal)</label>
              <input
                type="number"
                min="1"
                max="60"
                value={installments}
                onChange={(e) => setInstallments(parseInt(e.target.value) || 1)}
                className="w-full px-3 py-2 bg-gray-50 border-none rounded-lg text-sm outline-none focus:ring-2 focus:ring-blue-500/10"
              />
              {installments > 1 && (
                <p className="text-[10px] text-gray-400 mt-1 italic">
                  Serão criados {installments} registros de R$ {(parseFloat(amount || '0') / installments).toFixed(2)} cada.
                </p>
              )}
            </div>
          )}
        </div>

        <button
          type="submit"
          disabled={success}
          className={`w-full py-3 rounded-lg font-bold text-white text-xs transition-all ${
            success ? 'bg-emerald-500' : type === 'expense' ? 'bg-gray-900 hover:bg-black' : 'bg-emerald-600 hover:bg-emerald-700'
          }`}
        >
          {success ? 'Concluído' : installments > 1 ? 'Lançar Parcelas' : 'Adicionar'}
        </button>
      </form>
    </div>
  );
};

