                <div className="space-y-3">
                  {transactions.slice(0, 8).map((t) => (
                    <div key={t.id} className="flex items-center justify-between py-1 border-b border-gray-50 last:border-0">
                      <div>
                        <h4 className="font-medium text-xs text-gray-900 truncate max-w-[140px]">{t.description}</h4>
                        <p className="text-[8px] text-gray-400 font-bold uppercase">{t.category}</p>
                      </div>
                      <span className={`text-[11px] font-bold ${t.type === 'income' ? 'text-emerald-600' : 'text-red-500'}`}>
                        {formatCurrency(t.amount)}
                      </span>
                    </div>
                  ))}
                  {transactions.length === 0 && <p className="text-xs text-gray-300 text-center py-6">Vazio.</p>}
                </div>
              </div>
            </div>
          </div>
        );
      case 'add-expense': return renderTransactionManagement('expense');
      case 'add-income': return renderTransactionManagement('income');
      case 'categories': return <CategoryManager categories={categories} onAdd={addCategory} onDelete={deleteCategory} />;
      case 'reports': return <div className="max-w-5xl"><Reports transactions={transactions} onDelete={deleteTransaction} /></div>;
      default: return null;
    }
  };

  return (
    <div className="flex min-h-screen bg-gray-50">
      <Sidebar currentView={currentView} onViewChange={(v) => { setCurrentView(v); setIsFormOpen(false); }} />

      <main className="flex-1 overflow-y-auto">
        <div className="md:hidden bg-white border-b p-3 flex justify-between items-center sticky top-0 z-40">
          <h1 className="text-lg font-bold">FinancePro</h1>
          <button className="p-1 text-gray-500">
            <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="4" x2="20" y1="12" y2="12"/><line x1="4" x2="20" y1="6" y2="6"/><line x1="4" x2="20" y1="18" y2="18"/></svg>
          </button>
