import React, { useState, useEffect } from 'react';
import { TransactionType, UserCategories } from '../types';

interface TransactionFormProps {
  onAdd: (data: { description: string; amount: number; type: TransactionType; category: string; date: string }) => void;
  categories: UserCategories;
  onCancel?: () => void;
  initialType?: TransactionType;
}

const TransactionForm: React.FC<TransactionFormProps> = ({ onAdd, categories, onCancel, initialType = 'expense' }) => {
  const [description, setDescription] = useState('');
  const [amount, setAmount] = useState('');
  const [type, setType] = useState<TransactionType>(initialType);
  const [category, setCategory] = useState('');
  const [installments, setInstallments] = useState(1);
  const [success, setSuccess] = useState(false);

  useEffect(() => {
    setType(initialType);
    setCategory(categories[initialType][0] || '');
  }, [initialType, categories]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!description || !amount) return;

    const totalAmount = parseFloat(amount);
    const numInstallments = type === 'expense' ? installments : 1;
    const amountPerInstallment = totalAmount / numInstallments;

    for (let i = 0; i < numInstallments; i++) {
      const date = new Date();
      date.setMonth(date.getMonth() + i);

      const installmentLabel = numInstallments > 1 ? ` (${i + 1}/${numInstallments})` : '';

      onAdd({
        description: description + installmentLabel,
        amount: amountPerInstallment,
        type,
        category: category || 'Outros',
        date: date.toISOString()
      });
    }

    setDescription('');
    setAmount('');
    setInstallments(1);
    setSuccess(true);
    setTimeout(() => {
      setSuccess(false);
      if (onCancel) onCancel();
    }, 1000);
  };

  const handleTypeChange = (newType: TransactionType) => {
    setType(newType);
    setCategory(categories[newType][0] || '');
    if (newType === 'income') setInstallments(1);
  };

  return (
    <div className="bg-white p-8 rounded-[32px] shadow-2xl border border-slate-100 w-full max-w-md mx-auto animate-in fade-in zoom-in duration-300">
      <div className="flex justify-between items-center mb-8">
        <h2 className="text-xl font-bold text-slate-900 tracking-tight">Novo Registro</h2>
        {onCancel && (
          <button onClick={onCancel} className="p-2 text-slate-400 hover:text-slate-600 hover:bg-slate-50 rounded-full transition-all">
            <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M18 6 6 18"/><path d="m6 6 12 12"/></svg>
          </button>
        )}
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="flex gap-2 p-1.5 bg-slate-50 rounded-2xl border border-slate-100">
          {(['expense', 'income'] as const).map((t) => (
            <button
              key={t}
              type="button"
              onClick={() => handleTypeChange(t)}
              className={`flex-1 py-2.5 rounded-xl text-xs font-bold transition-all ${
                type === t 
                  ? 'bg-white shadow-sm text-indigo-600' 
                  : 'text-slate-400 hover:text-slate-600'
              }`}
            >
              {t === 'expense' ? 'DESPESA' : 'RECEITA'}
            </button>
          ))}
        </div>

        <div className="space-y-5">
          <div className="group">
            <label className="block text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1.5 ml-1">Descrição</label>
            <input
              type="text"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              className="w-full px-4 py-3 bg-slate-50 border-transparent border-2 rounded-2xl focus:bg-white focus:border-indigo-100 focus:ring-0 text-sm outline-none transition-all"
              required
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1.5 ml-1">Valor Total</label>
              <input
                type="number"
                value={amount}
                onChange={(e) => setAmount(e.target.value)}
                placeholder="0,00"
                step="0.01"
                className="w-full px-4 py-3 bg-slate-50 border-transparent border-2 rounded-2xl focus:bg-white focus:border-indigo-100 focus:ring-0 text-sm font-bold outline-none transition-all"
                required
              />
            </div>
            <div>
              <label className="block text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1.5 ml-1">Categoria</label>
              <select
                value={category}
                onChange={(e) => setCategory(e.target.value)}
                className="w-full px-4 py-3 bg-slate-50 border-transparent border-2 rounded-2xl focus:bg-white focus:border-indigo-100 focus:ring-0 text-sm outline-none transition-all appearance-none cursor-pointer"
              >
                {categories[type].map(cat => (
                  <option key={cat} value={cat}>{cat}</option>
                ))}
              </select>
            </div>
          </div>

          {type === 'expense' && (
            <div className="pt-2">
              <label className="block text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1.5 ml-1">Parcelas (Mensais)</label>
              <div className="flex items-center gap-4">
                 <input
                  type="range"
                  min="1"
                  max="12"
                  value={installments}
                  onChange={(e) => setInstallments(parseInt(e.target.value) || 1)}
                  className="flex-1 h-1.5 bg-slate-100 rounded-lg appearance-none cursor-pointer accent-indigo-600"
                />
                <span className="w-8 text-center text-xs font-bold text-indigo-600">{installments}x</span>
              </div>
              {installments > 1 && (
                <div className="mt-3 p-3 bg-indigo-50/50 rounded-xl border border-indigo-100/50">
                  <p className="text-[10px] text-indigo-700 font-semibold italic">
                    {installments}x de R$ {(parseFloat(amount || '0') / installments).toFixed(2)} lançadas mensalmente.
                  </p>
                </div>
              )}
            </div>
          )}
        </div>

        <button
          type="submit"
          disabled={success}
          className={`w-full py-4 rounded-2xl font-bold text-white text-xs tracking-widest uppercase transition-all shadow-lg ${
            success 
              ? 'bg-teal-500 shadow-teal-100' 
              : type === 'expense' 
                ? 'bg-slate-900 hover:bg-black shadow-slate-200' 
                : 'bg-indigo-600 hover:bg-indigo-700 shadow-indigo-100'
          }`}
        >
          {success ? '✓ Sucesso' : installments > 1 ? 'Confirmar Parcelamento' : 'Salvar Registro'}
        </button>
      </form>
    </div>
  );
};

export default TransactionForm;

import React from 'react';
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip, BarChart, Bar, XAxis, YAxis, CartesianGrid } from 'recharts';
import { Transaction } from '../types';
import { COLORS } from '../constants';

interface ChartsProps {
  transactions: Transaction[];
}

const Charts: React.FC<ChartsProps> = ({ transactions }) => {
  const expenseData = transactions
    .filter(t => t.type === 'expense')
    .reduce((acc: any[], t) => {
      const existing = acc.find(item => item.name === t.category);
      if (existing) {
        existing.value += t.amount;
      } else {
        acc.push({ name: t.category, value: t.amount });
      }
      return acc;
    }, []);

  const COLORS_LIST = ['#6366f1', '#14b8a6', '#f43f5e', '#f59e0b', '#8b5cf6', '#ec4899', '#94a3b8'];

  if (transactions.length === 0) return null;

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
      <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 h-80">
        <h3 className="text-sm font-bold mb-4 text-slate-800 tracking-tight">Gastos por Categoria</h3>
        <ResponsiveContainer width="100%" height="100%">
          <PieChart>
            <Pie
              data={expenseData}
              cx="50%"
              cy="50%"
              innerRadius={65}
              outerRadius={85}
              paddingAngle={8}
              dataKey="value"
              stroke="none"
            >
              {expenseData.map((entry, index) => (
                <Cell key={`cell-${index}`} fill={COLORS_LIST[index % COLORS_LIST.length]} />
              ))}
            </Pie>
            <Tooltip 
              formatter={(value: number) => `R$ ${value.toFixed(2)}`}
              contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)', fontSize: '12px' }}
            />
          </PieChart>
        </ResponsiveContainer>
      </div>

      <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 h-80">
        <h3 className="text-sm font-bold mb-4 text-slate-800 tracking-tight">Fluxo de Caixa Recente</h3>
        <ResponsiveContainer width="100%" height="100%">
          <BarChart data={transactions.slice(0, 6).reverse()}>
            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
            <XAxis dataKey="description" hide />
            <YAxis hide />
            <Tooltip 
              formatter={(value: number) => `R$ ${value.toFixed(2)}`}
              contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)', fontSize: '12px' }}
            />
            <Bar dataKey="amount" radius={[6, 6, 6, 6]} barSize={32}>
              {transactions.slice(0, 6).reverse().map((entry, index) => (
                <Cell key={`cell-${index}`} fill={entry.type === 'income' ? COLORS.income : COLORS.expense} />
              ))}
            </Bar>
          </BarChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
};

export default Charts;

