import React, { useState, useEffect } from 'react';
import { TransactionType, UserCategories } from '../types';

interface TransactionFormProps {
  onAdd: (data: { description: string; amount: number; type: TransactionType; category: string; date: string }) => void;
  categories: UserCategories;
  onCancel?: () => void;
  initialType?: TransactionType;
}

const TransactionForm: React.FC<TransactionFormProps> = ({ onAdd, categories, onCancel, initialType = 'expense' }) => {
  const [description, setDescription] = useState('');
  const [amount, setAmount] = useState('');
  const [type, setType] = useState<TransactionType>(initialType);
  const [category, setCategory] = useState('');
  const [installments, setInstallments] = useState(1);
  const [success, setSuccess] = useState(false);

  useEffect(() => {
    setType(initialType);
    setCategory(categories[initialType][0] || '');
  }, [initialType, categories]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!description || !amount) return;

    const totalAmount = parseFloat(amount);
    const numInstallments = type === 'expense' ? installments : 1;
    const amountPerInstallment = totalAmount / numInstallments;

    for (let i = 0; i < numInstallments; i++) {
      const date = new Date();
      date.setMonth(date.getMonth() + i);

      const installmentLabel = numInstallments > 1 ? ` (${i + 1}/${numInstallments})` : '';

      onAdd({
        description: description + installmentLabel,
        amount: amountPerInstallment,
        type,
        category: category || 'Outros',
        date: date.toISOString()
      });
    }

    setDescription('');
    setAmount('');
    setInstallments(1);
    setSuccess(true);
    setTimeout(() => {
      setSuccess(false);
      if (onCancel) onCancel();
    }, 1000);
  };

  const handleTypeChange = (newType: TransactionType) => {
    setType(newType);
    setCategory(categories[newType][0] || '');
    if (newType === 'income') setInstallments(1);
  };

  const installmentsValue = Math.max(1, installments);

  return (
    <div className="bg-white p-8 rounded-[32px] shadow-2xl border border-slate-100 w-full max-w-md mx-auto animate-in fade-in zoom-in duration-300">
      <div className="flex justify-between items-center mb-8">
        <h2 className="text-xl font-bold text-slate-900 tracking-tight">Novo Registro</h2>
        {onCancel && (
          <button onClick={onCancel} className="p-2 text-slate-400 hover:text-slate-600 hover:bg-slate-50 rounded-full transition-all">
            <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M18 6 6 18"/><path d="m6 6 12 12"/></svg>
          </button>
        )}
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="flex gap-2 p-1.5 bg-slate-50 rounded-2xl border border-slate-100">
          {(['expense', 'income'] as const).map((t) => (
            <button
              key={t}
              type="button"
              onClick={() => handleTypeChange(t)}
              className={`flex-1 py-2.5 rounded-xl text-xs font-bold transition-all ${
                type === t 
                  ? 'bg-white shadow-sm text-indigo-600' 
                  : 'text-slate-400 hover:text-slate-600'
              }`}
            >
              {t === 'expense' ? 'DESPESA' : 'RECEITA'}
            </button>
          ))}
        </div>

        <div className="space-y-5">
          <div className="group">
            <label className="block text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1.5 ml-1">Descrição</label>
            <input
              type="text"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="Ex: Supermercado"
              className="w-full px-4 py-3 bg-slate-50 border-transparent border-2 rounded-2xl focus:bg-white focus:border-indigo-100 focus:ring-0 text-sm outline-none transition-all font-medium"
              required
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1.5 ml-1">Valor Total</label>
              <input
                type="number"
                value={amount}
                onChange={(e) => setAmount(e.target.value)}
                placeholder="0,00"
                step="0.01"
                className="w-full px-4 py-3 bg-slate-50 border-transparent border-2 rounded-2xl focus:bg-white focus:border-indigo-100 focus:ring-0 text-sm font-bold outline-none transition-all"
                required
              />
            </div>
            <div>
              <label className="block text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1.5 ml-1">Categoria</label>
              <select
                value={category}
                onChange={(e) => setCategory(e.target.value)}
                className="w-full px-4 py-3 bg-slate-50 border-transparent border-2 rounded-2xl focus:bg-white focus:border-indigo-100 focus:ring-0 text-sm outline-none transition-all appearance-none cursor-pointer font-medium"
              >
                {categories[type].map(cat => (
                  <option key={cat} value={cat}>{cat}</option>
                ))}
              </select>
            </div>
          </div>

          {type === 'expense' && (
            <div className="animate-in fade-in slide-in-from-top-2 duration-300">
              <label className="block text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1.5 ml-1">Parcelas</label>
              <input
                type="number"
                min="1"
                max="60"
                value={installments}
                onChange={(e) => setInstallments(parseInt(e.target.value) || 1)}
                className="w-full px-4 py-3 bg-slate-50 border-transparent border-2 rounded-2xl focus:bg-white focus:border-indigo-100 focus:ring-0 text-sm font-bold outline-none transition-all"
              />
              {installmentsValue > 1 && (
                <div className="mt-3 p-4 bg-indigo-50/50 rounded-2xl border border-indigo-100/50">
                  <p className="text-[10px] text-indigo-700 font-bold uppercase tracking-tight text-center">
                    {installmentsValue}x de R$ {(parseFloat(amount || '0') / installmentsValue).toFixed(2)} lançadas mensalmente
                  </p>
                </div>
              )}
            </div>
          )}
        </div>

        <button
          type="submit"
          disabled={success}
          className={`w-full py-4 rounded-2xl font-bold text-white text-xs tracking-widest uppercase transition-all shadow-lg ${
            success 
              ? 'bg-teal-500 shadow-teal-100' 
              : type === 'expense' 
                ? 'bg-slate-900 hover:bg-black shadow-slate-200' 
                : 'bg-indigo-600 hover:bg-indigo-700 shadow-indigo-100'
          }`}
        >
          {success ? '✓ Sucesso' : installmentsValue > 1 ? 'Confirmar Parcelamento' : 'Salvar Registro'}
        </button>
      </form>
    </div>
  );
};

