                  <p className="text-[10px] text-indigo-700 font-bold uppercase tracking-tight text-center">
                    {installmentsValue}x de R$ {(parseFloat(amount || '0') / installmentsValue).toFixed(2)} lançadas mensalmente
                  </p>
                </div>
              )}
            </div>
          )}
        </div>

        <button
          type="submit"
          disabled={success}
          className={`w-full py-4 rounded-2xl font-bold text-white text-xs tracking-widest uppercase transition-all shadow-lg ${
            success 
              ? 'bg-teal-500 shadow-teal-100' 
              : type === 'expense' 
                ? 'bg-slate-900 hover:bg-black shadow-slate-200' 
                : 'bg-indigo-600 hover:bg-indigo-700 shadow-indigo-100'
          }`}
        >
          {success ? '✓ Sucesso' : installmentsValue > 1 ? 'Confirmar Parcelamento' : 'Salvar Registro'}
        </button>
      </form>
    </div>
  );
};

