export type TransactionType = 'income' | 'expense';

export interface User {
  id: string;
  name: string;
  avatarColor: string;
}

export interface Transaction {
  id: string;
  description: string;
  amount: number;
  type: TransactionType;
  category: string;
  date: string;
}

export interface Summary {
  balance: number;
  income: number;
  expenses: number;
}

export interface UserCategories {
  expense: string[];
  income: string[];
}

import { useState, useEffect, useCallback } from 'react';
import { Transaction, Summary, UserCategories } from '../types';

const DEFAULT_CATEGORIES: UserCategories = {
  expense: ['Alimentação', 'Moradia', 'Transporte', 'Lazer', 'Saúde', 'Outros'],
  income: ['Salário', 'Freelance', 'Investimentos', 'Presentes', 'Outros']
};

export const useFinanceData = (userId: string | null) => {
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [categories, setCategories] = useState<UserCategories>(DEFAULT_CATEGORIES);

  // Carrega dados quando o usuário muda
  useEffect(() => {
    if (!userId) {
      setTransactions([]);
      setCategories(DEFAULT_CATEGORIES);
      return;
    }

    const savedData = localStorage.getItem(`fp_data_${userId}`);
    const savedCats = localStorage.getItem(`fp_cats_${userId}`);

    setTransactions(savedData ? JSON.parse(savedData) : []);
    setCategories(savedCats ? JSON.parse(savedCats) : DEFAULT_CATEGORIES);
  }, [userId]);

  // Salva dados sempre que houver mudança e houver um usuário ativo
  useEffect(() => {
    if (userId) {
      localStorage.setItem(`fp_data_${userId}`, JSON.stringify(transactions));
    }
  }, [transactions, userId]);

  useEffect(() => {
    if (userId) {
      localStorage.setItem(`fp_cats_${userId}`, JSON.stringify(categories));
    }
  }, [categories, userId]);

  const addTransaction = useCallback((transaction: Omit<Transaction, 'id'>) => {
    const newTransaction: Transaction = {
      ...transaction,
      id: crypto.randomUUID(),
      date: transaction.date || new Date().toISOString(),
    };
    setTransactions(prev => [newTransaction, ...prev]);
  }, []);

  const deleteTransaction = useCallback((id: string) => {
    setTransactions(prev => prev.filter(t => t.id !== id));
  }, []);

  const addCategory = useCallback((type: 'income' | 'expense', name: string) => {
    setCategories(prev => ({
      ...prev,
      [type]: [...new Set([...prev[type], name])]
    }));
  }, []);

  const deleteCategory = useCallback((type: 'income' | 'expense', name: string) => {
    setCategories(prev => ({
      ...prev,
      [type]: prev[type].filter(cat => cat !== name)
    }));
  }, []);

  const getSummary = (): Summary => {
    return transactions.reduce((acc, t) => {
      if (t.type === 'income') {
        acc.income += t.amount;
        acc.balance += t.amount;
      } else {
        acc.expenses += t.amount;
        acc.balance -= t.amount;
      }
      return acc;
    }, { balance: 0, income: 0, expenses: 0 });
  };

  return {
    transactions,
    categories,
    addTransaction,
    deleteTransaction,
    addCategory,
    deleteCategory,
    summary: getSummary(),
  };
};

import React, { useState, useEffect } from 'react';
