            </div>
          </form>
        ) : (
          <button
            onClick={() => setIsAdding(true)}
            className="group p-8 rounded-[32px] border-2 border-dashed border-slate-200 hover:border-indigo-300 hover:bg-white transition-all flex flex-col items-center justify-center gap-4"
