import React, { useState, useEffect } from 'react';
import { User } from '../types';

interface AuthScreenProps {
  onSelectUser: (user: User) => void;
}

const COLORS = [
  'bg-indigo-500', 'bg-teal-500', 'bg-rose-500', 'bg-amber-500', 'bg-purple-500', 'bg-blue-500'
];

const AuthScreen: React.FC<AuthScreenProps> = ({ onSelectUser }) => {
  const [users, setUsers] = useState<User[]>([]);
  const [isAdding, setIsAdding] = useState(false);
  const [selectedUser, setSelectedUser] = useState<User | null>(null);

  const [newName, setNewName] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [loginPassword, setLoginPassword] = useState('');
  const [error, setError] = useState(false);

  useEffect(() => {
    const saved = localStorage.getItem('fp_profiles');
    if (saved) setUsers(JSON.parse(saved));
  }, []);

  const saveUsers = (updated: User[]) => {
    setUsers(updated);
    localStorage.setItem('fp_profiles', JSON.stringify(updated));
  };

  const handleCreateUser = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newName.trim() || !newPassword.trim()) return;

    const newUser: User = {
      id: crypto.randomUUID(),
      name: newName.trim(),
      password: newPassword, // Em um app real, usaríamos hash aqui
      avatarColor: COLORS[users.length % COLORS.length]
    };

    const updated = [...users, newUser];
    saveUsers(updated);
    setNewName('');
    setNewPassword('');
    setIsAdding(false);
    onSelectUser(newUser);
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedUser) return;

    if (selectedUser.password === loginPassword) {
      onSelectUser(selectedUser);
    } else {
      setError(true);
      setTimeout(() => setError(false), 500);
      setLoginPassword('');
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 animate-in fade-in duration-500">
