        <div className="w-16 h-16 bg-indigo-600 rounded-2xl flex items-center justify-center text-white text-2xl font-bold mx-auto mb-6 shadow-xl shadow-indigo-100">FP</div>
        <h1 className="text-3xl font-bold text-slate-900 tracking-tight mb-2">FinancePro</h1>
        <p className="text-slate-400 font-medium">
          {selectedUser ? `Olá, ${selectedUser.name}` : isAdding ? 'Crie sua conta privada' : 'Selecione seu perfil para entrar'}
        </p>
      </div>

      <div className="w-full max-w-2xl flex flex-col items-center">
        {selectedUser ? (
          // TELA DE LOGIN (SENHA)
          <div className={`bg-white p-10 rounded-[40px] border border-slate-100 shadow-2xl w-full max-w-md flex flex-col items-center animate-in zoom-in-95 duration-300 ${error ? 'animate-bounce' : ''}`}>
            <div className={`w-20 h-20 ${selectedUser.avatarColor} rounded-full flex items-center justify-center text-white text-3xl font-bold shadow-lg mb-6`}>
              {selectedUser.name.charAt(0).toUpperCase()}
            </div>

            <h2 className="text-xl font-bold text-slate-900 mb-8">{selectedUser.name}</h2>

            <form onSubmit={handleLogin} className="w-full space-y-4">
              <div className="relative">
                <input
                  autoFocus
                  type="password"
                  value={loginPassword}
                  onChange={(e) => setLoginPassword(e.target.value)}
                  placeholder="Sua senha"
                  className={`w-full px-6 py-4 bg-slate-50 border-2 rounded-2xl text-center font-bold text-slate-900 outline-none transition-all ${error ? 'border-rose-300 bg-rose-50' : 'border-transparent focus:bg-white focus:border-indigo-100'}`}
                />
                {error && <p className="text-center text-[10px] text-rose-500 font-bold uppercase mt-2 tracking-widest">Senha Incorreta</p>}
              </div>

              <button type="submit" className="w-full bg-slate-900 text-white py-4 rounded-2xl text-xs font-bold uppercase tracking-widest hover:bg-black transition-all shadow-lg">
                Acessar Conta
              </button>

              <button 
                type="button" 
                onClick={() => { setSelectedUser(null); setLoginPassword(''); setError(false); }} 
                className="w-full text-slate-400 text-[10px] font-bold uppercase tracking-widest pt-2 hover:text-indigo-600 transition-colors"
              >
                ← Voltar aos perfis
              </button>
            </form>
          </div>
        ) : isAdding ? (
          // TELA DE CADASTRO
          <div className="bg-white p-10 rounded-[40px] border border-slate-100 shadow-2xl w-full max-w-md animate-in zoom-in-95 duration-300">
             <h2 className="text-xl font-bold text-slate-900 mb-8 text-center">Novo Perfil Restrito</h2>
             <form onSubmit={handleCreateUser} className="space-y-5">
                <div>
                  <label className="block text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1.5 ml-1">Nome de Usuário</label>
                  <input
                    autoFocus
                    type="text"
                    value={newName}
                    onChange={(e) => setNewName(e.target.value)}
                    placeholder="Ex: João Silva"
                    className="w-full px-5 py-4 bg-slate-50 rounded-2xl text-sm font-bold text-slate-900 outline-none border-2 border-transparent focus:bg-white focus:border-indigo-100 transition-all"
                  />
                </div>
                <div>
                  <label className="block text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1.5 ml-1">Senha de Acesso</label>
                  <input
                    type="password"
                    value={newPassword}
                    onChange={(e) => setNewPassword(e.target.value)}
                    placeholder="••••••••"
                    className="w-full px-5 py-4 bg-slate-50 rounded-2xl text-sm font-bold text-slate-900 outline-none border-2 border-transparent focus:bg-white focus:border-indigo-100 transition-all"
                  />
                </div>

                <div className="pt-4 flex flex-col gap-3">
                  <button type="submit" className="w-full bg-indigo-600 text-white py-4 rounded-2xl text-xs font-bold uppercase tracking-widest hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-100">
