import { createClient } from '@supabase/supabase-js';

const supabaseUrl = 'https://iulzosgpgyjdgsokrfud.supabase.co';
const supabaseAnonKey = 'sb_publishable_KjRa0yFUB-9vfW6Yr3OjwA_imAmqP_U';

export const supabase = createClient(supabaseUrl, supabaseAnonKey);

import { useState, useEffect, useCallback } from 'react';
import { Transaction, Summary, UserCategories } from '../types';
import { supabase } from '../services/supabaseClient';

const DEFAULT_CATEGORIES: UserCategories = {
  expense: ['Alimentação', 'Moradia', 'Transporte', 'Lazer', 'Saúde', 'Outros'],
  income: ['Salário', 'Freelance', 'Investimentos', 'Presentes', 'Outros']
};

export const useFinanceData = (userId: string | null) => {
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [categories, setCategories] = useState<UserCategories>(DEFAULT_CATEGORIES);
  const [loading, setLoading] = useState(false);

  const fetchUserData = useCallback(async () => {
    if (!userId) return;
    setLoading(true);

    try {
      // Buscar Perfil (Categorias)
      const { data: profile } = await supabase
        .from('profiles')
        .select('categories')
        .eq('id', userId)
        .single();

      if (profile?.categories) {
        setCategories(profile.categories as unknown as UserCategories);
      }

      // Buscar Transações
      const { data: transData, error } = await supabase
        .from('transactions')
        .select('*')
        .eq('user_id', userId)
        .order('date', { ascending: false });

      if (error) throw error;
      setTransactions(transData || []);
    } catch (err) {
      console.error('Erro ao buscar dados:', err);
    } finally {
      setLoading(false);
    }
  }, [userId]);

  useEffect(() => {
    fetchUserData();
  }, [fetchUserData]);

  const addTransaction = useCallback(async (transaction: Omit<Transaction, 'id'>) => {
    if (!userId) return;

    try {
      const { data, error } = await supabase
        .from('transactions')
        .insert([{
          ...transaction,
          user_id: userId
        }])
        .select()
        .single();

      if (error) throw error;
      setTransactions(prev => [data, ...prev]);
    } catch (err) {
      console.error('Erro ao adicionar transação:', err);
    }
  }, [userId]);

  const deleteTransaction = useCallback(async (id: string) => {
    try {
      const { error } = await supabase
        .from('transactions')
        .delete()
        .eq('id', id);

      if (error) throw error;
      setTransactions(prev => prev.filter(t => t.id !== id));
    } catch (err) {
      console.error('Erro ao deletar transação:', err);
    }
  }, []);

  const updateCategories = async (newCats: UserCategories) => {
    if (!userId) return;
    try {
      await supabase
        .from('profiles')
        .update({ categories: newCats })
        .eq('id', userId);
      setCategories(newCats);
    } catch (err) {
      console.error('Erro ao atualizar categorias:', err);
    }
  };

  const addCategory = useCallback((type: 'income' | 'expense', name: string) => {
    const newCats = {
      ...categories,
      [type]: [...new Set([...categories[type], name])]
    };
    updateCategories(newCats);
  }, [categories, userId]);

  const deleteCategory = useCallback((type: 'income' | 'expense', name: string) => {
    const newCats = {
      ...categories,
      [type]: categories[type].filter(cat => cat !== name)
    };
    updateCategories(newCats);
  }, [categories, userId]);

  const getSummary = (): Summary => {
    return transactions.reduce((acc, t) => {
      const amt = Number(t.amount);
      if (t.type === 'income') {
        acc.income += amt;
        acc.balance += amt;
      } else {
        acc.expenses += amt;
        acc.balance -= amt;
      }
      return acc;
    }, { balance: 0, income: 0, expenses: 0 });
  };

  return {
    transactions,
    categories,
    addTransaction,
    deleteTransaction,
    addCategory,
    deleteCategory,
    summary: getSummary(),
    loading
  };
};

