  // Verificar sessão ativa ao carregar
  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session?.user) {
        fetchProfile(session.user.id);
      } else {
        setSessionLoading(false);
      }
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session?.user) {
        fetchProfile(session.user.id);
      } else {
        setCurrentUser(null);
        setSessionLoading(false);
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  const fetchProfile = async (uid: string) => {
    const { data: profile } = await supabase
      .from('profiles')
      .select('name, avatar_color')
      .eq('id', uid)
      .single();

    if (profile) {
      setCurrentUser({
        id: uid,
        name: profile.name,
        avatarColor: profile.avatar_color
      });
    }
    setSessionLoading(false);
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setCurrentUser(null);
    setCurrentView('dashboard');
  };

  const formatCurrency = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  if (sessionLoading) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center">
        <div className="w-8 h-8 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
      </div>
    );
  }

  if (!currentUser) {
    return <AuthScreen onSelectUser={setCurrentUser} />;
  }

  const renderTransactionManagement = (type: TransactionType) => {
    const filtered = transactions.filter(t => t.type === type);
    const title = type === 'expense' ? 'Minhas Despesas' : 'Minhas Receitas';
    const accentColor = type === 'expense' ? 'bg-rose-500' : 'bg-teal-600';

    return (
      <div className="space-y-6 max-w-5xl">
        <div className="flex justify-between items-end mb-4">
          <div>
            <h2 className="text-2xl font-bold text-slate-900 tracking-tight">{title}</h2>
            <p className="text-xs text-slate-400 font-medium">Histórico sincronizado na nuvem</p>
          </div>
          <button 
            onClick={() => setIsFormOpen(true)}
            className={`flex items-center gap-2 ${accentColor} text-white px-5 py-2.5 rounded-2xl text-[11px] font-bold uppercase tracking-widest shadow-lg shadow-slate-100 transform active:scale-95 transition-all`}
          >
            <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><path d="M12 5v14M5 12h14"/></svg>
            Novo Lançamento
          </button>
        </div>

        {isFormOpen && (
          <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-md z-50 flex items-center justify-center p-4">
            <TransactionForm 
              onAdd={addTransaction} 
              categories={categories}
              initialType={type} 
              onCancel={() => setIsFormOpen(false)}
            />
          </div>
        )}

        <div className="bg-white rounded-[32px] border border-slate-100 shadow-sm overflow-hidden">
          <table className="w-full text-left">
            <thead>
              <tr className="text-[10px] font-bold text-slate-400 uppercase tracking-widest border-b border-slate-50 bg-slate-50/30">
                <th className="py-4 px-6">Data</th>
                <th className="py-4 px-6">Descrição</th>
                <th className="py-4 px-6 text-right">Valor</th>
                <th className="py-4 px-6 w-12"></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filtered.map((t) => (
                <tr key={t.id} className="group hover:bg-slate-50/50 transition-colors">
                  <td className="py-4 px-6 text-xs text-slate-400 font-medium">
                    {new Date(t.date).toLocaleDateString('pt-BR')}
                  </td>
                  <td className="py-4 px-6">
                    <p className="text-sm font-semibold text-slate-900">{t.description}</p>
                    <span className="text-[10px] text-indigo-500 font-bold uppercase tracking-tight">{t.category}</span>
                  </td>
                  <td className={`py-4 px-6 text-right text-sm font-bold ${t.type === 'income' ? 'text-teal-600' : 'text-rose-500'}`}>
                    {formatCurrency(t.amount)}
                  </td>
                  <td className="py-4 px-6 text-right">
                    <button onClick={() => deleteTransaction(t.id)} className="opacity-0 group-hover:opacity-100 p-2 text-slate-300 hover:text-rose-500 hover:bg-rose-50 rounded-lg transition-all">
                      <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M3 6h18"/><path d="M19 6v14c0 1-1 2-2 2H7c-1 0-2-1-2-2V6"/></svg>
                    </button>
                  </td>
                </tr>
              ))}
              {filtered.length === 0 && !dataLoading && (
                <tr>
                  <td colSpan={4} className="py-20 text-center text-slate-300 text-xs font-medium">Não há registros para exibir.</td>
                </tr>
              )}
              {dataLoading && (
                <tr>
                  <td colSpan={4} className="py-20 text-center">
                    <div className="w-6 h-6 border-2 border-indigo-600 border-t-transparent rounded-full animate-spin mx-auto"></div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    );
  };

  const renderContent = () => {
    switch (currentView) {
      case 'dashboard':
        return (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="lg:col-span-8 space-y-8">
              <SummaryCards summary={summary} />
              <div className="grid grid-cols-1 gap-8">
                 <AIInsights transactions={transactions} />
                 <Charts transactions={transactions} />
              </div>
            </div>
            <div className="lg:col-span-4">
              <div className="bg-white p-6 rounded-[32px] shadow-sm border border-slate-100">
                <div className="flex items-center justify-between mb-6">
                  <h2 className="text-sm font-bold text-slate-900 tracking-tight">Recentes</h2>
                  <button onClick={() => setCurrentView('reports')} className="text-[11px] font-bold text-indigo-600 hover:text-indigo-800 tracking-tight transition-colors">Relatórios →</button>
                </div>
                <div className="space-y-4">
                  {transactions.slice(0, 10).map((t) => (
                    <div key={t.id} className="flex items-center justify-between py-2 border-b border-slate-50 last:border-0 group">
                      <div className="overflow-hidden">
                        <h4 className="font-semibold text-xs text-slate-900 truncate pr-2">{t.description}</h4>
                        <p className="text-[9px] text-slate-400 font-bold uppercase tracking-tight">{t.category}</p>
                      </div>
                      <span className={`text-[12px] font-bold shrink-0 ${t.type === 'income' ? 'text-teal-600' : 'text-rose-500'}`}>
                        {formatCurrency(t.amount)}
                      </span>
                    </div>
                  ))}
                  {transactions.length === 0 && !dataLoading && <p className="text-xs text-slate-300 text-center py-10 font-medium">Tudo limpo por aqui.</p>}
                  {dataLoading && <div className="py-10 text-center"><div className="w-5 h-5 border-2 border-indigo-200 border-t-indigo-600 rounded-full animate-spin mx-auto"></div></div>}
                </div>
              </div>
            </div>
          </div>
        );
      case 'add-expense': return renderTransactionManagement('expense');
      case 'add-income': return renderTransactionManagement('income');
      case 'categories': return <div className="animate-in fade-in duration-300"><CategoryManager categories={categories} onAdd={addCategory} onDelete={deleteCategory} /></div>;
      case 'reports': return <div className="max-w-5xl animate-in fade-in duration-300"><Reports transactions={transactions} onDelete={deleteTransaction} /></div>;
      default: return null;
    }
  };

  return (
    <div className="flex min-h-screen bg-slate-50/50">
      <Sidebar 
        currentView={currentView} 
        onViewChange={(v) => { setCurrentView(v); setIsFormOpen(false); }} 
        currentUser={currentUser}
        onLogout={handleLogout}
      />

      <main className="flex-1 overflow-y-auto">
        <div className="md:hidden bg-white border-b border-slate-100 p-4 flex justify-between items-center sticky top-0 z-40">
          <div className="flex items-center gap-2">
             <div className={`w-6 h-6 ${currentUser.avatarColor} rounded-full flex items-center justify-center text-white text-[8px] font-bold`}>
               {currentUser.name.charAt(0).toUpperCase()}
             </div>
             <h1 className="text-lg font-bold text-slate-900 tracking-tight">FinancePro</h1>
          </div>
          <button onClick={handleLogout} className="p-2 text-slate-500 hover:bg-slate-50 rounded-xl transition-colors">
            <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"/><polyline points="16 17 21 12 16 7"/><line x1="21" x2="9" y1="12" y2="12"/></svg>
          </button>
        </div>

        <div className="p-8 md:p-12 w-full max-w-7xl">
          <header className="mb-10 hidden md:block">
             <div className="flex justify-between items-center">
                <div>
                   <h2 className="text-3xl font-bold text-slate-900 tracking-tight mb-1">
                    {currentView === 'dashboard' ? 'Dashboard' : 
                     currentView === 'add-expense' ? 'Despesas' :
                     currentView === 'add-income' ? 'Receitas' : 
                     currentView === 'categories' ? 'Categorias' : 'Relatórios Detalhados'}
                   </h2>
                   <p className="text-[11px] text-slate-400 font-bold uppercase tracking-[0.2em]">Olá, {currentUser.name} • Gestão Cloud Ativa</p>
                </div>
                <div className="bg-white px-4 py-2 rounded-2xl border border-slate-100 flex items-center gap-2.5 shadow-sm">
                  <div className="w-2 h-2 rounded-full bg-teal-500 shadow-sm shadow-teal-100 animate-pulse"></div>
                  <span className="text-[10px] font-bold text-slate-500 uppercase tracking-tighter">Sincronizado com Supabase</span>
                </div>
             </div>
          </header>

          <div className="min-h-[60vh]">{renderContent()}</div>

          <footer className="mt-20 pt-8 border-t border-slate-100 flex justify-between items-center text-slate-400 text-[10px] uppercase font-bold tracking-[0.2em]">
            <p>© 2025 FinancePro</p>
            <div className="flex gap-6">
              <span className="flex items-center gap-1.5"><span className="w-1.5 h-1.5 rounded-full bg-indigo-400"></span> AI Assistant</span>
              <span className="flex items-center gap-1.5"><span className="w-1.5 h-1.5 rounded-full bg-slate-300"></span> Postgres DB</span>
            </div>
          </footer>
        </div>
      </main>
    </div>
  );
};

export default App;

