import React, { useState, useMemo } from 'react';
import { Transaction, UserCategories, Summary } from '../types';

interface ReportsProps {
  transactions: Transaction[];
  categories: UserCategories;
  onDelete: (id: string) => void;
  onTogglePaid: (id: string, currentStatus: boolean) => void;
}

const Reports: React.FC<ReportsProps> = ({ transactions, categories, onDelete, onTogglePaid }) => {
  const currentYYYYMM = new Date().toISOString().slice(0, 7);
  const [filter, setFilter] = useState<'all' | 'income' | 'expense'>('all');
  const [selectedMonth, setSelectedMonth] = useState(currentYYYYMM);
  const [selectedCategory, setSelectedCategory] = useState('all');
  const [statusFilter, setStatusFilter] = useState<'all' | 'paid' | 'pending'>('all');

  const { filteredTransactions, summary } = useMemo(() => {
    const filtered = transactions
      .filter(t => {
        if (filter !== 'all' && t.type !== filter) return false;
        const tMonth = t.date.slice(0, 7);
        if (selectedMonth && tMonth !== selectedMonth) return false;
        if (selectedCategory !== 'all' && t.category !== selectedCategory) return false;
        if (statusFilter === 'paid' && !t.is_paid) return false;
        if (statusFilter === 'pending' && t.is_paid) return false;
        return true;
      })
      .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    const stats = filtered.reduce((acc, t) => {
      const amt = Number(t.amount);
      if (t.type === 'income') {
        acc.income += amt;
        acc.balance += amt;
      } else {
        acc.expenses += amt;
        acc.balance -= amt;
      }
      return acc;
    }, { balance: 0, income: 0, expenses: 0 } as Summary);

    return { filteredTransactions: filtered, summary: stats };
  }, [transactions, filter, selectedMonth, selectedCategory, statusFilter]);

  const formatCurrency = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const resetFilters = () => {
    setFilter('all');
    setSelectedMonth(currentYYYYMM);
    setSelectedCategory('all');
    setStatusFilter('all');
  };

  const exportToExcel = () => {
    const headers = ["Data", "Descrição", "Categoria", "Tipo", "Valor", "Status"];
    const rows = filteredTransactions.map(t => [
      new Date(t.date).toLocaleDateString('pt-BR'),
      t.description.replace(/;/g, ','),
      t.category,
      t.type === 'income' ? 'Entrada' : 'Saída',
      t.amount.toString().replace('.', ','),
      t.is_paid ? 'Pago' : 'Pendente'
    ]);

    const csvContent = "data:text/csv;charset=utf-8,\uFEFF" 
      + headers.join(";") + "\n" 
      + rows.map(e => e.join(";")).join("\n");

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `extrato_${selectedMonth}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const exportToPDF = () => {
    const originalTitle = document.title;
    document.title = `Extrato_${selectedMonth}_FinancePro`;
    // Timeout para garantir que o navegador termine de renderizar antes de abrir o print
    setTimeout(() => {
      window.print();
      document.title = originalTitle;
    }, 150);
  };

  return (
    <div className="space-y-6">
      {/* Resumo do Período Filtrado */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="bg-white p-7 rounded-xl shadow-sm border border-slate-50 flex flex-col justify-center">
          <p className="text-slate-400 text-[10px] font-bold uppercase tracking-[0.1em] mb-2">PATRIMÔNIO LÍQUIDO</p>
          <h3 className="text-3xl font-bold text-slate-900">
            {formatCurrency(summary.balance)}
          </h3>
        </div>
        <div className="bg-white p-7 rounded-xl shadow-sm border border-slate-50 flex flex-col justify-center">
          <p className="text-slate-400 text-[10px] font-bold uppercase tracking-[0.1em] mb-2">ENTRADAS</p>
          <h3 className="text-3xl font-bold text-teal-600">
            {formatCurrency(summary.income)}
          </h3>
        </div>
        <div className="bg-white p-7 rounded-xl shadow-sm border border-slate-50 flex flex-col justify-center">
          <p className="text-slate-400 text-[10px] font-bold uppercase tracking-[0.1em] mb-2">SAÍDAS</p>
          <h3 className="text-3xl font-bold text-rose-500">
            {formatCurrency(summary.expenses)}
          </h3>
        </div>
      </div>

      {/* Painel de Filtros (Oculto na Impressão) */}
      <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 no-print">
        <div className="flex flex-col lg:flex-row gap-6 items-end justify-between">
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 w-full">
            <div className="flex flex-col">
              <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest ml-1 mb-1.5">Mês de Referência</label>
              <input 
                type="month" 
                value={selectedMonth} 
                onChange={(e) => setSelectedMonth(e.target.value)}
                className="bg-slate-50 border-2 border-transparent focus:border-indigo-100 rounded-lg px-4 py-2.5 text-xs font-bold text-indigo-600 outline-none transition-all"
              />
            </div>

            <div className="flex flex-col">
              <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest ml-1 mb-1.5">Categoria</label>
              <select 
                value={selectedCategory} 
                onChange={(e) => setSelectedCategory(e.target.value)}
                className="bg-slate-50 border-2 border-transparent focus:border-indigo-100 rounded-lg px-4 py-2.5 text-xs font-bold text-slate-700 outline-none transition-all"
              >
                <option value="all">Todas</option>
                {[...categories.expense, ...categories.income].sort().map(cat => (
                  <option key={cat} value={cat}>{cat}</option>
                ))}
              </select>
            </div>

            <div className="flex flex-col">
              <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest ml-1 mb-1.5">Status Pago</label>
              <select 
                value={statusFilter} 
                onChange={(e) => setStatusFilter(e.target.value as any)}
                className="bg-slate-50 border-2 border-transparent focus:border-indigo-100 rounded-lg px-4 py-2.5 text-xs font-bold text-slate-700 outline-none transition-all"
              >
                <option value="all">Todos</option>
                <option value="paid">Já Pagos</option>
                <option value="pending">Pendentes</option>
              </select>
            </div>

            <div className="flex flex-col">
              <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest ml-1 mb-1.5">Tipo Transação</label>
              <select 
                value={filter} 
                onChange={(e) => setFilter(e.target.value as any)}
                className="bg-slate-50 border-2 border-transparent focus:border-indigo-100 rounded-lg px-4 py-2.5 text-xs font-bold text-slate-700 outline-none transition-all"
              >
                <option value="all">Entradas/Saídas</option>
                <option value="income">Apenas Receitas</option>
                <option value="expense">Apenas Despesas</option>
              </select>
            </div>
          </div>

          <button 
            onClick={resetFilters}
            className="px-6 py-2.5 text-[10px] font-bold text-slate-400 uppercase hover:text-indigo-600 transition-colors border-2 border-transparent hover:border-indigo-50 rounded-lg"
          >
            Limpar Filtros
          </button>
        </div>
      </div>

      {/* Tabela de Dados */}
      <div className="bg-white p-6 md:p-10 rounded-xl shadow-sm border border-slate-100">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 mb-10">
          <div>
            <h2 className="text-2xl font-bold text-slate-900 tracking-tight">Extrato Detalhado</h2>
            <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">
              Listando {filteredTransactions.length} registros • {selectedMonth.split('-').reverse().join('/')}
            </p>
          </div>

          <div className="flex gap-3 no-print w-full md:w-auto">
            <button 
              onClick={exportToExcel}
              className="flex-1 md:flex-none flex items-center justify-center gap-2 bg-emerald-50 text-emerald-700 px-5 py-3 rounded-lg text-[10px] font-bold uppercase tracking-widest hover:bg-emerald-100 transition-all border border-emerald-100"
            >
              <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M14.5 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V7.5L14.5 2z"/><polyline points="14 2 14 8 20 8"/><path d="M8 13h2"/><path d="M8 17h2"/><path d="M14 13h2"/><path d="M14 17h2"/></svg>
              Exportar CSV
            </button>
            <button 
              onClick={exportToPDF}
              className="flex-1 md:flex-none flex items-center justify-center gap-2 bg-slate-900 text-white px-5 py-3 rounded-lg text-[10px] font-bold uppercase tracking-widest hover:bg-slate-800 transition-all shadow-xl shadow-slate-200 active:scale-95"
            >
              <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" x2="12" y1="15" y2="3"/></svg>
              Imprimir PDF
            </button>
          </div>
        </div>

        <div className="overflow-x-auto -mx-6 px-6 md:mx-0 md:px-0">
          <table className="w-full text-left min-w-[700px]">
            <thead>
              <tr className="text-[10px] font-bold text-slate-400 uppercase tracking-widest border-b-2 border-slate-50 bg-slate-50/20">
                <th className="py-4 px-4 text-center w-16 no-print">Pago</th>
