import React, { useState } from 'react';
import { UserCategories } from '../types';

interface CategoryManagerProps {
  categories: UserCategories;
  onAdd: (type: 'income' | 'expense', name: string) => void;
  onDelete: (type: 'income' | 'expense', name: string) => void;
}

const CategoryManager: React.FC<CategoryManagerProps> = ({ categories, onAdd, onDelete }) => {
  const [newCat, setNewCat] = useState('');
  const [activeType, setActiveType] = useState<'expense' | 'income'>('expense');

  const handleAdd = (e: React.FormEvent) => {
    e.preventDefault();
    if (newCat.trim()) {
      onAdd(activeType, newCat.trim());
      setNewCat('');
    }
  };

  return (
    <div className="max-w-2xl space-y-6">
      <div className="bg-white p-8 rounded-xl border border-slate-100 shadow-sm">
        <div className="flex justify-between items-start mb-6">
          <div>
            <h3 className="text-lg font-bold text-slate-900 tracking-tight">Suas Categorias</h3>
            <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">Personalize seus lançamentos</p>
          </div>
          <div className="bg-indigo-50 px-3 py-1.5 rounded-full">
            <span className="text-[9px] font-black text-indigo-600 uppercase tracking-tighter">Sincronizado no Perfil</span>
          </div>
        </div>

        <div className="flex gap-2 p-1.5 bg-slate-50 rounded-lg mb-8 border border-slate-100">
          {(['expense', 'income'] as const).map((t) => (
            <button
              key={t}
              onClick={() => setActiveType(t)}
              className={`flex-1 py-2 rounded text-xs font-bold transition-all ${
                activeType === t ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-400'
              }`}
            >
              {t === 'expense' ? 'DESPESAS' : 'RECEITAS'}
            </button>
          ))}
        </div>

        <form onSubmit={handleAdd} className="flex gap-3 mb-8">
          <input
            type="text"
            value={newCat}
            onChange={(e) => setNewCat(e.target.value)}
            placeholder="Ex: Assinaturas, Aluguel..."
            className="flex-1 px-4 py-3 bg-slate-50 border-transparent border-2 rounded-lg text-sm outline-none focus:bg-white focus:border-indigo-100 transition-all font-medium text-slate-900 placeholder:text-slate-300"
          />
          <button 
            type="submit"
            className="bg-indigo-600 text-white px-6 py-3 rounded-lg text-xs font-bold hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-100"
          >
            Adicionar
          </button>
        </form>

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
          {categories[activeType].map((cat) => (
            <div key={cat} className="flex items-center justify-between px-4 py-3 rounded-lg bg-slate-50/50 hover:bg-slate-50 border border-transparent hover:border-indigo-50 group transition-all">
              <span className="text-xs font-semibold text-slate-700">{cat}</span>
              <button 
                onClick={() => onDelete(activeType, cat)}
                className="opacity-0 group-hover:opacity-100 p-1.5 text-slate-300 hover:text-rose-500 hover:bg-white rounded-lg transition-all"
              >
                <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M18 6 6 18"/><path d="m6 6 12 12"/></svg>
              </button>
            </div>
          ))}
          {categories[activeType].length === 0 && (
            <p className="col-span-2 text-center py-10 text-xs text-slate-300 font-medium italic">Nenhuma categoria personalizada ainda.</p>
          )}
        </div>
      </div>
    </div>
  );
};

export default CategoryManager;

import React, { useState } from 'react';
import { CreditCard, Transaction } from '../types';

interface CardManagerProps {
  cards: CreditCard[];
  transactions: Transaction[];
  onAdd: (card: Omit<CreditCard, 'id'>) => void;
  onDelete: (id: string) => void;
}

const CardManager: React.FC<CardManagerProps> = ({ cards, transactions, onAdd, onDelete }) => {
  const [showAdd, setShowAdd] = useState(false);
  const [name, setName] = useState('');
  const [limit, setLimit] = useState('');
  const [closing, setClosing] = useState(5);
  const [due, setDue] = useState(15);
  const [color, setColor] = useState('#4f46e5');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onAdd({ name, credit_limit: parseFloat(limit), closing_day: closing, due_day: due, color });
    setName(''); setLimit(''); setShowAdd(false);
  };

  const getCardBalance = (cardId: string) => {
    return transactions
      .filter(t => t.card_id === cardId)
      .reduce((sum, t) => sum + Number(t.amount), 0);
  };

  return (
    <div className="max-w-4xl space-y-8 animate-in fade-in duration-500">
      <div className="flex justify-between items-end">
        <div>
          <h2 className="text-2xl font-bold text-slate-900 tracking-tight">Meus Cartões</h2>
          <p className="text-xs text-slate-400 font-medium">Gestão de limites e parcelamentos</p>
        </div>
        <button onClick={() => setShowAdd(true)} className="bg-slate-900 text-white px-5 py-2.5 rounded-lg text-[10px] font-bold uppercase tracking-widest shadow-xl transition-all active:scale-95">
          Adicionar Cartão
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {cards.map(card => {
          const balance = getCardBalance(card.id);
          const percent = Math.min(100, (balance / card.credit_limit) * 100);

          return (
            <div key={card.id} className="bg-white p-6 rounded-xl border border-slate-100 shadow-sm group hover:shadow-md transition-all">
              <div className="flex justify-between items-start mb-6">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded flex items-center justify-center text-white font-bold" style={{ backgroundColor: card.color }}>
                    {card.name.charAt(0)}
                  </div>
                  <div>
                    <h3 className="font-bold text-slate-900">{card.name}</h3>
                    <p className="text-[10px] text-slate-400 font-bold uppercase">Fecha dia {card.closing_day}</p>
                  </div>
                </div>
                <button onClick={() => onDelete(card.id)} className="p-2 text-slate-200 hover:text-rose-500 transition-colors">
                  <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M3 6h18"/><path d="M19 6v14c0 1-1 2-2 2H7c-1 0-2-1-2-2V6"/></svg>
                </button>
              </div>

              <div className="space-y-4">
                <div>
                  <div className="flex justify-between text-[11px] font-bold mb-1.5">
                    <span className="text-slate-400 uppercase tracking-tighter">Uso do Limite</span>
                    <span className="text-slate-900">R$ {balance.toLocaleString('pt-BR')} / R$ {card.credit_limit.toLocaleString('pt-BR')}</span>
                  </div>
                  <div className="h-2 bg-slate-50 rounded-full overflow-hidden">
                    <div className="h-full rounded-full transition-all duration-1000" style={{ width: `${percent}%`, backgroundColor: card.color }}></div>
                  </div>
                </div>

                <div className="flex gap-4 pt-2">
                  <div className="flex-1 bg-slate-50/50 p-3 rounded-lg border border-slate-50">
                    <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-0.5">Vencimento</p>
                    <p className="text-xs font-bold text-slate-700">Dia {card.due_day}</p>
                  </div>
                  <div className="flex-1 bg-slate-50/50 p-3 rounded-lg border border-slate-50">
                    <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-0.5">Disponível</p>
                    <p className="text-xs font-bold text-teal-600">R$ {(card.credit_limit - balance).toLocaleString('pt-BR')}</p>
                  </div>
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {showAdd && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white p-8 rounded-xl shadow-2xl w-full max-w-md animate-in zoom-in-95">
            <h3 className="text-xl font-bold text-slate-900 mb-6">Novo Cartão</h3>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="text-[10px] font-bold text-slate-400 uppercase block mb-1">Nome do Cartão</label>
                <input type="text" value={name} onChange={e => setName(e.target.value)} className="w-full px-4 py-3 bg-slate-50 rounded-lg outline-none border-2 border-transparent focus:border-indigo-100 font-medium text-slate-900" placeholder="Ex: Nubank" required />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-[10px] font-bold text-slate-400 uppercase block mb-1">Limite</label>
                  <input type="number" value={limit} onChange={e => setLimit(e.target.value)} className="w-full px-4 py-3 bg-slate-50 rounded-lg outline-none border-2 border-transparent focus:border-indigo-100 font-bold text-slate-900" placeholder="0,00" required />
                </div>
                <div>
                  <label className="text-[10px] font-bold text-slate-400 uppercase block mb-1">Cor</label>
                  <input type="color" value={color} onChange={e => setColor(e.target.value)} className="w-full h-[52px] p-1 bg-slate-50 rounded-lg outline-none cursor-pointer" />
                </div>
