              <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" x2="12" y1="15" y2="3"/></svg>
              Imprimir PDF
            </button>
          </div>
        </div>

        <div className="overflow-x-auto -mx-6 px-6 md:mx-0 md:px-0">
          <table className="w-full text-left min-w-[700px]">
            <thead>
              <tr className="text-[10px] font-bold text-slate-400 uppercase tracking-widest border-b-2 border-slate-50 bg-slate-50/20">
                <th className="py-4 px-4 text-center w-16 no-print">Pago</th>
                <th className="py-4 px-4">Data</th>
                <th className="py-4 px-4">Descrição</th>
                <th className="py-4 px-4">Categoria</th>
                <th className="py-4 px-4 text-right">Valor</th>
                <th className="py-4 px-4 w-24 no-print"></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredTransactions.map((t) => (
                <tr key={t.id} className={`group hover:bg-slate-50/40 transition-colors ${!t.is_paid ? 'bg-amber-50/15' : ''}`}>
                  <td className="py-5 px-4 text-center no-print">
                    <button 
                      onClick={() => onTogglePaid(t.id, t.is_paid)}
                      className={`w-6 h-6 rounded flex items-center justify-center border-2 mx-auto transition-all ${
                        t.is_paid ? 'bg-teal-500 border-teal-500 text-white' : 'bg-white border-slate-200 text-slate-200 hover:border-teal-400'
                      }`}
                    >
                      <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round"><path d="M20 6 9 17l-5-5"/></svg>
                    </button>
                  </td>
                  <td className="py-5 px-4 text-[11px] font-bold text-slate-500">
                    {new Date(t.date).toLocaleDateString('pt-BR')}
                  </td>
                  <td className="py-5 px-4">
                    <p className={`text-sm font-semibold text-slate-900 ${!t.is_paid ? 'text-slate-400 line-through decoration-slate-300' : ''}`}>
                      {t.description}
                    </p>
                  </td>
                  <td className="py-5 px-4">
                    <span className="px-3 py-1 bg-slate-50 border border-slate-100 rounded text-[9px] font-bold text-indigo-600 uppercase tracking-tighter">
                      {t.category}
                    </span>
                  </td>
                  <td className={`py-5 px-4 text-right font-bold text-sm ${t.type === 'income' ? 'text-teal-600' : 'text-rose-500'} ${!t.is_paid ? 'opacity-50' : ''}`}>
                    {t.type === 'income' ? '+' : '-'}{formatCurrency(t.amount)}
                  </td>
                  <td className="py-5 px-4 text-right no-print">
                    <div className="flex items-center justify-end gap-1 opacity-0 group-hover:opacity-100 transition-all">
                      <button onClick={() => onEdit(t)} className="p-2 text-slate-300 hover:text-indigo-600 transition-colors">
                        <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M12 20h9"/><path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z"/></svg>
                      </button>
                      <button 
                        onClick={() => onDelete(t.id)}
                        className="p-2 text-slate-300 hover:text-rose-500 transition-colors"
                      >
                        <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M3 6h18"/><path d="M19 6v14c0 1-1 2-2 2H7c-1 0-2-1-2-2V6"/></svg>
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
              {filteredTransactions.length === 0 && (
                <tr>
                  <td colSpan={6} className="py-24 text-center">
                    <div className="w-16 h-16 bg-slate-50 rounded-full flex items-center justify-center mx-auto mb-4">
                      <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="#cbd5e1" strokeWidth="2"><rect width="18" height="18" x="3" y="3" rx="2"/><path d="M3 9h18"/><path d="M9 21V9"/></svg>
                    </div>
                    <p className="text-xs font-bold text-slate-300 uppercase tracking-[0.2em] italic">Nenhum registro encontrado para estes filtros</p>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default Reports;

import React, { useState, useEffect, useMemo } from 'react';
import { supabase } from './services/supabaseClient';
import { useFinanceData } from './hooks/useFinanceData';
import SummaryCards from './components/SummaryCards';
import TransactionForm from './components/TransactionForm';
import Charts from './components/Charts';
import AIInsights from './components/AIInsights';
import Sidebar, { ViewType } from './components/Sidebar';
import Reports from './components/Reports';
import CategoryManager from './components/CategoryManager';
import CardManager from './components/CardManager';
import AuthScreen from './components/AuthScreen';
import { TransactionType, User, Summary, Transaction } from './types';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [sessionLoading, setSessionLoading] = useState(true);

  const { 
    transactions, 
    cards,
    categories, 
    addTransaction,
    updateTransaction,
    deleteTransaction, 
    togglePaid,
    addCard,
    deleteCard,
    addCategory, 
    deleteCategory, 
    loading: dataLoading
  } = useFinanceData(currentUser?.id || null);

  const [currentView, setCurrentView] = useState<ViewType>('dashboard');
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);

  // Estados de Filtro Globais/Iniciais
  const currentYYYYMM = new Date().toISOString().slice(0, 7); 
  const [selectedMonth, setSelectedMonth] = useState(currentYYYYMM);
  const [selectedCategory, setSelectedCategory] = useState('all');

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session?.user) fetchProfile(session.user.id);
      else setSessionLoading(false);
    });
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session?.user) fetchProfile(session.user.id);
      else { setCurrentUser(null); setSessionLoading(false); }
    });
    return () => subscription.unsubscribe();
  }, []);

  const fetchProfile = async (uid: string) => {
    const { data: profile } = await supabase.from('profiles').select('name, avatar_color').eq('id', uid).single();
    if (profile) setCurrentUser({ id: uid, name: profile.name, avatarColor: profile.avatar_color });
    setSessionLoading(false);
  };

  const handleLogout = async () => { await supabase.auth.signOut(); setCurrentUser(null); setCurrentView('dashboard'); };
  const formatCurrency = (val: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const handleEdit = (t: Transaction) => {
    setEditingTransaction(t);
    setIsFormOpen(true);
  };

  const closeForm = () => {
    setIsFormOpen(false);
    setEditingTransaction(null);
  };

  // Lógica de Filtragem e Ordenação para a Dashboard
  const dashboardData = useMemo(() => {
    const filtered = transactions
      .filter(t => {
        const tMonth = t.date.slice(0, 7);
        const matchesMonth = tMonth === selectedMonth;
        const matchesCategory = selectedCategory === 'all' || t.category === selectedCategory;
        return matchesMonth && matchesCategory;
      })
      .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    const summary: Summary = filtered.reduce((acc, t) => {
      const amt = Number(t.amount);
      if (t.type === 'income') {
        acc.income += amt;
        acc.balance += amt;
      } else {
        acc.expenses += amt;
        acc.balance -= amt;
      }
      return acc;
    }, { balance: 0, income: 0, expenses: 0 });

    return { filteredTransactions: filtered, summary };
  }, [transactions, selectedMonth, selectedCategory]);

  if (sessionLoading) return (
    <div className="min-h-screen bg-slate-50 flex items-center justify-center">
      <div className="w-8 h-8 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
    </div>
  );

  if (!currentUser) return <AuthScreen onSelectUser={setCurrentUser} />;

  const renderTransactionManagement = (type: TransactionType) => {
    const filtered = transactions
      .filter(t => t.type === type)
      .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    const accentColor = type === 'expense' ? 'bg-rose-500 hover:bg-rose-600' : 'bg-teal-600 hover:bg-teal-700';

    return (
      <div className="space-y-6 max-w-5xl mx-auto">
        <div className="flex flex-col items-center justify-center gap-4 mb-8">
          <div className="text-center">
            <h2 className="text-2xl md:text-3xl font-bold text-slate-900 tracking-tight">{type === 'expense' ? 'Despesas' : 'Receitas'}</h2>
            <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">Histórico em ordem cronológica</p>
          </div>
          <button onClick={() => setIsFormOpen(true)} className={`flex items-center gap-2 ${accentColor} text-white px-6 py-2.5 rounded-lg text-[11px] font-bold uppercase tracking-widest shadow-xl transition-all active:scale-95`}>
            Novo
          </button>
        </div>

        <div className="bg-white rounded-xl border border-slate-100 shadow-sm overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-left min-w-[600px]">
              <thead>
                <tr className="text-[10px] font-bold text-slate-400 uppercase tracking-widest border-b border-slate-50 bg-slate-50/30">
                  <th className="py-5 px-6 w-12 text-center">Pago</th>
                  <th className="py-5 px-6">Data</th>
                  <th className="py-5 px-6">Descrição</th>
                  <th className="py-5 px-6 text-center">Divisão</th>
                  <th className="py-5 px-6 text-right">Valor</th>
                  <th className="py-5 px-6 w-24 text-center">Ações</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {filtered.map((t) => (
                  <tr key={t.id} className={`hover:bg-slate-50/50 transition-colors ${!t.is_paid ? 'bg-amber-50/10' : ''}`}>
                    <td className="py-5 px-6 text-center">
                      <button 
                        onClick={() => togglePaid(t.id, t.is_paid)}
                        className={`w-6 h-6 rounded flex items-center justify-center border-2 mx-auto transition-all ${
                          t.is_paid ? 'bg-teal-500 border-teal-500 text-white' : 'bg-white border-slate-200 text-slate-200 hover:border-teal-400'
                        }`}
                      >
                        <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round"><path d="M20 6 9 17l-5-5"/></svg>
                      </button>
                    </td>
                    <td className="py-5 px-6 text-[11px] text-slate-400 font-bold">{new Date(t.date).toLocaleDateString('pt-BR')}</td>
                    <td className="py-5 px-6">
                      <p className={`text-sm font-semibold ${t.is_paid ? 'text-slate-900' : 'text-slate-400 line-through decoration-slate-300'}`}>{t.description}</p>
                      <div className="flex items-center gap-2 mt-0.5">
                        <span className="text-[9px] text-indigo-500 font-bold uppercase tracking-tight">{t.category}</span>
                        {t.card_id && (
                          <span className="text-[9px] bg-indigo-50 text-indigo-600 px-1.5 py-0.5 rounded font-bold uppercase">
                            {cards.find(c => c.id === t.card_id)?.name || 'Cartão'}
                          </span>
                        )}
                        {!t.is_paid && <span className="text-[8px] bg-amber-100 text-amber-700 px-1.5 py-0.5 rounded font-black uppercase">Pendente</span>}
                      </div>
                    </td>
                    <td className="py-5 px-6 text-center">
                      {t.is_split && t.split_details ? (
                        <div className="inline-block space-y-0.5 text-left">
                          <div className="flex justify-between gap-4 text-[9px] font-bold">
                            <span className="text-slate-400 uppercase tracking-tighter">Você:</span>
                            <span className="text-slate-700">{formatCurrency(t.split_details.userPart)}</span>
                          </div>
                          <div className="flex justify-between gap-4 text-[9px] font-bold">
                            <span className="text-slate-400 uppercase tracking-tighter">{t.split_details.partnerName}:</span>
                            <span className="text-indigo-600">{formatCurrency(t.split_details.partnerPart)}</span>
                          </div>
                        </div>
                      ) : (
                        <span className="text-[9px] text-slate-300 font-bold uppercase">Individual</span>
                      )}
                    </td>
                    <td className={`py-5 px-6 text-right text-sm font-bold ${t.type === 'income' ? 'text-teal-600' : 'text-rose-500'} ${!t.is_paid ? 'opacity-50' : ''}`}>
                      {formatCurrency(t.amount)}
                    </td>
                    <td className="py-5 px-6">
                      <div className="flex items-center justify-center gap-1">
                        <button onClick={() => handleEdit(t)} className="p-2 text-slate-400 hover:text-indigo-600 transition-colors">
                          <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M12 20h9"/><path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z"/></svg>
                        </button>
                        <button onClick={() => deleteTransaction(t.id)} className="p-2 text-slate-400 hover:text-rose-500 transition-colors">
                          <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M3 6h18"/><path d="M19 6v14c0 1-1 2-2 2H7c-1 0-2-1-2-2V6"/></svg>
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    );
  };

  const renderContent = () => {
    switch (currentView) {
      case 'dashboard':
        return (
          <div className="space-y-6 md:space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-20 md:pb-0">
            <div className="flex flex-col md:flex-row gap-4 items-center justify-between bg-white p-4 rounded-xl border border-slate-100 shadow-sm">
              <div className="flex items-center gap-3 w-full md:w-auto">
                <div className="flex flex-col">
                  <label className="text-[9px] font-bold text-slate-400 uppercase ml-1 mb-1">Período</label>
                  <input 
                    type="month" 
                    value={selectedMonth} 
                    onChange={(e) => setSelectedMonth(e.target.value)}
                    className="bg-slate-50 border-none rounded-lg px-4 py-2 text-xs font-bold text-indigo-600 outline-none focus:ring-2 focus:ring-indigo-100"
                  />
                </div>
                <div className="flex flex-col flex-1 md:w-48">
                  <label className="text-[9px] font-bold text-slate-400 uppercase ml-1 mb-1">Categoria</label>
                  <select 
                    value={selectedCategory} 
                    onChange={(e) => setSelectedCategory(e.target.value)}
                    className="bg-slate-50 border-none rounded-lg px-4 py-2 text-xs font-bold text-slate-700 outline-none focus:ring-2 focus:ring-indigo-100"
                  >
                    <option value="all">Todas as Categorias</option>
                    {[...categories.expense, ...categories.income].map(cat => (
                      <option key={cat} value={cat}>{cat}</option>
                    ))}
                  </select>
                </div>
              </div>

              <div className="hidden md:flex items-center gap-2">
                <button 
                  onClick={() => { setSelectedMonth(currentYYYYMM); setSelectedCategory('all'); }}
                  className="text-[10px] font-bold text-slate-400 uppercase hover:text-indigo-600 transition-colors px-3 py-2"
                >
                  Mês Atual
                </button>
              </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 md:gap-8">
              <div className="lg:col-span-8 space-y-6 md:space-y-8">
                <SummaryCards summary={dashboardData.summary} />
                <div className="grid grid-cols-1 gap-6 md:gap-8">
                   <AIInsights transactions={dashboardData.filteredTransactions} />
                   <Charts transactions={dashboardData.filteredTransactions} />
                </div>
              </div>
              <div className="lg:col-span-4">
                <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
                  <div className="flex justify-between items-center mb-6">
                     <h2 className="text-sm font-bold text-slate-900 tracking-tight">
                       Recentes do Mês
                     </h2>
                     <button onClick={() => setCurrentView('reports')} className="text-[10px] text-indigo-500 font-bold uppercase tracking-widest hover:text-indigo-700 transition-colors">Ver tudo</button>
                  </div>
                  <div className="space-y-4">
                    {[...dashboardData.filteredTransactions].reverse().slice(0, 10).map((t) => (
                      <div key={t.id} className="flex items-center gap-3 py-2 border-b border-slate-50 last:border-0 group">
                        <button 
                          onClick={() => togglePaid(t.id, t.is_paid)}
                          className={`w-5 h-5 rounded flex items-center justify-center border-2 shrink-0 transition-all ${
                            t.is_paid ? 'bg-teal-500 border-teal-500 text-white' : 'bg-white border-slate-200 text-slate-200 hover:border-teal-400'
                          }`}
                        >
                          <svg xmlns="http://www.w3.org/2000/svg" width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round"><path d="M20 6 9 17l-5-5"/></svg>
                        </button>
                        <div className="overflow-hidden flex-1">
                          <h4 className={`font-semibold text-xs text-slate-900 truncate ${!t.is_paid ? 'text-slate-400 line-through' : ''}`}>{t.description}</h4>
                          <div className="flex gap-1.5 items-center mt-0.5">
                            <span className="text-[8px] text-slate-400 font-bold uppercase">{t.category}</span>
                            {!t.is_paid && <span className="text-[7px] text-amber-600 font-black uppercase">Pendente</span>}
                          </div>
                        </div>
                        <div className="flex items-center gap-1 shrink-0">
                           <span className={`text-xs font-bold ${t.type === 'income' ? 'text-teal-600' : 'text-rose-500'} ${!t.is_paid ? 'opacity-50' : ''}`}>{formatCurrency(t.amount)}</span>
                           <button onClick={() => handleEdit(t)} className="p-1.5 text-slate-400 hover:text-indigo-600 transition-all">
                              <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><path d="M12 20h9"/><path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z"/></svg>
                           </button>
                        </div>
                      </div>
                    ))}
                    {dashboardData.filteredTransactions.length === 0 && (
                      <div className="text-center py-12">
                        <div className="w-12 h-12 bg-slate-50 rounded-full flex items-center justify-center mx-auto mb-3">
                          <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#cbd5e1" strokeWidth="2"><rect width="18" height="18" x="3" y="3" rx="2"/><path d="M3 9h18"/><path d="M9 21V9"/></svg>
                        </div>
                        <p className="text-[10px] text-slate-300 font-bold uppercase italic">Sem registros neste período</p>
                      </div>
                    )}
                  </div>
                </div>
              </div>
            </div>
          </div>
        );
      case 'cards': return <div className="pb-20 md:pb-0"><CardManager cards={cards} transactions={transactions} onAdd={addCard} onDelete={deleteCard} /></div>;
      case 'add-expense': return <div className="pb-20 md:pb-0">{renderTransactionManagement('expense')}</div>;
      case 'add-income': return <div className="pb-20 md:pb-0">{renderTransactionManagement('income')}</div>;
      case 'categories': return <div className="pb-20 md:pb-0"><CategoryManager categories={categories} onAdd={addCategory} onDelete={deleteCategory} /></div>;
      case 'reports': return <div className="pb-20 md:pb-0"><Reports transactions={transactions} onDelete={deleteTransaction} onTogglePaid={togglePaid} onEdit={handleEdit} categories={categories} /></div>;
      default: return null;
    }
  };

  const viewTitles: Record<string, string> = {
    'dashboard': 'Visão Geral',
    'cards': 'Meus Cartões',
    'add-expense': 'Despesas',
    'add-income': 'Receitas',
    'categories': 'Categorias',
    'reports': 'Extrato Detalhado'
  };

  return (
    <div className="flex min-h-screen bg-slate-50/50">
