                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default Reports;

import React, { useState } from 'react';
import { CreditCard, Transaction } from '../types';

interface CardManagerProps {
  cards: CreditCard[];
  transactions: Transaction[];
  onAdd: (card: Omit<CreditCard, 'id'>) => void;
  onDelete: (id: string) => void;
}

const CardManager: React.FC<CardManagerProps> = ({ cards, transactions, onAdd, onDelete }) => {
  const [showAdd, setShowAdd] = useState(false);
  const [name, setName] = useState('');
  const [limit, setLimit] = useState('');
  const [closing, setClosing] = useState(5);
  const [due, setDue] = useState(15);
  const [color, setColor] = useState('#4f46e5');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onAdd({ name, credit_limit: parseFloat(limit), closing_day: closing, due_day: due, color });
    setName(''); setLimit(''); setShowAdd(false);
  };

  const getCardBalance = (cardId: string) => {
    return transactions
      .filter(t => t.card_id === cardId)
      .reduce((sum, t) => sum + Number(t.amount), 0);
  };

  return (
    <div className="max-w-4xl space-y-6 md:space-y-8 animate-in fade-in duration-500">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-end gap-4">
        <div>
          <h2 className="text-xl md:text-2xl font-bold text-slate-900 tracking-tight">Meus Cartões</h2>
          <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-0.5">Gestão de limites e parcelamentos</p>
        </div>
        <button onClick={() => setShowAdd(true)} className="w-full sm:w-auto bg-slate-900 text-white px-6 py-3 rounded-xl text-[10px] font-bold uppercase tracking-widest shadow-xl transition-all active:scale-95">
          Adicionar Cartão
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6">
        {cards.map(card => {
          const balance = getCardBalance(card.id);
          const percent = Math.min(100, (balance / card.credit_limit) * 100);

          return (
            <div key={card.id} className="bg-white p-6 rounded-xl border border-slate-100 shadow-sm transition-all">
              <div className="flex justify-between items-start mb-6">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-lg flex items-center justify-center text-white font-bold shadow-lg" style={{ backgroundColor: card.color }}>
                    {card.name.charAt(0)}
                  </div>
                  <div>
                    <h3 className="font-bold text-slate-900 text-sm">{card.name}</h3>
                    <p className="text-[9px] text-slate-400 font-bold uppercase">Fecha dia {card.closing_day}</p>
                  </div>
                </div>
                <button onClick={() => onDelete(card.id)} className="p-2 text-slate-300 hover:text-rose-500 transition-colors">
                  <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M3 6h18"/><path d="M19 6v14c0 1-1 2-2 2H7c-1 0-2-1-2-2V6"/></svg>
                </button>
              </div>

              <div className="space-y-4">
                <div>
                  <div className="flex justify-between text-[10px] font-bold mb-1.5">
                    <span className="text-slate-400 uppercase tracking-tighter">Uso do Limite</span>
                    <span className="text-slate-900">R$ {balance.toLocaleString('pt-BR')} / R$ {card.credit_limit.toLocaleString('pt-BR')}</span>
                  </div>
                  <div className="h-2 bg-slate-50 rounded-full overflow-hidden">
                    <div className="h-full rounded-full transition-all duration-1000" style={{ width: `${percent}%`, backgroundColor: card.color }}></div>
                  </div>
                </div>

                <div className="flex gap-4 pt-2">
                  <div className="flex-1 bg-slate-50/50 p-3 rounded-lg border border-slate-50">
                    <p className="text-[8px] font-bold text-slate-400 uppercase tracking-widest mb-0.5">Vencimento</p>
                    <p className="text-xs font-bold text-slate-700">Dia {card.due_day}</p>
                  </div>
                  <div className="flex-1 bg-slate-50/50 p-3 rounded-lg border border-slate-50">
                    <p className="text-[8px] font-bold text-slate-400 uppercase tracking-widest mb-0.5">Disponível</p>
                    <p className="text-xs font-bold text-teal-600">R$ {(card.credit_limit - balance).toLocaleString('pt-BR')}</p>
                  </div>
                </div>
              </div>
            </div>
          );
        })}
        {cards.length === 0 && (
          <div className="md:col-span-2 py-20 text-center bg-white rounded-xl border-2 border-dashed border-slate-100">
            <p className="text-[10px] text-slate-300 font-bold uppercase tracking-widest italic">Nenhum cartão cadastrado</p>
          </div>
        )}
      </div>

      {showAdd && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[70] flex items-center justify-center p-4">
          <div className="bg-white p-6 md:p-8 rounded-2xl shadow-2xl w-full max-w-md animate-in zoom-in-95">
            <h3 className="text-lg md:text-xl font-bold text-slate-900 mb-6">Novo Cartão</h3>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="text-[10px] font-bold text-slate-400 uppercase block mb-1">Nome do Cartão</label>
                <input type="text" value={name} onChange={e => setName(e.target.value)} className="w-full px-4 py-3 bg-slate-50 rounded-xl outline-none border-2 border-transparent focus:border-indigo-100 font-medium text-slate-900" placeholder="Ex: Nubank" required />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-[10px] font-bold text-slate-400 uppercase block mb-1">Limite</label>
                  <input type="number" value={limit} onChange={e => setLimit(e.target.value)} className="w-full px-4 py-3 bg-slate-50 rounded-xl outline-none border-2 border-transparent focus:border-indigo-100 font-bold text-slate-900" placeholder="0,00" required />
                </div>
                <div className="relative">
                  <label className="text-[10px] font-bold text-slate-400 uppercase block mb-1">Cor</label>
                  <input type="color" value={color} onChange={e => setColor(e.target.value)} className="w-full h-[52px] p-1 bg-slate-50 rounded-xl outline-none cursor-pointer" />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-[10px] font-bold text-slate-400 uppercase block mb-1">Dia Fechamento</label>
                  <input type="number" min="1" max="31" value={closing} onChange={e => setClosing(parseInt(e.target.value))} className="w-full px-4 py-3 bg-slate-50 rounded-xl outline-none border-2 border-transparent focus:border-indigo-100 font-bold text-slate-900" />
                </div>
                <div>
                  <label className="text-[10px] font-bold text-slate-400 uppercase block mb-1">Dia Vencimento</label>
                  <input type="number" min="1" max="31" value={due} onChange={e => setDue(parseInt(e.target.value))} className="w-full px-4 py-3 bg-slate-50 rounded-xl outline-none border-2 border-transparent focus:border-indigo-100 font-bold text-slate-900" />
                </div>
              </div>
              <div className="flex gap-3 pt-6">
                <button type="button" onClick={() => setShowAdd(false)} className="flex-1 py-4 text-slate-500 font-bold text-xs uppercase tracking-widest hover:text-slate-700 transition-colors">Cancelar</button>
                <button type="submit" className="flex-1 bg-indigo-600 text-white rounded-xl font-bold text-xs uppercase tracking-widest shadow-lg shadow-indigo-100 hover:bg-indigo-700 transition-all">Salvar</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default CardManager;

import React, { useState, useMemo } from 'react';
import { Transaction, UserCategories, Summary } from '../types';

interface ReportsProps {
  transactions: Transaction[];
  categories: UserCategories;
  onDelete: (id: string) => void;
  onTogglePaid: (id: string, currentStatus: boolean) => void;
  onEdit: (t: Transaction) => void;
}

const Reports: React.FC<ReportsProps> = ({ transactions, categories, onDelete, onTogglePaid, onEdit }) => {
  const currentYYYYMM = new Date().toISOString().slice(0, 7);
  const [filter, setFilter] = useState<'all' | 'income' | 'expense'>('all');
  const [selectedMonth, setSelectedMonth] = useState(currentYYYYMM);
  const [selectedCategory, setSelectedCategory] = useState('all');
  const [statusFilter, setStatusFilter] = useState<'all' | 'paid' | 'pending'>('all');

  const { filteredTransactions, summary } = useMemo(() => {
    const filtered = transactions
      .filter(t => {
        if (filter !== 'all' && t.type !== filter) return false;
        const tMonth = t.date.slice(0, 7);
        if (selectedMonth && tMonth !== selectedMonth) return false;
        if (selectedCategory !== 'all' && t.category !== selectedCategory) return false;
        if (statusFilter === 'paid' && !t.is_paid) return false;
        if (statusFilter === 'pending' && t.is_paid) return false;
        return true;
      })
      .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    const stats = filtered.reduce((acc, t) => {
      const amt = Number(t.amount);
      if (t.type === 'income') {
        acc.income += amt;
        acc.balance += amt;
      } else {
        acc.expenses += amt;
        acc.balance -= amt;
      }
      return acc;
    }, { balance: 0, income: 0, expenses: 0 } as Summary);

    return { filteredTransactions: filtered, summary: stats };
  }, [transactions, filter, selectedMonth, selectedCategory, statusFilter]);

  const formatCurrency = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const resetFilters = () => {
    setFilter('all');
    setSelectedMonth(currentYYYYMM);
    setSelectedCategory('all');
    setStatusFilter('all');
  };

  const exportToExcel = () => {
    const headers = ["Data", "Descrição", "Categoria", "Tipo", "Valor", "Status"];
    const rows = filteredTransactions.map(t => [
      new Date(t.date).toLocaleDateString('pt-BR'),
      t.description.replace(/;/g, ','),
      t.category,
      t.type === 'income' ? 'Entrada' : 'Saída',
      t.amount.toString().replace('.', ','),
      t.is_paid ? 'Pago' : 'Pendente'
    ]);

    const csvContent = "data:text/csv;charset=utf-8,\uFEFF" 
      + headers.join(";") + "\n" 
      + rows.map(e => e.join(";")).join("\n");

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `extrato_${selectedMonth}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-4 md:space-y-6 pb-20 md:pb-0">
      {/* Cabeçalho de Resumo Otimizado para Impressão */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-3 md:gap-4 print:mb-8 print:border-b print:pb-6">
        <div className="bg-white p-5 md:p-7 rounded-xl shadow-sm border border-slate-50 flex flex-col justify-center print:border-none print:p-0">
          <p className="text-slate-400 text-[9px] font-bold uppercase tracking-[0.1em] mb-1">PATRIMÔNIO LÍQUIDO</p>
          <h3 className="text-xl md:text-3xl font-bold text-slate-900">{formatCurrency(summary.balance)}</h3>
        </div>
        <div className="bg-white p-5 md:p-7 rounded-xl shadow-sm border border-slate-50 flex flex-col justify-center print:border-none print:p-0">
          <p className="text-slate-400 text-[9px] font-bold uppercase tracking-[0.1em] mb-1">ENTRADAS</p>
          <h3 className="text-xl md:text-3xl font-bold text-teal-600">{formatCurrency(summary.income)}</h3>
        </div>
        <div className="bg-white p-5 md:p-7 rounded-xl shadow-sm border border-slate-50 flex flex-col justify-center print:border-none print:p-0">
          <p className="text-slate-400 text-[9px] font-bold uppercase tracking-[0.1em] mb-1">SAÍDAS</p>
          <h3 className="text-xl md:text-3xl font-bold text-rose-500">{formatCurrency(summary.expenses)}</h3>
        </div>
      </div>

      <div className="bg-white p-4 md:p-6 rounded-xl shadow-sm border border-slate-100 no-print">
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 items-end">
          <div>
            <label className="text-[9px] font-bold text-slate-400 uppercase tracking-widest block mb-1.5">Mês de Referência</label>
            <input 
              type="month" 
              value={selectedMonth} 
              onChange={(e) => setSelectedMonth(e.target.value)}
              className="w-full bg-slate-50 border-none rounded-lg px-4 py-3 text-xs font-bold text-indigo-600 outline-none"
            />
          </div>
          <div>
            <label className="text-[9px] font-bold text-slate-400 uppercase tracking-widest block mb-1.5">Categoria</label>
            <select 
              value={selectedCategory} 
              onChange={(e) => setSelectedCategory(e.target.value)}
              className="w-full bg-slate-50 border-none rounded-lg px-4 py-3 text-xs font-bold text-slate-700 outline-none"
            >
              <option value="all">Todas</option>
              {[...categories.expense, ...categories.income].sort().map(cat => (
                <option key={cat} value={cat}>{cat}</option>
              ))}
            </select>
          </div>
          <div>
            <label className="text-[9px] font-bold text-slate-400 uppercase tracking-widest block mb-1.5">Status Pago</label>
            <select 
              value={statusFilter} 
              onChange={(e) => setStatusFilter(e.target.value as any)}
              className="w-full bg-slate-50 border-none rounded-lg px-4 py-3 text-xs font-bold text-slate-700 outline-none"
            >
              <option value="all">Todos</option>
              <option value="paid">Já Pagos</option>
              <option value="pending">Pendentes</option>
            </select>
          </div>
          <button 
            onClick={resetFilters}
            className="w-full py-3 text-[9px] font-bold text-slate-400 uppercase hover:text-indigo-600 transition-colors text-center"
          >
            Limpar Filtros
          </button>
        </div>
      </div>

      <div className="bg-white p-4 md:p-10 rounded-xl shadow-sm border border-slate-100 overflow-hidden print:p-0 print:border-none print:shadow-none">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 mb-8 print:mb-4">
          <div>
            <h2 className="text-lg md:text-2xl font-bold text-slate-900 tracking-tight">Registros do Período</h2>
            <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest mt-0.5">
              Listando {filteredTransactions.length} registros
            </p>
          </div>

          <div className="flex gap-2 no-print w-full md:w-auto">
            <button 
              onClick={exportToExcel}
              className="flex-1 md:flex-none flex items-center justify-center gap-2 bg-emerald-50 text-emerald-700 px-4 py-3 rounded-lg text-[9px] font-bold uppercase tracking-widest hover:bg-emerald-100 transition-all border border-emerald-100"
            >
              <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M14.5 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V7.5L14.5 2z"/><polyline points="14 2 14 8 20 8"/></svg>
              Exportar
            </button>
            <button 
              onClick={() => window.print()}
              className="flex-1 md:flex-none flex items-center justify-center gap-2 bg-slate-900 text-white px-4 py-3 rounded-lg text-[9px] font-bold uppercase tracking-widest hover:bg-slate-800 transition-all shadow-lg active:scale-95"
            >
              <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><polyline points="7 10 12 15 17 10"/><line x1="12" x2="12" y1="15" y2="3"/></svg>
              PDF
            </button>
          </div>
        </div>

        <div className="overflow-x-auto scrollbar-hide -mx-4 px-4 md:mx-0 md:px-0 print:overflow-visible print:mx-0 print:px-0">
          <table className="w-full text-left min-w-[700px] print:min-w-0">
            <thead>
              <tr className="text-[10px] font-bold text-slate-400 uppercase tracking-widest border-b-2 border-slate-50 bg-slate-50/20">
