      <div className="grid grid-cols-1 gap-6">
        {cards.map(card => {
          const stats = getCardStats(card.id);
          const percent = Math.min(100, (stats.total / card.credit_limit) * 100);
          const isExpanded = expandedCardId === card.id;
          const cardTrans = getCardTransactions(card.id);

          return (
            <div key={card.id} className="space-y-4">
              {/* Card Header */}
              <div 
                onClick={() => setExpandedCardId(isExpanded ? null : card.id)}
                className={`bg-white p-6 rounded-xl border transition-all cursor-pointer hover:shadow-md ${isExpanded ? 'border-indigo-200 ring-2 ring-indigo-50 shadow-sm' : 'border-slate-100 shadow-sm'}`}
              >
                <div className="flex justify-between items-start mb-6">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-lg flex items-center justify-center text-white font-bold shadow-lg" style={{ backgroundColor: card.color }}>
                      {card.name.charAt(0)}
                    </div>
                    <div>
                      <h3 className="font-bold text-slate-900 text-sm">{card.name}</h3>
                      <p className="text-[9px] text-slate-400 font-bold uppercase">Fecha dia {card.closing_day} • Vencimento dia {card.due_day}</p>
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    <button 
                      onClick={(e) => { e.stopPropagation(); onDelete(card.id); }} 
                      className="p-2 text-slate-300 hover:text-rose-500 transition-colors"
                    >
                      <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M3 6h18"/><path d="M19 6v14c0 1-1 2-2 2H7c-1 0-2-1-2-2V6"/></svg>
                    </button>
                    <div className={`transition-transform duration-300 text-slate-300 ${isExpanded ? 'rotate-180' : ''}`}>
                      <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="m6 9 6 6 6-6"/></svg>
                    </div>
                  </div>
                </div>

                <div className="space-y-4">
                  <div>
                    <div className="flex justify-between text-[10px] font-bold mb-1.5">
                      <span className="text-slate-400 uppercase tracking-tighter">Uso do Limite</span>
                      <span className="text-slate-900">R$ {stats.total.toLocaleString('pt-BR')} / R$ {card.credit_limit.toLocaleString('pt-BR')}</span>
                    </div>
                    <div className="h-2 bg-slate-50 rounded-full overflow-hidden">
                      <div className="h-full rounded-full transition-all duration-1000" style={{ width: `${percent}%`, backgroundColor: card.color }}></div>
                    </div>
                  </div>

                  <div className="flex gap-4 pt-2">
                    <div className="flex-1 bg-slate-50/50 p-3 rounded-lg border border-slate-50">
                      <p className="text-[8px] font-bold text-slate-400 uppercase tracking-widest mb-0.5">Total Fatura</p>
                      <p className="text-xs font-bold text-slate-700">{formatCurrency(stats.total)}</p>
                    </div>
                    <div className="flex-1 bg-slate-50/50 p-3 rounded-lg border border-slate-50">
                      <p className="text-[8px] font-bold text-slate-400 uppercase tracking-widest mb-0.5">Disponível</p>
                      <p className="text-xs font-bold text-teal-600">{formatCurrency(card.credit_limit - stats.total)}</p>
                    </div>
                  </div>
                </div>
              </div>

              {/* Card Transactions Details */}
              {isExpanded && (
                <div className="bg-white border border-slate-100 rounded-xl shadow-inner p-4 md:p-6 animate-in slide-in-from-top-4 duration-300 space-y-6">
                  <div className="flex justify-between items-center border-b border-slate-50 pb-4">
                    <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Lançamentos Vinculados</h4>
                    <div className="flex gap-6">
                      <div className="text-right">
                        <p className="text-[8px] font-bold text-slate-400 uppercase mb-0.5">Sua Parte</p>
                        <p className="text-xs font-bold text-slate-900">{formatCurrency(stats.userPart)}</p>
                      </div>
                      <div className="text-right">
                        <p className="text-[8px] font-bold text-indigo-400 uppercase mb-0.5">Parte {stats.partnerName}</p>
                        <p className="text-xs font-bold text-indigo-600">{formatCurrency(stats.partnerPart)}</p>
                      </div>
                    </div>
                  </div>

                  <div className="space-y-1">
                    {cardTrans.map((t) => (
                      <div key={t.id} className="flex items-center justify-between py-3 px-2 rounded-lg hover:bg-slate-50/50 transition-colors border-b border-slate-50 last:border-0">
                        <div className="flex items-center gap-3">
                          <div className="bg-slate-50 p-2 rounded text-[9px] font-bold text-slate-400 uppercase whitespace-nowrap">
                            {new Date(t.date).toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit' })}
                          </div>
                          <div>
                            <p className="text-xs font-bold text-slate-800">{t.description}</p>
                            <p className="text-[9px] font-bold text-slate-400 uppercase">{t.category}</p>
                          </div>
                        </div>
                        <div className="text-right">
                          <p className="text-xs font-bold text-slate-900">{formatCurrency(t.amount)}</p>
                          {t.is_split && t.split_details && (
                            <p className="text-[8px] font-bold text-indigo-500 uppercase">Dividido: {formatCurrency(t.split_details.partnerPart)} p/ {t.split_details.partnerName}</p>
                          )}
                        </div>
                      </div>
                    ))}
                    {cardTrans.length === 0 && (
                      <div className="py-8 text-center">
                        <p className="text-[10px] text-slate-300 font-bold uppercase tracking-widest italic">Nenhum lançamento neste cartão</p>
                      </div>
                    )}
                  </div>
                </div>
              )}
            </div>
          );
        })}
        {cards.length === 0 && (
          <div className="py-20 text-center bg-white rounded-xl border-2 border-dashed border-slate-100">
            <p className="text-[10px] text-slate-300 font-bold uppercase tracking-widest italic">Nenhum cartão cadastrado</p>
          </div>
        )}
      </div>

      {showAdd && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[70] flex items-center justify-center p-4">
          <div className="bg-white p-6 md:p-8 rounded-2xl shadow-2xl w-full max-w-md animate-in zoom-in-95">
            <h3 className="text-lg md:text-xl font-bold text-slate-900 mb-6">Novo Cartão</h3>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="text-[10px] font-bold text-slate-400 uppercase block mb-1">Nome do Cartão</label>
                <input type="text" value={name} onChange={e => setName(e.target.value)} className="w-full px-4 py-3 bg-slate-50 rounded-xl outline-none border-2 border-transparent focus:border-indigo-100 font-medium text-slate-900" placeholder="Ex: Nubank" required />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-[10px] font-bold text-slate-400 uppercase block mb-1">Limite</label>
                  <input type="number" value={limit} onChange={e => setLimit(e.target.value)} className="w-full px-4 py-3 bg-slate-50 rounded-xl outline-none border-2 border-transparent focus:border-indigo-100 font-bold text-slate-900" placeholder="0,00" required />
                </div>
                <div className="relative">
                  <label className="text-[10px] font-bold text-slate-400 uppercase block mb-1">Cor</label>
                  <input type="color" value={color} onChange={e => setColor(e.target.value)} className="w-full h-[52px] p-1 bg-slate-50 rounded-xl outline-none cursor-pointer" />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-[10px] font-bold text-slate-400 uppercase block mb-1">Dia Fechamento</label>
                  <input type="number" min="1" max="31" value={closing} onChange={e => setClosing(parseInt(e.target.value))} className="w-full px-4 py-3 bg-slate-50 rounded-xl outline-none border-2 border-transparent focus:border-indigo-100 font-bold text-slate-900" />
                </div>
                <div>
                  <label className="text-[10px] font-bold text-slate-400 uppercase block mb-1">Dia Vencimento</label>
                  <input type="number" min="1" max="31" value={due} onChange={e => setDue(parseInt(e.target.value))} className="w-full px-4 py-3 bg-slate-50 rounded-xl outline-none border-2 border-transparent focus:border-indigo-100 font-bold text-slate-900" />
                </div>
              </div>
              <div className="flex gap-3 pt-6">
                <button type="button" onClick={() => setShowAdd(false)} className="flex-1 py-4 text-slate-500 font-bold text-xs uppercase tracking-widest hover:text-slate-700 transition-colors">Cancelar</button>
                <button type="submit" className="flex-1 bg-indigo-600 text-white rounded-xl font-bold text-xs uppercase tracking-widest shadow-lg shadow-indigo-100 hover:bg-indigo-700 transition-all">Salvar</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default CardManager;

import { useState, useEffect, useCallback } from 'react';
import { Transaction, Summary, UserCategories, CreditCard } from '../types';
import { supabase } from '../services/supabaseClient';

const DEFAULT_CATEGORIES: UserCategories = {
  expense: ['Alimentação', 'Moradia', 'Transporte', 'Lazer', 'Saúde', 'Cartão', 'Outros'],
  income: ['Salário', 'Freelance', 'Investimentos', 'Presentes', 'Outros']
};

export const useFinanceData = (userId: string | null) => {
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [cards, setCards] = useState<CreditCard[]>([]);
  const [categories, setCategories] = useState<UserCategories>(DEFAULT_CATEGORIES);
  const [loading, setLoading] = useState(false);

  const fetchData = useCallback(async () => {
    if (!userId) return;
    setLoading(true);

    try {
      const { data: profile } = await supabase.from('profiles').select('categories').eq('id', userId).single();
      if (profile?.categories) setCategories(profile.categories as unknown as UserCategories);

      const { data: cardsData } = await supabase.from('credit_cards').select('*').eq('user_id', userId);
      setCards(cardsData || []);

      const { data: transData, error: transError } = await supabase
        .from('transactions')
        .select('*')
        .eq('user_id', userId)
        .order('date', { ascending: false });

      if (transError) throw transError;
      setTransactions(transData || []);
    } catch (err) {
      console.error('Erro ao sincronizar:', err);
    } finally {
      setLoading(false);
    }
  }, [userId]);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const addTransaction = useCallback(async (transaction: Omit<Transaction, 'id'>) => {
    if (!userId) return false;
    try {
      const { data, error } = await supabase
        .from('transactions')
        .insert([{ ...transaction, user_id: userId, is_paid: transaction.is_paid ?? true }])
        .select().single();
      if (error) throw error;
      setTransactions(prev => [data, ...prev]);
      return true;
    } catch (err) { 
      console.error(err);
      return false;
    }
  }, [userId]);

  const updateTransaction = useCallback(async (id: string, updates: Partial<Transaction>) => {
    try {
      const { data, error } = await supabase
        .from('transactions')
        .update(updates)
        .eq('id', id)
        .select().single();

      if (error) throw error;
      setTransactions(prev => prev.map(t => t.id === id ? data : t));
      return true;
    } catch (err) { 
      console.error('Erro ao atualizar transação:', err);
      return false;
    }
  }, []);

  const togglePaid = useCallback(async (id: string, currentStatus: boolean) => {
    try {
      const { error } = await supabase
        .from('transactions')
        .update({ is_paid: !currentStatus })
        .eq('id', id);

      if (!error) {
        setTransactions(prev => prev.map(t => t.id === id ? { ...t, is_paid: !currentStatus } : t));
      }
    } catch (err) { console.error(err); }
  }, []);

  const addCard = async (card: Omit<CreditCard, 'id'>) => {
    if (!userId) return;
    const { data, error } = await supabase.from('credit_cards').insert([{ ...card, user_id: userId }]).select().single();
    if (!error && data) setCards(prev => [...prev, data]);
  };

  const deleteCard = async (id: string) => {
    const { error } = await supabase.from('credit_cards').delete().eq('id', id);
    if (!error) setCards(prev => prev.filter(c => c.id !== id));
  };

  const deleteTransaction = useCallback(async (id: string) => {
    const { error } = await supabase.from('transactions').delete().eq('id', id);
    if (!error) setTransactions(prev => prev.filter(t => t.id !== id));
  }, []);

  const persistCategories = async (newCats: UserCategories) => {
    if (!userId) return;
    const { error } = await supabase.from('profiles').update({ categories: newCats }).eq('id', userId);
    if (!error) setCategories(newCats);
  };

  const addCategory = (type: 'income' | 'expense', name: string) => {
    const newCats = { ...categories, [type]: [...new Set([...categories[type], name])] };
    persistCategories(newCats);
  };

  const deleteCategory = (type: 'income' | 'expense', name: string) => {
    const newCats = { ...categories, [type]: categories[type].filter(cat => cat !== name) };
    persistCategories(newCats);
  };

  const getSummary = (): Summary => {
    return transactions.reduce((acc, t) => {
      const amt = Number(t.amount);
      if (t.type === 'income') {
        acc.income += amt;
        acc.balance += amt;
      } else {
        acc.expenses += amt;
        acc.balance -= amt;
      }
      return acc;
    }, { balance: 0, income: 0, expenses: 0 });
  };

  return {
    transactions, cards, categories,
    addTransaction, updateTransaction, deleteTransaction, togglePaid,
    addCard, deleteCard,
    addCategory, deleteCategory,
    summary: getSummary(),
    loading
  };
};

import React, { useState, useEffect } from 'react';
import { Transaction, TransactionType, UserCategories, CreditCard, SplitDetails } from '../types';

interface TransactionFormProps {
  onAdd: (data: any) => Promise<boolean>;
  onUpdate?: (id: string, data: any) => Promise<boolean>;
  editingTransaction?: Transaction | null;
  categories: UserCategories;
  cards: CreditCard[];
  onCancel?: () => void;
  initialType?: TransactionType;
}

const TransactionForm: React.FC<TransactionFormProps> = ({ 
  onAdd, 
  onUpdate,
  editingTransaction,
  categories, 
  cards, 
  onCancel, 
  initialType = 'expense' 
}) => {
  const [description, setDescription] = useState('');
  const [amount, setAmount] = useState('');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [type, setType] = useState<TransactionType>(initialType);
  const [category, setCategory] = useState('');
  const [selectedCardId, setSelectedCardId] = useState('');
  const [installments, setInstallments] = useState(1);
  const [isFixedValue, setIsFixedValue] = useState(false);
  const [isSplit, setIsSplit] = useState(false);
  const [partnerPart, setPartnerPart] = useState('');
  const [partnerName, setPartnerName] = useState('Isa');
  const [success, setSuccess] = useState(false);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (editingTransaction) {
      setDescription(editingTransaction.description);
      setAmount(editingTransaction.amount.toString());
      setDate(editingTransaction.date.split('T')[0]);
      setType(editingTransaction.type);
      setCategory(editingTransaction.category);
      setSelectedCardId(editingTransaction.card_id || '');
      setIsSplit(!!editingTransaction.is_split);
      if (editingTransaction.split_details) {
        setPartnerPart(editingTransaction.split_details.partnerPart.toString());
        setPartnerName(editingTransaction.split_details.partnerName);
      }
    } else {
      // Reset completo quando não está editando
      setDescription('');
      setAmount('');
      setDate(new Date().toISOString().split('T')[0]);
      setType(initialType);
      setCategory(initialType === 'expense' ? 'Cartão' : categories[initialType][0] || '');
      setSelectedCardId('');
      setInstallments(1);
      setIsFixedValue(false);
      setIsSplit(false);
      setPartnerPart('');
      setPartnerName('Isa');
    }
  }, [editingTransaction, initialType, categories]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!description || !amount || !date || loading) return;

    setLoading(true);
    const inputValue = parseFloat(amount);

    // Helper para garantir que a data não mude de dia por fuso horário
    const getSafeISO = (dateStr: string) => {
      return new Date(dateStr + 'T12:00:00').toISOString();
    };

    if (editingTransaction && onUpdate) {
      const splitInfo: SplitDetails | undefined = isSplit ? {
        userPart: inputValue - (parseFloat(partnerPart) || 0),
        partnerPart: parseFloat(partnerPart) || 0,
        partnerName: partnerName
      } : undefined;

      const success = await onUpdate(editingTransaction.id, {
        description,
        amount: inputValue,
        type,
        category,
        date: getSafeISO(date),
        card_id: selectedCardId || null,
        is_split: isSplit,
        split_details: splitInfo,
        is_paid: editingTransaction.is_paid // Preserva o status atual
      });

      if (success) {
        setSuccess(true);
        setTimeout(() => {
          setSuccess(false);
          setLoading(false);
          if (onCancel) onCancel();
        }, 800);
      } else {
        setLoading(false);
        alert('Ocorreu um erro ao salvar as alterações.');
      }
      return;
    }

    const numInstallments = Math.max(1, installments);
    const amountPerInstallment = isFixedValue ? inputValue : (inputValue / numInstallments);
    const pPartTotal = isSplit ? parseFloat(partnerPart) || inputValue / 2 : 0;
    const pPartPerMonth = isFixedValue ? pPartTotal : (pPartTotal / numInstallments);
    const uPartPerMonth = amountPerInstallment - pPartPerMonth;

    const [year, month, day] = date.split('-').map(Number);

    let allSuccess = true;
    for (let i = 0; i < numInstallments; i++) {
      const targetDate = new Date(year, month - 1 + i, day, 12, 0, 0);
      const labelPrefix = isFixedValue ? '[REC] ' : '';
      const installmentLabel = numInstallments > 1 ? ` (${i + 1}/${numInstallments})` : '';

      const splitInfo: SplitDetails | undefined = isSplit ? {
        userPart: uPartPerMonth,
        partnerPart: pPartPerMonth,
        partnerName: partnerName
      } : undefined;

      const res = await onAdd({
        description: labelPrefix + description + installmentLabel,
        amount: amountPerInstallment,
        type,
        category: selectedCardId ? 'Cartão' : category || 'Outros',
        date: targetDate.toISOString(),
        card_id: selectedCardId || null,
        is_split: isSplit,
        split_details: splitInfo,
        is_paid: type === 'income' 
      });
      if (!res) allSuccess = false;
    }

    if (allSuccess) {
      setSuccess(true);
      setTimeout(() => {
        setSuccess(false);
        setLoading(false);
        if (onCancel) onCancel();
      }, 1000);
    } else {
      setLoading(false);
      alert('Ocorreu um erro ao cadastrar alguns lançamentos.');
    }
  };

  return (
    <div className="bg-white p-6 md:p-8 rounded-xl shadow-2xl border border-slate-100 w-full max-w-lg mx-auto animate-in fade-in zoom-in duration-300 overflow-y-auto max-h-[95vh] mb-12 md:mb-0">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-xl font-bold text-slate-900">{editingTransaction ? 'Editar Lançamento' : 'Novo Lançamento'}</h2>
        {onCancel && (
          <button onClick={onCancel} className="p-2 text-slate-400 hover:bg-slate-50 rounded-full transition-all">
            <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M18 6 6 18"/><path d="m6 6 12 12"/></svg>
          </button>
        )}
      </div>

      <form onSubmit={handleSubmit} className="space-y-4 md:space-y-5">
        {!editingTransaction && (
          <div className="flex gap-2 p-1 bg-slate-100 rounded-lg">
            {(['expense', 'income'] as const).map((t) => (
              <button
                key={t}
                type="button"
                onClick={() => { setType(t); setCategory(t === 'expense' ? 'Cartão' : categories[t][0]); }}
                className={`flex-1 py-2 rounded-md text-[10px] font-bold transition-all ${type === t ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}
              >
                {t === 'expense' ? 'DESPESA' : 'RECEITA'}
              </button>
            ))}
          </div>
        )}

        <div className="space-y-4">
          <div>
            <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest block mb-1">Descrição</label>
            <input type="text" value={description} onChange={e => setDescription(e.target.value)} className="w-full px-4 py-3 bg-slate-50 border-2 border-transparent focus:border-indigo-100 rounded-lg outline-none text-sm font-medium text-slate-900 placeholder:text-slate-300" placeholder="Ex: Aluguel ou Compra de Mercado" required />
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest block mb-1">Valor Total</label>
              <input type="number" step="0.01" value={amount} onChange={e => setAmount(e.target.value)} className="w-full px-4 py-3 bg-slate-50 border-2 border-transparent focus:border-indigo-100 rounded-lg outline-none text-sm font-bold text-slate-900 placeholder:text-slate-300" placeholder="0,00" required />
            </div>
            <div>
              <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest block mb-1">Data Base / Vencimento</label>
              <input type="date" value={date} onChange={e => setDate(e.target.value)} className="w-full px-4 py-3 bg-slate-50 border-2 border-transparent focus:border-indigo-100 rounded-lg outline-none text-sm font-bold text-slate-900" required />
            </div>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest block mb-1">Categoria</label>
              <select value={category} onChange={e => setCategory(e.target.value)} className="w-full px-4 py-3 bg-slate-50 border-2 border-transparent focus:border-indigo-100 rounded-lg outline-none text-sm font-medium text-slate-900">
                {categories[type].map(cat => <option key={cat} value={cat}>{cat}</option>)}
              </select>
            </div>
            <div>
              <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest block mb-1">Cartão (Opcional)</label>
              <select value={selectedCardId} onChange={e => setSelectedCardId(e.target.value)} className="w-full px-4 py-3 bg-slate-50 border-2 border-transparent focus:border-indigo-100 rounded-lg outline-none text-sm font-medium text-slate-900">
                <option value="">Nenhum (Dinheiro/Pix)</option>
                {cards.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
              </select>
            </div>
          </div>

          {!editingTransaction && (
            <div className="p-4 bg-slate-50 rounded-lg border border-slate-100">
