import { GoogleGenAI, Type } from "@google/genai";
import { Transaction } from "../types";

// Fix: Use process.env.API_KEY directly as per guidelines
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const getFinancialInsights = async (transactions: Transaction[]) => {
  if (transactions.length === 0) return "Add some transactions to get AI insights!";

  const summary = transactions.map(t => ({
    type: t.type,
    amount: t.amount,
    category: t.category,
    description: t.description
  }));

  const prompt = `Based on the following list of transactions, provide a brief, professional, and actionable financial insight in Portuguese. 
  Focus on identifying patterns, suggesting potential savings, and offering a quick tip.
  Transactions: ${JSON.stringify(summary)}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction: "You are a helpful, minimalist financial advisor. Your advice should be concise and direct.",
        temperature: 0.7,
      },
    });

    return response.text || "Could not generate insights at this moment.";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Erro ao carregar insights financeiros via IA.";
  }
};

import React, { useState, useMemo } from 'react';
import { CreditCard, Transaction } from '../types';

interface CardManagerProps {
  cards: CreditCard[];
  transactions: Transaction[];
  onAdd: (card: Omit<CreditCard, 'id'>) => void;
  onDelete: (id: string) => void;
}

const CardManager: React.FC<CardManagerProps> = ({ cards, transactions, onAdd, onDelete }) => {
  const [showAdd, setShowAdd] = useState(false);
  const [expandedCardId, setExpandedCardId] = useState<string | null>(null);

  // Estados para o Filtro de Datas
  const getInitialDates = () => {
    const now = new Date();
    const firstDay = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().split('T')[0];
    const lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0).toISOString().split('T')[0];
    return { firstDay, lastDay };
  };

  const { firstDay: initStart, lastDay: initEnd } = getInitialDates();
  const [startDate, setStartDate] = useState(initStart);
  const [endDate, setEndDate] = useState(initEnd);

  // Estados para o formulário de novo cartão
  const [name, setName] = useState('');
  const [limit, setLimit] = useState('');
  const [closing, setClosing] = useState(5);
  const [due, setDue] = useState(15);
  const [color, setColor] = useState('#4f46e5');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onAdd({ name, credit_limit: parseFloat(limit), closing_day: closing, due_day: due, color });
    setName(''); setLimit(''); setShowAdd(false);
  };

  const resetFilters = () => {
    const { firstDay, lastDay } = getInitialDates();
    setStartDate(firstDay);
    setEndDate(lastDay);
  };

  const formatCurrency = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  // Funções de auxílio para cálculo de estatísticas por cartão no período
  const cardDataMap = useMemo(() => {
    const map = new Map();

    cards.forEach(card => {
      const cardTrans = transactions
        .filter(t => {
          if (t.card_id !== card.id) return false;
          const tDate = t.date.split('T')[0];
          return tDate >= startDate && tDate <= endDate;
        })
        .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

      const stats = cardTrans.reduce((acc, t) => {
        const amt = Number(t.amount);
        acc.total += amt;
        if (t.is_split && t.split_details) {
          acc.userPart += Number(t.split_details.userPart);
          const pName = t.split_details.partnerName || 'Outros';
          acc.others[pName] = (acc.others[pName] || 0) + Number(t.split_details.partnerPart);
        } else {
          acc.userPart += amt;
        }
        return acc;
      }, { total: 0, userPart: 0, others: {} as Record<string, number> });

      map.set(card.id, { transactions: cardTrans, stats });
    });

    return map;
  }, [cards, transactions, startDate, endDate]);

