import React, { useState, useEffect, useMemo } from 'react';
import { supabase } from './services/supabaseClient';
import { useFinanceData } from './hooks/useFinanceData';
import SummaryCards from './components/SummaryCards';
import TransactionForm from './components/TransactionForm';
import Charts from './components/Charts';
import AIInsights from './components/AIInsights';
import Sidebar, { ViewType } from './components/Sidebar';
import Reports from './components/Reports';
import CategoryManager from './components/CategoryManager';
import CardManager from './components/CardManager';
import PayerManager from './components/PayerManager';
import PayerReports from './components/PayerReports';
import AuthScreen from './components/AuthScreen';
import { TransactionType, User, Summary, Transaction } from './types';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [sessionLoading, setSessionLoading] = useState(true);

  const { 
    transactions, 
    cards,
    categories, 
    addTransaction,
    updateTransaction,
    deleteTransaction, 
    togglePaid,
    addCard,
    deleteCard,
    addCategory, 
    deleteCategory, 
    loading: dataLoading
  } = useFinanceData(currentUser?.id || null);

  const [currentView, setCurrentView] = useState<ViewType>('dashboard');
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);

  const getInitialDates = () => {
    const now = new Date();
    const firstDay = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().split('T')[0];
    const lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0).toISOString().split('T')[0];
    return { firstDay, lastDay };
  };

  const { firstDay: initStart, lastDay: initEnd } = getInitialDates();
  const [startDate, setStartDate] = useState(initStart);
  const [endDate, setEndDate] = useState(initEnd);
  const [selectedCategory, setSelectedCategory] = useState('all');
  const [selectedPayer, setSelectedPayer] = useState('all');
  const [statusFilter, setStatusFilter] = useState<'all' | 'paid' | 'pending'>('all');

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session?.user) fetchProfile(session.user.id);
      else setSessionLoading(false);
    });
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session?.user) fetchProfile(session.user.id);
      else { setCurrentUser(null); setSessionLoading(false); }
    });
    return () => subscription.unsubscribe();
  }, []);

  const fetchProfile = async (uid: string) => {
    const { data: profile } = await supabase.from('profiles').select('name, avatar_color').eq('id', uid).maybeSingle();
    setCurrentUser(profile ? { id: uid, name: profile.name, avatarColor: profile.avatar_color } : { id: uid, name: 'Usuário', avatarColor: '#4f46e5' });
    setSessionLoading(false);
  };

  const handleLogout = async () => { await supabase.auth.signOut(); setCurrentUser(null); setCurrentView('dashboard'); };
  const formatCurrency = (val: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const handleEdit = (t: Transaction) => {
    setEditingTransaction(t);
    setIsFormOpen(true);
  };

  const closeForm = () => {
    setIsFormOpen(false);
    setEditingTransaction(null);
  };

  const resetFilters = () => {
    const { firstDay, lastDay } = getInitialDates();
    setStartDate(firstDay);
    setEndDate(lastDay);
    setSelectedCategory('all');
    setSelectedPayer('all');
    setStatusFilter('all');
  };

  const dashboardData = useMemo(() => {
    const filtered = transactions.filter(t => {
      const tDate = t.date.split('T')[0];
      const matchesDate = tDate >= startDate && tDate <= endDate;
      const matchesCategory = selectedCategory === 'all' || t.category === selectedCategory;
      let matchesPayer = true;
      if (selectedPayer === 'individual') matchesPayer = !t.is_split;
      else if (selectedPayer !== 'all') matchesPayer = t.is_split && t.split_details?.partnerName === selectedPayer;

      return matchesDate && matchesCategory && matchesPayer;
    });

    const summary: Summary = filtered.reduce((acc, t) => {
      const amt = Number(t.amount);
      if (t.type === 'income') { acc.income += amt; acc.balance += amt; }
      else { acc.expenses += amt; acc.balance -= amt; }
      return acc;
    }, { balance: 0, income: 0, expenses: 0 });

    const groupedByCard = filtered.reduce((acc: any, t) => {
      if (t.type !== 'expense') return acc;
      const cardKey = t.card_id || 'no-card';
      if (!acc[cardKey]) {
        acc[cardKey] = {
          cardId: t.card_id,
          total: 0,
          userPart: 0,
          others: {},
          hasPending: false,
          description: t.card_id ? cards.find(c => c.id === t.card_id)?.name : 'Dinheiro/Pix'
        };
      }

      const amt = Number(t.amount);
      acc[cardKey].total += amt;
      if (!t.is_paid) acc[cardKey].hasPending = true;

      if (t.is_split && t.split_details) {
        acc[cardKey].userPart += Number(t.split_details.userPart);
        const pName = t.split_details.partnerName || 'Indefinido';
        acc[cardKey].others[pName] = (acc[cardKey].others[pName] || 0) + Number(t.split_details.partnerPart);
      } else {
        acc[cardKey].userPart += amt;
      }
      return acc;
    }, {});

    return { filteredTransactions: filtered, summary, cardSummaries: Object.values(groupedByCard) };
  }, [transactions, startDate, endDate, selectedCategory, selectedPayer, cards]);

  const renderTransactionManagement = (type: TransactionType) => {
    const filtered = transactions
      .filter(t => {
        if (t.type !== type) return false;
        const tDate = t.date.split('T')[0];
        if (tDate < startDate || tDate > endDate) return false;
        if (selectedCategory !== 'all' && t.category !== selectedCategory) return false;
        if (statusFilter === 'paid' && !t.is_paid) return false;
        if (statusFilter === 'pending' && t.is_paid) return false;

        if (selectedPayer === 'individual') return !t.is_split;
        if (selectedPayer !== 'all') return t.is_split && t.split_details?.partnerName === selectedPayer;

        return true;
      })
      .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    return (
      <div className="space-y-6 max-w-6xl mx-auto pb-24 md:pb-0 animate-in fade-in duration-500">
        <div className="bg-white p-4 md:p-6 rounded-xl border border-slate-100 shadow-sm">
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-4 items-end">
            <div className="col-span-1 sm:col-span-2 grid grid-cols-2 gap-2">
              <div>
                <label className="text-[9px] font-bold text-slate-400 uppercase mb-2 block">Início</label>
                <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="w-full bg-slate-50 border-none rounded-lg px-3 py-3 text-xs font-bold text-indigo-600 outline-none" />
              </div>
              <div>
                <label className="text-[9px] font-bold text-slate-400 uppercase mb-2 block">Fim</label>
                <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="w-full bg-slate-50 border-none rounded-lg px-3 py-3 text-xs font-bold text-indigo-600 outline-none" />
              </div>
            </div>
            <div>
              <label className="text-[9px] font-bold text-slate-400 uppercase mb-2 block">Categoria</label>
              <select value={selectedCategory} onChange={(e) => setSelectedCategory(e.target.value)} className="w-full bg-slate-50 border-none rounded-lg px-4 py-3 text-xs font-bold text-slate-700 outline-none">
                <option value="all">Todas</option>
                {categories[type].map(cat => <option key={cat} value={cat}>{cat}</option>)}
              </select>
            </div>
            <div>
              <label className="text-[9px] font-bold text-slate-400 uppercase mb-2 block">Pagante</label>
              <select value={selectedPayer} onChange={(e) => setSelectedPayer(e.target.value)} className="w-full bg-slate-50 border-none rounded-lg px-4 py-3 text-xs font-bold text-slate-700 outline-none">
                <option value="all">Todos</option>
                <option value="individual">Apenas Eu</option>
                {categories.payers?.map(p => <option key={p} value={p}>{p}</option>)}
              </select>
            </div>
            <button onClick={resetFilters} className="w-full py-3 text-[10px] font-bold text-slate-400 uppercase hover:text-indigo-600 transition-colors">Limpar Filtros</button>
          </div>
        </div>

        <div className="bg-white rounded-xl border border-slate-100 shadow-sm overflow-hidden overflow-x-auto">
          <table className="w-full text-left min-w-[800px]">
            <thead>
              <tr className="text-[10px] font-bold text-slate-400 uppercase tracking-widest border-b border-slate-50 bg-slate-50/30">
                <th className="py-5 px-6 w-12 text-center">Status</th>
                <th className="py-5 px-6">Data</th>
                <th className="py-5 px-6">Descrição</th>
                <th className="py-5 px-6 text-center">Divisão</th>
                <th className="py-5 px-6 text-right">Valor</th>
                <th className="py-5 px-6 w-28 text-center">Ações</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filtered.map((t) => (
                <tr key={t.id} className="hover:bg-slate-50/50 transition-colors">
                  <td className="py-5 px-6 text-center">
                    <button onClick={() => togglePaid(t.id, t.is_paid)} className={`w-6 h-6 rounded flex items-center justify-center border-2 mx-auto transition-all ${t.is_paid ? 'bg-teal-500 border-teal-500 text-white' : 'bg-white border-slate-200 text-slate-200'}`}>
                      <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4"><path d="M20 6 9 17l-5-5"/></svg>
                    </button>
                  </td>
                  <td className="py-5 px-6 text-[11px] text-slate-400 font-bold whitespace-nowrap">{new Date(t.date).toLocaleDateString('pt-BR')}</td>
                  <td className="py-5 px-6">
                    <p className={`text-sm font-semibold text-slate-900 ${!t.is_paid ? 'opacity-40' : ''}`}>{t.description}</p>
                    <span className="text-[9px] text-indigo-500 font-bold uppercase">{t.category}</span>
                  </td>
                  <td className="py-5 px-6 text-center">
                    {t.is_split && t.split_details ? (
                      <div className="text-[9px] font-bold">
                        <div className="text-slate-400">EU: {formatCurrency(t.split_details.userPart)}</div>
                        <div className="text-indigo-600">{t.split_details.partnerName}: {formatCurrency(t.split_details.partnerPart)}</div>
                      </div>
                    ) : <span className="text-[9px] text-slate-300 font-bold uppercase">Individual</span>}
                  </td>
                  <td className={`py-5 px-6 text-right text-sm font-bold ${t.type === 'income' ? 'text-teal-600' : 'text-rose-500'} ${!t.is_paid ? 'opacity-40' : ''}`}>
                    {formatCurrency(t.amount)}
                  </td>
                  <td className="py-5 px-6">
                    <div className="flex justify-center gap-2">
                      <button onClick={() => handleEdit(t)} className="p-2 text-indigo-500 hover:bg-indigo-50 rounded-lg transition-colors"><svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M12 20h9"/><path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z"/></svg></button>
                      <button onClick={() => deleteTransaction(t.id)} className="p-2 text-rose-500 hover:bg-rose-50 rounded-lg transition-colors"><svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M3 6h18"/><path d="M19 6v14c0 1-1 2-2 2H7c-1 0-2-1-2-2V6"/></svg></button>
                    </div>
                  </td>
                </tr>
              ))}
              {filtered.length === 0 && <tr><td colSpan={6} className="py-20 text-center text-slate-300 text-[10px] font-bold uppercase italic">Nenhum registro encontrado.</td></tr>}
            </tbody>
          </table>
        </div>
      </div>
    );
  };

  const renderContent = () => {
    switch (currentView) {
      case 'dashboard':
        return (
          <div className="space-y-6 md:space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-24 md:pb-0">
            <div className="flex flex-col md:flex-row gap-4 items-center justify-between bg-white p-4 rounded-xl border border-slate-100 shadow-sm">
              <div className="flex items-center gap-2">
                <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="bg-slate-50 border-none rounded-lg px-4 py-2 text-xs font-bold text-indigo-600 outline-none" />
                <input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} className="bg-slate-50 border-none rounded-lg px-4 py-2 text-xs font-bold text-indigo-600 outline-none" />
              </div>
              <div className="flex items-center gap-2">
                <label className="text-[10px] font-bold text-slate-400 uppercase mr-2">Filtrar Pagante:</label>
                <select value={selectedPayer} onChange={(e) => setSelectedPayer(e.target.value)} className="bg-slate-50 border-none rounded-lg px-4 py-2 text-xs font-bold text-indigo-600 outline-none">
                  <option value="all">Todos</option>
                  <option value="individual">Apenas Eu</option>
                  {categories.payers?.map(p => <option key={p} value={p}>{p}</option>)}
                </select>
              </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
              <div className="lg:col-span-8 space-y-8">
                <SummaryCards summary={dashboardData.summary} />
                <AIInsights transactions={dashboardData.filteredTransactions} />
                <Charts transactions={dashboardData.filteredTransactions} />
              </div>
              <div className="lg:col-span-4">
                <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 h-full">
                  <h2 className="text-sm font-bold text-slate-900 tracking-tight uppercase mb-8">Faturas por Pagante</h2>
                  <div className="space-y-6">
                    {dashboardData.cardSummaries.map((card: any) => (
                      <div key={card.cardId || 'cash'} className="p-5 bg-slate-50/40 rounded-2xl border border-slate-100 transition-all hover:bg-white hover:border-indigo-100 hover:shadow-xl">
                        <div className="flex justify-between items-start mb-5">
                          <div><h4 className="font-black text-xs text-slate-900 uppercase tracking-widest">{card.description}</h4>{card.hasPending && <span className="text-[7px] text-amber-600 font-black uppercase tracking-widest bg-amber-50 px-1.5 py-0.5 rounded border border-amber-100">Pendente</span>}</div>
                        </div>
                        <div className="pt-4 border-t border-slate-100/60 space-y-3">
                          <div className="flex justify-between"><span className="text-[10px] font-black text-slate-400 uppercase">EU:</span><span className="text-[13px] font-black text-slate-900">{formatCurrency(card.userPart)}</span></div>
                          {Object.entries(card.others).map(([name, val]: [any, any]) => (
                            <div key={name} className="flex justify-between"><span className="text-[10px] font-black text-indigo-400 uppercase">{name}:</span><span className="text-[13px] font-black text-indigo-600">{formatCurrency(val as number)}</span></div>
                          ))}
                          <div className="pt-2 flex justify-between items-center border-t border-dashed border-slate-200"><span className="text-[8px] font-bold text-slate-400 uppercase tracking-widest">Total</span><span className="text-base font-black text-slate-900">{formatCurrency(card.total)}</span></div>
                        </div>
                      </div>
                    ))}
                    {dashboardData.cardSummaries.length === 0 && (
                      <div className="py-10 text-center italic text-slate-300 text-xs">Nenhum gasto no período.</div>
                    )}
                  </div>
                </div>
              </div>
            </div>
          </div>
        );
      case 'add-expense': return renderTransactionManagement('expense');
      case 'add-income': return renderTransactionManagement('income');
      case 'payers': return <PayerManager categories={categories} onAdd={addCategory} onDelete={deleteCategory} />;
      case 'cards': return <CardManager cards={cards} transactions={transactions} onAdd={addCard} onDelete={deleteCard} />;
      case 'reports': return <Reports transactions={transactions} categories={categories} />;
      case 'payer-reports': return <PayerReports transactions={transactions} categories={categories} />;
      case 'categories': return <CategoryManager categories={categories} onAdd={addCategory} onDelete={deleteCategory} />;
    }
  };

  if (sessionLoading) return <div className="min-h-screen flex items-center justify-center"><div className="w-8 h-8 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div></div>;
  if (!currentUser) return <AuthScreen onSelectUser={setCurrentUser} />;

  const viewTitles: Record<string, string> = {
    'dashboard': 'Visão Geral',
    'cards': 'Meus Cartões',
    'add-expense': 'Gerenciar Despesas',
    'add-income': 'Gerenciar Receitas',
    'categories': 'Minhas Categorias',
    'reports': 'Extrato Detalhado',
    'payers': 'Gerenciar Pagantes',
    'payer-reports': 'Extrato por Pagante'
  };

  return (
    <div className="flex min-h-screen bg-slate-50/50">
      <Sidebar currentView={currentView} onViewChange={setCurrentView} currentUser={currentUser} onLogout={handleLogout} />
      <main className="flex-1 p-4 md:p-8 lg:p-12 w-full max-w-7xl mx-auto">
        <header className="mb-14 flex flex-col items-center text-center">
          <h2 className="text-4xl font-extrabold text-slate-900 tracking-tight">{viewTitles[currentView]}</h2>
          <button onClick={() => { setEditingTransaction(null); setIsFormOpen(true); }} className="mt-8 bg-indigo-600 text-white px-8 py-4 rounded-xl shadow-xl hover:bg-indigo-700 transition-all font-bold text-xs uppercase tracking-widest flex items-center gap-2">
            <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3"><path d="M12 5v14M5 12h14"/></svg>
            Novo Lançamento
          </button>
        </header>
        {isFormOpen && (
          <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[60] flex items-center justify-center p-4">
            <TransactionForm onAdd={addTransaction} onUpdate={updateTransaction} editingTransaction={editingTransaction} categories={categories} cards={cards} onCancel={closeForm} initialType={currentView === 'add-income' ? 'income' : 'expense'} />
          </div>
        )}
        {renderContent()}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Transaction, UserCategories } from '../types';

interface PayerReportsProps {
  transactions: Transaction[];
  categories: UserCategories;
}

const PayerReports: React.FC<PayerReportsProps> = ({ transactions, categories }) => {
  const getInitialDates = () => {
    const now = new Date();
    const firstDay = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().split('T')[0];
    const lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0).toISOString().split('T')[0];
    return { firstDay, lastDay };
  };

  const { firstDay: initStart, lastDay: initEnd } = getInitialDates();
  const [startDate, setStartDate] = useState(initStart);
  const [endDate, setEndDate] = useState(initEnd);
  const [expandedPayer, setExpandedPayer] = useState<string | null>(null);

  const formatCurrency = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const payerData = useMemo(() => {
    const results: Record<string, {
      totalToReceive: number;
      paid: number;
      pending: number;
      transactions: Transaction[];
    }> = {};

    // Inicializar com todos os pagantes cadastrados
    categories.payers.forEach(p => {
      results[p] = { totalToReceive: 0, paid: 0, pending: 0, transactions: [] };
    });

    // Filtrar e agrupar transações splitadas
    transactions
      .filter(t => t.is_split && t.split_details)
      .forEach(t => {
        const tDate = t.date.split('T')[0];
        if (tDate >= startDate && tDate <= endDate) {
          const name = t.split_details!.partnerName;
          const part = Number(t.split_details!.partnerPart);

          if (!results[name]) {
            results[name] = { totalToReceive: 0, paid: 0, pending: 0, transactions: [] };
          }

          results[name].totalToReceive += part;
          if (t.is_paid) results[name].paid += part;
          else results[name].pending += part;

          results[name].transactions.push(t);
        }
      });

    return Object.entries(results).map(([name, data]) => ({ name, ...data }));
  }, [transactions, categories.payers, startDate, endDate]);

  const grandTotalPending = payerData.reduce((acc, curr) => acc + curr.pending, 0);

  const exportToExcel = () => {
    const headers = ["Pagante", "Status", "Data", "Descrição", "Valor Total", "Parte do Pagante"];
    const rows: string[][] = [];

    payerData.forEach(payer => {
      payer.transactions.forEach(t => {
        rows.push([
          payer.name,
          t.is_paid ? "Pago" : "Pendente",
          new Date(t.date).toLocaleDateString('pt-BR'),
          t.description.replace(/;/g, ','),
          t.amount.toString().replace('.', ','),
          (t.split_details?.partnerPart || 0).toString().replace('.', ',')
        ]);
      });
    });

    const csvContent = "data:text/csv;charset=utf-8,\uFEFF" 
      + headers.join(";") + "\n" 
      + rows.map(e => e.join(";")).join("\n");

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `extrato_pagantes_${startDate}_ate_${endDate}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-6 md:space-y-8 animate-in fade-in duration-500 pb-24 md:pb-0">
      {/* Header com Filtros e Exportação */}
      <div className="bg-white p-4 md:p-6 rounded-xl border border-slate-100 shadow-sm flex flex-col lg:flex-row items-center justify-between gap-6 no-print">
        <div className="flex items-center gap-3 w-full lg:w-auto">
           <div className="p-3 bg-amber-50 rounded-xl">
             <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="#f59e0b" strokeWidth="2.5"><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg>
           </div>
           <div>
             <h3 className="text-xl font-bold text-slate-900">Extrato de Pagantes</h3>
             <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Resumo de divisões e pendências</p>
           </div>
        </div>

        <div className="flex flex-col md:flex-row items-center gap-4 w-full lg:w-auto">
          <div className="flex items-center gap-2 w-full md:w-auto">
            <input 
              type="date" 
              value={startDate} 
              onChange={e => setStartDate(e.target.value)} 
              className="flex-1 md:flex-none bg-slate-50 border-none rounded-lg px-4 py-2.5 text-xs font-bold text-indigo-600 outline-none" 
            />
            <input 
              type="date" 
              value={endDate} 
              onChange={e => setEndDate(e.target.value)} 
              className="flex-1 md:flex-none bg-slate-50 border-none rounded-lg px-4 py-2.5 text-xs font-bold text-indigo-600 outline-none" 
            />
          </div>

          <div className="flex gap-2 w-full md:w-auto border-t md:border-t-0 md:border-l border-slate-100 pt-4 md:pt-0 md:pl-4">
            <button 
              onClick={exportToExcel}
              className="flex-1 md:flex-none flex items-center justify-center gap-2 bg-emerald-50 text-emerald-700 px-4 py-2.5 rounded-lg text-[9px] font-bold uppercase tracking-widest hover:bg-emerald-100 transition-all border border-emerald-100"
            >
              <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M14.5 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V7.5L14.5 2z"/><polyline points="14 2 14 8 20 8"/></svg>
              Exportar
            </button>
            <button 
              onClick={() => window.print()}
              className="flex-1 md:flex-none flex items-center justify-center gap-2 bg-slate-900 text-white px-4 py-2.5 rounded-lg text-[9px] font-bold uppercase tracking-widest hover:bg-slate-800 transition-all shadow-lg active:scale-95"
            >
              <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><polyline points="7 10 12 15 17 10"/><line x1="12" x2="12" y1="15" y2="3"/></svg>
              PDF
            </button>
          </div>
        </div>
      </div>

      {/* Título de Impressão */}
      <div className="hidden print:block mb-8 border-b pb-6">
        <h2 className="text-2xl font-bold text-slate-900">Extrato de Pagantes</h2>
        <p className="text-xs text-slate-500 font-bold uppercase mt-1">Período: {new Date(startDate).toLocaleDateString('pt-BR')} - {new Date(endDate).toLocaleDateString('pt-BR')}</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {/* Card de Resumo Geral */}
        <div className="md:col-span-2 lg:col-span-3 bg-white p-6 rounded-2xl border border-indigo-100 shadow-sm flex items-center justify-between print:border-slate-200">
          <div>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Total Geral a Receber</p>
            <h2 className="text-3xl font-black text-indigo-600">{formatCurrency(grandTotalPending)}</h2>
          </div>
          <div className="text-right">
             <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest mb-1">Total Já Pago no Período</p>
             <p className="text-xl font-black text-slate-400">{formatCurrency(payerData.reduce((acc, curr) => acc + curr.paid, 0))}</p>
          </div>
        </div>

        {payerData.map(payer => {
          const isExpanded = expandedPayer === payer.name;
          return (
            <div key={payer.name} className={`bg-white rounded-2xl border transition-all print:break-inside-avoid print:border-slate-200 print:mb-6 print:shadow-none ${isExpanded ? 'ring-2 ring-indigo-50 border-indigo-200 lg:col-span-3 md:col-span-2' : 'border-slate-100 hover:shadow-lg no-print'}`}>
              <div 
                onClick={() => setExpandedPayer(isExpanded ? null : payer.name)}
                className={`p-6 cursor-pointer flex justify-between items-center ${isExpanded ? 'border-b border-slate-50' : ''} print:cursor-default print:border-b print:pb-4`}
              >
                <div className="flex items-center gap-4">
                  <div className="w-12 h-12 rounded-xl bg-slate-50 flex items-center justify-center text-indigo-600 font-black text-lg border border-slate-100 print:bg-slate-100">
                    {payer.name.charAt(0).toUpperCase()}
                  </div>
                  <div>
                    <h4 className="font-bold text-slate-900 text-base">{payer.name}</h4>
                    <p className={`text-[10px] font-black uppercase tracking-tighter ${payer.pending > 0 ? 'text-amber-500' : 'text-teal-600'}`}>
                      {payer.pending > 0 ? `Pendente: ${formatCurrency(payer.pending)}` : 'Tudo em dia'}
                    </p>
                  </div>
                </div>
                <div className={`transition-transform duration-300 no-print ${isExpanded ? 'rotate-180' : ''}`}>
                  <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="m6 9 6 6 6-6"/></svg>
                </div>
              </div>

              {/* Detalhes (Sempre visível na impressão) */}
              <div className={`px-6 pb-6 ${isExpanded ? 'animate-in slide-in-from-top-2 block pt-6' : 'hidden print:block print:pt-6'}`}>
                <div className="bg-slate-50 rounded-xl p-4 mb-6 grid grid-cols-2 gap-4 print:bg-white print:border print:border-slate-100">
                  <div>
                    <p className="text-[8px] font-black text-slate-400 uppercase mb-1">Recebido</p>
                    <p className="text-sm font-bold text-teal-600">{formatCurrency(payer.paid)}</p>
                  </div>
                  <div>
                    <p className="text-[8px] font-black text-slate-400 uppercase mb-1">A Receber</p>
                    <p className="text-sm font-bold text-rose-500">{formatCurrency(payer.pending)}</p>
                  </div>
                </div>

                <div className="space-y-3">
                  <h5 className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-2">Transações Vinculadas</h5>
                  <div className="overflow-x-auto print:overflow-visible">
                    <table className="w-full text-left min-w-[500px] print:min-w-0">
                      <thead>
                        <tr className="text-[8px] font-black text-slate-300 uppercase border-b border-slate-100">
                          <th className="pb-2">Data</th>
                          <th className="pb-2">Descrição</th>
                          <th className="pb-2 text-right">Total</th>
                          <th className="pb-2 text-right">Parte Dele(a)</th>
                          <th className="pb-2 text-center">Status</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-50">
                        {payer.transactions.map(t => (
                          <tr key={t.id} className="text-xs group hover:bg-slate-50/50 transition-colors">
                            <td className="py-3 text-slate-400 font-bold whitespace-nowrap">{new Date(t.date).toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit' })}</td>
                            <td className="py-3 pr-4">
                              <p className="font-bold text-slate-800">{t.description}</p>
                              <p className="text-[9px] text-indigo-400 font-bold uppercase">{t.category}</p>
                            </td>
                            <td className="py-3 text-right font-medium text-slate-400 italic">{formatCurrency(t.amount)}</td>
                            <td className="py-3 text-right font-black text-slate-900">{formatCurrency(Number(t.split_details?.partnerPart || 0))}</td>
                            <td className="py-3 text-center">
                              <span className={`inline-block px-1.5 py-0.5 rounded text-[7px] font-black uppercase tracking-widest border ${t.is_paid ? 'bg-teal-50 border-teal-100 text-teal-600' : 'bg-amber-50 border-amber-100 text-amber-600'}`}>
                                {t.is_paid ? 'PAGO' : 'PENDENTE'}
                              </span>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                  {payer.transactions.length === 0 && (
                    <p className="py-6 text-center italic text-slate-300 text-[10px] font-bold uppercase">Nenhuma transação encontrada</p>
                  )}
                </div>
              </div>
            </div>
          );
        })}

        {payerData.length === 0 && (
          <div className="col-span-full py-20 text-center bg-white rounded-3xl border-2 border-dashed border-slate-100">
             <p className="text-slate-300 font-bold uppercase tracking-widest text-[10px]">Nenhum pagante ou transação dividida encontrada no período.</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default PayerReports;

import React, { useState, useEffect, useMemo } from 'react';
import { supabase } from './services/supabaseClient';
import { useFinanceData } from './hooks/useFinanceData';
import SummaryCards from './components/SummaryCards';
import TransactionForm from './components/TransactionForm';
import Charts from './components/Charts';
import AIInsights from './components/AIInsights';
import Sidebar, { ViewType } from './components/Sidebar';
import Reports from './components/Reports';
import CategoryManager from './components/CategoryManager';
import CardManager from './components/CardManager';
import PayerManager from './components/PayerManager';
import PayerReports from './components/PayerReports';
import AuthScreen from './components/AuthScreen';
import { TransactionType, User, Summary, Transaction } from './types';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [sessionLoading, setSessionLoading] = useState(true);

  const { 
    transactions, 
    cards,
    categories, 
    addTransaction,
    updateTransaction,
    deleteTransaction, 
    togglePaid,
    addCard,
    deleteCard,
    addCategory, 
    deleteCategory, 
    loading: dataLoading
  } = useFinanceData(currentUser?.id || null);

  const [currentView, setCurrentView] = useState<ViewType>('dashboard');
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);

  const getInitialDates = () => {
    const now = new Date();
    const firstDay = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().split('T')[0];
    const lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0).toISOString().split('T')[0];
    return { firstDay, lastDay };
  };

  const { firstDay: initStart, lastDay: initEnd } = getInitialDates();
  const [startDate, setStartDate] = useState(initStart);
  const [endDate, setEndDate] = useState(initEnd);
  const [selectedCategory, setSelectedCategory] = useState('all');
  const [selectedPayer, setSelectedPayer] = useState('all');
  const [statusFilter, setStatusFilter] = useState<'all' | 'paid' | 'pending'>('all');

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session?.user) fetchProfile(session.user.id);
      else setSessionLoading(false);
    });
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session?.user) fetchProfile(session.user.id);
      else { setCurrentUser(null); setSessionLoading(false); }
    });
    return () => subscription.unsubscribe();
  }, []);

  const fetchProfile = async (uid: string) => {
    const { data: profile } = await supabase.from('profiles').select('name, avatar_color').eq('id', uid).maybeSingle();
    setCurrentUser(profile ? { id: uid, name: profile.name, avatarColor: profile.avatar_color } : { id: uid, name: 'Usuário', avatarColor: '#4f46e5' });
    setSessionLoading(false);
  };

  const handleLogout = async () => { await supabase.auth.signOut(); setCurrentUser(null); setCurrentView('dashboard'); };
  const formatCurrency = (val: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const handleEdit = (t: Transaction) => {
    setEditingTransaction(t);
    setIsFormOpen(true);
  };

  const closeForm = () => {
    setIsFormOpen(false);
    setEditingTransaction(null);
  };

  const resetFilters = () => {
    const { firstDay, lastDay } = getInitialDates();
    setStartDate(firstDay);
    setEndDate(lastDay);
    setSelectedCategory('all');
    setSelectedPayer('all');
    setStatusFilter('all');
  };

  const dashboardData = useMemo(() => {
    const filtered = transactions.filter(t => {
      const tDate = t.date.split('T')[0];
      const matchesDate = tDate >= startDate && tDate <= endDate;
      const matchesCategory = selectedCategory === 'all' || t.category === selectedCategory;
      let matchesPayer = true;
      if (selectedPayer === 'individual') matchesPayer = !t.is_split;
      else if (selectedPayer !== 'all') matchesPayer = t.is_split && t.split_details?.partnerName === selectedPayer;

      return matchesDate && matchesCategory && matchesPayer;
    });

    const summary: Summary = filtered.reduce((acc, t) => {
      const amt = Number(t.amount);
      if (t.type === 'income') { acc.income += amt; acc.balance += amt; }
      else { acc.expenses += amt; acc.balance -= amt; }
      return acc;
    }, { balance: 0, income: 0, expenses: 0 });

    const groupedByCard = filtered.reduce((acc: any, t) => {
      if (t.type !== 'expense') return acc;
      const cardKey = t.card_id || 'no-card';
      if (!acc[cardKey]) {
        acc[cardKey] = {
          cardId: t.card_id,
          total: 0,
          userPart: 0,
          others: {},
          hasPending: false,
          description: t.card_id ? cards.find(c => c.id === t.card_id)?.name : 'Dinheiro/Pix'
        };
      }

      const amt = Number(t.amount);
      acc[cardKey].total += amt;
      if (!t.is_paid) acc[cardKey].hasPending = true;

      if (t.is_split && t.split_details) {
        acc[cardKey].userPart += Number(t.split_details.userPart);
        const pName = t.split_details.partnerName || 'Indefinido';
        acc[cardKey].others[pName] = (acc[cardKey].others[pName] || 0) + Number(t.split_details.partnerPart);
      } else {
        acc[cardKey].userPart += amt;
      }
      return acc;
    }, {});

    return { filteredTransactions: filtered, summary, cardSummaries: Object.values(groupedByCard) };
  }, [transactions, startDate, endDate, selectedCategory, selectedPayer, cards]);

  const renderTransactionManagement = (type: TransactionType) => {
    const filtered = transactions
      .filter(t => {
        if (t.type !== type) return false;
        const tDate = t.date.split('T')[0];
        if (tDate < startDate || tDate > endDate) return false;
        if (selectedCategory !== 'all' && t.category !== selectedCategory) return false;
        if (statusFilter === 'paid' && !t.is_paid) return false;
        if (statusFilter === 'pending' && t.is_paid) return false;

        if (selectedPayer === 'individual') return !t.is_split;
        if (selectedPayer !== 'all') return t.is_split && t.split_details?.partnerName === selectedPayer;

        return true;
      })
      .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    return (
      <div className="space-y-6 max-w-6xl mx-auto pb-24 md:pb-0 animate-in fade-in duration-500">
        <div className="bg-white p-4 md:p-6 rounded-xl border border-slate-100 shadow-sm">
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-4 items-end">
            <div className="col-span-1 sm:col-span-2 grid grid-cols-2 gap-2">
              <div>
                <label className="text-[9px] font-bold text-slate-400 uppercase mb-2 block">Início</label>
                <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="w-full bg-slate-50 border-none rounded-lg px-3 py-3 text-xs font-bold text-indigo-600 outline-none" />
              </div>
              <div>
                <label className="text-[9px] font-bold text-slate-400 uppercase mb-2 block">Fim</label>
                <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="w-full bg-slate-50 border-none rounded-lg px-3 py-3 text-xs font-bold text-indigo-600 outline-none" />
              </div>
            </div>
            <div>
              <label className="text-[9px] font-bold text-slate-400 uppercase mb-2 block">Categoria</label>
              <select value={selectedCategory} onChange={(e) => setSelectedCategory(e.target.value)} className="w-full bg-slate-50 border-none rounded-lg px-4 py-3 text-xs font-bold text-slate-700 outline-none">
                <option value="all">Todas</option>
                {categories[type].map(cat => <option key={cat} value={cat}>{cat}</option>)}
              </select>
            </div>
            <div>
              <label className="text-[9px] font-bold text-slate-400 uppercase mb-2 block">Pagante</label>
              <select value={selectedPayer} onChange={(e) => setSelectedPayer(e.target.value)} className="w-full bg-slate-50 border-none rounded-lg px-4 py-3 text-xs font-bold text-slate-700 outline-none">
                <option value="all">Todos</option>
                <option value="individual">Apenas Eu</option>
                {categories.payers?.map(p => <option key={p} value={p}>{p}</option>)}
              </select>
            </div>
            <button onClick={resetFilters} className="w-full py-3 text-[10px] font-bold text-slate-400 uppercase hover:text-indigo-600 transition-colors">Limpar Filtros</button>
          </div>
        </div>

        <div className="bg-white rounded-xl border border-slate-100 shadow-sm overflow-hidden overflow-x-auto">
          <table className="w-full text-left min-w-[800px]">
            <thead>
              <tr className="text-[10px] font-bold text-slate-400 uppercase tracking-widest border-b border-slate-50 bg-slate-50/30">
                <th className="py-5 px-6 w-12 text-center">Status</th>
                <th className="py-5 px-6">Data</th>
                <th className="py-5 px-6">Descrição</th>
                <th className="py-5 px-6 text-center">Divisão</th>
                <th className="py-5 px-6 text-right">Valor</th>
                <th className="py-5 px-6 w-28 text-center">Ações</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filtered.map((t) => (
                <tr key={t.id} className="hover:bg-slate-50/50 transition-colors">
                  <td className="py-5 px-6 text-center">
                    <button onClick={() => togglePaid(t.id, t.is_paid)} className={`w-6 h-6 rounded flex items-center justify-center border-2 mx-auto transition-all ${t.is_paid ? 'bg-teal-500 border-teal-500 text-white' : 'bg-white border-slate-200 text-slate-200'}`}>
                      <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4"><path d="M20 6 9 17l-5-5"/></svg>
                    </button>
                  </td>
                  <td className="py-5 px-6 text-[11px] text-slate-400 font-bold whitespace-nowrap">{new Date(t.date).toLocaleDateString('pt-BR')}</td>
                  <td className="py-5 px-6">
                    <p className={`text-sm font-semibold text-slate-900 ${!t.is_paid ? 'opacity-40' : ''}`}>{t.description}</p>
                    <span className="text-[9px] text-indigo-500 font-bold uppercase">{t.category}</span>
                  </td>
                  <td className="py-5 px-6 text-center">
                    {t.is_split && t.split_details ? (
                      <div className="text-[9px] font-bold">
                        <div className="text-slate-400">EU: {formatCurrency(t.split_details.userPart)}</div>
                        <div className="text-indigo-600">{t.split_details.partnerName}: {formatCurrency(t.split_details.partnerPart)}</div>
                      </div>
                    ) : <span className="text-[9px] text-slate-300 font-bold uppercase">Individual</span>}
                  </td>
                  <td className={`py-5 px-6 text-right text-sm font-bold ${t.type === 'income' ? 'text-teal-600' : 'text-rose-500'} ${!t.is_paid ? 'opacity-40' : ''}`}>
                    {formatCurrency(t.amount)}
                  </td>
                  <td className="py-5 px-6">
                    <div className="flex justify-center gap-2">
                      <button onClick={() => handleEdit(t)} className="p-2 text-indigo-500 hover:bg-indigo-50 rounded-lg transition-colors"><svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M12 20h9"/><path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z"/></svg></button>
                      <button onClick={() => deleteTransaction(t.id)} className="p-2 text-rose-500 hover:bg-rose-50 rounded-lg transition-colors"><svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M3 6h18"/><path d="M19 6v14c0 1-1 2-2 2H7c-1 0-2-1-2-2V6"/></svg></button>
                    </div>
                  </td>
                </tr>
              ))}
              {filtered.length === 0 && <tr><td colSpan={6} className="py-20 text-center text-slate-300 text-[10px] font-bold uppercase italic">Nenhum registro encontrado.</td></tr>}
            </tbody>
          </table>
        </div>
      </div>
    );
  };

  const renderContent = () => {
    switch (currentView) {
      case 'dashboard':
        return (
          <div className="space-y-6 md:space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-24 md:pb-0">
            <div className="flex flex-col md:flex-row gap-4 items-center justify-between bg-white p-4 rounded-xl border border-slate-100 shadow-sm">
              <div className="flex items-center gap-2">
                <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="bg-slate-50 border-none rounded-lg px-4 py-2 text-xs font-bold text-indigo-600 outline-none" />
                <input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} className="bg-slate-50 border-none rounded-lg px-4 py-2 text-xs font-bold text-indigo-600 outline-none" />
              </div>
              <div className="flex items-center gap-2">
                <label className="text-[10px] font-bold text-slate-400 uppercase mr-2">Filtrar Pagante:</label>
                <select value={selectedPayer} onChange={(e) => setSelectedPayer(e.target.value)} className="bg-slate-50 border-none rounded-lg px-4 py-2 text-xs font-bold text-indigo-600 outline-none">
                  <option value="all">Todos</option>
                  <option value="individual">Apenas Eu</option>
                  {categories.payers?.map(p => <option key={p} value={p}>{p}</option>)}
                </select>
              </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
              <div className="lg:col-span-8 space-y-8">
                <SummaryCards summary={dashboardData.summary} />
                <AIInsights transactions={dashboardData.filteredTransactions} />
                <Charts transactions={dashboardData.filteredTransactions} />
              </div>
              <div className="lg:col-span-4">
                <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 h-full">
                  <h2 className="text-sm font-bold text-slate-900 tracking-tight uppercase mb-8">Faturas por Pagante</h2>
                  <div className="space-y-6">
                    {dashboardData.cardSummaries.map((card: any) => (
                      <div key={card.cardId || 'cash'} className="p-5 bg-slate-50/40 rounded-2xl border border-slate-100 transition-all hover:bg-white hover:border-indigo-100 hover:shadow-xl">
                        <div className="flex justify-between items-start mb-5">
                          <div><h4 className="font-black text-xs text-slate-900 uppercase tracking-widest">{card.description}</h4>{card.hasPending && <span className="text-[7px] text-amber-600 font-black uppercase tracking-widest bg-amber-50 px-1.5 py-0.5 rounded border border-amber-100">Pendente</span>}</div>
                        </div>
                        <div className="pt-4 border-t border-slate-100/60 space-y-3">
                          <div className="flex justify-between"><span className="text-[10px] font-black text-slate-400 uppercase">EU:</span><span className="text-[13px] font-black text-slate-900">{formatCurrency(card.userPart)}</span></div>
                          {Object.entries(card.others).map(([name, val]: [any, any]) => (
                            <div key={name} className="flex justify-between"><span className="text-[10px] font-black text-indigo-400 uppercase">{name}:</span><span className="text-[13px] font-black text-indigo-600">{formatCurrency(val as number)}</span></div>
                          ))}
                          <div className="pt-2 flex justify-between items-center border-t border-dashed border-slate-200"><span className="text-[8px] font-bold text-slate-400 uppercase tracking-widest">Total</span><span className="text-base font-black text-slate-900">{formatCurrency(card.total)}</span></div>
                        </div>
                      </div>
                    ))}
                    {dashboardData.cardSummaries.length === 0 && (
                      <div className="py-10 text-center italic text-slate-300 text-xs">Nenhum gasto no período.</div>
                    )}
                  </div>
                </div>
              </div>
            </div>
          </div>
        );
      case 'add-expense': return renderTransactionManagement('expense');
      case 'add-income': return renderTransactionManagement('income');
      case 'payers': return <PayerManager categories={categories} onAdd={addCategory} onDelete={deleteCategory} />;
      case 'cards': return <CardManager cards={cards} transactions={transactions} onAdd={addCard} onDelete={deleteCard} />;
      case 'reports': return <Reports transactions={transactions} categories={categories} />;
      case 'payer-reports': return <PayerReports transactions={transactions} categories={categories} />;
      case 'categories': return <CategoryManager categories={categories} onAdd={addCategory} onDelete={deleteCategory} />;
    }
  };

  if (sessionLoading) return <div className="min-h-screen flex items-center justify-center"><div className="w-8 h-8 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div></div>;
  if (!currentUser) return <AuthScreen onSelectUser={setCurrentUser} />;

  const viewTitles: Record<string, string> = {
    'dashboard': 'Visão Geral',
    'cards': 'Meus Cartões',
    'add-expense': 'Gerenciar Despesas',
    'add-income': 'Gerenciar Receitas',
    'categories': 'Minhas Categorias',
    'reports': 'Extrato Detalhado',
    'payers': 'Gerenciar Pagantes',
    'payer-reports': 'Extrato por Pagante'
  };

  // Condição para mostrar o botão de Novo Lançamento
  const showNewTransactionButton = currentView !== 'reports' && currentView !== 'payer-reports';

  return (
    <div className="flex min-h-screen bg-slate-50/50">
      <Sidebar currentView={currentView} onViewChange={setCurrentView} currentUser={currentUser} onLogout={handleLogout} />
      <main className="flex-1 p-4 md:p-8 lg:p-12 w-full max-w-7xl mx-auto">
        <header className="mb-14 flex flex-col items-center text-center">
          <h2 className="text-4xl font-extrabold text-slate-900 tracking-tight">{viewTitles[currentView]}</h2>

          {showNewTransactionButton && (
            <button 
              onClick={() => { setEditingTransaction(null); setIsFormOpen(true); }} 
              className="mt-8 bg-indigo-600 text-white px-8 py-4 rounded-xl shadow-xl hover:bg-indigo-700 transition-all font-bold text-xs uppercase tracking-widest flex items-center gap-2"
            >
              <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3"><path d="M12 5v14M5 12h14"/></svg>
              Novo Lançamento
            </button>
          )}
        </header>
        {isFormOpen && (
          <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[60] flex items-center justify-center p-4">
            <TransactionForm onAdd={addTransaction} onUpdate={updateTransaction} editingTransaction={editingTransaction} categories={categories} cards={cards} onCancel={closeForm} initialType={currentView === 'add-income' ? 'income' : 'expense'} />
          </div>
        )}
        {renderContent()}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Transaction, TransactionType, UserCategories, CreditCard, SplitDetails } from '../types';

interface TransactionFormProps {
  onAdd: (data: any) => Promise<boolean>;
  onUpdate?: (id: string, data: any) => Promise<boolean>;
  editingTransaction?: Transaction | null;
  categories: UserCategories;
  cards: CreditCard[];
  onCancel?: () => void;
  initialType?: TransactionType;
}

const TransactionForm: React.FC<TransactionFormProps> = ({ 
  onAdd, 
  onUpdate,
  editingTransaction,
  categories, 
  cards, 
  onCancel, 
  initialType = 'expense' 
}) => {
  const [description, setDescription] = useState('');
  const [amount, setAmount] = useState('');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [type, setType] = useState<TransactionType>(initialType);
  const [category, setCategory] = useState('');
  const [selectedCardId, setSelectedCardId] = useState('');
  const [installments, setInstallments] = useState(1);
  const [isFixedValue, setIsFixedValue] = useState(false);
  const [isSplit, setIsSplit] = useState(false);
  const [partnerPart, setPartnerPart] = useState('');
  const [partnerName, setPartnerName] = useState(categories.payers?.[0] || 'Isa');
  const [success, setSuccess] = useState(false);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (editingTransaction) {
      setDescription(editingTransaction.description);
      setAmount(editingTransaction.amount.toString());
      setDate(editingTransaction.date.split('T')[0]);
      setType(editingTransaction.type);
      setCategory(editingTransaction.category);
      setSelectedCardId(editingTransaction.card_id || '');
      setIsSplit(!!editingTransaction.is_split);
      if (editingTransaction.split_details) {
        setPartnerPart(editingTransaction.split_details.partnerPart.toString());
        setPartnerName(editingTransaction.split_details.partnerName);
      }
    } else {
      setDescription('');
      setAmount('');
      setDate(new Date().toISOString().split('T')[0]);
      setType(initialType);
      // Ajuste: Não forçar categoria "Cartão", usar a primeira disponível ou "Outros"
      setCategory(categories[initialType][0] || 'Outros');
      setSelectedCardId('');
      setInstallments(1);
      setIsFixedValue(false);
      setIsSplit(false);
      setPartnerPart('');
      setPartnerName(categories.payers?.[0] || 'Isa');
    }
  }, [editingTransaction, initialType, categories]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!description || !amount || !date || loading) return;

    setLoading(true);

    try {
      const inputValue = parseFloat(amount);
      const getSafeISO = (dateStr: string) => {
        const d = new Date(dateStr + 'T12:00:00');
        return d.toISOString();
      };

      if (editingTransaction && onUpdate) {
        const splitInfo: SplitDetails | undefined = isSplit ? {
          userPart: inputValue - (parseFloat(partnerPart) || 0),
          partnerPart: parseFloat(partnerPart) || 0,
          partnerName: partnerName
        } : undefined;

        const res = await onUpdate(editingTransaction.id, {
          description,
          amount: inputValue,
          type,
          category, // Agora respeita a categoria selecionada independentemente do cartão
          date: getSafeISO(date),
          card_id: selectedCardId || null,
          is_split: isSplit,
          split_details: splitInfo,
          is_paid: editingTransaction.is_paid
        });

        if (res) {
          setSuccess(true);
          setTimeout(() => { if (onCancel) onCancel(); }, 800);
        } else {
          setLoading(false);
          alert('Erro ao atualizar lançamento.');
        }
        return;
      }

      const numInstallments = Math.max(1, installments);
      const amountPerInstallment = isFixedValue ? inputValue : (inputValue / numInstallments);
      const pPartTotal = isSplit ? parseFloat(partnerPart) || inputValue / 2 : 0;
      const pPartPerMonth = isFixedValue ? pPartTotal : (pPartTotal / numInstallments);
      const uPartPerMonth = amountPerInstallment - pPartPerMonth;

      const [year, month, day] = date.split('-').map(Number);
      let allSuccess = true;

      for (let i = 0; i < numInstallments; i++) {
        const targetDate = new Date(year, month - 1 + i, day, 12, 0, 0);
        const labelPrefix = isFixedValue ? '[REC] ' : '';
        const installmentLabel = numInstallments > 1 ? ` (${i + 1}/${numInstallments})` : '';

        const splitInfo: SplitDetails | undefined = isSplit ? {
          userPart: uPartPerMonth,
          partnerPart: pPartPerMonth,
          partnerName: partnerName
        } : undefined;

        const res = await onAdd({
          description: labelPrefix + description + installmentLabel,
          amount: amountPerInstallment,
          type,
          category: category || 'Outros', // Mantém a categoria selecionada
          date: targetDate.toISOString(),
          card_id: selectedCardId || null,
          is_split: isSplit,
          split_details: splitInfo,
          is_paid: type === 'income' 
        });
        if (!res) allSuccess = false;
      }

      if (allSuccess) {
        setSuccess(true);
        setTimeout(() => { if (onCancel) onCancel(); }, 1000);
      } else {
        setLoading(false);
        alert('Erro ao cadastrar lançamentos.');
      }
    } catch (err) {
      setLoading(false);
    }
  };

  return (
    <div className="bg-white p-6 md:p-8 rounded-xl shadow-2xl border border-slate-100 w-full max-w-lg mx-auto animate-in fade-in zoom-in duration-300 overflow-y-auto max-h-[95vh]">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-xl font-bold text-slate-900">{editingTransaction ? 'Editar Lançamento' : 'Novo Lançamento'}</h2>
        {onCancel && (
          <button onClick={onCancel} className="p-2 text-slate-400 hover:bg-slate-50 rounded-full transition-all">
            <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M18 6 6 18"/><path d="m6 6 12 12"/></svg>
          </button>
        )}
      </div>

      <form onSubmit={handleSubmit} className="space-y-4 md:space-y-5">
        {!editingTransaction && (
          <div className="flex gap-2 p-1 bg-slate-100 rounded-lg">
            {(['expense', 'income'] as const).map((t) => (
              <button
                key={t}
                type="button"
                onClick={() => { setType(t); setCategory(categories[t][0] || 'Outros'); }}
                className={`flex-1 py-2 rounded-md text-[10px] font-bold transition-all ${type === t ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}
              >
                {t === 'expense' ? 'DESPESA' : 'RECEITA'}
              </button>
            ))}
          </div>
        )}

        <div className="space-y-4">
          <div>
            <label className="text-[10px] font-bold text-slate-400 uppercase block mb-1">Descrição</label>
            <input type="text" value={description} onChange={e => setDescription(e.target.value)} className="w-full px-4 py-3 bg-slate-50 border-2 border-transparent focus:border-indigo-100 rounded-lg outline-none text-sm font-medium text-slate-900" placeholder="Ex: Mercado" required />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="text-[10px] font-bold text-slate-400 uppercase block mb-1">Valor Total</label>
              <input type="number" step="0.01" value={amount} onChange={e => setAmount(e.target.value)} className="w-full px-4 py-3 bg-slate-50 border-2 border-transparent focus:border-indigo-100 rounded-lg outline-none text-sm font-bold text-slate-900" placeholder="0,00" required />
            </div>
            <div>
              <label className="text-[10px] font-bold text-slate-400 uppercase block mb-1">Data</label>
              <input type="date" value={date} onChange={e => setDate(e.target.value)} className="w-full px-4 py-3 bg-slate-50 border-2 border-transparent focus:border-indigo-100 rounded-lg outline-none text-sm font-bold text-slate-900" required />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="text-[10px] font-bold text-slate-400 uppercase block mb-1">Categoria</label>
              <select value={category} onChange={e => setCategory(e.target.value)} className="w-full px-4 py-3 bg-slate-50 border-2 border-transparent focus:border-indigo-100 rounded-lg outline-none text-sm font-medium text-slate-900">
                {categories[type].map(cat => <option key={cat} value={cat}>{cat}</option>)}
              </select>
            </div>
            <div>
              <label className="text-[10px] font-bold text-slate-400 uppercase block mb-1">Cartão (Opcional)</label>
              <select value={selectedCardId} onChange={e => setSelectedCardId(e.target.value)} className="w-full px-4 py-3 bg-slate-50 border-2 border-transparent focus:border-indigo-100 rounded-lg outline-none text-sm font-medium text-slate-900">
                <option value="">Dinheiro/Pix</option>
                {cards.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
              </select>
            </div>
          </div>

          {type === 'expense' && (
            <div className="p-5 bg-indigo-50/50 rounded-xl border border-indigo-100">
              <div className="flex items-center justify-between mb-4">
                <span className="text-[10px] font-bold text-indigo-900 uppercase tracking-widest">Dividir Gasto</span>
                <button type="button" onClick={() => setIsSplit(!isSplit)} className={`w-10 h-5 rounded-full transition-colors relative ${isSplit ? 'bg-indigo-600' : 'bg-slate-200'}`}>
                  <div className={`absolute top-1 w-3 h-3 bg-white rounded-full transition-all ${isSplit ? 'left-6' : 'left-1'}`}></div>
                </button>
              </div>

              {isSplit && (
                <div className="space-y-4 animate-in fade-in slide-in-from-top-2">
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="text-[10px] font-bold text-indigo-400 uppercase mb-1 block">Pagante</label>
                      <select 
                        value={partnerName} 
                        onChange={e => setPartnerName(e.target.value)} 
                        className="w-full px-3 py-2 bg-white rounded border border-indigo-100 text-xs font-semibold text-slate-900"
                      >
                        {categories.payers?.map(p => <option key={p} value={p}>{p}</option>)}
                      </select>
                    </div>
                    <div>
                      <label className="text-[10px] font-bold text-indigo-400 uppercase mb-1 block">Parte dele(a)</label>
                      <input type="number" value={partnerPart} onChange={e => setPartnerPart(e.target.value)} placeholder="0,00" className="w-full px-3 py-2 bg-white rounded border border-indigo-100 text-xs font-bold text-slate-900" />
                    </div>
                  </div>
                </div>
              )}
            </div>
          )}
        </div>

        <button 
          type="submit" 
          disabled={success || loading} 
          className={`w-full py-4 rounded-lg text-xs font-bold uppercase tracking-widest transition-all text-white shadow-lg ${
            success ? 'bg-teal-500 shadow-teal-100' : 'bg-indigo-600 hover:bg-indigo-700 shadow-indigo-100 disabled:opacity-50'
          }`}
        >
          {loading ? 'Salvando...' : (success ? '✓ Sucesso' : (editingTransaction ? 'Salvar Alterações' : 'Confirmar'))}
        </button>
      </form>
    </div>
  );
};

export default TransactionForm;

import React, { useState, useEffect, useMemo } from 'react';
import { supabase } from './services/supabaseClient';
import { useFinanceData } from './hooks/useFinanceData';
import SummaryCards from './components/SummaryCards';
import TransactionForm from './components/TransactionForm';
import Charts from './components/Charts';
import AIInsights from './components/AIInsights';
import Sidebar, { ViewType } from './components/Sidebar';
import Reports from './components/Reports';
import CategoryManager from './components/CategoryManager';
import CardManager from './components/CardManager';
import PayerManager from './components/PayerManager';
import PayerReports from './components/PayerReports';
import AuthScreen from './components/AuthScreen';
import { TransactionType, User, Summary, Transaction } from './types';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [sessionLoading, setSessionLoading] = useState(true);

  const { 
    transactions, 
    cards,
    categories, 
    addTransaction,
    updateTransaction,
    deleteTransaction, 
    togglePaid,
    addCard,
    deleteCard,
    addCategory, 
    deleteCategory, 
    loading: dataLoading
  } = useFinanceData(currentUser?.id || null);

  const [currentView, setCurrentView] = useState<ViewType>('dashboard');
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);

  const getInitialDates = () => {
    const now = new Date();
    const firstDay = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().split('T')[0];
    const lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0).toISOString().split('T')[0];
    return { firstDay, lastDay };
  };

  const { firstDay: initStart, lastDay: initEnd } = getInitialDates();
  const [startDate, setStartDate] = useState(initStart);
  const [endDate, setEndDate] = useState(initEnd);
  const [selectedCategory, setSelectedCategory] = useState('all');
  const [selectedPayer, setSelectedPayer] = useState('all');
  const [statusFilter, setStatusFilter] = useState<'all' | 'paid' | 'pending'>('all');

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session?.user) fetchProfile(session.user.id);
      else setSessionLoading(false);
    });
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session?.user) fetchProfile(session.user.id);
      else { setCurrentUser(null); setSessionLoading(false); }
    });
    return () => subscription.unsubscribe();
  }, []);

  const fetchProfile = async (uid: string) => {
    const { data: profile } = await supabase.from('profiles').select('name, avatar_color').eq('id', uid).maybeSingle();
    setCurrentUser(profile ? { id: uid, name: profile.name, avatarColor: profile.avatar_color } : { id: uid, name: 'Usuário', avatarColor: '#4f46e5' });
    setSessionLoading(false);
  };

  const handleLogout = async () => { await supabase.auth.signOut(); setCurrentUser(null); setCurrentView('dashboard'); };
  const formatCurrency = (val: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const handleEdit = (t: Transaction) => {
    setEditingTransaction(t);
    setIsFormOpen(true);
  };

  const closeForm = () => {
    setIsFormOpen(false);
    setEditingTransaction(null);
  };

  const resetFilters = () => {
    const { firstDay, lastDay } = getInitialDates();
    setStartDate(firstDay);
    setEndDate(lastDay);
    setSelectedCategory('all');
    setSelectedPayer('all');
    setStatusFilter('all');
  };

  const dashboardData = useMemo(() => {
    const filtered = transactions.filter(t => {
      const tDate = t.date.split('T')[0];
      const matchesDate = tDate >= startDate && tDate <= endDate;
      const matchesCategory = selectedCategory === 'all' || t.category === selectedCategory;
      let matchesPayer = true;
      if (selectedPayer === 'individual') matchesPayer = !t.is_split;
      else if (selectedPayer !== 'all') matchesPayer = t.is_split && t.split_details?.partnerName === selectedPayer;

      return matchesDate && matchesCategory && matchesPayer;
    });

    const summary: Summary = filtered.reduce((acc, t) => {
      const amt = Number(t.amount);
      if (t.type === 'income') { acc.income += amt; acc.balance += amt; }
      else { acc.expenses += amt; acc.balance -= amt; }
      return acc;
    }, { balance: 0, income: 0, expenses: 0 });

    const groupedByCard = filtered.reduce((acc: any, t) => {
      if (t.type !== 'expense') return acc;
      const cardKey = t.card_id || 'no-card';
      if (!acc[cardKey]) {
        acc[cardKey] = {
          cardId: t.card_id,
          total: 0,
          userPart: 0,
          others: {},
          hasPending: false,
          description: t.card_id ? cards.find(c => c.id === t.card_id)?.name : 'Dinheiro/Pix'
        };
      }

      const amt = Number(t.amount);
      acc[cardKey].total += amt;
      if (!t.is_paid) acc[cardKey].hasPending = true;

      if (t.is_split && t.split_details) {
        acc[cardKey].userPart += Number(t.split_details.userPart);
        const pName = t.split_details.partnerName || 'Indefinido';
        acc[cardKey].others[pName] = (acc[cardKey].others[pName] || 0) + Number(t.split_details.partnerPart);
      } else {
        acc[cardKey].userPart += amt;
      }
      return acc;
    }, {});

    return { filteredTransactions: filtered, summary, cardSummaries: Object.values(groupedByCard) };
  }, [transactions, startDate, endDate, selectedCategory, selectedPayer, cards]);

  const renderTransactionManagement = (type: TransactionType) => {
    const filtered = transactions
      .filter(t => {
        if (t.type !== type) return false;
        const tDate = t.date.split('T')[0];
        if (tDate < startDate || tDate > endDate) return false;
        if (selectedCategory !== 'all' && t.category !== selectedCategory) return false;
        if (statusFilter === 'paid' && !t.is_paid) return false;
        if (statusFilter === 'pending' && t.is_paid) return false;

        if (selectedPayer === 'individual') return !t.is_split;
        if (selectedPayer !== 'all') return t.is_split && t.split_details?.partnerName === selectedPayer;

        return true;
      })
      .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    return (
      <div className="space-y-6 max-w-7xl mx-auto pb-24 md:pb-0 animate-in fade-in duration-500">
        <div className="bg-white p-4 md:p-6 rounded-xl border border-slate-100 shadow-sm">
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-4 items-end">
            <div className="col-span-1 sm:col-span-2 grid grid-cols-2 gap-2">
              <div>
                <label className="text-[9px] font-bold text-slate-400 uppercase mb-2 block">Início</label>
                <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="w-full bg-slate-50 border-none rounded-lg px-3 py-3 text-xs font-bold text-indigo-600 outline-none" />
              </div>
              <div>
                <label className="text-[9px] font-bold text-slate-400 uppercase mb-2 block">Fim</label>
                <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="w-full bg-slate-50 border-none rounded-lg px-3 py-3 text-xs font-bold text-indigo-600 outline-none" />
              </div>
            </div>
            <div>
              <label className="text-[9px] font-bold text-slate-400 uppercase mb-2 block">Categoria</label>
              <select value={selectedCategory} onChange={(e) => setSelectedCategory(e.target.value)} className="w-full bg-slate-50 border-none rounded-lg px-4 py-3 text-xs font-bold text-slate-700 outline-none">
                <option value="all">Todas</option>
                {categories[type].map(cat => <option key={cat} value={cat}>{cat}</option>)}
              </select>
            </div>
            <div>
              <label className="text-[9px] font-bold text-slate-400 uppercase mb-2 block">Pagante</label>
              <select value={selectedPayer} onChange={(e) => setSelectedPayer(e.target.value)} className="w-full bg-slate-50 border-none rounded-lg px-4 py-3 text-xs font-bold text-slate-700 outline-none">
                <option value="all">Todos</option>
                <option value="individual">Apenas Eu</option>
                {categories.payers?.map(p => <option key={p} value={p}>{p}</option>)}
              </select>
            </div>
            <button onClick={resetFilters} className="w-full py-3 text-[10px] font-bold text-slate-400 uppercase hover:text-indigo-600 transition-colors">Limpar Filtros</button>
          </div>
        </div>

        <div className="bg-white rounded-xl border border-slate-100 shadow-sm overflow-hidden overflow-x-auto">
          <table className="w-full text-left min-w-[1000px]">
            <thead>
              <tr className="text-[10px] font-bold text-slate-400 uppercase tracking-widest border-b border-slate-50 bg-slate-50/30">
                <th className="py-5 px-6 w-12 text-center">Status</th>
                <th className="py-5 px-6">Data</th>
                <th className="py-5 px-6">Descrição</th>
                <th className="py-5 px-6">Categoria</th>
                <th className="py-5 px-6">Pagamento</th>
                <th className="py-5 px-6 text-center">Divisão</th>
                <th className="py-5 px-6 text-right">Valor</th>
                <th className="py-5 px-6 w-28 text-center">Ações</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filtered.map((t) => {
                const card = cards.find(c => c.id === t.card_id);
                return (
                  <tr key={t.id} className="hover:bg-slate-50/50 transition-colors">
                    <td className="py-5 px-6 text-center">
                      <button onClick={() => togglePaid(t.id, t.is_paid)} className={`w-6 h-6 rounded flex items-center justify-center border-2 mx-auto transition-all ${t.is_paid ? 'bg-teal-500 border-teal-500 text-white' : 'bg-white border-slate-200 text-slate-200'}`}>
                        <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4"><path d="M20 6 9 17l-5-5"/></svg>
                      </button>
                    </td>
                    <td className="py-5 px-6 text-[11px] text-slate-400 font-bold whitespace-nowrap">{new Date(t.date).toLocaleDateString('pt-BR')}</td>
                    <td className="py-5 px-6">
                      <p className={`text-sm font-semibold text-slate-900 ${!t.is_paid ? 'opacity-40' : ''}`}>{t.description}</p>
                    </td>
                    <td className="py-5 px-6 whitespace-nowrap">
                      <span className="text-[10px] text-indigo-500 font-bold uppercase bg-indigo-50 px-2 py-1 rounded border border-indigo-100">{t.category}</span>
                    </td>
                    <td className="py-5 px-6 whitespace-nowrap">
                      <div className="flex items-center gap-2">
                        {card ? (
                          <>
                            <div className="w-3 h-3 rounded-full" style={{ backgroundColor: card.color }}></div>
                            <span className="text-xs font-bold text-slate-600 uppercase">{card.name}</span>
                          </>
                        ) : (
                          <span className="text-xs font-bold text-slate-400 uppercase">Dinheiro/Pix</span>
                        )}
                      </div>
                    </td>
                    <td className="py-5 px-6 text-center">
                      {t.is_split && t.split_details ? (
                        <div className="text-[9px] font-bold">
                          <div className="text-slate-400">EU: {formatCurrency(t.split_details.userPart)}</div>
                          <div className="text-indigo-600">{t.split_details.partnerName}: {formatCurrency(t.split_details.partnerPart)}</div>
                        </div>
                      ) : <span className="text-[9px] text-slate-300 font-bold uppercase">Individual</span>}
                    </td>
                    <td className={`py-5 px-6 text-right text-sm font-bold ${t.type === 'income' ? 'text-teal-600' : 'text-rose-500'} ${!t.is_paid ? 'opacity-40' : ''}`}>
                      {formatCurrency(t.amount)}
                    </td>
                    <td className="py-5 px-6">
                      <div className="flex justify-center gap-2">
                        <button onClick={() => handleEdit(t)} className="p-2 text-indigo-500 hover:bg-indigo-50 rounded-lg transition-colors"><svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M12 20h9"/><path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z"/></svg></button>
                        <button onClick={() => deleteTransaction(t.id)} className="p-2 text-rose-500 hover:bg-rose-50 rounded-lg transition-colors"><svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M3 6h18"/><path d="M19 6v14c0 1-1 2-2 2H7c-1 0-2-1-2-2V6"/></svg></button>
                      </div>
                    </td>
                  </tr>
                );
              })}
              {filtered.length === 0 && <tr><td colSpan={8} className="py-20 text-center text-slate-300 text-[10px] font-bold uppercase italic">Nenhum registro encontrado.</td></tr>}
            </tbody>
          </table>
        </div>
      </div>
    );
  };

  const renderContent = () => {
    switch (currentView) {
      case 'dashboard':
        return (
          <div className="space-y-6 md:space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-24 md:pb-0">
            <div className="flex flex-col md:flex-row gap-4 items-center justify-between bg-white p-4 rounded-xl border border-slate-100 shadow-sm">
              <div className="flex items-center gap-2">
                <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="bg-slate-50 border-none rounded-lg px-4 py-2 text-xs font-bold text-indigo-600 outline-none" />
                <input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} className="bg-slate-50 border-none rounded-lg px-4 py-2 text-xs font-bold text-indigo-600 outline-none" />
              </div>
              <div className="flex items-center gap-2">
                <label className="text-[10px] font-bold text-slate-400 uppercase mr-2">Filtrar Pagante:</label>
                <select value={selectedPayer} onChange={(e) => setSelectedPayer(e.target.value)} className="bg-slate-50 border-none rounded-lg px-4 py-2 text-xs font-bold text-indigo-600 outline-none">
                  <option value="all">Todos</option>
                  <option value="individual">Apenas Eu</option>
                  {categories.payers?.map(p => <option key={p} value={p}>{p}</option>)}
                </select>
              </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
              <div className="lg:col-span-8 space-y-8">
                <SummaryCards summary={dashboardData.summary} />
                <AIInsights transactions={dashboardData.filteredTransactions} />
                <Charts transactions={dashboardData.filteredTransactions} />
              </div>
              <div className="lg:col-span-4">
                <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 h-full">
                  <h2 className="text-sm font-bold text-slate-900 tracking-tight uppercase mb-8">Faturas por Pagante</h2>
                  <div className="space-y-6">
                    {dashboardData.cardSummaries.map((card: any) => (
                      <div key={card.cardId || 'cash'} className="p-5 bg-slate-50/40 rounded-2xl border border-slate-100 transition-all hover:bg-white hover:border-indigo-100 hover:shadow-xl">
                        <div className="flex justify-between items-start mb-5">
                          <div><h4 className="font-black text-xs text-slate-900 uppercase tracking-widest">{card.description}</h4>{card.hasPending && <span className="text-[7px] text-amber-600 font-black uppercase tracking-widest bg-amber-50 px-1.5 py-0.5 rounded border border-amber-100">Pendente</span>}</div>
                        </div>
                        <div className="pt-4 border-t border-slate-100/60 space-y-3">
                          <div className="flex justify-between"><span className="text-[10px] font-black text-slate-400 uppercase">EU:</span><span className="text-[13px] font-black text-slate-900">{formatCurrency(card.userPart)}</span></div>
                          {Object.entries(card.others).map(([name, val]: [any, any]) => (
                            <div key={name} className="flex justify-between"><span className="text-[10px] font-black text-indigo-400 uppercase">{name}:</span><span className="text-[13px] font-black text-indigo-600">{formatCurrency(val as number)}</span></div>
                          ))}
                          <div className="pt-2 flex justify-between items-center border-t border-dashed border-slate-200"><span className="text-[8px] font-bold text-slate-400 uppercase tracking-widest">Total</span><span className="text-base font-black text-slate-900">{formatCurrency(card.total)}</span></div>
                        </div>
                      </div>
                    ))}
                    {dashboardData.cardSummaries.length === 0 && (
                      <div className="py-10 text-center italic text-slate-300 text-xs">Nenhum gasto no período.</div>
                    )}
                  </div>
                </div>
              </div>
            </div>
          </div>
        );
      case 'add-expense': return renderTransactionManagement('expense');
      case 'add-income': return renderTransactionManagement('income');
      case 'payers': return <PayerManager categories={categories} onAdd={addCategory} onDelete={deleteCategory} />;
      case 'cards': return <CardManager cards={cards} transactions={transactions} onAdd={addCard} onDelete={deleteCard} />;
      case 'reports': return <Reports transactions={transactions} categories={categories} />;
      case 'payer-reports': return <PayerReports transactions={transactions} categories={categories} />;
      case 'categories': return <CategoryManager categories={categories} onAdd={addCategory} onDelete={deleteCategory} />;
    }
  };

  if (sessionLoading) return <div className="min-h-screen flex items-center justify-center"><div className="w-8 h-8 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div></div>;
  if (!currentUser) return <AuthScreen onSelectUser={setCurrentUser} />;

  const viewTitles: Record<string, string> = {
    'dashboard': 'Visão Geral',
    'cards': 'Meus Cartões',
    'add-expense': 'Gerenciar Despesas',
    'add-income': 'Gerenciar Receitas',
    'categories': 'Minhas Categorias',
    'reports': 'Extrato Detalhado',
    'payers': 'Gerenciar Pagantes',
    'payer-reports': 'Extrato por Pagante'
  };

  // Condição para mostrar o botão de Novo Lançamento
  const showNewTransactionButton = currentView !== 'reports' && currentView !== 'payer-reports';

  return (
    <div className="flex min-h-screen bg-slate-50/50">
      <Sidebar currentView={currentView} onViewChange={setCurrentView} currentUser={currentUser} onLogout={handleLogout} />
      <main className="flex-1 p-4 md:p-8 lg:p-12 w-full max-w-7xl mx-auto">
        <header className="mb-14 flex flex-col items-center text-center">
          <h2 className="text-4xl font-extrabold text-slate-900 tracking-tight">{viewTitles[currentView]}</h2>

          {showNewTransactionButton && (
            <button 
              onClick={() => { setEditingTransaction(null); setIsFormOpen(true); }} 
              className="mt-8 bg-indigo-600 text-white px-8 py-4 rounded-xl shadow-xl hover:bg-indigo-700 transition-all font-bold text-xs uppercase tracking-widest flex items-center gap-2"
            >
              <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3"><path d="M12 5v14M5 12h14"/></svg>
              Novo Lançamento
            </button>
          )}
        </header>
        {isFormOpen && (
          <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[60] flex items-center justify-center p-4">
            <TransactionForm onAdd={addTransaction} onUpdate={updateTransaction} editingTransaction={editingTransaction} categories={categories} cards={cards} onCancel={closeForm} initialType={currentView === 'add-income' ? 'income' : 'expense'} />
          </div>
        )}
        {renderContent()}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Transaction, UserCategories, Summary, CreditCard } from '../types';
import { supabase } from '../services/supabaseClient';

interface ReportsProps {
  transactions: Transaction[];
  categories: UserCategories;
}

const Reports: React.FC<ReportsProps> = ({ transactions, categories }) => {
  const [cards, setCards] = useState<CreditCard[]>([]);

  React.useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session?.user) {
        supabase.from('credit_cards').select('*').eq('user_id', session.user.id).then(({ data }) => {
          if (data) setCards(data);
        });
      }
    });
  }, []);

  const getInitialDates = () => {
    const now = new Date();
    const firstDay = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().split('T')[0];
    const lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0).toISOString().split('T')[0];
    return { firstDay, lastDay };
  };

  const { firstDay: initStart, lastDay: initEnd } = getInitialDates();
  const [filter, setFilter] = useState<'all' | 'income' | 'expense'>('all');
  const [startDate, setStartDate] = useState(initStart);
  const [endDate, setEndDate] = useState(initEnd);
  const [selectedCategory, setSelectedCategory] = useState('all');
  const [selectedPayer, setSelectedPayer] = useState('all');
  const [statusFilter, setStatusFilter] = useState<'all' | 'paid' | 'pending'>('all');

  const { filteredTransactions, summary } = useMemo(() => {
    const filtered = transactions
      .filter(t => {
        if (filter !== 'all' && t.type !== filter) return false;
        const tDate = t.date.split('T')[0];
        if (tDate < startDate || tDate > endDate) return false;
        if (selectedCategory !== 'all' && t.category !== selectedCategory) return false;
        if (statusFilter === 'paid' && !t.is_paid) return false;
        if (statusFilter === 'pending' && t.is_paid) return false;

        if (selectedPayer === 'individual') return !t.is_split;
        if (selectedPayer !== 'all') return t.is_split && t.split_details?.partnerName === selectedPayer;

        return true;
      })
      .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    const stats = filtered.reduce((acc, t) => {
      const amt = Number(t.amount);
      if (t.type === 'income') {
        acc.income += amt;
        acc.balance += amt;
      } else {
        acc.expenses += amt;
        acc.balance -= amt;
      }
      return acc;
    }, { balance: 0, income: 0, expenses: 0 } as Summary);

    return { filteredTransactions: filtered, summary: stats };
  }, [transactions, filter, startDate, endDate, selectedCategory, selectedPayer, statusFilter]);

  const formatCurrency = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const resetFilters = () => {
    const { firstDay, lastDay } = getInitialDates();
    setFilter('all');
    setStartDate(firstDay);
    setEndDate(lastDay);
    setSelectedCategory('all');
    setSelectedPayer('all');
    setStatusFilter('all');
  };

  const exportToExcel = () => {
    const headers = ["Data", "Descrição", "Categoria", "Pagamento", "Tipo", "Valor", "Status"];
    const rows = filteredTransactions.map(t => {
      const card = cards.find(c => c.id === t.card_id);
      return [
        new Date(t.date).toLocaleDateString('pt-BR'),
        t.description.replace(/;/g, ','),
        t.category,
        card ? card.name : 'Dinheiro/Pix',
        t.type === 'income' ? 'Entrada' : 'Saída',
        t.amount.toString().replace('.', ','),
        t.is_paid ? 'Pago' : 'Pendente'
      ];
    });

    const csvContent = "data:text/csv;charset=utf-8,\uFEFF" 
      + headers.join(";") + "\n" 
      + rows.map(e => e.join(";")).join("\n");

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `extrato_${startDate}_ate_${endDate}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-4 md:space-y-6 pb-20 md:pb-0">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-3 md:gap-4 print:mb-8 print:border-b print:pb-6">
        <div className="bg-white p-5 md:p-7 rounded-xl shadow-sm border border-slate-50 flex flex-col justify-center print:border-none print:p-0">
          <p className="text-slate-400 text-[9px] font-bold uppercase tracking-[0.1em] mb-1">PATRIMÔNIO LÍQUIDO</p>
          <h3 className="text-xl md:text-3xl font-bold text-slate-900">{formatCurrency(summary.balance)}</h3>
        </div>
        <div className="bg-white p-5 md:p-7 rounded-xl shadow-sm border border-slate-50 flex flex-col justify-center print:border-none print:p-0">
          <p className="text-slate-400 text-[9px] font-bold uppercase tracking-[0.1em] mb-1">ENTRADAS</p>
          <h3 className="text-xl md:text-3xl font-bold text-teal-600">{formatCurrency(summary.income)}</h3>
        </div>
        <div className="bg-white p-5 md:p-7 rounded-xl shadow-sm border border-slate-50 flex flex-col justify-center print:border-none print:p-0">
          <p className="text-slate-400 text-[9px] font-bold uppercase tracking-[0.1em] mb-1">SAÍDAS</p>
          <h3 className="text-xl md:text-3xl font-bold text-rose-500">{formatCurrency(summary.expenses)}</h3>
        </div>
      </div>

      <div className="bg-white p-4 md:p-6 rounded-xl shadow-sm border border-slate-100 no-print">
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-6 gap-4 items-end">
          <div className="col-span-1 sm:col-span-2 grid grid-cols-2 gap-2">
            <div>
              <label className="text-[9px] font-bold text-slate-400 uppercase mb-2 block">Início</label>
              <input 
                type="date" 
                value={startDate} 
                onChange={(e) => setStartDate(e.target.value)}
                style={{ colorScheme: 'light' }}
                className="w-full bg-slate-50 border-none rounded-lg px-3 py-3 text-xs font-bold text-indigo-600 outline-none"
              />
            </div>
            <div>
              <label className="text-[9px] font-bold text-slate-400 uppercase mb-2 block">Fim</label>
              <input 
                type="date" 
                value={endDate} 
                onChange={(e) => setEndDate(e.target.value)}
                style={{ colorScheme: 'light' }}
                className="w-full bg-slate-50 border-none rounded-lg px-3 py-3 text-xs font-bold text-indigo-600 outline-none"
              />
            </div>
          </div>
          <div>
            <label className="text-[9px] font-bold text-slate-400 uppercase mb-2 block">Categoria</label>
            <select 
              value={selectedCategory} 
              onChange={(e) => setSelectedCategory(e.target.value)}
              className="w-full bg-slate-50 border-none rounded-lg px-4 py-3 text-xs font-bold text-slate-700 outline-none"
            >
              <option value="all">Todas</option>
              {[...categories.expense, ...categories.income].sort().map(cat => (
                <option key={cat} value={cat}>{cat}</option>
              ))}
            </select>
          </div>
          <div>
            <label className="text-[9px] font-bold text-slate-400 uppercase mb-2 block">Pagante</label>
            <select 
              value={selectedPayer} 
              onChange={(e) => setSelectedPayer(e.target.value)}
              className="w-full bg-slate-50 border-none rounded-lg px-4 py-3 text-xs font-bold text-slate-700 outline-none"
            >
              <option value="all">Todos</option>
              <option value="individual">Apenas Eu</option>
              {categories.payers?.map(p => <option key={p} value={p}>{p}</option>)}
            </select>
          </div>
          <div>
            <label className="text-[9px] font-bold text-slate-400 uppercase mb-2 block">Status</label>
            <select 
              value={statusFilter} 
              onChange={(e) => setStatusFilter(e.target.value as any)}
              className="w-full bg-slate-50 border-none rounded-lg px-4 py-3 text-xs font-bold text-slate-700 outline-none"
            >
              <option value="all">Todos</option>
              <option value="paid">Pagos</option>
              <option value="pending">Pendentes</option>
            </select>
          </div>
          <button 
            onClick={resetFilters}
            className="w-full py-3 text-[9px] font-bold text-slate-400 uppercase hover:text-indigo-600 transition-colors text-center"
          >
            Resetar
          </button>
        </div>
      </div>

      <div className="bg-white p-4 md:p-10 rounded-xl shadow-sm border border-slate-100 overflow-hidden print:p-0 print:border-none print:shadow-none">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 mb-8 print:mb-4">
          <div>
            <h2 className="text-lg md:text-2xl font-bold text-slate-900 tracking-tight">Registros do Período</h2>
            <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest mt-0.5">
              Filtrado de {new Date(startDate).toLocaleDateString('pt-BR')} até {new Date(endDate).toLocaleDateString('pt-BR')}
            </p>
          </div>

          <div className="flex gap-2 no-print w-full md:w-auto">
            <button 
              onClick={exportToExcel}
              className="flex-1 md:flex-none flex items-center justify-center gap-2 bg-emerald-50 text-emerald-700 px-4 py-3 rounded-lg text-[9px] font-bold uppercase tracking-widest hover:bg-emerald-100 transition-all border border-emerald-100"
            >
              <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M14.5 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V7.5L14.5 2z"/><polyline points="14 2 14 8 20 8"/></svg>
              Exportar
            </button>
            <button 
              onClick={() => window.print()}
              className="flex-1 md:flex-none flex items-center justify-center gap-2 bg-slate-900 text-white px-4 py-3 rounded-lg text-[9px] font-bold uppercase tracking-widest hover:bg-slate-800 transition-all shadow-lg active:scale-95"
            >
              <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><polyline points="7 10 12 15 17 10"/><line x1="12" x2="12" y1="15" y2="3"/></svg>
              PDF
            </button>
          </div>
        </div>

        <div className="overflow-x-auto scrollbar-hide -mx-4 px-4 md:mx-0 md:px-0 print:overflow-visible print:mx-0 print:px-0">
          <table className="w-full text-left min-w-[900px] print:min-w-0">
            <thead>
              <tr className="text-[10px] font-bold text-slate-400 uppercase tracking-widest border-b-2 border-slate-50 bg-slate-50/20">
                <th className="py-5 px-4 text-center w-24">Status</th>
                <th className="py-5 px-4">Data</th>
                <th className="py-5 px-4">Descrição</th>
                <th className="py-5 px-4">Categoria</th>
                <th className="py-5 px-4">Pagamento</th>
                <th className="py-5 px-4 text-right">Valor</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredTransactions.map((t) => {
                const card = cards.find(c => c.id === t.card_id);
                return (
                  <tr key={t.id} className={`hover:bg-slate-50/40 transition-colors ${!t.is_paid ? 'bg-amber-50/5' : ''}`}>
                    <td className="py-6 px-4 text-center">
                      <span className={`inline-block px-2 py-1 rounded-[4px] text-[8px] font-black uppercase tracking-widest border ${
                        t.is_paid 
                          ? 'bg-teal-50 border-teal-100 text-teal-600' 
                          : 'bg-amber-50 border-amber-100 text-amber-600'
                      }`}>
                        {t.is_paid ? 'Pago' : 'Pendente'}
                      </span>
                    </td>
                    <td className="py-6 px-4 text-[11px] font-bold text-slate-500 whitespace-nowrap">
                      {new Date(t.date).toLocaleDateString('pt-BR')}
                    </td>
                    <td className="py-6 px-4">
                      <p className={`text-sm font-semibold text-slate-900 truncate max-w-[200px] md:max-w-none print:max-w-none ${!t.is_paid ? 'text-slate-400 italic' : ''}`}>
                        {t.description}
                      </p>
                      {t.is_split && t.split_details && (
                        <span className="text-[8px] text-indigo-400 font-bold uppercase block mt-0.5">Participação: {t.split_details.partnerName}</span>
                      )}
                    </td>
                    <td className="py-6 px-4 whitespace-nowrap">
                      <span className="px-3 py-1 bg-slate-50 border border-slate-100 rounded text-[9px] font-bold text-indigo-600 uppercase tracking-tighter print:border-none print:p-0">
                        {t.category}
                      </span>
                    </td>
                    <td className="py-6 px-4 whitespace-nowrap">
                       <span className="text-[10px] font-bold text-slate-500 uppercase">
                         {card ? card.name : 'Dinheiro/Pix'}
                       </span>
                    </td>
                    <td className={`py-6 px-4 text-right font-bold text-sm whitespace-nowrap ${t.type === 'income' ? 'text-teal-600' : 'text-rose-500'} ${!t.is_paid ? 'opacity-50' : ''}`}>
                      {formatCurrency(t.amount)}
                    </td>
                  </tr>
                );
              })}
              {filteredTransactions.length === 0 && (
                <tr>
                   <td colSpan={6} className="py-20 text-center text-slate-300 text-[10px] font-bold uppercase italic tracking-widest">Nenhum registro no período</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

