               <p className="text-xs font-bold text-indigo-700 mt-0.5">{installments}x de {formatCurrency(parseFloat(amount) / installments)}</p>
             </div>
          )}

          {type === 'expense' && (
            <div className="p-6 bg-slate-50/50 rounded-3xl border border-slate-100">
              <div className="flex items-center justify-between">
