const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [sessionLoading, setSessionLoading] = useState(true);
  const [showLanding, setShowLanding] = useState(true);

  const { 
    transactions, cards, categories, 
    addTransaction, updateTransaction, deleteTransaction, togglePaid,
    addCard, deleteCard, addCategory, deleteCategory, loading: dataLoading
  } = useFinanceData(currentUser?.id || null);

  const [currentView, setCurrentView] = useState<ViewType>('dashboard');
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);

  const getInitialDates = () => {
    const now = new Date();
    const firstDay = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().split('T')[0];
    const lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0).toISOString().split('T')[0];
    return { firstDay, lastDay };
  };

  const { firstDay: initStart, lastDay: initEnd } = getInitialDates();
  const [startDate, setStartDate] = useState(initStart);
  const [endDate, setEndDate] = useState(initEnd);
  const [selectedCategory, setSelectedCategory] = useState('all');
  const [selectedPayer, setSelectedPayer] = useState('all');
  const [statusFilter, setStatusFilter] = useState<'all' | 'paid' | 'pending'>('all');

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session?.user) {
        fetchProfile(session.user.id);
        setShowLanding(false);
      } else {
        setSessionLoading(false);
      }
    });
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session?.user) {
        fetchProfile(session.user.id);
        setShowLanding(false);
      } else {
        setCurrentUser(null);
        setSessionLoading(false);
      }
    });
    return () => subscription.unsubscribe();
  }, []);

  const fetchProfile = async (uid: string) => {
    const { data: profile } = await supabase.from('profiles').select('name, avatar_color').eq('id', uid).maybeSingle();
    setCurrentUser(profile ? { id: uid, name: profile.name, avatarColor: profile.avatar_color } : { id: uid, name: 'Usuário', avatarColor: '#4f46e5' });
    setSessionLoading(false);
  };

  const handleLogout = async () => { 
    await supabase.auth.signOut(); 
    setCurrentUser(null); 
    setCurrentView('dashboard');
    setShowLanding(true);
  };

  const dashboardData = useMemo(() => {
    const filtered = transactions.filter(t => {
      const tDate = t.date.split('T')[0];
      const matchesDate = tDate >= startDate && tDate <= endDate;
      const matchesCategory = selectedCategory === 'all' || t.category === selectedCategory;
      let matchesPayer = true;
      if (selectedPayer === 'individual') matchesPayer = true;
      else if (selectedPayer !== 'all') matchesPayer = t.is_split && t.split_details?.partnerName === selectedPayer;
      return matchesDate && matchesCategory && matchesPayer;
    });

    const summary: Summary = filtered.reduce((acc, t) => {
      let amt = Number(t.amount);
      if (selectedPayer === 'individual' && t.is_split && t.split_details) {
        amt = Number(t.split_details.userPart);
      } else if (selectedPayer !== 'all' && t.is_split && t.split_details) {
        amt = Number(t.split_details.partnerPart);
      }

      if (t.type === 'income') { acc.income += amt; acc.balance += amt; }
      else { acc.expenses += amt; acc.balance -= amt; }
      return acc;
    }, { balance: 0, income: 0, expenses: 0 });

    const groupedByCard = filtered.reduce((acc: any, t) => {
      if (t.type !== 'expense') return acc;
      const cardKey = t.card_id || 'no-card';
      if (!acc[cardKey]) {
        acc[cardKey] = {
          cardId: t.card_id,
          total: 0,
          userPart: 0,
          others: {},
          hasPending: false,
          description: t.card_id ? cards.find(c => c.id === t.card_id)?.name : 'Dinheiro/Pix'
        };
      }

      const amt = Number(t.amount);
      acc[cardKey].total += amt;
      if (!t.is_paid) acc[cardKey].hasPending = true;

      if (t.is_split && t.split_details) {
        acc[cardKey].userPart += Number(t.split_details.userPart);
        const pName = t.split_details.partnerName || 'Indefinido';
        acc[cardKey].others[pName] = (acc[cardKey].others[pName] || 0) + Number(t.split_details.partnerPart);
      } else {
        acc[cardKey].userPart += amt;
      }
      return acc;
    }, {});

    return { filteredTransactions: filtered, summary, cardSummaries: Object.values(groupedByCard) };
  }, [transactions, startDate, endDate, selectedCategory, selectedPayer, cards]);

  const renderContent = () => {
    switch (currentView) {
      case 'dashboard':
        return (
          <Dashboard 
            currentUser={currentUser}
            summary={dashboardData.summary}
            transactions={dashboardData.filteredTransactions}
            cardSummaries={dashboardData.cardSummaries}
            startDate={startDate}
            endDate={endDate}
            onDateChange={(s, e) => { setStartDate(s); setEndDate(e); }}
            selectedPayer={selectedPayer}
            onPayerChange={setSelectedPayer}
            payers={categories.payers}
          />
        );
      case 'add-expense':
      case 'add-income':
        return (
          <TransactionManagement 
            type={currentView === 'add-expense' ? 'expense' : 'income'}
            transactions={transactions}
            cards={cards}
            categories={categories}
            startDate={startDate}
            endDate={endDate}
            setStartDate={setStartDate}
            setEndDate={setEndDate}
            selectedCategory={selectedCategory}
            setSelectedCategory={setSelectedCategory}
            selectedPayer={selectedPayer}
            setSelectedPayer={setSelectedPayer}
            statusFilter={statusFilter}
            setStatusFilter={setStatusFilter}
            resetFilters={() => {
               const dates = getInitialDates();
               setStartDate(dates.firstDay);
               setEndDate(dates.lastDay);
               setSelectedCategory('all');
               setSelectedPayer('all');
               setStatusFilter('all');
            }}
            togglePaid={togglePaid}
            onEdit={(t) => { setEditingTransaction(t); setIsFormOpen(true); }}
            onDelete={deleteTransaction}
          />
        );
      case 'profile': return <ProfileSettings currentUser={currentUser} onUpdate={setCurrentUser} />;
      case 'payers': return <PayerManager categories={categories} onAdd={addCategory} onDelete={deleteCategory} />;
      case 'cards': return <CardManager cards={cards} transactions={transactions} onAdd={addCard} onDelete={deleteCard} />;
      case 'reports': return <Reports transactions={transactions} categories={categories} />;
      case 'payer-reports': return <PayerReports transactions={transactions} categories={categories} />;
      case 'categories': return <CategoryManager categories={categories} onAdd={addCategory} onDelete={deleteCategory} />;
      default: return null;
    }
  };

  if (sessionLoading) return <div className="min-h-screen flex items-center justify-center"><div className="w-8 h-8 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div></div>;
  if (showLanding) return <LandingPage onGetStarted={() => setShowLanding(false)} />;
  if (!currentUser) return <AuthScreen onSelectUser={setCurrentUser} />;

  const viewTitles: Record<string, string> = {
    'dashboard': 'Visão Geral',
    'cards': 'Meus Cartões',
    'add-expense': 'Gerenciar Despesas',
    'add-income': 'Gerenciar Receitas',
    'categories': 'Minhas Categorias',
    'reports': 'Extrato Detalhado',
    'payers': 'Gerenciar Pagantes',
    'payer-reports': 'Extrato por Pagante',
    'profile': 'Configurações de Perfil'
  };

  const showNewTransactionButton = ['add-expense', 'add-income', 'cards', 'payers', 'categories'].includes(currentView);

  return (
    <div className="flex min-h-screen bg-slate-50/50">
      <Sidebar currentView={currentView} onViewChange={setCurrentView} currentUser={currentUser} onLogout={handleLogout} />
      <main className="flex-1 p-4 md:p-8 lg:p-12 w-full max-w-7xl mx-auto">
        <div className="flex justify-end mb-4 no-print">
           <button 
             onClick={() => setShowLanding(true)}
             className="text-[9px] font-bold text-slate-400 hover:text-indigo-600 uppercase tracking-widest flex items-center gap-1.5 px-3 py-1 bg-white rounded-full border border-slate-100"
           >
             <svg xmlns="http://www.w3.org/2000/svg" width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3"><path d="M12 2v8"/><path d="m4.93 4.93 7.07 7.07"/><path d="M2 12h8"/></svg>
             Página de Vendas (Demo)
           </button>
        </div>
        <header className="mb-14 flex flex-col items-center text-center">
          <h2 className="text-4xl font-extrabold text-slate-900 tracking-tight">{viewTitles[currentView]}</h2>
          {showNewTransactionButton && (
            <button 
              onClick={() => { setEditingTransaction(null); setIsFormOpen(true); }} 
              className="mt-8 bg-indigo-600 text-white px-8 py-4 rounded-xl shadow-xl hover:bg-indigo-700 transition-all font-bold text-xs uppercase tracking-widest flex items-center gap-2"
            >
              <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3"><path d="M12 5v14M5 12h14"/></svg>
              Novo Lançamento
            </button>
          )}
        </header>
        {isFormOpen && (
          <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[60] flex items-center justify-center p-4">
            <TransactionForm onAdd={addTransaction} onUpdate={updateTransaction} editingTransaction={editingTransaction} categories={categories} cards={cards} onCancel={() => { setIsFormOpen(false); setEditingTransaction(null); }} initialType={currentView === 'add-income' ? 'income' : 'expense'} />
          </div>
        )}
        {renderContent()}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Transaction, TransactionType, UserCategories, CreditCard, SplitDetails } from '../types';

interface TransactionFormProps {
  onAdd: (data: any) => Promise<boolean>;
  onUpdate?: (id: string, data: any) => Promise<boolean>;
  editingTransaction?: Transaction | null;
  categories: UserCategories;
  cards: CreditCard[];
  onCancel?: () => void;
  initialType?: TransactionType;
}

const TransactionForm: React.FC<TransactionFormProps> = ({ 
  onAdd, 
  onUpdate,
  editingTransaction,
  categories, 
  cards, 
  onCancel, 
  initialType = 'expense' 
}) => {
  const [description, setDescription] = useState('');
  const [amount, setAmount] = useState('');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [type, setType] = useState<TransactionType>(initialType);
  const [category, setCategory] = useState('');
  const [selectedCardId, setSelectedCardId] = useState('');
  const [installments, setInstallments] = useState(1);
  const [installmentMode, setInstallmentMode] = useState<'divide' | 'repeat'>('divide'); // 'divide' = ratear, 'repeat' = provisionar
  const [isSplit, setIsSplit] = useState(false);
  const [partnerPart, setPartnerPart] = useState('');
  const [partnerName, setPartnerName] = useState(categories.payers?.[0] || 'Isa');
  const [success, setSuccess] = useState(false);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (editingTransaction) {
      setDescription(editingTransaction.description);
      setAmount(editingTransaction.amount.toString());
      setDate(editingTransaction.date.split('T')[0]);
      setType(editingTransaction.type);
      setCategory(editingTransaction.category);
      setSelectedCardId(editingTransaction.card_id || '');
      setIsSplit(!!editingTransaction.is_split);
      if (editingTransaction.split_details) {
        setPartnerPart(editingTransaction.split_details.partnerPart.toString());
        setPartnerName(editingTransaction.split_details.partnerName);
      }
    } else {
      setDescription('');
      setAmount('');
      setDate(new Date().toISOString().split('T')[0]);
      setType(initialType);
      setCategory(categories[initialType][0] || 'Outros');
      setSelectedCardId('');
      setInstallments(1);
      setInstallmentMode('divide');
      setIsSplit(false);
      setPartnerPart('');
      setPartnerName(categories.payers?.[0] || 'Isa');
    }
  }, [editingTransaction, initialType, categories]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!description || !amount || !date || loading) return;

    setLoading(true);

    try {
      const inputValue = parseFloat(amount);
      const getSafeISO = (dateStr: string) => {
        const d = new Date(dateStr + 'T12:00:00');
        return d.toISOString();
      };

      if (editingTransaction && onUpdate) {
        const splitInfo: SplitDetails | undefined = isSplit ? {
          userPart: inputValue - (parseFloat(partnerPart) || 0),
          partnerPart: parseFloat(partnerPart) || 0,
          partnerName: partnerName
        } : undefined;

        const res = await onUpdate(editingTransaction.id, {
          description,
          amount: inputValue,
          type,
          category,
          date: getSafeISO(date),
          card_id: selectedCardId || null,
          is_split: isSplit,
          split_details: splitInfo,
          is_paid: editingTransaction.is_paid
        });

        if (res) {
          setSuccess(true);
          setTimeout(() => { if (onCancel) onCancel(); }, 800);
        } else {
          setLoading(false);
        }
        return;
      }

      const numInstallments = Math.max(1, installments);

      // Lógica de cálculo baseada no modo (Dividir vs Repetir)
      const amountPerInstallment = installmentMode === 'divide' 
        ? inputValue / numInstallments 
        : inputValue;

      const pPartInput = parseFloat(partnerPart) || 0;
      const pPartPerMonth = installmentMode === 'divide' 
        ? pPartInput / numInstallments 
        : pPartInput;

      const uPartPerMonth = amountPerInstallment - pPartPerMonth;

      const [year, month, day] = date.split('-').map(Number);
      let allSuccess = true;

      for (let i = 0; i < numInstallments; i++) {
        const targetDate = new Date(year, month - 1 + i, day, 12, 0, 0);
        const installmentLabel = numInstallments > 1 ? ` (${i + 1}/${numInstallments})` : '';

        const splitInfo: SplitDetails | undefined = isSplit ? {
          userPart: uPartPerMonth,
          partnerPart: pPartPerMonth,
          partnerName: partnerName
        } : undefined;

        const res = await onAdd({
          description: description + installmentLabel,
          amount: amountPerInstallment,
          type,
          category: category || 'Outros',
          date: targetDate.toISOString(),
          card_id: selectedCardId || null,
          is_split: isSplit,
          split_details: splitInfo,
          is_paid: false
        });
        if (!res) allSuccess = false;
      }

      if (allSuccess) {
        setSuccess(true);
        setTimeout(() => { if (onCancel) onCancel(); }, 1000);
      } else {
        setLoading(false);
        alert('Erro ao cadastrar lançamentos.');
      }
    } catch (err) {
      setLoading(false);
    }
  };

  const formatCurrency = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const inputClasses = "w-full h-[52px] px-5 bg-slate-50 border-2 border-transparent focus:border-indigo-100 focus:bg-white rounded-xl outline-none text-sm font-semibold text-slate-800 placeholder:text-slate-300 transition-all flex items-center";
  const labelClasses = "text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2 ml-1 whitespace-nowrap overflow-hidden text-ellipsis";

  return (
    <div className="bg-white p-6 md:p-10 rounded-[28px] shadow-2xl border border-slate-50 w-full max-w-xl mx-auto animate-in fade-in zoom-in duration-300 overflow-y-auto max-h-[95vh] relative scrollbar-hide">
      <div className="flex justify-between items-center mb-8">
        <h2 className="text-2xl font-black text-slate-900 tracking-tight">
          {editingTransaction ? 'Editar Lançamento' : 'Novo Lançamento'}
        </h2>
        {onCancel && (
          <button onClick={onCancel} className="p-2 text-slate-300 hover:text-slate-500 hover:bg-slate-50 rounded-full transition-all">
            <svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M18 6 6 18"/><path d="m6 6 12 12"/></svg>
          </button>
        )}
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        {!editingTransaction && (
          <div className="flex p-1 bg-slate-100/60 rounded-xl">
            {(['expense', 'income'] as const).map((t) => (
              <button
                key={t}
                type="button"
                onClick={() => { setType(t); setCategory(categories[t][0] || 'Outros'); }}
                className={`flex-1 py-3.5 rounded-lg text-[11px] font-black tracking-[0.15em] transition-all uppercase ${type === t ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-500'}`}
              >
                {t === 'expense' ? 'DESPESA' : 'RECEITA'}
              </button>
            ))}
          </div>
        )}

        <div className="space-y-5">
          <div>
            <label className={labelClasses}>Descrição</label>
            <input type="text" value={description} onChange={e => setDescription(e.target.value)} className={inputClasses} placeholder="Ex: Mercado" required />
          </div>

          <div className="grid grid-cols-2 gap-5">
            <div>
              <label className={labelClasses}>Valor {installmentMode === 'divide' ? 'Total' : 'Mensal'}</label>
              <input type="number" step="0.01" value={amount} onChange={e => setAmount(e.target.value)} className={inputClasses} placeholder="0,00" required />
            </div>
            <div>
              <label className={labelClasses}>Data da 1ª Parcela</label>
              <input type="date" value={date} onChange={e => setDate(e.target.value)} className={inputClasses} required />
            </div>
          </div>

          <div className="grid grid-cols-3 gap-5">
            <div>
              <label className={labelClasses}>Categoria</label>
              <select value={category} onChange={e => setCategory(e.target.value)} className={`${inputClasses} appearance-none pr-10 bg-[url('data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%2216%22%20height%3D%2216%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%23cbd5e1%22%20stroke-width%3D%223%22%3E%3Cpath%20d%3D%22m6%209%206%206%206-6%22%2F%3E%3C%2Fsvg%3E')] bg-[length:16px_16px] bg-[right_1rem_center] bg-no-repeat`}>
                {categories[type].map(cat => <option key={cat} value={cat}>{cat}</option>)}
              </select>
            </div>
            <div>
              <label className={labelClasses}>Cartão (Opcional)</label>
              <select value={selectedCardId} onChange={e => setSelectedCardId(e.target.value)} className={`${inputClasses} appearance-none pr-10 bg-[url('data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%2216%22%20height%3D%2216%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%23cbd5e1%22%20stroke-width%3D%223%22%3E%3Cpath%20d%3D%22m6%209%206%206%206-6%22%2F%3E%3C%2Fsvg%3E')] bg-[length:16px_16px] bg-[right_1rem_center] bg-no-repeat`}>
                <option value="">Dinheiro/Pix</option>
                {cards.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
              </select>
            </div>
            <div>
              <label className={`${labelClasses} text-indigo-500`}>Parcelas</label>
              <input 
                type="number" 
                min="1" 
                max="99" 
                value={installments} 
                disabled={!!editingTransaction}
                onChange={e => setInstallments(parseInt(e.target.value) || 1)} 
                className={`${inputClasses} border-indigo-50 bg-indigo-50/20 focus:border-indigo-200 focus:bg-white text-indigo-700 font-bold disabled:opacity-50 disabled:cursor-not-allowed`} 
              />
            </div>
          </div>

          {!editingTransaction && installments > 1 && (
            <div className="p-1 bg-slate-50 rounded-xl border border-slate-100 animate-in fade-in slide-in-from-top-1">
              <div className="flex gap-1">
                <button
                  type="button"
                  onClick={() => setInstallmentMode('divide')}
                  className={`flex-1 py-2 rounded-lg text-[9px] font-black uppercase tracking-widest transition-all ${installmentMode === 'divide' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}
                >
                  Dividir Total
                </button>
                <button
                  type="button"
                  onClick={() => setInstallmentMode('repeat')}
                  className={`flex-1 py-2 rounded-lg text-[9px] font-black uppercase tracking-widest transition-all ${installmentMode === 'repeat' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}
                >
                  Provisionar (Repetir)
                </button>
              </div>
            </div>
          )}

          {!editingTransaction && installments > 1 && amount && (
             <div className="px-5 py-4 bg-indigo-50/40 rounded-xl border border-dashed border-indigo-100 flex flex-col gap-1 animate-in fade-in">
               <div className="flex justify-between items-center">
                 <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest">Plano de {installmentMode === 'divide' ? 'Parcelamento' : 'Provisionamento'}:</p>
                 <p className="text-sm font-black text-indigo-600">
                    {installments}x de {formatCurrency(installmentMode === 'divide' ? parseFloat(amount) / installments : parseFloat(amount))}
                 </p>
               </div>
               <p className="text-[9px] font-bold text-slate-400 text-right">
                 Total do Lançamento: {formatCurrency(installmentMode === 'divide' ? parseFloat(amount) : parseFloat(amount) * installments)}
               </p>
             </div>
          )}

          {type === 'expense' && (
            <div className={`p-6 rounded-2xl border transition-all duration-300 ${isSplit ? 'bg-indigo-50/30 border-indigo-100' : 'bg-slate-50/50 border-slate-100'}`}>
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-4">
                   <div className={`w-11 h-11 rounded-xl flex items-center justify-center transition-all ${isSplit ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-100' : 'bg-slate-200 text-slate-400'}`}>
                     <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3"><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg>
                   </div>
                   <span className="text-xs font-black text-slate-800 uppercase tracking-[0.1em]">Dividir Gasto</span>
                </div>
                <button type="button" onClick={() => setIsSplit(!isSplit)} className={`w-14 h-7 rounded-full transition-all relative ${isSplit ? 'bg-indigo-600' : 'bg-slate-200'}`}>
                  <div className={`absolute top-1 w-5 h-5 bg-white rounded-full shadow-md transition-all ${isSplit ? 'left-8' : 'left-1'}`}></div>
                </button>
              </div>

              {isSplit && (
                <div className="mt-6 pt-6 border-t border-indigo-100/50 space-y-4 animate-in fade-in slide-in-from-top-2">
                  <div className="grid grid-cols-2 gap-5">
                    <div>
                      <label className="text-[10px] font-bold text-indigo-400 uppercase mb-2 block ml-1">Pagante</label>
                      <select 
                        value={partnerName} 
                        onChange={e => setPartnerName(e.target.value)} 
                        className="w-full h-11 px-4 bg-white rounded-lg border-2 border-indigo-50 text-xs font-bold text-slate-800 outline-none focus:border-indigo-100"
                      >
                        {categories.payers?.map(p => <option key={p} value={p}>{p}</option>)}
                      </select>
                    </div>
                    <div>
                      <label className="text-[10px] font-bold text-indigo-400 uppercase mb-2 block ml-1">Parte dele(a) {installmentMode === 'repeat' ? 'Mensal' : ''}</label>
                      <input type="number" step="0.01" value={partnerPart} onChange={e => setPartnerPart(e.target.value)} placeholder="0,00" className="w-full h-11 px-4 bg-white rounded-lg border-2 border-indigo-50 text-xs font-black text-slate-800 outline-none focus:border-indigo-100" />
                    </div>
                  </div>
                </div>
              )}
            </div>
          )}
        </div>

        <button 
          type="submit" 
          disabled={success || loading} 
          className={`w-full py-5 rounded-xl text-[12px] font-black uppercase tracking-[0.25em] transition-all text-white shadow-2xl transform active:scale-[0.97] mt-4 ${
            success ? 'bg-teal-500 shadow-teal-100' : 'bg-indigo-600 hover:bg-indigo-700 shadow-indigo-200 disabled:opacity-50'
          }`}
        >
          {loading ? 'Processando...' : (success ? '✓ Sucesso' : (editingTransaction ? 'Salvar Alterações' : 'Confirmar'))}
        </button>
      </form>
    </div>
  );
};

export default TransactionForm;

import React, { useState, useEffect } from 'react';
import { Transaction, TransactionType, UserCategories, CreditCard, SplitDetails } from '../types';

interface TransactionFormProps {
  onAdd: (data: any) => Promise<boolean>;
  onUpdate?: (id: string, data: any) => Promise<boolean>;
  editingTransaction?: Transaction | null;
  categories: UserCategories;
  cards: CreditCard[];
  onCancel?: () => void;
  initialType?: TransactionType;
}

const TransactionForm: React.FC<TransactionFormProps> = ({ 
  onAdd, 
  onUpdate,
  editingTransaction,
  categories, 
  cards, 
  onCancel, 
  initialType = 'expense' 
}) => {
  const [description, setDescription] = useState('');
  const [amount, setAmount] = useState('');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [type, setType] = useState<TransactionType>(initialType);
  const [category, setCategory] = useState('');
  const [selectedCardId, setSelectedCardId] = useState('');
  const [installments, setInstallments] = useState(1);
  const [installmentMode, setInstallmentMode] = useState<'divide' | 'repeat'>('divide');
  const [isSplit, setIsSplit] = useState(false);
  const [partnerPart, setPartnerPart] = useState('');
  const [partnerName, setPartnerName] = useState(categories.payers?.[0] || 'Isa');
  const [success, setSuccess] = useState(false);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (editingTransaction) {
      setDescription(editingTransaction.description);
      setAmount(editingTransaction.amount.toString());
      setDate(editingTransaction.date.split('T')[0]);
      setType(editingTransaction.type);
      setCategory(editingTransaction.category);
      setSelectedCardId(editingTransaction.card_id || '');
      setIsSplit(!!editingTransaction.is_split);
      if (editingTransaction.split_details) {
        setPartnerPart(editingTransaction.split_details.partnerPart.toString());
        setPartnerName(editingTransaction.split_details.partnerName);
      }
    } else {
      setDescription('');
      setAmount('');
      setDate(new Date().toISOString().split('T')[0]);
      setType(initialType);
      setCategory(categories[initialType][0] || 'Outros');
      setSelectedCardId('');
      setInstallments(1);
      setInstallmentMode('divide');
      setIsSplit(false);
      setPartnerPart('');
      setPartnerName(categories.payers?.[0] || 'Isa');
    }
  }, [editingTransaction, initialType, categories]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!description || !amount || !date || loading) return;
    setLoading(true);

    try {
      const inputValue = parseFloat(amount);
      const getSafeISO = (dateStr: string) => {
        const d = new Date(dateStr + 'T12:00:00');
        return d.toISOString();
      };

      if (editingTransaction && onUpdate) {
        const splitInfo: SplitDetails | undefined = isSplit ? {
          userPart: inputValue - (parseFloat(partnerPart) || 0),
          partnerPart: parseFloat(partnerPart) || 0,
          partnerName: partnerName
        } : undefined;

        const res = await onUpdate(editingTransaction.id, {
          description,
          amount: inputValue,
          type,
          category,
          date: getSafeISO(date),
          card_id: selectedCardId || null,
          is_split: isSplit,
          split_details: splitInfo,
          is_paid: editingTransaction.is_paid
        });

        if (res) {
          setSuccess(true);
          setTimeout(() => { if (onCancel) onCancel(); }, 800);
        } else {
          setLoading(false);
        }
        return;
      }

      const numInstallments = Math.max(1, installments);
      const amountPerInstallment = installmentMode === 'divide' ? inputValue / numInstallments : inputValue;
      const pPartInput = parseFloat(partnerPart) || 0;
      const pPartPerMonth = installmentMode === 'divide' ? pPartInput / numInstallments : pPartInput;
      const uPartPerMonth = amountPerInstallment - pPartPerMonth;

      const [year, month, day] = date.split('-').map(Number);
      let allSuccess = true;

      for (let i = 0; i < numInstallments; i++) {
        const targetDate = new Date(year, month - 1 + i, day, 12, 0, 0);
        const installmentLabel = numInstallments > 1 ? ` (${i + 1}/${numInstallments})` : '';
        const splitInfo: SplitDetails | undefined = isSplit ? {
          userPart: uPartPerMonth,
          partnerPart: pPartPerMonth,
          partnerName: partnerName
        } : undefined;

        const res = await onAdd({
          description: description + installmentLabel,
          amount: amountPerInstallment,
          type,
          category: category || 'Outros',
          date: targetDate.toISOString(),
          card_id: selectedCardId || null,
          is_split: isSplit,
          split_details: splitInfo,
          is_paid: false
        });
        if (!res) allSuccess = false;
      }

      if (allSuccess) {
        setSuccess(true);
        setTimeout(() => { if (onCancel) onCancel(); }, 1000);
      } else {
        setLoading(false);
      }
    } catch (err) {
      setLoading(false);
    }
  };

  const formatCurrency = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const inputClasses = "w-full h-[40px] px-4 bg-slate-50 border-2 border-transparent focus:border-indigo-100 focus:bg-white rounded-lg outline-none text-xs font-semibold text-slate-800 placeholder:text-slate-300 transition-all flex items-center";
  const labelClasses = "text-[9px] font-black text-slate-400 uppercase tracking-widest block mb-1.5 ml-1";

  return (
    <div className="bg-white p-6 md:p-8 rounded-[32px] shadow-2xl border border-slate-50 w-full max-w-4xl mx-auto animate-in fade-in zoom-in duration-300 relative">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-xl font-black text-slate-900 tracking-tight">
          {editingTransaction ? 'Editar Lançamento' : 'Novo Lançamento'}
        </h2>
        {onCancel && (
          <button onClick={onCancel} className="p-1.5 text-slate-300 hover:text-slate-500 hover:bg-slate-50 rounded-full transition-all">
            <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3"><path d="M18 6 6 18"/><path d="m6 6 12 12"/></svg>
          </button>
        )}
      </div>

      <form onSubmit={handleSubmit} className="space-y-4">
        {!editingTransaction && (
          <div className="flex p-1 bg-slate-100/60 rounded-xl max-w-sm">
            {(['expense', 'income'] as const).map((t) => (
              <button
                key={t}
                type="button"
                onClick={() => { setType(t); setCategory(categories[t][0] || 'Outros'); }}
                className={`flex-1 py-2 rounded-lg text-[10px] font-black tracking-widest transition-all uppercase ${type === t ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}
              >
                {t === 'expense' ? 'DESPESA' : 'RECEITA'}
              </button>
            ))}
          </div>
        )}

        <div className="space-y-4">
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-4">
            <div className="lg:col-span-8">
              <label className={labelClasses}>Descrição</label>
              <input type="text" value={description} onChange={e => setDescription(e.target.value)} className={inputClasses} placeholder="Ex: Mercado mensal" required />
            </div>
            <div className="lg:col-span-4">
              <label className={labelClasses}>Data da 1ª Parcela</label>
              <input type="date" value={date} onChange={e => setDate(e.target.value)} className={inputClasses} required />
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            <div>
              <label className={labelClasses}>Valor {installmentMode === 'divide' ? 'Total' : 'Mensal'}</label>
              <input type="number" step="0.01" value={amount} onChange={e => setAmount(e.target.value)} className={inputClasses} placeholder="0,00" required />
            </div>
            <div>
              <label className={labelClasses}>Categoria</label>
              <select value={category} onChange={e => setCategory(e.target.value)} className={`${inputClasses} appearance-none pr-8 bg-[url('data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%2214%22%20height%3D%2214%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%23cbd5e1%22%20stroke-width%3D%223%22%3E%3Cpath%20d%3D%22m6%209%206%206%206-6%22%2F%3E%3C%2Fsvg%3E')] bg-[length:14px_14px] bg-[right_0.75rem_center] bg-no-repeat`}>
                {categories[type].map(cat => <option key={cat} value={cat}>{cat}</option>)}
              </select>
            </div>
            <div>
              <label className={labelClasses}>Cartão</label>
              <select value={selectedCardId} onChange={e => setSelectedCardId(e.target.value)} className={`${inputClasses} appearance-none pr-8 bg-[url('data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%2214%22%20height%3D%2214%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%23cbd5e1%22%20stroke-width%3D%223%22%3E%3Cpath%20d%3D%22m6%209%206%206%206-6%22%2F%3E%3C%2Fsvg%3E')] bg-[length:14px_14px] bg-[right_0.75rem_center] bg-no-repeat`}>
                <option value="">Dinheiro/Pix</option>
                {cards.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
              </select>
            </div>
            <div>
              <label className={`${labelClasses} text-indigo-500`}>Parcelas</label>
              <input 
                type="number" 
                min="1" 
                max="99" 
                value={installments} 
                disabled={!!editingTransaction}
                onChange={e => setInstallments(parseInt(e.target.value) || 1)} 
                className={`${inputClasses} border-indigo-50 bg-indigo-50/20 font-bold text-indigo-700 disabled:opacity-50`} 
              />
            </div>
          </div>

          {!editingTransaction && installments > 1 && (
            <div className="flex flex-col lg:flex-row items-center gap-4 bg-slate-50 p-3 rounded-xl border border-slate-100">
              <div className="flex p-1 bg-white rounded-lg border border-slate-100 w-full lg:w-auto shrink-0">
                <button
                  type="button"
                  onClick={() => setInstallmentMode('divide')}
                  className={`px-4 py-1.5 rounded-md text-[8px] font-black uppercase tracking-widest transition-all ${installmentMode === 'divide' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-400'}`}
                >
                  Dividir Total
                </button>
                <button
                  type="button"
                  onClick={() => setInstallmentMode('repeat')}
                  className={`px-4 py-1.5 rounded-md text-[8px] font-black uppercase tracking-widest transition-all ${installmentMode === 'repeat' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-400'}`}
                >
                  Provisionar (Repetir)
                </button>
              </div>

              {amount && (
                <div className="flex-1 flex justify-between items-center px-4 border-l border-slate-200 ml-0 lg:ml-2">
                  <p className="text-[9px] font-bold text-slate-500 uppercase">
                    {installments}x de <span className="text-indigo-600 font-black">{formatCurrency(installmentMode === 'divide' ? parseFloat(amount) / installments : parseFloat(amount))}</span>
                  </p>
                  <p className="text-[9px] font-bold text-slate-400 uppercase">
                    Total: <span className="text-slate-600">{formatCurrency(installmentMode === 'divide' ? parseFloat(amount) : parseFloat(amount) * installments)}</span>
                  </p>
                </div>
              )}
            </div>
          )}

          {type === 'expense' && (
            <div className={`p-4 rounded-xl border transition-all duration-300 ${isSplit ? 'bg-indigo-50/20 border-indigo-100' : 'bg-slate-50/50 border-slate-100'}`}>
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-3">
                   <div className={`w-8 h-8 rounded-lg flex items-center justify-center transition-all ${isSplit ? 'bg-indigo-600 text-white' : 'bg-slate-200 text-slate-400'}`}>
                     <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3"><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/></svg>
                   </div>
                   <span className="text-[10px] font-black text-slate-800 uppercase tracking-widest">Dividir Gasto</span>
                </div>
                <button type="button" onClick={() => setIsSplit(!isSplit)} className={`w-12 h-6 rounded-full transition-all relative ${isSplit ? 'bg-indigo-600' : 'bg-slate-200'}`}>
                  <div className={`absolute top-1 w-4 h-4 bg-white rounded-full shadow-sm transition-all ${isSplit ? 'left-7' : 'left-1'}`}></div>
                </button>
              </div>

              {isSplit && (
                <div className="mt-4 pt-4 border-t border-indigo-100/50 flex flex-col md:flex-row gap-4 animate-in fade-in">
                  <div className="flex-1">
                    <label className="text-[8px] font-bold text-indigo-400 uppercase mb-1 block ml-1">Pagante</label>
                    <select 
                      value={partnerName} 
                      onChange={e => setPartnerName(e.target.value)} 
                      className="w-full h-9 px-3 bg-white rounded-lg border-2 border-indigo-50 text-[10px] font-bold text-slate-800 outline-none"
                    >
                      {categories.payers?.map(p => <option key={p} value={p}>{p}</option>)}
                    </select>
                  </div>
                  <div className="flex-1">
                    <label className="text-[8px] font-bold text-indigo-400 uppercase mb-1 block ml-1">Parte dele(a)</label>
                    <input type="number" step="0.01" value={partnerPart} onChange={e => setPartnerPart(e.target.value)} placeholder="0,00" className="w-full h-9 px-3 bg-white rounded-lg border-2 border-indigo-50 text-[10px] font-black text-slate-800 outline-none" />
                  </div>
                </div>
              )}
            </div>
          )}
        </div>

        <div className="pt-4">
          <button 
            type="submit" 
            disabled={success || loading} 
            className={`w-full py-4 rounded-xl text-[10px] font-black uppercase tracking-[0.2em] transition-all text-white shadow-xl transform active:scale-[0.98] ${
              success ? 'bg-teal-500' : 'bg-indigo-600 hover:bg-indigo-700 disabled:opacity-50'
            }`}
          >
            {loading ? 'Processando...' : (success ? '✓ Lançamento Realizado' : (editingTransaction ? 'Salvar Alterações' : 'Confirmar Lançamento'))}
          </button>
        </div>
      </form>
    </div>
  );
};

