            <div>
              <label className={`${labelClasses} text-indigo-500`}>Nº de Meses</label>
              <input type="number" min="1" max="99" value={installments} disabled={!!editingTransaction} onChange={e => setInstallments(parseInt(e.target.value) || 1)} className={`${inputClasses} border-indigo-50 bg-indigo-50/20 font-black text-indigo-700 disabled:opacity-50`} />
            </div>
          </div>

          {!editingTransaction && installments > 1 && (
            <div className="flex flex-col lg:flex-row items-center gap-4 bg-slate-50 p-3 rounded-xl border border-slate-100">
              <div className="flex p-1 bg-white rounded-lg border border-slate-100 w-full lg:w-auto">
                <button type="button" onClick={() => setInstallmentMode('divide')} className={`flex-1 lg:flex-none px-4 py-1.5 rounded-md text-[9px] font-black uppercase tracking-widest transition-all ${installmentMode === 'divide' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-400 hover:text-slate-600'}`}>Ratear Total</button>
                <button type="button" onClick={() => setInstallmentMode('repeat')} className={`flex-1 lg:flex-none px-4 py-1.5 rounded-md text-[9px] font-black uppercase tracking-widest transition-all ${installmentMode === 'repeat' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-400 hover:text-slate-600'}`}>Provisionar</button>
              </div>
              {amount && (
                <div className="flex-1 flex flex-col md:flex-row justify-between items-center w-full px-2 gap-4">
                  <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Plano: <span className="text-indigo-600">{installments}x</span> de <span className="text-indigo-600">{formatCurrency(installmentMode === 'divide' ? parseFloat(amount) / installments : parseFloat(amount))}</span></p>
                  <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Total: <span className="text-slate-900">{formatCurrency(installmentMode === 'divide' ? parseFloat(amount) : parseFloat(amount) * installments)}</span></p>
                </div>
              )}
            </div>
          )}

          {type === 'expense' && (
            <div className={`p-4 rounded-xl border transition-all duration-300 ${isSplit ? 'bg-indigo-50/20 border-indigo-100' : 'bg-slate-50/50 border-slate-100'}`}>
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-3">
                   <div className={`w-8 h-8 rounded-lg flex items-center justify-center transition-all ${isSplit ? 'bg-indigo-600 text-white shadow-md' : 'bg-slate-200 text-slate-400'}`}>
                     <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3"><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/></svg>
                   </div>
                   <span className="text-[10px] font-black text-slate-800 uppercase tracking-widest">Dividir com Parceiro(a)</span>
                </div>
                <button type="button" onClick={() => setIsSplit(!isSplit)} className={`w-10 h-5 rounded-full transition-all relative ${isSplit ? 'bg-indigo-600' : 'bg-slate-200'}`}>
                  <div className={`absolute top-0.5 w-4 h-4 bg-white rounded-full shadow-sm transition-all ${isSplit ? 'left-5.5' : 'left-0.5'}`}></div>
                </button>
              </div>
              {isSplit && (
                <div className="mt-4 pt-4 border-t border-indigo-100/50 grid grid-cols-1 md:grid-cols-2 gap-4 animate-in fade-in">
                  <div>
                    <label className="text-[8px] font-black text-indigo-400 uppercase mb-1 block ml-1">Quem vai pagar?</label>
                    <select value={partnerName} onChange={e => setPartnerName(e.target.value)} className="w-full h-9 px-3 bg-white rounded-lg border-2 border-indigo-50 text-[10px] font-black text-slate-800 outline-none appearance-none">
                      {categories.payers?.map(p => <option key={p} value={p}>{p}</option>)}
                    </select>
                  </div>
                  <div>
                    <label className="text-[8px] font-black text-indigo-400 uppercase mb-1 block ml-1">Parte Dele(a)</label>
                    <input type="number" step="0.01" value={partnerPart} onChange={e => setPartnerPart(e.target.value)} placeholder="0,00" className="w-full h-9 px-3 bg-white rounded-lg border-2 border-indigo-50 text-[10px] font-black text-slate-800 outline-none" />
                  </div>
                </div>
              )}
            </div>
          )}
        </div>

        <div className="pt-2">
          <button type="submit" disabled={success || loading} className={`w-full py-3.5 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all text-white shadow-xl transform active:scale-[0.98] ${success ? 'bg-teal-500 shadow-teal-100' : 'bg-indigo-600 hover:bg-indigo-700 shadow-indigo-100 disabled:opacity-50'}`}>
            {loading ? 'Sincronizando...' : (success ? '✓ Lançamento Concluído' : (editingTransaction ? 'Atualizar Registro' : 'Confirmar Lançamento'))}
          </button>
        </div>
      </form>
    </div>
  );
};

