                className="w-full bg-slate-50 border-none rounded-md px-3 py-3 text-xs font-bold text-indigo-600 outline-none"
              />
            </div>
            <div>
              <label className="text-[9px] font-bold text-slate-400 uppercase mb-2 block">Fim</label>
              <input 
                type="date" 
                value={endDate} 
                onChange={(e) => setEndDate(e.target.value)}
