        systemInstruction: "Você é um consultor financeiro sênior especializado em finanças pessoais. Sua missão é analisar dados e fornecer conselhos ultra-personalizados e acionáveis.",
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            analysis: {
