import React, { useState } from 'react';
import { supabase } from '../services/supabaseClient';
import { Transaction, CreditCard, UserCategories } from '../types';

interface DataManagementProps {
  userId: string;
  transactions: Transaction[];
  cards: CreditCard[];
  categories: UserCategories;
  onRefresh: () => void;
}

const DataManagement: React.FC<DataManagementProps> = ({ userId, transactions, cards, categories, onRefresh }) => {
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState<{ text: string, type: 'success' | 'error' } | null>(null);

  const handleExportJSON = () => {
    try {
      const dataToExport = {
        version: "1.0",
        exportDate: new Date().toISOString(),
        categories,
        cards,
        transactions
      };

      const blob = new Blob([JSON.stringify(dataToExport, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `backup_financepro_${new Date().toISOString().split('T')[0]}.json`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);

      setMessage({ text: 'Backup JSON exportado com sucesso!', type: 'success' });
    } catch (err) {
      setMessage({ text: 'Erro ao exportar JSON.', type: 'error' });
    }
  };

  const handleExportSQL = () => {
    try {
      let sql = `-- Script de Migração FinancePro\n`;
      sql += `-- Gerado em: ${new Date().toLocaleString('pt-BR')}\n\n`;
      sql += `BEGIN;\n\n`;

      // 1. Perfil / Categorias
      const catsJson = JSON.stringify(categories).replace(/'/g, "''");
      sql += `-- 1. Atualizar Categorias do Perfil\n`;
      sql += `UPDATE profiles SET categories = '${catsJson}'::jsonb WHERE id = auth.uid();\n\n`;

      // 2. Cartões
      if (cards.length > 0) {
        sql += `-- 2. Inserir Cartões\n`;
        cards.forEach(card => {
          const name = card.name.replace(/'/g, "''");
          sql += `INSERT INTO credit_cards (id, user_id, name, color, credit_limit, closing_day, due_day) \n`;
          sql += `VALUES ('${card.id}', auth.uid(), '${name}', '${card.color}', ${card.credit_limit}, ${card.closing_day}, ${card.due_day}) \n`;
          sql += `ON CONFLICT (id) DO NOTHING;\n`;
        });
        sql += `\n`;
      }

      // 3. Transações
      if (transactions.length > 0) {
        sql += `-- 3. Inserir Transações\n`;
        transactions.forEach(t => {
          const desc = t.description.replace(/'/g, "''");
          const cardId = t.card_id ? `'${t.card_id}'` : 'NULL';
          const pDate = t.payment_date ? `'${t.payment_date}'` : 'NULL';
          const splitDetails = t.split_details ? `'${JSON.stringify(t.split_details).replace(/'/g, "''")}'::jsonb` : 'NULL';

          sql += `INSERT INTO transactions (id, user_id, description, amount, type, category, date, payment_date, card_id, is_split, split_details, is_paid) \n`;
          sql += `VALUES ('${t.id}', auth.uid(), '${desc}', ${t.amount}, '${t.type}', '${t.category}', '${t.date}', ${pDate}, ${cardId}, ${t.is_split}, ${splitDetails}, ${t.is_paid}) \n`;
          sql += `ON CONFLICT (id) DO NOTHING;\n`;
        });
      }

      sql += `\nCOMMIT;`;

      const blob = new Blob([sql], { type: 'text/plain' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `migracao_supabase_${new Date().toISOString().split('T')[0]}.sql`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);

      setMessage({ text: 'Script SQL gerado! Rode-o no Editor SQL do seu novo projeto Supabase.', type: 'success' });
    } catch (err) {
      setMessage({ text: 'Erro ao gerar script SQL.', type: 'error' });
    }
  };

  const handleImport = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const confirmImport = window.confirm("Atenção: A importação irá ADICIONAR os dados do arquivo ao seu banco atual. Deseja continuar?");
    if (!confirmImport) return;

    setLoading(true);
    setMessage(null);

    try {
      const reader = new FileReader();
      reader.onload = async (e) => {
        try {
          const importedData = JSON.parse(e.target?.result as string);

          if (importedData.categories) {
            await supabase.from('profiles').update({ categories: importedData.categories }).eq('id', userId);
          }

          const cardIdMap: Record<string, string> = {};
          if (importedData.cards && Array.isArray(importedData.cards)) {
            for (const card of importedData.cards) {
              const { id: oldId, ...cardWithoutId } = card;
              const { data, error } = await supabase.from('credit_cards').insert([{ ...cardWithoutId, user_id: userId }]).select().single();
              if (data) cardIdMap[oldId] = data.id;
            }
          }

          if (importedData.transactions && Array.isArray(importedData.transactions)) {
            const transactionsToInsert = importedData.transactions.map((t: any) => {
              const { id, ...transWithoutId } = t;
              return {
                ...transWithoutId,
                user_id: userId,
                card_id: t.card_id ? (cardIdMap[t.card_id] || null) : null
              };
            });

            const batchSize = 50;
            for (let i = 0; i < transactionsToInsert.length; i += batchSize) {
              const batch = transactionsToInsert.slice(i, i + batchSize);
              const { error } = await supabase.from('transactions').insert(batch);
              if (error) throw error;
            }
          }

          setMessage({ text: 'Importação concluída com sucesso! Recarregando...', type: 'success' });
          setTimeout(() => { onRefresh(); setLoading(false); }, 2000);
        } catch (err: any) {
          setMessage({ text: `Erro ao processar arquivo: ${err.message}`, type: 'error' });
          setLoading(false);
        }
      };
      reader.readAsText(file);
    } catch (err) {
      setMessage({ text: 'Erro ao ler arquivo.', type: 'error' });
      setLoading(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto space-y-8 animate-in fade-in duration-500">
      <div className="bg-white p-8 rounded-2xl border border-slate-100 shadow-sm">
        <div className="mb-8">
          <h2 className="text-xl font-black text-slate-900 tracking-tight">Portabilidade de Dados</h2>
          <p className="text-xs font-medium text-slate-400 mt-1">Exportação direta para o banco de dados ou backup local.</p>
        </div>

        {message && (
          <div className={`mb-8 p-4 rounded-xl border ${message.type === 'success' ? 'bg-teal-50 border-teal-100 text-teal-700' : 'bg-rose-50 border-rose-100 text-rose-700'} text-xs font-bold uppercase tracking-widest text-center`}>
            {message.text}
          </div>
        )}

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {/* SQL Export */}
          <div className="p-6 rounded-2xl border-2 border-indigo-100 bg-indigo-50/10 flex flex-col items-center text-center group hover:bg-indigo-50/30 transition-all">
            <div className="w-10 h-10 bg-indigo-600 rounded-lg flex items-center justify-center text-white mb-4 shadow-lg shadow-indigo-100">
              <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" x2="12" y1="3" y2="15"/></svg>
            </div>
            <h3 className="text-[10px] font-black text-indigo-700 uppercase tracking-widest mb-2">Exportar SQL</h3>
            <p className="text-[9px] text-slate-400 font-bold uppercase tracking-tight mb-4 leading-tight">Gera script para rodar no Editor SQL do Supabase.</p>
            <button 
              onClick={handleExportSQL}
              className="w-full py-2.5 bg-indigo-600 text-white rounded-lg text-[9px] font-black uppercase tracking-widest transition-all hover:bg-indigo-700 active:scale-95"
            >
              Gerar Script
            </button>
          </div>

          {/* JSON Export */}
          <div className="p-6 rounded-2xl border-2 border-slate-50 bg-slate-50/30 flex flex-col items-center text-center group hover:border-slate-200 transition-all">
            <div className="w-10 h-10 bg-white border border-slate-100 rounded-lg flex items-center justify-center text-slate-400 mb-4">
              <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="12" x2="12" y1="18" y2="12"/><line x1="9" x2="15" y1="15" y2="15"/></svg>
            </div>
            <h3 className="text-[10px] font-black text-slate-800 uppercase tracking-widest mb-2">Backup JSON</h3>
            <p className="text-[9px] text-slate-400 font-bold uppercase tracking-tight mb-4 leading-tight">Backup universal para importar via interface do app.</p>
            <button 
              onClick={handleExportJSON}
              className="w-full py-2.5 bg-slate-800 text-white rounded-lg text-[9px] font-black uppercase tracking-widest transition-all hover:bg-slate-900 active:scale-95"
            >
              Baixar JSON
            </button>
          </div>

          {/* Import */}
          <div className="p-6 rounded-2xl border-2 border-dashed border-slate-200 bg-white flex flex-col items-center text-center group hover:border-indigo-200 transition-all">
            <div className="w-10 h-10 bg-teal-50 rounded-lg flex items-center justify-center text-teal-600 mb-4">
              <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" x2="12" y1="15" y2="3"/></svg>
            </div>
            <h3 className="text-[10px] font-black text-slate-800 uppercase tracking-widest mb-2">Importar JSON</h3>
            <p className="text-[9px] text-slate-400 font-bold uppercase tracking-tight mb-4 leading-tight">Restaura transações de um arquivo backup anterior.</p>
            <label className={`w-full py-2.5 bg-teal-600 text-white rounded-lg text-[9px] font-black uppercase tracking-widest text-center cursor-pointer hover:bg-teal-700 transition-all ${loading ? 'opacity-50' : ''}`}>
              {loading ? 'Lendo...' : 'Selecionar'}
              <input type="file" accept=".json" onChange={handleImport} disabled={loading} className="hidden" />
            </label>
          </div>
        </div>

        <div className="mt-12 p-4 bg-amber-50 rounded-xl border border-amber-100 flex gap-4">
           <div className="text-amber-500 shrink-0">
             <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3Z"/><line x1="12" x2="12" y1="9" y2="13"/><line x1="12" x2="12.01" y1="17" y2="17"/></svg>
           </div>
           <div>
             <p className="text-[10px] font-black text-amber-700 uppercase tracking-tight mb-1">Como usar o Script SQL:</p>
             <p className="text-[9px] font-bold text-amber-600 uppercase tracking-tight leading-relaxed">
               1. Baixe o arquivo .sql | 2. No seu novo Supabase, vá em "SQL Editor" | 3. Cole o conteúdo do arquivo e clique em "RUN". Seus dados serão vinculados ao usuário logado no momento da execução.
             </p>
           </div>
        </div>
      </div>
    </div>
  );
};

