import React, { useState } from 'react';
import { supabase } from '../services/supabaseClient';
import { User } from '../types';
import Logo from './Logo';

interface AuthScreenProps {
  onSelectUser: (user: User) => void;
}

const AuthScreen: React.FC<AuthScreenProps> = ({ onSelectUser }) => {
  const [isSignUp, setIsSignUp] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [successMsg, setSuccessMsg] = useState('');

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    setSuccessMsg('');

    try {
      if (isSignUp) {
        const { data, error: signUpError } = await supabase.auth.signUp({
          email,
          password,
          options: {
            data: { name }
          }
        });

        if (signUpError) throw signUpError;

        if (data.user && data.session) {
          // Se o e-mail de confirmação estiver DESATIVADO no Supabase, ele loga direto
          onSelectUser({
            id: data.user.id,
            name: name,
            avatarColor: '#4f46e5'
          });
        } else if (data.user) {
          // Se o e-mail de confirmação estiver ATIVADO
          setSuccessMsg('Conta criada! Verifique seu e-mail para confirmar o cadastro. (Dica: Você pode desativar essa exigência no painel do Supabase em Authentication > Settings)');
        }
      } else {
        const { data, error: signInError } = await supabase.auth.signInWithPassword({
          email,
          password
        });

        if (signInError) {
          if (signInError.message.includes('Email not confirmed')) {
            throw new Error('E-mail ainda não confirmado. Verifique sua caixa de entrada ou desative a confirmação no painel do Supabase.');
          }
          throw signInError;
        }

        const { data: profile } = await supabase
          .from('profiles')
          .select('name, avatar_color')
          .eq('id', data.user.id)
          .maybeSingle();

        if (data.user) {
          onSelectUser({
            id: data.user.id,
            name: profile?.name || data.user.email?.split('@')[0] || 'Usuário',
            avatarColor: profile?.avatar_color || '#4f46e5'
          });
        }
      }
    } catch (err: any) {
      setError(err.message || 'Erro na autenticação');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 animate-in fade-in duration-500">
      <div className="w-full max-w-xl text-center mb-10">
