  onSelectUser: (user: User) => void;
}

const AuthScreen: React.FC<AuthScreenProps> = ({ onSelectUser }) => {
  const [isSignUp, setIsSignUp] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [loading, setLoading] = useState(false);
  const [cooldown, setCooldown] = useState(0);
  const [error, setError] = useState('');
  const [successMsg, setSuccessMsg] = useState('');

  useEffect(() => {
    let timer: any;
    if (cooldown > 0) {
      timer = setInterval(() => setCooldown(prev => prev - 1), 1000);
    }
    return () => clearInterval(timer);
  }, [cooldown]);

  const triggerResend = async (targetEmail: string) => {
    try {
      const { error: resendError } = await supabase.auth.resend({
        type: 'signup',
        email: targetEmail,
        options: { emailRedirectTo: window.location.origin }
      });
      if (resendError) throw resendError;
      setSuccessMsg('E-mail de confirmação enviado automaticamente! Verifique sua caixa de entrada.');
      setCooldown(60);
    } catch (err: any) {
      setError('O usuário já existe, mas houve um erro ao tentar reenviar o e-mail de confirmação.');
    }
  };

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    setSuccessMsg('');

    try {
      if (isSignUp) {
        const { data, error: signUpError } = await supabase.auth.signUp({
          email,
          password,
          options: {
            data: { name },
            emailRedirectTo: window.location.origin,
          }
        });

        if (signUpError) {
          // SEGREDO AQUI: Se o usuário já existe mas não está confirmado, 
          // nós forçamos o reenvio do e-mail para ser automático.
          if (signUpError.message.toLowerCase().includes('already registered')) {
            await triggerResend(email);
            return;
          }
          throw signUpError;
        }

        if (data.user && data.session) {
          onSelectUser({
            id: data.user.id,
            name: name,
            avatarColor: '#4f46e5'
          });
        } else {
          setSuccessMsg(`Cadastro realizado! O link de confirmação foi enviado para ${email}.`);
          setCooldown(30);
        }
      } else {
        const { data, error: signInError } = await supabase.auth.signInWithPassword({
          email,
          password
        });

        if (signInError) {
          if (signInError.message.toLowerCase().includes('email not confirmed')) {
            setError('Seu e-mail ainda não foi confirmado.');
            // Tenta reenviar automaticamente se o login falhar por falta de confirmação
            await triggerResend(email);
            return;
          }
          throw signInError;
        }

        const { data: profile } = await supabase
          .from('profiles')
          .select('name, avatar_color')
          .eq('id', data.user.id)
          .maybeSingle();

        onSelectUser({
          id: data.user.id,
          name: profile?.name || data.user.email?.split('@')[0] || 'Usuário',
          avatarColor: profile?.avatar_color || '#4f46e5'
        });
      }
    } catch (err: any) {
      setError(err.message || 'Erro na autenticação');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 animate-in fade-in duration-500">
      <div className="w-full max-w-xl text-center mb-10">
