                      </div>
                    </td>
                    <td className="py-4 px-6">
                       <span className="text-[10px] font-black text-slate-400 uppercase tracking-tight">{card ? card.name : 'DINHEIRO/PIX'}</span>
                    </td>
                    <td className="py-4 px-6">
                      {t.is_split && t.split_details ? (
                        <div className="space-y-0.5">
                           <p className="text-[8px] font-black text-slate-400 uppercase tracking-tighter">VOCÊ: <span className="text-slate-900">{formatCurrency(t.split_details.userPart)}</span></p>
                           <p className="text-[8px] font-black text-indigo-400 uppercase tracking-tighter">{t.split_details.partnerName.toUpperCase()}: <span className="text-indigo-600">{formatCurrency(t.split_details.partnerPart)}</span></p>
                        </div>
                      ) : (
                        <span className="text-[9px] font-black text-slate-300 uppercase italic">SOLO</span>
                      )}
                    </td>
                    <td className={`py-4 px-6 text-right text-sm font-black ${t.type === 'income' ? 'text-teal-600' : 'text-rose-500'}`}>{formatCurrency(t.amount)}</td>
                    <td className="py-4 px-6">
                      <div className="flex justify-center gap-1">
                        <button onClick={() => { setEditingTransaction(t); setIsFormOpen(true); }} className="p-2 text-indigo-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-all"><svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z"/></svg></button>
                        <button onClick={() => deleteTransaction(t.id)} className="p-2 text-rose-300 hover:text-rose-500 hover:bg-rose-50 rounded-lg transition-all"><svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M3 6h18"/><path d="M19 6v14c0 1-1 2-2 2H7c-1 0-2-1-2-2V6"/></svg></button>
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
          {filtered.length === 0 && (
            <div className="py-20 text-center text-slate-300 font-black text-[10px] uppercase tracking-widest">Nenhum lançamento encontrado</div>
          )}
        </div>
      </div>
    );
  };

  const renderContent = () => {
    switch (currentView) {
      case 'dashboard':
        return (
          <div className="space-y-6 md:space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-24 md:pb-0">
            {dbError && (
              <div className="p-5 bg-rose-600 rounded-[32px] shadow-2xl shadow-rose-100 flex flex-col md:flex-row items-center gap-6 border border-rose-500 animate-in zoom-in-95">
                <div className="w-12 h-12 bg-white/20 rounded-2xl flex items-center justify-center text-white shrink-0">
                   <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3"><path d="m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3Z"/><line x1="12" x2="12" y1="9" y2="13"/><line x1="12" x2="12.01" y1="17" y2="17"/></svg>
                </div>
                <div className="flex-1 text-center md:text-left">
                  <p className="text-xs font-black text-white uppercase tracking-widest leading-relaxed">{dbError}</p>
                </div>
                <button 
                  onClick={() => setCurrentView('data-management')}
                  className="px-6 py-3 bg-white text-rose-600 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-rose-50 transition-all shadow-lg active:scale-95"
                >
                  Como Corrigir?
                </button>
              </div>
            )}

            <div className="mb-6 text-center md:text-left">
              <h1 className="text-xl md:text-2xl font-bold text-slate-900 tracking-tight">
                Olá, <span className="text-indigo-600">{currentUser?.name.split(' ')[0]}!</span> 👋
              </h1>
              <p className="text-xs font-medium text-slate-400 mt-1">Sua situação financeira hoje</p>
            </div>

            {renderFilterBar()}

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
              <div className="lg:col-span-8 space-y-6">
                <SummaryCards summary={dashboardData.summary} />
                <AIInsights transactions={dashboardData.filteredTransactions} />
                <Charts transactions={dashboardData.filteredTransactions} />
              </div>
              <div className="lg:col-span-4">
                <div className="bg-white p-5 rounded-3xl shadow-sm border border-slate-100 h-full">
                  <h2 className="text-[10px] font-black text-slate-900 tracking-tight uppercase mb-6 border-b border-slate-50 pb-3">Extrato por Pagante</h2>
                  <div className="space-y-3">
                    {dashboardData.cardSummaries.map((card: any) => (
                      <div key={card.cardId || 'cash'} className="p-4 bg-slate-50/40 rounded-2xl border border-slate-100">
                        <div className="flex justify-between items-start mb-4">
                          <h4 className="font-black text-[10px] text-slate-900 uppercase tracking-widest">{card.description}</h4>
                        </div>
                        <div className="pt-3 border-t border-slate-100/60 space-y-2">
                          <div className="flex justify-between items-baseline"><span className="text-[8px] font-black text-slate-400 uppercase tracking-tighter">VOCÊ</span><span className="text-xs font-black text-slate-900">{formatCurrency(card.userPart)}</span></div>
                          {Object.entries(card.others).map(([name, val]: [any, any]) => (
                            <div key={name} className="flex justify-between items-baseline"><span className="text-[8px] font-black text-indigo-400 uppercase tracking-tighter">{name}</span><span className="text-xs font-black text-indigo-600">{formatCurrency(val as number)}</span></div>
                          ))}
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </div>
          </div>
        );
      case 'add-expense': return renderTransactionManagement('expense');
      case 'add-income': return renderTransactionManagement('income');
      case 'payers': return <PayerManager categories={categories} onAdd={addCategory} onDelete={deleteCategory} />;
      case 'cards': return <CardManager cards={cards} transactions={transactions} onAdd={addCard} onDelete={deleteCard} />;
      case 'reports': return <Reports transactions={transactions} categories={categories} />;
      case 'payer-reports': return <PayerReports transactions={transactions} categories={categories} />;
      case 'categories': return <CategoryManager categories={categories} onAdd={addCategory} onDelete={deleteCategory} />;
      case 'data-management': return <DataManagement userId={currentUser!.id} transactions={transactions} cards={cards} categories={categories} onRefresh={() => window.location.reload()} />;
    }
  };

  if (sessionLoading) return <div className="min-h-screen flex items-center justify-center"><div className="w-8 h-8 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div></div>;
  if (!currentUser) return <AuthScreen onSelectUser={setCurrentUser} />;

  const viewTitles: Record<string, string> = {
    'dashboard': 'Visão Geral', 'cards': 'Meus Cartões', 'add-expense': 'Despesas', 'add-income': 'Receitas', 'categories': 'Categorias', 'reports': 'Extrato', 'payers': 'Pagantes', 'payer-reports': 'Acerto de Contas', 'data-management': 'Configurações Avançadas'
  };

  const showNewTransactionButton = !['dashboard', 'reports', 'payer-reports', 'data-management'].includes(currentView);

  return (
    <div className="flex min-h-screen bg-slate-50/50">
      <Sidebar currentView={currentView} onViewChange={setCurrentView} currentUser={currentUser} onLogout={handleLogout} />
      <main className="flex-1 p-4 md:p-8 w-full max-w-7xl mx-auto">
        <header className="mb-6 md:mb-10 flex flex-col items-center text-center">
          <h2 className="text-2xl md:text-3xl font-black text-slate-900 tracking-tight uppercase">{viewTitles[currentView]}</h2>
          {showNewTransactionButton && (
            <button onClick={() => { setEditingTransaction(null); setIsFormOpen(true); }} className="mt-4 bg-indigo-600 text-white px-8 py-3 rounded-2xl shadow-xl hover:bg-indigo-700 transition-all font-black text-[10px] uppercase tracking-widest flex items-center gap-2 active:scale-95">
              <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4"><path d="M12 5v14M5 12h14"/></svg>
              Novo Lançamento
            </button>
          )}
        </header>

        {isFormOpen && (
          <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[60] overflow-y-auto p-4 md:flex md:justify-center md:items-start py-8 md:py-16">
            <div className="w-full max-w-4xl mx-auto">
              <TransactionForm onAdd={addTransaction} onUpdate={updateTransaction} editingTransaction={editingTransaction} categories={categories} cards={cards} onCancel={() => setIsFormOpen(false)} initialType={currentView === 'add-income' ? 'income' : 'expense'} />
            </div>
          </div>
        )}

        {/* Modal Sutil de Data de Pagamento */}
        {isPaymentModalOpen && (
          <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[100] p-4 flex justify-center items-center">
             <div className="bg-white p-6 rounded-[24px] shadow-2xl border border-slate-100 w-full max-w-sm animate-in zoom-in-95 duration-200">
                <div className="flex items-center gap-3 mb-5">
                  <div className="w-10 h-10 bg-teal-50 text-teal-600 rounded-xl flex items-center justify-center">
                    <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20Z"/><path d="m9 12 2 2 4-4"/></svg>
                  </div>
                  <h3 className="text-lg font-black text-slate-900 tracking-tight">Confirmar Pagamento</h3>
                </div>

                <div className="mb-6">
                   <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest block mb-1.5 ml-1">Quando foi pago?</label>
                   <input 
                     type="date" 
                     value={selectedPaymentDate} 
                     onChange={(e) => setSelectedPaymentDate(e.target.value)} 
                     className="w-full h-12 px-4 bg-slate-50 border-none rounded-xl text-sm font-black text-slate-800 outline-none focus:ring-2 focus:ring-teal-100 transition-all"
                   />
                </div>

                <div className="flex gap-3">
                  <button 
                    onClick={() => setIsPaymentModalOpen(false)} 
                    className="flex-1 py-3 text-[10px] font-black uppercase text-slate-400 hover:text-slate-600 transition-all"
                  >
                    Cancelar
                  </button>
                  <button 
                    onClick={confirmPayment} 
                    className="flex-[2] py-3 bg-teal-500 text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg shadow-teal-100 hover:bg-teal-600 active:scale-95 transition-all"
                  >
                    Confirmar Pagamento
                  </button>
                </div>
             </div>
          </div>
        )}

        <div className="w-full max-w-full mx-auto">
          {renderContent()}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Transaction, UserCategories, Summary, CreditCard } from '../types';
import { supabase } from '../services/supabaseClient';
import { getCategoryIcon } from '../utils/icons';

interface ReportsProps {
  transactions: Transaction[];
  categories: UserCategories;
}

const Reports: React.FC<ReportsProps> = ({ transactions, categories }) => {
  const [cards, setCards] = useState<CreditCard[]>([]);

  React.useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session?.user) {
        supabase.from('credit_cards').select('*').eq('user_id', session.user.id).then(({ data }) => {
          if (data) setCards(data);
        });
      }
    });
  }, []);

  const getInitialDates = () => {
    const now = new Date();
    const firstDay = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().split('T')[0];
    const lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0).toISOString().split('T')[0];
    return { firstDay, lastDay };
  };

  const { firstDay: initStart, lastDay: initEnd } = getInitialDates();
  const [filter, setFilter] = useState<'all' | 'income' | 'expense'>('all');
  const [startDate, setStartDate] = useState(initStart);
  const [endDate, setEndDate] = useState(initEnd);
  const [selectedCategory, setSelectedCategory] = useState('all');
  const [selectedPayer, setSelectedPayer] = useState('all');
  const [statusFilter, setStatusFilter] = useState<'all' | 'paid' | 'pending'>('all');

  const { filteredTransactions, summary } = useMemo(() => {
    const filtered = transactions
      .filter(t => {
        if (filter !== 'all' && t.type !== filter) return false;
        const tDate = t.date.split('T')[0];
        if (tDate < startDate || tDate > endDate) return false;
        if (selectedCategory !== 'all' && t.category !== selectedCategory) return false;
        if (statusFilter === 'paid' && !t.is_paid) return false;
        if (statusFilter === 'pending' && t.is_paid) return false;

        if (selectedPayer === 'individual') return true;
        if (selectedPayer !== 'all') return t.is_split && t.split_details?.partnerName === selectedPayer;

        return true;
      })
      .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    const stats = filtered.reduce((acc, t) => {
      let amt = Number(t.amount);
      if (selectedPayer === 'individual' && t.is_split && t.split_details) {
        amt = Number(t.split_details.userPart);
      } else if (selectedPayer !== 'all' && t.is_split && t.split_details) {
        amt = Number(t.split_details.partnerPart);
      }

      if (t.type === 'income') {
        acc.income += amt;
        acc.balance += amt;
      } else {
        acc.expenses += amt;
        acc.balance -= amt;
      }
      return acc;
    }, { balance: 0, income: 0, expenses: 0 } as Summary);

    return { filteredTransactions: filtered, summary: stats };
  }, [transactions, filter, startDate, endDate, selectedCategory, selectedPayer, statusFilter]);

  const formatCurrency = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const resetFilters = () => {
    const { firstDay, lastDay } = getInitialDates();
    setFilter('all');
    setStartDate(firstDay);
    setEndDate(lastDay);
    setSelectedCategory('all');
    setSelectedPayer('all');
    setStatusFilter('all');
  };

  const exportToExcel = () => {
    const headers = ["Vencimento", "Pagamento", "Descrição", "Categoria", "Tipo", "Valor", "Status"];
    const rows = filteredTransactions.map(t => {
      const card = cards.find(c => c.id === t.card_id);
      let val = t.amount;
      if (selectedPayer === 'individual' && t.is_split && t.split_details) {
        val = t.split_details.userPart;
      } else if (selectedPayer !== 'all' && t.is_split && t.split_details) {
        val = t.split_details.partnerPart;
      }

      return [
        new Date(t.date).toLocaleDateString('pt-BR'),
        t.payment_date ? new Date(t.payment_date).toLocaleDateString('pt-BR') : '-',
        t.description.replace(/;/g, ','),
        t.category,
        t.type === 'income' ? 'Entrada' : 'Saída',
        val.toString().replace('.', ','),
        t.is_paid ? 'Pago' : 'Pendente'
      ];
    });

    const csvContent = "data:text/csv;charset=utf-8,\uFEFF" 
      + headers.join(";") + "\n" 
      + rows.map(e => e.join(";")).join("\n");

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `extrato_${startDate}_ate_${endDate}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-4 md:space-y-6 pb-20 md:pb-0">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-3 md:gap-4 print:mb-8 print:border-b print:pb-6">
        <div className="bg-white p-4 md:p-7 rounded-lg shadow-sm border border-slate-50 flex flex-col justify-center">
          <p className="text-slate-400 text-[9px] font-bold uppercase tracking-[0.1em] mb-1">SALDO</p>
          <h3 className="text-xl md:text-3xl font-bold text-slate-900">{formatCurrency(summary.balance)}</h3>
        </div>
        <div className="bg-white p-4 md:p-7 rounded-lg shadow-sm border border-slate-50 flex flex-col justify-center">
          <p className="text-slate-400 text-[9px] font-bold uppercase tracking-[0.1em] mb-1">ENTRADAS</p>
          <h3 className="text-xl md:text-3xl font-bold text-teal-600">{formatCurrency(summary.income)}</h3>
        </div>
        <div className="bg-white p-4 md:p-7 rounded-lg shadow-sm border border-slate-50 flex flex-col justify-center">
          <p className="text-slate-400 text-[9px] font-bold uppercase tracking-[0.1em] mb-1">SAÍDAS</p>
          <h3 className="text-xl md:text-3xl font-bold text-rose-500">{formatCurrency(summary.expenses)}</h3>
        </div>
      </div>

      <div className="bg-white p-4 rounded-lg shadow-sm border border-slate-100 no-print">
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-6 gap-3 items-end">
          <div className="col-span-1 sm:col-span-2 grid grid-cols-2 gap-2">
            <div>
              <label className="text-[9px] font-bold text-slate-400 uppercase mb-1.5 block">Início</label>
              <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="w-full bg-slate-50 border-none rounded-md px-3 py-2 text-xs font-bold text-indigo-600 outline-none" />
            </div>
            <div>
              <label className="text-[9px] font-bold text-slate-400 uppercase mb-1.5 block">Fim</label>
              <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="w-full bg-slate-50 border-none rounded-md px-3 py-2 text-xs font-bold text-indigo-600 outline-none" />
            </div>
          </div>
          <div>
            <label className="text-[9px] font-bold text-slate-400 uppercase mb-1.5 block">Categoria</label>
            <select value={selectedCategory} onChange={(e) => setSelectedCategory(e.target.value)} className="w-full bg-slate-50 border-none rounded-md px-4 py-2 text-xs font-bold text-slate-700 outline-none">
              <option value="all">Todas</option>
              {[...categories.expense, ...categories.income].sort().map(cat => (
                <option key={cat} value={cat}>{cat}</option>
              ))}
            </select>
          </div>
          <div>
            <label className="text-[9px] font-bold text-slate-400 uppercase mb-1.5 block">Pagante</label>
            <select value={selectedPayer} onChange={(e) => setSelectedPayer(e.target.value)} className="w-full bg-slate-50 border-none rounded-md px-4 py-2 text-xs font-bold text-slate-700 outline-none">
              <option value="all">Todos</option>
              <option value="individual">Apenas Eu</option>
              {categories.payers?.map(p => <option key={p} value={p}>{p}</option>)}
            </select>
          </div>
          <button onClick={resetFilters} className="w-full py-2 text-[9px] font-bold text-slate-400 uppercase hover:text-indigo-600 transition-colors">Resetar</button>
        </div>
      </div>

      <div className="bg-white p-4 md:p-8 rounded-lg shadow-sm border border-slate-100 overflow-hidden">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-6">
          <div>
            <h2 className="text-lg md:text-2xl font-bold text-slate-900 tracking-tight">Extrato Detalhado</h2>
            <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest mt-0.5">Filtro aplicado pelo período selecionado</p>
          </div>
          <div className="flex gap-2 no-print w-full md:w-auto">
            <button onClick={exportToExcel} className="flex-1 md:flex-none bg-emerald-50 text-emerald-700 px-4 py-2 rounded-md text-[9px] font-bold uppercase transition-all border border-emerald-100">Exportar</button>
            <button onClick={() => window.print()} className="flex-1 md:flex-none bg-slate-900 text-white px-4 py-2 rounded-md text-[9px] font-bold uppercase transition-all shadow-lg">PDF</button>
          </div>
        </div>

        {/* View para Desktop */}
        <div className="hidden md:block overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="text-[10px] font-bold text-slate-400 uppercase tracking-widest border-b-2 border-slate-50 bg-slate-50/20">
                <th className="py-4 px-4 text-center w-24">Status</th>
                <th className="py-4 px-4">Datas</th>
                <th className="py-4 px-4">Descrição / Categoria</th>
                <th className="py-4 px-4">Pagamento</th>
                <th className="py-4 px-4 text-right">Valor</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredTransactions.map((t) => {
                const card = cards.find(c => c.id === t.card_id);
                let displayVal = t.amount;
                if (selectedPayer === 'individual' && t.is_split && t.split_details) { displayVal = t.split_details.userPart; }
                else if (selectedPayer !== 'all' && t.is_split && t.split_details) { displayVal = t.split_details.partnerPart; }

                return (
                  <tr key={t.id} className="hover:bg-slate-50/40 transition-colors">
                    <td className="py-4 px-4 text-center">
                      <span className={`inline-block px-2 py-1 rounded-[4px] text-[8px] font-black uppercase tracking-widest border ${t.is_paid ? 'bg-teal-50 border-teal-100 text-teal-600' : 'bg-amber-50 border-amber-100 text-amber-600'}`}>
                        {t.is_paid ? 'Pago' : 'Pendente'}
                      </span>
                    </td>
                    <td className="py-4 px-4">
                      <p className="text-[11px] font-bold text-slate-500 uppercase tracking-tighter">Venc: {new Date(t.date).toLocaleDateString('pt-BR')}</p>
                      {t.payment_date && <p className="text-[9px] font-black text-teal-600 uppercase tracking-tighter">Pago: {new Date(t.payment_date).toLocaleDateString('pt-BR')}</p>}
                    </td>
                    <td className="py-4 px-4">
                      <div className="flex items-center gap-3">
                        <div className="w-8 h-8 rounded-xl bg-slate-50 text-slate-500 flex items-center justify-center border border-slate-100 shrink-0">
                          {getCategoryIcon(t.category)}
                        </div>
                        <div>
                          <p className="text-xs font-bold text-slate-900 leading-tight">{t.description}</p>
                          <span className="text-[9px] text-indigo-400 font-bold uppercase tracking-tighter">{t.category}</span>
                        </div>
                      </div>
                    </td>
                    <td className="py-4 px-4 text-[10px] font-bold text-slate-500 uppercase">{card ? card.name : 'Dinheiro/Pix'}</td>
                    <td className={`py-4 px-4 text-right font-bold text-sm ${t.type === 'income' ? 'text-teal-600' : 'text-rose-500'} ${!t.is_paid ? 'opacity-50' : ''}`}>
                      {formatCurrency(displayVal)}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>

        {/* View para Mobile */}
        <div className="md:hidden space-y-4">
          {filteredTransactions.map((t) => {
            const card = cards.find(c => c.id === t.card_id);
            let displayVal = t.amount;
            if (selectedPayer === 'individual' && t.is_split && t.split_details) { displayVal = t.split_details.userPart; }
            else if (selectedPayer !== 'all' && t.is_split && t.split_details) { displayVal = t.split_details.partnerPart; }

            return (
              <div key={t.id} className="flex flex-col gap-2 p-3 bg-slate-50/50 rounded-lg border border-transparent hover:border-slate-100 transition-all">
                <div className="flex justify-between items-center">
                   <div className="flex flex-col">
                     <span className="text-[8px] font-bold text-slate-400 uppercase">Venc: {new Date(t.date).toLocaleDateString('pt-BR')}</span>
                     {t.payment_date && <span className="text-[8px] font-black text-teal-600 uppercase">Pago: {new Date(t.payment_date).toLocaleDateString('pt-BR')}</span>}
                   </div>
                   <span className={`px-2 py-0.5 rounded text-[7px] font-black uppercase tracking-widest border ${t.is_paid ? 'bg-teal-50 border-teal-100 text-teal-600' : 'bg-amber-50 border-amber-100 text-amber-600'}`}>
                     {t.is_paid ? 'Pago' : 'Pendente'}
                   </span>
                </div>
                <div className="flex justify-between items-end">
                   <div className="flex items-center gap-3">
                      <div className="w-8 h-8 rounded-xl bg-white text-slate-500 border border-slate-100 flex items-center justify-center shrink-0 print:hidden">
                        {getCategoryIcon(t.category)}
                      </div>
                      <div>
                        <p className="text-xs font-bold text-slate-800 leading-tight mb-0.5">{t.description}</p>
                        <p className="text-[8px] text-indigo-500 font-black uppercase tracking-tighter">{t.category} • {card ? card.name : 'Dinheiro'}</p>
                      </div>
                   </div>
                   <p className={`text-sm font-black ${t.type === 'income' ? 'text-teal-600' : 'text-rose-500'} ${!t.is_paid ? 'opacity-50' : ''}`}>
                     {formatCurrency(displayVal)}
                   </p>
                </div>
              </div>
            );
          })}
        </div>

        {filteredTransactions.length === 0 && (
          <div className="py-16 text-center text-slate-300 text-[10px] font-bold uppercase tracking-widest italic">Nenhum registro no período</div>
        )}
      </div>
    </div>
  );
};

export default Reports;

import React from 'react';

export const getCategoryStyles = (category: string) => {
  const cat = category.toLowerCase();

  if (cat.includes('alimento') || cat.includes('comer') || cat.includes('restaurante') || cat.includes('mercado') || cat.includes('food')) {
    return { bg: 'bg-emerald-50', text: 'text-emerald-600', border: 'border-emerald-100' };
  }
  if (cat.includes('casa') || cat.includes('moradia') || cat.includes('aluguel') || cat.includes('luz') || cat.includes('água') || cat.includes('rent')) {
    return { bg: 'bg-blue-50', text: 'text-blue-600', border: 'border-blue-100' };
  }
  if (cat.includes('transporte') || cat.includes('carro') || cat.includes('uber') || cat.includes('combustível') || cat.includes('transport')) {
    return { bg: 'bg-orange-50', text: 'text-orange-600', border: 'border-orange-100' };
  }
  if (cat.includes('saúde') || cat.includes('médico') || cat.includes('farmácia') || cat.includes('health')) {
    return { bg: 'bg-rose-50', text: 'text-rose-600', border: 'border-rose-100' };
  }
  if (cat.includes('lazer') || cat.includes('diversão') || cat.includes('viagem') || cat.includes('entertainment')) {
    return { bg: 'bg-purple-50', text: 'text-purple-600', border: 'border-purple-100' };
  }
  if (cat.includes('salário') || cat.includes('pagamento') || cat.includes('salary') || cat.includes('freelance')) {
    return { bg: 'bg-teal-50', text: 'text-teal-600', border: 'border-teal-100' };
  }
  if (cat.includes('invest') || cat.includes('bolsa') || cat.includes('investments')) {
    return { bg: 'bg-cyan-50', text: 'text-cyan-600', border: 'border-cyan-100' };
  }
  if (cat.includes('cartão') || cat.includes('shopping') || cat.includes('compras')) {
    return { bg: 'bg-pink-50', text: 'text-pink-600', border: 'border-pink-100' };
  }
  if (cat.includes('educação') || cat.includes('estudo') || cat.includes('curso')) {
    return { bg: 'bg-amber-50', text: 'text-amber-600', border: 'border-amber-100' };
  }

  return { bg: 'bg-slate-50', text: 'text-slate-500', border: 'border-slate-100' };
};

