export const getCategoryStyles = (category: string, userCategories?: UserCategories) => {
  // 1. Verifica se existe cor personalizada no cadastro do usuário
  if (userCategories?.colors && userCategories.colors[category]) {
    const customColor = userCategories.colors[category];
    return { 
      bg: '', // Usado via inline style
      text: '', // Usado via inline style
      border: '', // Usado via inline style
      customColor: customColor,
      isCustom: true
    };
  }

  // 2. Fallback para detecção automática por nome (Tailwind Classes)
  const cat = category.toLowerCase();

  if (cat.includes('alimento') || cat.includes('comer') || cat.includes('restaurante') || cat.includes('mercado') || cat.includes('food')) {
    return { bg: 'bg-emerald-50', text: 'text-emerald-600', border: 'border-emerald-100', isCustom: false };
  }
  if (cat.includes('casa') || cat.includes('moradia') || cat.includes('aluguel') || cat.includes('luz') || cat.includes('água') || cat.includes('rent')) {
    return { bg: 'bg-blue-50', text: 'text-blue-600', border: 'border-blue-100', isCustom: false };
  }
  if (cat.includes('transporte') || cat.includes('carro') || cat.includes('uber') || cat.includes('combustível') || cat.includes('transport')) {
    return { bg: 'bg-orange-50', text: 'text-orange-600', border: 'border-orange-100', isCustom: false };
  }
  if (cat.includes('saúde') || cat.includes('médico') || cat.includes('farmácia') || cat.includes('health')) {
    return { bg: 'bg-rose-50', text: 'text-rose-600', border: 'border-rose-100', isCustom: false };
  }
  if (cat.includes('lazer') || cat.includes('diversão') || cat.includes('viagem') || cat.includes('entertainment')) {
    return { bg: 'bg-purple-50', text: 'text-purple-600', border: 'border-purple-100', isCustom: false };
  }
  if (cat.includes('salário') || cat.includes('pagamento') || cat.includes('salary') || cat.includes('freelance')) {
    return { bg: 'bg-teal-50', text: 'text-teal-600', border: 'border-teal-100', isCustom: false };
  }
  if (cat.includes('invest') || cat.includes('bolsa') || cat.includes('investments')) {
    return { bg: 'bg-cyan-50', text: 'text-cyan-600', border: 'border-cyan-100', isCustom: false };
  }
  if (cat.includes('cartão') || cat.includes('shopping') || cat.includes('compras')) {
    return { bg: 'bg-pink-50', text: 'text-pink-600', border: 'border-pink-100', isCustom: false };
  }
  if (cat.includes('educação') || cat.includes('estudo') || cat.includes('curso')) {
    return { bg: 'bg-amber-50', text: 'text-amber-600', border: 'border-amber-100', isCustom: false };
  }

  return { bg: 'bg-slate-50', text: 'text-slate-500', border: 'border-slate-100', isCustom: false };
};

