    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((event, session) => {
      if (session?.user) fetchProfile(session.user);
      else { setCurrentUser(null); setSessionLoading(false); }
    });

    return () => subscription.unsubscribe();
  }, []);

  const fetchProfile = async (authUser: any) => {
    try {
      const { data: profile } = await supabase
        .from('profiles')
        .select('name, avatar_color, categories')
        .eq('id', authUser.id)
        .maybeSingle();

      if (profile) {
        setCurrentUser({ id: authUser.id, name: profile.name, avatarColor: profile.avatar_color });
        setDbError(null);
      } else {
        const userName = authUser.user_metadata?.name || authUser.email?.split('@')[0] || 'Usuário';
        const defaultCategories = {
          expense: ['Alimentação', 'Moradia', 'Transporte', 'Lazer', 'Saúde', 'Cartão', 'Outros'],
          income: ['Salário', 'Freelance', 'Investimentos', 'Presentes', 'Outros'],
          payers: [userName.split(' ')[0] || 'Eu'],
          colors: {}
        };

        const { error: insertError } = await supabase.from('profiles').upsert({
          id: authUser.id,
          name: userName,
          avatar_color: '#4f46e5',
          categories: defaultCategories,
          updated_at: new Date().toISOString()
        });

        if (insertError) {
          setDbError("Atenção: Seu banco está bloqueando a gravação (Regra de INSERT faltando).");
        } else {
          setCurrentUser({ id: authUser.id, name: userName, avatarColor: '#4f46e5' });
          setDbError(null);
        }
      }
    } catch (err) {
      console.error(err);
    } finally {
      setSessionLoading(false);
    }
  };

  const handleLogout = async () => { 
    await supabase.auth.signOut(); 
    setCurrentUser(null); 
    setCurrentView('dashboard'); 
  };

  const formatCurrency = (val: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const handleTogglePaidRequest = (id: string, isPaid: boolean) => {
    if (!isPaid) {
      setPendingPaymentId(id);
      setSelectedPaymentDate(new Date().toISOString().split('T')[0]);
      setIsPaymentModalOpen(true);
    } else {
      if (window.confirm("Deseja marcar este lançamento como Pendente?")) {
        togglePaid(id, true, null);
      }
    }
  };

  const confirmPayment = () => {
    if (pendingPaymentId) {
      const paymentISO = new Date(selectedPaymentDate + 'T12:00:00').toISOString();
      togglePaid(pendingPaymentId, false, paymentISO);
      setIsPaymentModalOpen(false);
      setPendingPaymentId(null);
    }
  };

  const dashboardData = useMemo(() => {
    const filtered = transactions.filter(t => {
      const tDate = t.date.split('T')[0];
      const matchesDate = tDate >= startDate && tDate <= endDate;
      const matchesType = selectedType === 'all' || t.type === selectedType;
      const matchesCategory = selectedCategory === 'all' || t.category === selectedCategory;
      let matchesPayer = true;
      if (selectedPayer === 'individual') matchesPayer = true;
      else if (selectedPayer !== 'all') matchesPayer = t.is_split && t.split_details?.partnerName === selectedPayer;
      return matchesDate && matchesType && matchesCategory && matchesPayer;
    });

    const summary: Summary = filtered.reduce((acc, t) => {
      let amt = Number(t.amount);
      if (selectedPayer === 'individual' && t.is_split && t.split_details) {
        amt = Number(t.split_details.userPart);
      } else if (selectedPayer !== 'all' && t.is_split && t.split_details) {
        amt = Number(t.split_details.partnerPart);
      }

      if (t.type === 'income') { acc.income += amt; acc.balance += amt; }
      else { acc.expenses += amt; acc.balance -= amt; }
      return acc;
    }, { balance: 0, income: 0, expenses: 0 });

    const groupedByCard = filtered.reduce((acc: any, t) => {
      if (t.type !== 'expense') return acc;
      const cardKey = t.card_id || 'no-card';
      if (!acc[cardKey]) {
        acc[cardKey] = {
          cardId: t.card_id,
          total: 0,
          userPart: 0,
          others: {},
          hasPending: false,
          description: t.card_id ? cards.find(c => c.id === t.card_id)?.name : 'Dinheiro/Pix'
        };
      }
      const amt = Number(t.amount);
      acc[cardKey].total += amt;
      if (!t.is_paid) acc[cardKey].hasPending = true;
      if (t.is_split && t.split_details) {
        acc[cardKey].userPart += Number(t.split_details.userPart);
        const pName = t.split_details.partnerName || 'Indefinido';
        acc[cardKey].others[pName] = (acc[cardKey].others[pName] || 0) + Number(t.split_details.partnerPart);
      } else {
        acc[cardKey].userPart += amt;
      }
      return acc;
    }, {});

    return { filteredTransactions: filtered, summary, cardSummaries: Object.values(groupedByCard) };
  }, [transactions, startDate, endDate, selectedType, selectedCategory, selectedPayer, cards]);

  const renderFilterBar = () => {
    let catsToShow: string[] = [];
    if (selectedType === 'all') {
      catsToShow = Array.from(new Set([...categories.expense, ...categories.income])).sort();
    } else if (selectedType === 'expense') {
      catsToShow = [...categories.expense].sort();
    } else {
      catsToShow = [...categories.income].sort();
    }

    return (
      <div className="bg-white p-4 rounded-xl border border-slate-100 shadow-sm mb-6">
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-6 gap-3 items-end">
          <div className="col-span-1 sm:col-span-2 grid grid-cols-2 gap-2">
            <div>
              <label className="text-[9px] font-bold text-slate-400 uppercase mb-1.5 block">Início</label>
              <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="w-full bg-slate-50 border-none rounded-md px-3 py-2 text-xs font-bold text-indigo-600 outline-none" />
            </div>
            <div>
              <label className="text-[9px] font-bold text-slate-400 uppercase mb-1.5 block">Fim</label>
              <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="w-full bg-slate-50 border-none rounded-md px-3 py-2 text-xs font-bold text-indigo-600 outline-none" />
            </div>
          </div>
          <div>
            <label className="text-[9px] font-bold text-slate-400 uppercase mb-1.5 block">Tipo</label>
            <select value={selectedType} onChange={(e) => { setSelectedType(e.target.value as any); setSelectedCategory('all'); }} className="w-full bg-slate-50 border-none rounded-md px-4 py-2 text-xs font-bold text-slate-700 outline-none">
              <option value="all">Todos</option>
              <option value="expense">Saídas</option>
              <option value="income">Entradas</option>
            </select>
          </div>
          <div>
            <label className="text-[9px] font-bold text-slate-400 uppercase mb-1.5 block">Categoria</label>
            <select value={selectedCategory} onChange={(e) => setSelectedCategory(e.target.value)} className="w-full bg-slate-50 border-none rounded-md px-4 py-2 text-xs font-bold text-slate-700 outline-none">
              <option value="all">Todas</option>
              {catsToShow.map(cat => <option key={cat} value={cat}>{cat}</option>)}
            </select>
          </div>
          <button 
            onClick={() => { 
              const { firstDay, lastDay } = getInitialDates();
              setStartDate(firstDay); 
              setEndDate(lastDay); 
              setSelectedType('all');
              setSelectedCategory('all'); 
            }} 
            className="w-full py-2 text-[10px] font-bold text-slate-400 uppercase hover:text-indigo-600 transition-colors"
          >
            Limpar Filtros
          </button>
        </div>
      </div>
    );
  };

  const renderTransactionManagement = (type: TransactionType) => {
    const filtered = transactions
      .filter(t => {
        if (t.type !== type) return false;
        const tDate = t.date.split('T')[0];
        if (tDate < startDate || tDate > endDate) return false;
        if (selectedCategory !== 'all' && t.category !== selectedCategory) return false;
        if (statusFilter === 'paid' && !t.is_paid) return false;
        if (statusFilter === 'pending' && t.is_paid) return false;
        return true;
      })
      .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    return (
      <div className="space-y-4 max-w-full mx-auto pb-24 md:pb-0">
        {renderFilterBar()}

        <div className="hidden md:block bg-white rounded-2xl border border-slate-100 shadow-sm overflow-hidden">
          <table className="w-full text-left">
            <thead>
              <tr className="text-[10px] font-black text-slate-400 uppercase tracking-widest border-b border-slate-50 bg-slate-50/30">
                <th className="py-4 px-6 text-center">Status</th>
                <th className="py-4 px-6">Vencimento</th>
                <th className="py-4 px-6">Descrição / Categoria</th>
                <th className="py-4 px-6">Pagamento</th>
                <th className="py-4 px-6">Divisão</th>
                <th className="py-4 px-6 text-right">Valor</th>
                <th className="py-4 px-6 w-24 text-center">Ações</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filtered.map((t) => {
                const card = t.card_id ? cards.find(c => c.id === t.card_id) : null;
                const styles = getCategoryStyles(t.category, categories);
                const inlineStyles = styles.isCustom ? {
                  backgroundColor: `${styles.customColor}15`,
                  color: styles.customColor,
                  borderColor: `${styles.customColor}30`
                } : {};

                return (
                  <tr key={t.id} className="hover:bg-slate-50/50 transition-colors group">
                    <td className="py-4 px-6">
                      <button onClick={() => handleTogglePaidRequest(t.id, t.is_paid)} className={`w-6 h-6 rounded-lg flex items-center justify-center border-2 mx-auto transition-all ${t.is_paid ? 'bg-teal-500 border-teal-500 text-white' : 'bg-white border-slate-200 text-slate-200 hover:border-teal-300'}`}>
                        <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4"><path d="M20 6 9 17l-5-5"/></svg>
                      </button>
                    </td>
                    <td className="py-4 px-6">
                      <p className="text-[11px] text-slate-900 font-black whitespace-nowrap">{new Date(t.date).toLocaleDateString('pt-BR')}</p>
                      {t.is_paid && t.payment_date && (
                        <p className="text-[9px] text-teal-500 font-bold uppercase tracking-tighter whitespace-nowrap">Pago: {new Date(t.payment_date).toLocaleDateString('pt-BR')}</p>
                      )}
                    </td>
                    <td className="py-4 px-6">
                      <div className="flex items-center gap-3">
                        <div 
                          className={`w-9 h-9 rounded-xl flex items-center justify-center border ${!styles.isCustom ? `${styles.bg} ${styles.text} ${styles.border}` : ''}`}
                          style={inlineStyles}
                        >
                          {getCategoryIcon(t.category, 18)}
                        </div>
                        <div className="min-w-0">
                          <p className="text-xs font-black text-slate-900 leading-tight truncate">{t.description}</p>
                          <span className={`text-[9px] font-black uppercase tracking-widest ${styles.isCustom ? '' : styles.text}`} style={styles.isCustom ? { color: styles.customColor } : {}}>{t.category}</span>
                        </div>
                      </div>
                    </td>
                    <td className="py-4 px-6">
                       <span className="text-[10px] font-black text-slate-400 uppercase tracking-tight">{card ? card.name : 'DINHEIRO/PIX'}</span>
                    </td>
                    <td className="py-4 px-6">
                      {t.is_split && t.split_details ? (
                        <div className="space-y-0.5">
                           <p className="text-[8px] font-black text-slate-400 uppercase tracking-tighter">VOCÊ: <span className="text-slate-900">{formatCurrency(t.split_details.userPart)}</span></p>
                           <p className="text-[8px] font-black text-indigo-400 uppercase tracking-tighter">{t.split_details.partnerName.toUpperCase()}: <span className="text-indigo-600">{formatCurrency(t.split_details.partnerPart)}</span></p>
                        </div>
                      ) : (
                        <span className="text-[9px] font-black text-slate-300 uppercase italic">SOLO</span>
                      )}
                    </td>
                    <td className={`py-4 px-6 text-right text-sm font-black ${t.type === 'income' ? 'text-teal-600' : 'text-rose-500'}`}>{formatCurrency(t.amount)}</td>
                    <td className="py-4 px-6">
                      <div className="flex justify-center gap-1">
                        <button onClick={() => { setEditingTransaction(t); setIsFormOpen(true); }} className="p-2 text-indigo-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-all"><svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z"/></svg></button>
                        <button onClick={() => deleteTransaction(t.id)} className="p-2 text-rose-300 hover:text-rose-500 hover:bg-rose-50 rounded-lg transition-all"><svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M3 6h18"/><path d="M19 6v14c0 1-1 2-2 2H7c-1 0-2-1-2-2V6"/></svg></button>
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
          {filtered.length === 0 && (
            <div className="py-20 text-center text-slate-300 font-black text-[10px] uppercase tracking-widest">Nenhum lançamento encontrado</div>
          )}
        </div>
      </div>
    );
  };

  const renderContent = () => {
    switch (currentView) {
      case 'dashboard':
        return (
          <div className="space-y-6 md:space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-24 md:pb-0">
            {dbError && (
              <div className="p-5 bg-rose-600 rounded-[32px] shadow-2xl shadow-rose-100 flex flex-col md:flex-row items-center gap-6 border border-rose-500 animate-in zoom-in-95">
                <div className="w-12 h-12 bg-white/20 rounded-2xl flex items-center justify-center text-white shrink-0">
                   <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3"><path d="m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3Z"/><line x1="12" x2="12" y1="9" y2="13"/><line x1="12" x2="12.01" y1="17" y2="17"/></svg>
                </div>
                <div className="flex-1 text-center md:text-left">
                  <p className="text-xs font-black text-white uppercase tracking-widest leading-relaxed">{dbError}</p>
                </div>
                <button 
                  onClick={() => setCurrentView('data-management')}
                  className="px-6 py-3 bg-white text-rose-600 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-rose-50 transition-all shadow-lg active:scale-95"
                >
                  Como Corrigir?
                </button>
              </div>
            )}

            <div className="mb-6 text-center md:text-left">
              <h1 className="text-xl md:text-2xl font-bold text-slate-900 tracking-tight">
                Olá, <span className="text-indigo-600">{currentUser?.name.split(' ')[0]}!</span> 👋
              </h1>
              <p className="text-xs font-medium text-slate-400 mt-1">Sua situação financeira hoje</p>
            </div>

            {renderFilterBar()}

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
              <div className="lg:col-span-8 space-y-6">
                <SummaryCards summary={dashboardData.summary} />
                <AIInsights transactions={dashboardData.filteredTransactions} />
                <Charts transactions={dashboardData.filteredTransactions} />
              </div>
              <div className="lg:col-span-4">
                <div className="bg-white p-5 rounded-3xl shadow-sm border border-slate-100 h-full">
                  <h2 className="text-[10px] font-black text-slate-900 tracking-tight uppercase mb-6 border-b border-slate-50 pb-3">Extrato por Pagante</h2>
                  <div className="space-y-3">
                    {dashboardData.cardSummaries.map((card: any) => (
                      <div key={card.cardId || 'cash'} className="p-4 bg-slate-50/40 rounded-2xl border border-slate-100">
                        <div className="flex justify-between items-start mb-4">
                          <h4 className="font-black text-[10px] text-slate-900 uppercase tracking-widest">{card.description}</h4>
                        </div>
                        <div className="pt-3 border-t border-slate-100/60 space-y-2">
                          <div className="flex justify-between items-baseline"><span className="text-[8px] font-black text-slate-400 uppercase tracking-tighter">VOCÊ</span><span className="text-xs font-black text-slate-900">{formatCurrency(card.userPart)}</span></div>
                          {Object.entries(card.others).map(([name, val]: [any, any]) => (
                            <div key={name} className="flex justify-between items-baseline"><span className="text-[8px] font-black text-indigo-400 uppercase tracking-tighter">{name}</span><span className="text-xs font-black text-indigo-600">{formatCurrency(val as number)}</span></div>
                          ))}
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </div>
          </div>
        );
      case 'add-expense': return renderTransactionManagement('expense');
      case 'add-income': return renderTransactionManagement('income');
      case 'payers': return <PayerManager categories={categories} onAdd={addCategory} onDelete={deleteCategory} />;
      case 'cards': return <CardManager cards={cards} transactions={transactions} onAdd={addCard} onDelete={deleteCard} />;
      case 'reports': return <Reports transactions={transactions} categories={categories} />;
      case 'payer-reports': return <PayerReports transactions={transactions} categories={categories} />;
      case 'categories': return <CategoryManager categories={categories} onAdd={addCategory} onDelete={deleteCategory} />;
      case 'data-management': return <DataManagement userId={currentUser!.id} transactions={transactions} cards={cards} categories={categories} onRefresh={() => window.location.reload()} />;
    }
  };

  if (sessionLoading) return <div className="min-h-screen flex items-center justify-center"><div className="w-8 h-8 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div></div>;
  if (!currentUser) return <AuthScreen onSelectUser={setCurrentUser} />;

  const viewTitles: Record<string, string> = {
    'dashboard': 'Visão Geral', 'cards': 'Meus Cartões', 'add-expense': 'Despesas', 'add-income': 'Receitas', 'categories': 'Categorias', 'reports': 'Extrato', 'payers': 'Pagantes', 'payer-reports': 'Acerto de Contas', 'data-management': 'Configurações Avançadas'
  };

  const showNewTransactionButton = !['dashboard', 'reports', 'payer-reports', 'data-management'].includes(currentView);

  return (
    <div className="flex min-h-screen bg-slate-50/50">
      <Sidebar currentView={currentView} onViewChange={setCurrentView} currentUser={currentUser} onLogout={handleLogout} />
      <main className="flex-1 p-4 md:p-8 w-full max-w-7xl mx-auto">
        <header className="mb-6 md:mb-10 flex flex-col items-center text-center">
          <h2 className="text-2xl md:text-3xl font-black text-slate-900 tracking-tight uppercase">{viewTitles[currentView]}</h2>
          {showNewTransactionButton && (
            <button onClick={() => { setEditingTransaction(null); setIsFormOpen(true); }} className="mt-4 bg-indigo-600 text-white px-8 py-3 rounded-2xl shadow-xl hover:bg-indigo-700 transition-all font-black text-[10px] uppercase tracking-widest flex items-center gap-2 active:scale-95">
              <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4"><path d="M12 5v14M5 12h14"/></svg>
              Novo Lançamento
            </button>
          )}
        </header>

        {isFormOpen && (
          <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[60] overflow-y-auto p-4 md:flex md:justify-center md:items-start py-8 md:py-16">
            <div className="w-full max-w-4xl mx-auto">
              <TransactionForm onAdd={addTransaction} onUpdate={updateTransaction} editingTransaction={editingTransaction} categories={categories} cards={cards} onCancel={() => setIsFormOpen(false)} initialType={currentView === 'add-income' ? 'income' : 'expense'} />
            </div>
          </div>
        )}

        {isPaymentModalOpen && (
          <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[100] p-4 flex justify-center items-center">
             <div className="bg-white p-6 rounded-[24px] shadow-2xl border border-slate-100 w-full max-w-sm animate-in zoom-in-95 duration-200">
                <div className="flex items-center gap-3 mb-5">
                  <div className="w-10 h-10 bg-teal-50 text-teal-600 rounded-xl flex items-center justify-center">
                    <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20Z"/><path d="m9 12 2 2 4-4"/></svg>
                  </div>
                  <h3 className="text-lg font-black text-slate-900 tracking-tight">Confirmar Pagamento</h3>
                </div>

                <div className="mb-6">
                   <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest block mb-1.5 ml-1">Quando foi pago?</label>
                   <input 
                     type="date" 
                     value={selectedPaymentDate} 
                     onChange={(e) => setSelectedPaymentDate(e.target.value)} 
                     className="w-full h-12 px-4 bg-slate-50 border-none rounded-xl text-sm font-black text-slate-800 outline-none focus:ring-2 focus:ring-teal-100 transition-all"
                   />
                </div>

                <div className="flex gap-3">
                  <button 
                    onClick={() => setIsPaymentModalOpen(false)} 
                    className="flex-1 py-3 text-[10px] font-black uppercase text-slate-400 hover:text-slate-600 transition-all"
                  >
                    Cancelar
                  </button>
                  <button 
                    onClick={confirmPayment} 
                    className="flex-[2] py-3 bg-teal-500 text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg shadow-teal-100 hover:bg-teal-600 active:scale-95 transition-all"
                  >
                    Confirmar Pagamento
                  </button>
                </div>
             </div>
          </div>
        )}

        <div className="w-full max-w-full mx-auto">
          {renderContent()}
        </div>
      </main>
    </div>
  );
};

export default App;

import { useState, useEffect, useCallback } from 'react';
import { Transaction, Summary, UserCategories, CreditCard } from '../types';
import { supabase } from '../services/supabaseClient';

const DEFAULT_CATEGORIES: UserCategories = {
  expense: ['Alimentação', 'Moradia', 'Transporte', 'Lazer', 'Saúde', 'Cartão', 'Outros'],
  income: ['Salário', 'Freelance', 'Investimentos', 'Presentes', 'Outros'],
  payers: ['Isa'],
  colors: {}
};

export const useFinanceData = (userId: string | null) => {
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [cards, setCards] = useState<CreditCard[]>([]);
  const [categories, setCategories] = useState<UserCategories>(DEFAULT_CATEGORIES);
  const [loading, setLoading] = useState(false);

  const fetchData = useCallback(async () => {
    if (!userId) return;
    setLoading(true);

    try {
      const { data: profile } = await supabase
        .from('profiles')
        .select('categories')
        .eq('id', userId)
        .maybeSingle();

      if (profile?.categories) {
        const cats = profile.categories as unknown as UserCategories;
        setCategories({
          ...DEFAULT_CATEGORIES,
          ...cats,
          payers: cats.payers || DEFAULT_CATEGORIES.payers,
          colors: cats.colors || {}
        });
      }

      const { data: cardsData } = await supabase.from('credit_cards').select('*').eq('user_id', userId);
      setCards(cardsData || []);

      const { data: transData, error: transError } = await supabase
        .from('transactions')
        .select('*')
        .eq('user_id', userId)
        .order('date', { ascending: false });

      if (transError) throw transError;
      setTransactions(transData || []);
    } catch (err) {
      console.error('Erro ao sincronizar dados:', err);
    } finally {
      setLoading(false);
    }
  }, [userId]);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const addTransaction = useCallback(async (transaction: Omit<Transaction, 'id'>) => {
    if (!userId) return false;
    try {
      const { data, error } = await supabase
        .from('transactions')
        .insert([{ ...transaction, user_id: userId, is_paid: transaction.is_paid ?? true }])
        .select();

      if (error) throw error;
      if (data && data.length > 0) {
        setTransactions(prev => [data[0], ...prev]);
        return true;
      }
      return false;
    } catch (err) { 
      console.error('Erro ao adicionar transação:', err);
      return false;
    }
  }, [userId]);

  const updateTransaction = useCallback(async (id: string, updates: Partial<Transaction>) => {
    if (!userId || !id) return false;
    try {
      const allowedKeys = ['description', 'amount', 'type', 'category', 'date', 'payment_date', 'card_id', 'is_split', 'split_details', 'is_paid'];
      const payload = Object.fromEntries(
        Object.entries(updates).filter(([key]) => allowedKeys.includes(key))
      );

      const { data, error } = await supabase
        .from('transactions')
        .update(payload)
        .eq('id', id)
        .eq('user_id', userId)
        .select();

      if (error) return false;
      if (data && data.length > 0) {
        setTransactions(prev => prev.map(t => t.id === id ? data[0] : t));
        return true;
      }
      return false;
    } catch (err) { 
      console.error('Erro no update:', err);
      return false;
    }
  }, [userId]);

  const togglePaid = useCallback(async (id: string, currentStatus: boolean, paymentDate?: string | null) => {
    if (!userId) return;
    try {
      const updates: any = { is_paid: !currentStatus };
      if (!currentStatus) {
        updates.payment_date = paymentDate || new Date().toISOString();
      } else {
        updates.payment_date = null;
      }

      const { data, error } = await supabase
        .from('transactions')
        .update(updates)
        .eq('id', id)
        .eq('user_id', userId)
        .select();

      if (!error && data && data.length > 0) {
        setTransactions(prev => prev.map(t => t.id === id ? data[0] : t));
      }
    } catch (err) { console.error('Erro ao alternar status:', err); }
  }, [userId]);

  const addCard = async (card: Omit<CreditCard, 'id'>) => {
    if (!userId) return;
    const { data, error } = await supabase.from('credit_cards').insert([{ ...card, user_id: userId }]).select();
    if (!error && data && data.length > 0) setCards(prev => [...prev, data[0]]);
  };

  const deleteCard = async (id: string) => {
    if (!userId) return;
    const { error } = await supabase.from('credit_cards').delete().eq('id', id).eq('user_id', userId);
    if (!error) setCards(prev => prev.filter(c => c.id !== id));
  };

  const deleteTransaction = useCallback(async (id: string) => {
    if (!userId) return;
    const { error } = await supabase.from('transactions').delete().eq('id', id).eq('user_id', userId);
    if (!error) setTransactions(prev => prev.filter(t => t.id !== id));
  }, [userId]);

  const persistCategories = async (newCats: UserCategories) => {
    if (!userId) return;
    const { error } = await supabase.from('profiles').update({ categories: newCats }).eq('id', userId);
    if (!error) setCategories(newCats);
  };

  const addCategory = (type: 'income' | 'expense' | 'payers', name: string, color?: string) => {
    const target = type === 'payers' ? 'payers' : type;
    const newColors = { ...categories.colors, [name]: color || '#64748b' };
    const newCats = { 
      ...categories, 
      [target]: [...new Set([...categories[target as keyof UserCategories] as string[], name])],
      colors: type !== 'payers' ? newColors : categories.colors
    };
    persistCategories(newCats);
  };

  const updateCategory = async (type: 'income' | 'expense', oldName: string, newName: string, newColor: string) => {
    if (!userId) return;
    const target = type === 'expense' ? 'expense' : 'income';
    const newList = [...categories[target]];
    const index = newList.indexOf(oldName);

    if (index !== -1) {
      newList[index] = newName;
    } else {
      newList.push(newName);
    }

    const newColors = { ...categories.colors };
    if (oldName !== newName) delete newColors[oldName];
    newColors[newName] = newColor;

    const newCats = {
      ...categories,
      [target]: newList,
      colors: newColors
    };

    await persistCategories(newCats);
  };

  const deleteCategory = (type: 'income' | 'expense' | 'payers', name: string) => {
    const target = type === 'payers' ? 'payers' : type;
    const newColors = { ...categories.colors };
    delete newColors[name];
    const newCats = { 
      ...categories, 
      [target]: (categories[target as keyof UserCategories] as string[]).filter(cat => cat !== name),
      colors: type !== 'payers' ? newColors : categories.colors
    };
    persistCategories(newCats);
  };

  return {
    transactions, cards, categories,
    addTransaction, updateTransaction, deleteTransaction, togglePaid,
    addCard, deleteCard,
    addCategory, updateCategory, deleteCategory,
    loading
  };
};

import React, { useState, useEffect, useMemo } from 'react';
import { supabase } from './services/supabaseClient';
import { useFinanceData } from './hooks/useFinanceData';
import SummaryCards from './components/SummaryCards';
import TransactionForm from './components/TransactionForm';
import Charts from './components/Charts';
import AIInsights from './components/AIInsights';
import Sidebar, { ViewType } from './components/Sidebar';
import Reports from './components/Reports';
import CategoryManager from './components/CategoryManager';
import CardManager from './components/CardManager';
import PayerManager from './components/PayerManager';
import PayerReports from './components/PayerReports';
import DataManagement from './components/DataManagement';
import AuthScreen from './components/AuthScreen';
import Logo from './components/Logo';
import { TransactionType, User, Summary, Transaction } from './types';
import { getCategoryIcon, getCategoryStyles } from './utils/icons';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [sessionLoading, setSessionLoading] = useState(true);
  const [dbError, setDbError] = useState<string | null>(null);

  const { 
    transactions, cards, categories, 
    addTransaction, updateTransaction, deleteTransaction, togglePaid,
    addCard, deleteCard, addCategory, updateCategory, deleteCategory, loading: dataLoading
  } = useFinanceData(currentUser?.id || null);

  const [currentView, setCurrentView] = useState<ViewType>('dashboard');
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);

  const [isPaymentModalOpen, setIsPaymentModalOpen] = useState(false);
  const [pendingPaymentId, setPendingPaymentId] = useState<string | null>(null);
  const [selectedPaymentDate, setSelectedPaymentDate] = useState(new Date().toISOString().split('T')[0]);

  const getInitialDates = () => {
    const now = new Date();
    const firstDay = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().split('T')[0];
    const lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0).toISOString().split('T')[0];
    return { firstDay, lastDay };
  };

  const { firstDay: initStart, lastDay: initEnd } = getInitialDates();
  const [startDate, setStartDate] = useState(initStart);
  const [endDate, setEndDate] = useState(initEnd);
  const [selectedType, setSelectedType] = useState<'all' | 'expense' | 'income'>('all');
  const [selectedCategory, setSelectedCategory] = useState('all');
  const [selectedPayer, setSelectedPayer] = useState('all');
  const [statusFilter, setStatusFilter] = useState<'all' | 'paid' | 'pending'>('all');

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session?.user) fetchProfile(session.user);
      else setSessionLoading(false);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((event, session) => {
      if (session?.user) fetchProfile(session.user);
      else { setCurrentUser(null); setSessionLoading(false); }
    });

    return () => subscription.unsubscribe();
  }, []);

  const fetchProfile = async (authUser: any) => {
    try {
      const { data: profile } = await supabase
        .from('profiles')
        .select('name, avatar_color, categories')
        .eq('id', authUser.id)
        .maybeSingle();

      if (profile) {
        setCurrentUser({ id: authUser.id, name: profile.name, avatarColor: profile.avatar_color });
        setDbError(null);
      } else {
        const userName = authUser.user_metadata?.name || authUser.email?.split('@')[0] || 'Usuário';
        const defaultCategories = {
          expense: ['Alimentação', 'Moradia', 'Transporte', 'Lazer', 'Saúde', 'Cartão', 'Outros'],
          income: ['Salário', 'Freelance', 'Investimentos', 'Presentes', 'Outros'],
          payers: [userName.split(' ')[0] || 'Eu'],
          colors: {}
        };

        const { error: insertError } = await supabase.from('profiles').upsert({
          id: authUser.id,
          name: userName,
          avatar_color: '#4f46e5',
          categories: defaultCategories,
          updated_at: new Date().toISOString()
        });

        if (insertError) {
          setDbError("Atenção: Seu banco está bloqueando a gravação (Regra de INSERT faltando).");
        } else {
          setCurrentUser({ id: authUser.id, name: userName, avatarColor: '#4f46e5' });
          setDbError(null);
        }
      }
    } catch (err) {
      console.error(err);
    } finally {
      setSessionLoading(false);
    }
  };

  const handleLogout = async () => { 
    await supabase.auth.signOut(); 
    setCurrentUser(null); 
    setCurrentView('dashboard'); 
  };

  const formatCurrency = (val: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const handleTogglePaidRequest = (id: string, isPaid: boolean) => {
    if (!isPaid) {
      setPendingPaymentId(id);
      setSelectedPaymentDate(new Date().toISOString().split('T')[0]);
      setIsPaymentModalOpen(true);
    } else {
      if (window.confirm("Deseja marcar este lançamento como Pendente?")) {
        togglePaid(id, true, null);
      }
    }
  };

  const confirmPayment = () => {
    if (pendingPaymentId) {
      const paymentISO = new Date(selectedPaymentDate + 'T12:00:00').toISOString();
      togglePaid(pendingPaymentId, false, paymentISO);
      setIsPaymentModalOpen(false);
      setPendingPaymentId(null);
    }
  };

  const dashboardData = useMemo(() => {
    const filtered = transactions.filter(t => {
      const tDate = t.date.split('T')[0];
      const matchesDate = tDate >= startDate && tDate <= endDate;
      const matchesType = selectedType === 'all' || t.type === selectedType;
      const matchesCategory = selectedCategory === 'all' || t.category === selectedCategory;
      let matchesPayer = true;
      if (selectedPayer === 'individual') matchesPayer = true;
      else if (selectedPayer !== 'all') matchesPayer = t.is_split && t.split_details?.partnerName === selectedPayer;
      return matchesDate && matchesType && matchesCategory && matchesPayer;
    });

    const summary: Summary = filtered.reduce((acc, t) => {
      let amt = Number(t.amount);
      if (selectedPayer === 'individual' && t.is_split && t.split_details) {
        amt = Number(t.split_details.userPart);
      } else if (selectedPayer !== 'all' && t.is_split && t.split_details) {
        amt = Number(t.split_details.partnerPart);
      }

      if (t.type === 'income') { acc.income += amt; acc.balance += amt; }
      else { acc.expenses += amt; acc.balance -= amt; }
      return acc;
    }, { balance: 0, income: 0, expenses: 0 });

    const groupedByCard = filtered.reduce((acc: any, t) => {
      if (t.type !== 'expense') return acc;
      const cardKey = t.card_id || 'no-card';
      if (!acc[cardKey]) {
        acc[cardKey] = {
          cardId: t.card_id,
          total: 0,
          userPart: 0,
          others: {},
          hasPending: false,
          description: t.card_id ? cards.find(c => c.id === t.card_id)?.name : 'Dinheiro/Pix'
        };
      }
      const amt = Number(t.amount);
      acc[cardKey].total += amt;
      if (!t.is_paid) acc[cardKey].hasPending = true;
      if (t.is_split && t.split_details) {
        acc[cardKey].userPart += Number(t.split_details.userPart);
        const pName = t.split_details.partnerName || 'Indefinido';
        acc[cardKey].others[pName] = (acc[cardKey].others[pName] || 0) + Number(t.split_details.partnerPart);
      } else {
        acc[cardKey].userPart += amt;
      }
      return acc;
    }, {});

    return { filteredTransactions: filtered, summary, cardSummaries: Object.values(groupedByCard) };
  }, [transactions, startDate, endDate, selectedType, selectedCategory, selectedPayer, cards]);

  const renderFilterBar = () => {
    let catsToShow: string[] = [];
    if (selectedType === 'all') {
      catsToShow = Array.from(new Set([...categories.expense, ...categories.income])).sort();
    } else if (selectedType === 'expense') {
      catsToShow = [...categories.expense].sort();
    } else {
      catsToShow = [...categories.income].sort();
    }

    return (
      <div className="bg-white p-4 rounded-xl border border-slate-100 shadow-sm mb-6">
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-6 gap-3 items-end">
          <div className="col-span-1 sm:col-span-2 grid grid-cols-2 gap-2">
            <div>
              <label className="text-[9px] font-bold text-slate-400 uppercase mb-1.5 block">Início</label>
              <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="w-full bg-slate-50 border-none rounded-md px-3 py-2 text-xs font-bold text-indigo-600 outline-none" />
            </div>
            <div>
              <label className="text-[9px] font-bold text-slate-400 uppercase mb-1.5 block">Fim</label>
              <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="w-full bg-slate-50 border-none rounded-md px-3 py-2 text-xs font-bold text-indigo-600 outline-none" />
            </div>
          </div>
          <div>
            <label className="text-[9px] font-bold text-slate-400 uppercase mb-1.5 block">Tipo</label>
            <select value={selectedType} onChange={(e) => { setSelectedType(e.target.value as any); setSelectedCategory('all'); }} className="w-full bg-slate-50 border-none rounded-md px-4 py-2 text-xs font-bold text-slate-700 outline-none">
              <option value="all">Todos</option>
              <option value="expense">Saídas</option>
              <option value="income">Entradas</option>
            </select>
          </div>
          <div>
            <label className="text-[9px] font-bold text-slate-400 uppercase mb-1.5 block">Categoria</label>
            <select value={selectedCategory} onChange={(e) => setSelectedCategory(e.target.value)} className="w-full bg-slate-50 border-none rounded-md px-4 py-2 text-xs font-bold text-slate-700 outline-none">
              <option value="all">Todas</option>
              {catsToShow.map(cat => <option key={cat} value={cat}>{cat}</option>)}
            </select>
          </div>
          <button 
            onClick={() => { 
              const { firstDay, lastDay } = getInitialDates();
              setStartDate(firstDay); 
              setEndDate(lastDay); 
              setSelectedType('all');
              setSelectedCategory('all'); 
            }} 
            className="w-full py-2 text-[10px] font-bold text-slate-400 uppercase hover:text-indigo-600 transition-colors"
          >
            Limpar Filtros
          </button>
        </div>
      </div>
    );
  };

  const renderTransactionManagement = (type: TransactionType) => {
    const filtered = transactions
      .filter(t => {
        if (t.type !== type) return false;
        const tDate = t.date.split('T')[0];
        if (tDate < startDate || tDate > endDate) return false;
        if (selectedCategory !== 'all' && t.category !== selectedCategory) return false;
        if (statusFilter === 'paid' && !t.is_paid) return false;
        if (statusFilter === 'pending' && t.is_paid) return false;
        return true;
      })
      .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    return (
      <div className="space-y-4 max-w-full mx-auto pb-24 md:pb-0">
        {renderFilterBar()}

        <div className="hidden md:block bg-white rounded-2xl border border-slate-100 shadow-sm overflow-hidden">
          <table className="w-full text-left">
            <thead>
              <tr className="text-[10px] font-black text-slate-400 uppercase tracking-widest border-b border-slate-50 bg-slate-50/30">
                <th className="py-4 px-6 text-center">Status</th>
                <th className="py-4 px-6">Vencimento</th>
                <th className="py-4 px-6">Descrição / Categoria</th>
                <th className="py-4 px-6">Pagamento</th>
                <th className="py-4 px-6">Divisão</th>
                <th className="py-4 px-6 text-right">Valor</th>
                <th className="py-4 px-6 w-24 text-center">Ações</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filtered.map((t) => {
                const card = t.card_id ? cards.find(c => c.id === t.card_id) : null;
                const styles = getCategoryStyles(t.category, categories);
                const inlineStyles = styles.isCustom ? {
                  backgroundColor: `${styles.customColor}15`,
                  color: styles.customColor,
                  borderColor: `${styles.customColor}30`
                } : {};

                return (
                  <tr key={t.id} className="hover:bg-slate-50/50 transition-colors group">
                    <td className="py-4 px-6">
                      <button onClick={() => handleTogglePaidRequest(t.id, t.is_paid)} className={`w-6 h-6 rounded-lg flex items-center justify-center border-2 mx-auto transition-all ${t.is_paid ? 'bg-teal-500 border-teal-500 text-white' : 'bg-white border-slate-200 text-slate-200 hover:border-teal-300'}`}>
                        <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4"><path d="M20 6 9 17l-5-5"/></svg>
                      </button>
                    </td>
                    <td className="py-4 px-6">
                      <p className="text-[11px] text-slate-900 font-black whitespace-nowrap">{new Date(t.date).toLocaleDateString('pt-BR')}</p>
                      {t.is_paid && t.payment_date && (
                        <p className="text-[9px] text-teal-500 font-bold uppercase tracking-tighter whitespace-nowrap">Pago: {new Date(t.payment_date).toLocaleDateString('pt-BR')}</p>
                      )}
                    </td>
                    <td className="py-4 px-6">
                      <div className="flex items-center gap-3">
                        <div 
                          className={`w-9 h-9 rounded-xl flex items-center justify-center border ${!styles.isCustom ? `${styles.bg} ${styles.text} ${styles.border}` : ''}`}
                          style={inlineStyles}
                        >
                          {getCategoryIcon(t.category, 18)}
                        </div>
                        <div className="min-w-0">
                          <p className="text-xs font-black text-slate-900 leading-tight truncate">{t.description}</p>
                          <span className={`text-[9px] font-black uppercase tracking-widest ${styles.isCustom ? '' : styles.text}`} style={styles.isCustom ? { color: styles.customColor } : {}}>{t.category}</span>
                        </div>
                      </div>
                    </td>
                    <td className="py-4 px-6">
                       <span className="text-[10px] font-black text-slate-400 uppercase tracking-tight">{card ? card.name : 'DINHEIRO/PIX'}</span>
                    </td>
                    <td className="py-4 px-6">
                      {t.is_split && t.split_details ? (
                        <div className="space-y-0.5">
                           <p className="text-[8px] font-black text-slate-400 uppercase tracking-tighter">VOCÊ: <span className="text-slate-900">{formatCurrency(t.split_details.userPart)}</span></p>
                           <p className="text-[8px] font-black text-indigo-400 uppercase tracking-tighter">{t.split_details.partnerName.toUpperCase()}: <span className="text-indigo-600">{formatCurrency(t.split_details.partnerPart)}</span></p>
                        </div>
                      ) : (
                        <span className="text-[9px] font-black text-slate-300 uppercase italic">SOLO</span>
                      )}
                    </td>
                    <td className={`py-4 px-6 text-right text-sm font-black ${t.type === 'income' ? 'text-teal-600' : 'text-rose-500'}`}>{formatCurrency(t.amount)}</td>
                    <td className="py-4 px-6">
                      <div className="flex justify-center gap-1">
                        <button onClick={() => { setEditingTransaction(t); setIsFormOpen(true); }} className="p-2 text-indigo-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-all"><svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z"/></svg></button>
                        <button onClick={() => deleteTransaction(t.id)} className="p-2 text-rose-300 hover:text-rose-500 hover:bg-rose-50 rounded-lg transition-all"><svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M3 6h18"/><path d="M19 6v14c0 1-1 2-2 2H7c-1 0-2-1-2-2V6"/></svg></button>
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
          {filtered.length === 0 && (
            <div className="py-20 text-center text-slate-300 font-black text-[10px] uppercase tracking-widest">Nenhum lançamento encontrado</div>
          )}
        </div>
      </div>
    );
  };

  const renderContent = () => {
    switch (currentView) {
      case 'dashboard':
        return (
          <div className="space-y-6 md:space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-24 md:pb-0">
            {dbError && (
              <div className="p-5 bg-rose-600 rounded-[32px] shadow-2xl shadow-rose-100 flex flex-col md:flex-row items-center gap-6 border border-rose-500 animate-in zoom-in-95">
                <div className="w-12 h-12 bg-white/20 rounded-2xl flex items-center justify-center text-white shrink-0">
                   <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3"><path d="m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3Z"/><line x1="12" x2="12" y1="9" y2="13"/><line x1="12" x2="12.01" y1="17" y2="17"/></svg>
                </div>
                <div className="flex-1 text-center md:text-left">
                  <p className="text-xs font-black text-white uppercase tracking-widest leading-relaxed">{dbError}</p>
                </div>
                <button 
                  onClick={() => setCurrentView('data-management')}
                  className="px-6 py-3 bg-white text-rose-600 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-rose-50 transition-all shadow-lg active:scale-95"
                >
                  Como Corrigir?
                </button>
              </div>
            )}

            <div className="mb-6 text-center md:text-left">
              <h1 className="text-xl md:text-2xl font-bold text-slate-900 tracking-tight">
                Olá, <span className="text-indigo-600">{currentUser?.name.split(' ')[0]}!</span> 👋
              </h1>
              <p className="text-xs font-medium text-slate-400 mt-1">Sua situação financeira hoje</p>
            </div>

            {renderFilterBar()}

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
              <div className="lg:col-span-8 space-y-6">
                <SummaryCards summary={dashboardData.summary} />
                <AIInsights transactions={dashboardData.filteredTransactions} />
                <Charts transactions={dashboardData.filteredTransactions} />
              </div>
              <div className="lg:col-span-4">
                <div className="bg-white p-5 rounded-3xl shadow-sm border border-slate-100 h-full">
                  <h2 className="text-[10px] font-black text-slate-900 tracking-tight uppercase mb-6 border-b border-slate-50 pb-3">Extrato por Pagante</h2>
                  <div className="space-y-3">
                    {dashboardData.cardSummaries.map((card: any) => (
                      <div key={card.cardId || 'cash'} className="p-4 bg-slate-50/40 rounded-2xl border border-slate-100">
                        <div className="flex justify-between items-start mb-4">
                          <h4 className="font-black text-[10px] text-slate-900 uppercase tracking-widest">{card.description}</h4>
                        </div>
                        <div className="pt-3 border-t border-slate-100/60 space-y-2">
                          <div className="flex justify-between items-baseline"><span className="text-[8px] font-black text-slate-400 uppercase tracking-tighter">VOCÊ</span><span className="text-xs font-black text-slate-900">{formatCurrency(card.userPart)}</span></div>
                          {Object.entries(card.others).map(([name, val]: [any, any]) => (
                            <div key={name} className="flex justify-between items-baseline"><span className="text-[8px] font-black text-indigo-400 uppercase tracking-tighter">{name}</span><span className="text-xs font-black text-indigo-600">{formatCurrency(val as number)}</span></div>
                          ))}
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </div>
          </div>
        );
      case 'add-expense': return renderTransactionManagement('expense');
      case 'add-income': return renderTransactionManagement('income');
      case 'payers': return <PayerManager categories={categories} onAdd={addCategory} onDelete={deleteCategory} />;
      case 'cards': return <CardManager cards={cards} transactions={transactions} onAdd={addCard} onDelete={deleteCard} />;
      case 'reports': return <Reports transactions={transactions} categories={categories} />;
      case 'payer-reports': return <PayerReports transactions={transactions} categories={categories} />;
      case 'categories': return <CategoryManager categories={categories} onAdd={addCategory} onUpdate={updateCategory} onDelete={deleteCategory} />;
      case 'data-management': return <DataManagement userId={currentUser!.id} transactions={transactions} cards={cards} categories={categories} onRefresh={() => window.location.reload()} />;
    }
  };

  if (sessionLoading) return <div className="min-h-screen flex items-center justify-center"><div className="w-8 h-8 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div></div>;
  if (!currentUser) return <AuthScreen onSelectUser={setCurrentUser} />;

  const viewTitles: Record<string, string> = {
    'dashboard': 'Visão Geral', 'cards': 'Meus Cartões', 'add-expense': 'Despesas', 'add-income': 'Receitas', 'categories': 'Categorias', 'reports': 'Extrato', 'payers': 'Pagantes', 'payer-reports': 'Acerto de Contas', 'data-management': 'Configurações Avançadas'
  };

  const showNewTransactionButton = !['dashboard', 'reports', 'payer-reports', 'data-management'].includes(currentView);

  return (
    <div className="flex min-h-screen bg-slate-50/50">
      <Sidebar currentView={currentView} onViewChange={setCurrentView} currentUser={currentUser} onLogout={handleLogout} />
      <main className="flex-1 p-4 md:p-8 w-full max-w-7xl mx-auto">
        <header className="mb-6 md:mb-10 flex flex-col items-center text-center">
          <h2 className="text-2xl md:text-3xl font-black text-slate-900 tracking-tight uppercase">{viewTitles[currentView]}</h2>
          {showNewTransactionButton && (
            <button onClick={() => { setEditingTransaction(null); setIsFormOpen(true); }} className="mt-4 bg-indigo-600 text-white px-8 py-3 rounded-2xl shadow-xl hover:bg-indigo-700 transition-all font-black text-[10px] uppercase tracking-widest flex items-center gap-2 active:scale-95">
              <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4"><path d="M12 5v14M5 12h14"/></svg>
              Novo Lançamento
            </button>
          )}
        </header>

        {isFormOpen && (
          <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[60] overflow-y-auto p-4 md:flex md:justify-center md:items-start py-8 md:py-16">
            <div className="w-full max-w-4xl mx-auto">
              <TransactionForm onAdd={addTransaction} onUpdate={updateTransaction} editingTransaction={editingTransaction} categories={categories} cards={cards} onCancel={() => setIsFormOpen(false)} initialType={currentView === 'add-income' ? 'income' : 'expense'} />
            </div>
          </div>
        )}

        {isPaymentModalOpen && (
          <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[100] p-4 flex justify-center items-center">
             <div className="bg-white p-6 rounded-[24px] shadow-2xl border border-slate-100 w-full max-w-sm animate-in zoom-in-95 duration-200">
                <div className="flex items-center gap-3 mb-5">
                  <div className="w-10 h-10 bg-teal-50 text-teal-600 rounded-xl flex items-center justify-center">
                    <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20Z"/><path d="m9 12 2 2 4-4"/></svg>
                  </div>
                  <h3 className="text-lg font-black text-slate-900 tracking-tight">Confirmar Pagamento</h3>
                </div>

                <div className="mb-6">
                   <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest block mb-1.5 ml-1">Quando foi pago?</label>
                   <input 
                     type="date" 
                     value={selectedPaymentDate} 
                     onChange={(e) => setSelectedPaymentDate(e.target.value)} 
                     className="w-full h-12 px-4 bg-slate-50 border-none rounded-xl text-sm font-black text-slate-800 outline-none focus:ring-2 focus:ring-teal-100 transition-all"
                   />
                </div>

                <div className="flex gap-3">
                  <button 
                    onClick={() => setIsPaymentModalOpen(false)} 
                    className="flex-1 py-3 text-[10px] font-black uppercase text-slate-400 hover:text-slate-600 transition-all"
                  >
                    Cancelar
                  </button>
                  <button 
                    onClick={confirmPayment} 
                    className="flex-[2] py-3 bg-teal-500 text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg shadow-teal-100 hover:bg-teal-600 active:scale-95 transition-all"
                  >
                    Confirmar Pagamento
                  </button>
                </div>
             </div>
          </div>
        )}

        <div className="w-full max-w-full mx-auto">
          {renderContent()}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { UserCategories } from '../types';
import { getCategoryIcon, getCategoryStyles } from '../utils/icons';

interface CategoryManagerProps {
  categories: UserCategories;
  onAdd: (type: 'income' | 'expense', name: string, color?: string) => void;
  onUpdate: (type: 'income' | 'expense', oldName: string, newName: string, newColor: string) => void;
  onDelete: (type: 'income' | 'expense', name: string) => void;
}

const CategoryManager: React.FC<CategoryManagerProps> = ({ categories, onAdd, onUpdate, onDelete }) => {
  const [newCat, setNewCat] = useState('');
  const [newColor, setNewColor] = useState('#6366f1');
  const [activeType, setActiveType] = useState<'expense' | 'income'>('expense');

  // Estado para edição
  const [editingCatName, setEditingCatName] = useState<string | null>(null);
  const [editValue, setEditValue] = useState('');
  const [editColor, setEditColor] = useState('');

  const handleAdd = (e: React.FormEvent) => {
    e.preventDefault();
    if (newCat.trim()) {
      onAdd(activeType, newCat.trim(), newColor);
      setNewCat('');
    }
  };

  const startEditing = (name: string) => {
    setEditingCatName(name);
    setEditValue(name);
    const styles = getCategoryStyles(name, categories);
    setEditColor(styles.isCustom ? styles.customColor! : '#64748b');
  };

  const handleUpdate = () => {
    if (editingCatName && editValue.trim()) {
      onUpdate(activeType, editingCatName, editValue.trim(), editColor);
      setEditingCatName(null);
    }
  };

  return (
    <div className="max-w-2xl space-y-6">
      <div className="bg-white p-8 rounded-xl border border-slate-100 shadow-sm">
        <div className="flex justify-between items-start mb-6">
          <div>
            <h3 className="text-lg font-bold text-slate-900 tracking-tight">Suas Categorias</h3>
            <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">Personalize seus lançamentos</p>
          </div>
          <div className="bg-indigo-50 px-3 py-1.5 rounded-full">
            <span className="text-[9px] font-black text-indigo-600 uppercase tracking-tighter">Sincronizado no Perfil</span>
          </div>
        </div>

        <div className="flex gap-2 p-1.5 bg-slate-50 rounded-lg mb-8 border border-slate-100">
          {(['expense', 'income'] as const).map((t) => (
            <button
              key={t}
              onClick={() => setActiveType(t)}
              className={`flex-1 py-2 rounded text-xs font-bold transition-all ${
                activeType === t ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-400'
              }`}
            >
              {t === 'expense' ? 'DESPESAS' : 'RECEITAS'}
            </button>
          ))}
        </div>

        <form onSubmit={handleAdd} className="flex flex-col sm:flex-row gap-3 mb-8">
          <div className="flex-1 flex gap-2">
            <input
              type="text"
              value={newCat}
              onChange={(e) => setNewCat(e.target.value)}
              placeholder="Ex: Assinaturas, Aluguel..."
              className="flex-1 px-4 py-3 bg-slate-50 border-transparent border-2 rounded-lg text-sm outline-none focus:bg-white focus:border-indigo-100 transition-all font-medium text-slate-900 placeholder:text-slate-300"
            />
            <div className="relative group shrink-0">
               <input 
                 type="color" 
                 value={newColor} 
                 onChange={e => setNewColor(e.target.value)} 
                 className="w-12 h-12 p-1 bg-slate-50 border-transparent border-2 rounded-lg cursor-pointer outline-none focus:border-indigo-100" 
                 title="Escolha a cor da categoria"
               />
            </div>
          </div>
          <button 
            type="submit"
            className="bg-indigo-600 text-white px-6 py-3 rounded-lg text-xs font-bold hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-100"
          >
            Adicionar
          </button>
        </form>

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
          {categories[activeType].map((cat) => {
            const styles = getCategoryStyles(cat, categories);
            const isEditing = editingCatName === cat;

            const currentItemStyles = styles.isCustom ? {
               backgroundColor: `${styles.customColor}15`,
               color: styles.customColor,
               borderColor: `${styles.customColor}30`
            } : {};

            if (isEditing) {
              return (
                <div key={cat} className="flex flex-col gap-2 p-3 bg-indigo-50/20 rounded-lg border border-indigo-100 animate-in fade-in duration-200">
                  <div className="flex gap-2">
                    <input 
                      type="text" 
                      value={editValue} 
                      onChange={e => setEditValue(e.target.value)}
                      className="flex-1 px-3 py-2 bg-white border border-indigo-100 rounded text-xs font-bold text-slate-700 outline-none"
                    />
                    <input 
                      type="color" 
                      value={editColor} 
                      onChange={e => setEditColor(e.target.value)}
                      className="w-8 h-8 p-0.5 bg-white border border-indigo-100 rounded cursor-pointer"
                    />
                  </div>
                  <div className="flex justify-end gap-2">
                    <button onClick={() => setEditingCatName(null)} className="text-[8px] font-black uppercase text-slate-400 hover:text-slate-600">Cancelar</button>
                    <button onClick={handleUpdate} className="bg-indigo-600 text-white px-3 py-1.5 rounded text-[8px] font-black uppercase tracking-widest">Salvar</button>
                  </div>
                </div>
              );
            }

            return (
              <div key={cat} className="flex items-center justify-between px-4 py-3 rounded-lg bg-slate-50/50 hover:bg-slate-50 border border-transparent hover:border-indigo-50 group transition-all">
                <div className="flex items-center gap-3">
                  <div 
                    className={`w-8 h-8 rounded-lg flex items-center justify-center border shrink-0 ${!styles.isCustom ? `${styles.bg} ${styles.text} ${styles.border}` : ''}`}
                    style={currentItemStyles}
                  >
                    {getCategoryIcon(cat, 16)}
                  </div>
                  <span className="text-xs font-semibold text-slate-700">{cat}</span>
                </div>
                <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-all">
                  <button 
                    onClick={() => startEditing(cat)}
                    className="p-1.5 text-slate-300 hover:text-indigo-600 hover:bg-white rounded-lg transition-all"
                    title="Editar categoria"
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M17 3a2.85 2.83 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5Z"/><path d="m15 5 4 4"/></svg>
                  </button>
                  <button 
                    onClick={() => onDelete(activeType, cat)}
                    className="p-1.5 text-slate-300 hover:text-rose-500 hover:bg-white rounded-lg transition-all"
                    title="Excluir categoria"
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M18 6 6 18"/><path d="m6 6 12 12"/></svg>
                  </button>
                </div>
              </div>
            );
          })}
          {categories[activeType].length === 0 && (
            <p className="col-span-2 text-center py-10 text-xs text-slate-300 font-medium italic">Nenhuma categoria personalizada ainda.</p>
          )}
        </div>
      </div>
    </div>
  );
};

export default CategoryManager;

import React, { useState, useEffect, useMemo } from 'react';
import { supabase } from './services/supabaseClient';
import { useFinanceData } from './hooks/useFinanceData';
import SummaryCards from './components/SummaryCards';
import TransactionForm from './components/TransactionForm';
import Charts from './components/Charts';
import AIInsights from './components/AIInsights';
import Sidebar, { ViewType } from './components/Sidebar';
import Reports from './components/Reports';
import CategoryManager from './components/CategoryManager';
import CardManager from './components/CardManager';
import PayerManager from './components/PayerManager';
import PayerReports from './components/PayerReports';
import DataManagement from './components/DataManagement';
import AuthScreen from './components/AuthScreen';
import Logo from './components/Logo';
import { TransactionType, User, Summary, Transaction } from './types';
import { getCategoryIcon, getCategoryStyles } from './utils/icons';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [sessionLoading, setSessionLoading] = useState(true);
  const [dbError, setDbError] = useState<string | null>(null);

  const { 
    transactions, cards, categories, 
    addTransaction, updateTransaction, deleteTransaction, togglePaid,
    addCard, deleteCard, addCategory, updateCategory, deleteCategory, loading: dataLoading
  } = useFinanceData(currentUser?.id || null);

  const [currentView, setCurrentView] = useState<ViewType>('dashboard');
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);

  const [isPaymentModalOpen, setIsPaymentModalOpen] = useState(false);
  const [pendingPaymentId, setPendingPaymentId] = useState<string | null>(null);
  const [selectedPaymentDate, setSelectedPaymentDate] = useState(new Date().toISOString().split('T')[0]);

  const getInitialDates = () => {
    const now = new Date();
    const firstDay = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().split('T')[0];
    const lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0).toISOString().split('T')[0];
    return { firstDay, lastDay };
  };

  const { firstDay: initStart, lastDay: initEnd } = getInitialDates();
  const [startDate, setStartDate] = useState(initStart);
  const [endDate, setEndDate] = useState(initEnd);
  const [selectedType, setSelectedType] = useState<'all' | 'expense' | 'income'>('all');
  const [selectedCategory, setSelectedCategory] = useState('all');
  const [selectedPayer, setSelectedPayer] = useState('all');
  const [statusFilter, setStatusFilter] = useState<'all' | 'paid' | 'pending'>('all');

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session?.user) fetchProfile(session.user);
      else setSessionLoading(false);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((event, session) => {
      if (session?.user) fetchProfile(session.user);
      else { setCurrentUser(null); setSessionLoading(false); }
    });

    return () => subscription.unsubscribe();
  }, []);

  const fetchProfile = async (authUser: any) => {
    try {
      const { data: profile } = await supabase
        .from('profiles')
        .select('name, avatar_color, categories')
        .eq('id', authUser.id)
        .maybeSingle();

      if (profile) {
        setCurrentUser({ id: authUser.id, name: profile.name, avatarColor: profile.avatar_color });
        setDbError(null);
      } else {
        const userName = authUser.user_metadata?.name || authUser.email?.split('@')[0] || 'Usuário';
        const defaultCategories = {
          expense: ['Alimentação', 'Moradia', 'Transporte', 'Lazer', 'Saúde', 'Cartão', 'Outros'],
          income: ['Salário', 'Freelance', 'Investimentos', 'Presentes', 'Outros'],
          payers: [userName.split(' ')[0] || 'Eu'],
          colors: {}
        };

        const { error: insertError } = await supabase.from('profiles').upsert({
          id: authUser.id,
          name: userName,
          avatar_color: '#4f46e5',
          categories: defaultCategories,
          updated_at: new Date().toISOString()
        });

        if (insertError) {
          setDbError("Atenção: Seu banco está bloqueando a gravação (Regra de INSERT faltando).");
        } else {
          setCurrentUser({ id: authUser.id, name: userName, avatarColor: '#4f46e5' });
          setDbError(null);
        }
      }
    } catch (err) {
      console.error(err);
    } finally {
      setSessionLoading(false);
    }
  };

  const handleLogout = async () => { 
    await supabase.auth.signOut(); 
    setCurrentUser(null); 
    setCurrentView('dashboard'); 
  };

  const formatCurrency = (val: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const handleTogglePaidRequest = (id: string, isPaid: boolean) => {
    if (!isPaid) {
      setPendingPaymentId(id);
      setSelectedPaymentDate(new Date().toISOString().split('T')[0]);
      setIsPaymentModalOpen(true);
    } else {
      if (window.confirm("Deseja marcar este lançamento como Pendente?")) {
        togglePaid(id, true, null);
      }
    }
  };

  const confirmPayment = () => {
    if (pendingPaymentId) {
      const paymentISO = new Date(selectedPaymentDate + 'T12:00:00').toISOString();
      togglePaid(pendingPaymentId, false, paymentISO);
      setIsPaymentModalOpen(false);
      setPendingPaymentId(null);
    }
  };

  const dashboardData = useMemo(() => {
    const filtered = transactions.filter(t => {
      const tDate = t.date.split('T')[0];
      const matchesDate = tDate >= startDate && tDate <= endDate;
      const matchesType = selectedType === 'all' || t.type === selectedType;
      const matchesCategory = selectedCategory === 'all' || t.category === selectedCategory;
      let matchesPayer = true;
      if (selectedPayer === 'individual') matchesPayer = true;
      else if (selectedPayer !== 'all') matchesPayer = t.is_split && t.split_details?.partnerName === selectedPayer;
      return matchesDate && matchesType && matchesCategory && matchesPayer;
    });

    const summary: Summary = filtered.reduce((acc, t) => {
      let amt = Number(t.amount);
      if (selectedPayer === 'individual' && t.is_split && t.split_details) {
        amt = Number(t.split_details.userPart);
      } else if (selectedPayer !== 'all' && t.is_split && t.split_details) {
        amt = Number(t.split_details.partnerPart);
      }

      if (t.type === 'income') { acc.income += amt; acc.balance += amt; }
      else { acc.expenses += amt; acc.balance -= amt; }
      return acc;
    }, { balance: 0, income: 0, expenses: 0 });

    const groupedByCard = filtered.reduce((acc: any, t) => {
      if (t.type !== 'expense') return acc;
      const cardKey = t.card_id || 'no-card';
      if (!acc[cardKey]) {
        acc[cardKey] = {
          cardId: t.card_id,
          total: 0,
          userPart: 0,
          others: {},
          hasPending: false,
          description: t.card_id ? cards.find(c => c.id === t.card_id)?.name : 'Dinheiro/Pix'
        };
      }
      const amt = Number(t.amount);
      acc[cardKey].total += amt;
      if (!t.is_paid) acc[cardKey].hasPending = true;
      if (t.is_split && t.split_details) {
        acc[cardKey].userPart += Number(t.split_details.userPart);
        const pName = t.split_details.partnerName || 'Indefinido';
        acc[cardKey].others[pName] = (acc[cardKey].others[pName] || 0) + Number(t.split_details.partnerPart);
      } else {
        acc[cardKey].userPart += amt;
      }
      return acc;
    }, {});

    return { filteredTransactions: filtered, summary, cardSummaries: Object.values(groupedByCard) };
  }, [transactions, startDate, endDate, selectedType, selectedCategory, selectedPayer, cards]);

  const renderFilterBar = () => {
    let catsToShow: string[] = [];
    if (selectedType === 'all') {
      catsToShow = Array.from(new Set([...categories.expense, ...categories.income])).sort();
    } else if (selectedType === 'expense') {
      catsToShow = [...categories.expense].sort();
    } else {
      catsToShow = [...categories.income].sort();
    }

    return (
      <div className="bg-white p-4 rounded-xl border border-slate-100 shadow-sm mb-6">
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-6 gap-3 items-end">
          <div className="col-span-1 sm:col-span-2 grid grid-cols-2 gap-2">
            <div>
              <label className="text-[9px] font-bold text-slate-400 uppercase mb-1.5 block">Início</label>
              <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="w-full bg-slate-50 border-none rounded-md px-3 py-2 text-xs font-bold text-indigo-600 outline-none" />
            </div>
            <div>
              <label className="text-[9px] font-bold text-slate-400 uppercase mb-1.5 block">Fim</label>
              <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="w-full bg-slate-50 border-none rounded-md px-3 py-2 text-xs font-bold text-indigo-600 outline-none" />
            </div>
          </div>
          <div>
            <label className="text-[9px] font-bold text-slate-400 uppercase mb-1.5 block">Tipo</label>
            <select value={selectedType} onChange={(e) => { setSelectedType(e.target.value as any); setSelectedCategory('all'); }} className="w-full bg-slate-50 border-none rounded-md px-4 py-2 text-xs font-bold text-slate-700 outline-none">
              <option value="all">Todos</option>
              <option value="expense">Saídas</option>
              <option value="income">Entradas</option>
            </select>
          </div>
          <div>
            <label className="text-[9px] font-bold text-slate-400 uppercase mb-1.5 block">Categoria</label>
            <select value={selectedCategory} onChange={(e) => setSelectedCategory(e.target.value)} className="w-full bg-slate-50 border-none rounded-md px-4 py-2 text-xs font-bold text-slate-700 outline-none">
              <option value="all">Todas</option>
              {catsToShow.map(cat => <option key={cat} value={cat}>{cat}</option>)}
            </select>
          </div>
          <button 
            onClick={() => { 
              const { firstDay, lastDay } = getInitialDates();
              setStartDate(firstDay); 
              setEndDate(lastDay); 
              setSelectedType('all');
              setSelectedCategory('all'); 
            }} 
            className="w-full py-2 text-[10px] font-bold text-slate-400 uppercase hover:text-indigo-600 transition-colors"
          >
            Limpar Filtros
          </button>
        </div>
      </div>
    );
  };

  const renderTransactionManagement = (type: TransactionType) => {
    const filtered = transactions
      .filter(t => {
        if (t.type !== type) return false;
        const tDate = t.date.split('T')[0];
        if (tDate < startDate || tDate > endDate) return false;
        if (selectedCategory !== 'all' && t.category !== selectedCategory) return false;
        if (statusFilter === 'paid' && !t.is_paid) return false;
        if (statusFilter === 'pending' && t.is_paid) return false;
        return true;
      })
      .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    return (
      <div className="space-y-4 max-w-full mx-auto pb-24 md:pb-0">
        {renderFilterBar()}

        {/* Visualização para Desktop */}
        <div className="hidden md:block bg-white rounded-2xl border border-slate-100 shadow-sm overflow-hidden">
          <table className="w-full text-left">
            <thead>
              <tr className="text-[10px] font-black text-slate-400 uppercase tracking-widest border-b border-slate-50 bg-slate-50/30">
                <th className="py-4 px-6 text-center">Status</th>
                <th className="py-4 px-6">Vencimento</th>
                <th className="py-4 px-6">Descrição / Categoria</th>
                <th className="py-4 px-6">Pagamento</th>
                <th className="py-4 px-6">Divisão</th>
                <th className="py-4 px-6 text-right">Valor</th>
                <th className="py-4 px-6 w-24 text-center">Ações</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filtered.map((t) => {
                const card = t.card_id ? cards.find(c => c.id === t.card_id) : null;
                const styles = getCategoryStyles(t.category, categories);
                const inlineStyles = styles.isCustom ? {
                  backgroundColor: `${styles.customColor}15`,
                  color: styles.customColor,
                  borderColor: `${styles.customColor}30`
                } : {};

                return (
                  <tr key={t.id} className="hover:bg-slate-50/50 transition-colors group">
                    <td className="py-4 px-6">
                      <button onClick={() => handleTogglePaidRequest(t.id, t.is_paid)} className={`w-6 h-6 rounded-lg flex items-center justify-center border-2 mx-auto transition-all ${t.is_paid ? 'bg-teal-500 border-teal-500 text-white' : 'bg-white border-slate-200 text-slate-200 hover:border-teal-300'}`}>
                        <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4"><path d="M20 6 9 17l-5-5"/></svg>
                      </button>
                    </td>
                    <td className="py-4 px-6">
                      <p className="text-[11px] text-slate-900 font-black whitespace-nowrap">{new Date(t.date).toLocaleDateString('pt-BR')}</p>
                      {t.is_paid && t.payment_date && (
                        <p className="text-[9px] text-teal-500 font-bold uppercase tracking-tighter whitespace-nowrap">Pago: {new Date(t.payment_date).toLocaleDateString('pt-BR')}</p>
                      )}
                    </td>
                    <td className="py-4 px-6">
                      <div className="flex items-center gap-3">
                        <div 
                          className={`w-9 h-9 rounded-xl flex items-center justify-center border ${!styles.isCustom ? `${styles.bg} ${styles.text} ${styles.border}` : ''}`}
                          style={inlineStyles}
                        >
                          {getCategoryIcon(t.category, 18)}
                        </div>
                        <div className="min-w-0">
                          <p className="text-xs font-black text-slate-900 leading-tight truncate">{t.description}</p>
                          <span className={`text-[9px] font-black uppercase tracking-widest ${styles.isCustom ? '' : styles.text}`} style={styles.isCustom ? { color: styles.customColor } : {}}>{t.category}</span>
                        </div>
                      </div>
                    </td>
                    <td className="py-4 px-6">
                       <span className="text-[10px] font-black text-slate-400 uppercase tracking-tight">{card ? card.name : 'DINHEIRO/PIX'}</span>
                    </td>
                    <td className="py-4 px-6">
                      {t.is_split && t.split_details ? (
                        <div className="space-y-0.5">
                           <p className="text-[8px] font-black text-slate-400 uppercase tracking-tighter">VOCÊ: <span className="text-slate-900">{formatCurrency(t.split_details.userPart)}</span></p>
                           <p className="text-[8px] font-black text-indigo-400 uppercase tracking-tighter">{t.split_details.partnerName.toUpperCase()}: <span className="text-indigo-600">{formatCurrency(t.split_details.partnerPart)}</span></p>
                        </div>
                      ) : (
                        <span className="text-[9px] font-black text-slate-300 uppercase italic">SOLO</span>
                      )}
                    </td>
                    <td className={`py-4 px-6 text-right text-sm font-black ${t.type === 'income' ? 'text-teal-600' : 'text-rose-500'}`}>{formatCurrency(t.amount)}</td>
                    <td className="py-4 px-6">
                      <div className="flex justify-center gap-1">
                        <button onClick={() => { setEditingTransaction(t); setIsFormOpen(true); }} className="p-2 text-indigo-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-all"><svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z"/></svg></button>
                        <button onClick={() => deleteTransaction(t.id)} className="p-2 text-rose-300 hover:text-rose-500 hover:bg-rose-50 rounded-lg transition-all"><svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M3 6h18"/><path d="M19 6v14c0 1-1 2-2 2H7c-1 0-2-1-2-2V6"/></svg></button>
                      </div>
                    </td>
                  </tr>
                );
