            return (
              <div key={t.id} className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm flex flex-col gap-3">
                <div className="flex justify-between items-start">
                  <div className="flex flex-col">
                    <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Venc: {new Date(t.date).toLocaleDateString('pt-BR')}</span>
                    {t.is_paid && t.payment_date && (
                      <span className="text-[9px] font-black text-teal-600 uppercase tracking-widest mt-0.5">Pago: {new Date(t.payment_date).toLocaleDateString('pt-BR')}</span>
                    )}
                  </div>
                  <button onClick={() => handleTogglePaidRequest(t.id, t.is_paid)} className={`px-2 py-1 rounded-lg text-[8px] font-black uppercase tracking-widest border transition-all ${t.is_paid ? 'bg-teal-50 border-teal-100 text-teal-600' : 'bg-amber-50 border-amber-100 text-amber-600'}`}>
