                className="w-full px-4 py-3.5 bg-slate-50 rounded-xl text-sm font-bold text-slate-900 outline-none border border-transparent focus:bg-white focus:border-indigo-200 transition-all placeholder:text-slate-300"
                required
              />
            </div>
          )}

          {view === 'updatePassword' && (
            <div>
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1.5 ml-1">Nova Senha</label>
              <input
                type="password"
                value={newPassword}
                onChange={(e) => setNewPassword(e.target.value)}
                placeholder="Mínimo 6 caracteres"
                className="w-full px-4 py-3.5 bg-slate-50 rounded-xl text-sm font-bold text-slate-900 outline-none border border-transparent focus:bg-white focus:border-indigo-200 transition-all placeholder:text-slate-300"
                required
              />
            </div>
          )}

          {(view === 'signIn' || view === 'signUp') && (
            <div>
              <div className="flex justify-between items-center mb-1.5 ml-1">
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest">Senha</label>
