export default Reports;

export type TransactionType = 'income' | 'expense';

export interface User {
  id: string;
  name: string;
  avatarColor: string;
}

export interface SplitDetails {
  userPart: number;
  partnerPart: number;
  partnerName: string;
}

export interface Account {
  id: string;
  name: string;
  type: 'checking' | 'investment' | 'cash' | 'savings' | 'other';
  initial_balance: number;
  color: string;
}

export interface Transaction {
  id: string;
  description: string;
  amount: number;
  type: TransactionType;
  category: string;
  date: string;
  payment_date?: string | null;
  card_id?: string | null;
  account_id?: string | null; // Nova vinculação
  is_split?: boolean;
  split_details?: SplitDetails;
  is_paid: boolean;
}

export interface CreditCard {
  id: string;
  name: string;
  color: string;
  credit_limit: number;
  closing_day: number;
  due_day: number;
}

export interface Summary {
  balance: number;
  income: number;
  expenses: number;
}

export interface UserCategories {
  expense: string[];
  income: string[];
  payers: string[];
  colors?: Record<string, string>;
  icons?: Record<string, string>;
}

import { useState, useEffect, useCallback } from 'react';
import { Transaction, Summary, UserCategories, CreditCard, Account } from '../types';
import { supabase } from '../services/supabaseClient';

const DEFAULT_CATEGORIES: UserCategories = {
  expense: ['Alimentação', 'Moradia', 'Transporte', 'Lazer', 'Saúde', 'Cartão', 'Outros'],
  income: ['Salário', 'Freelance', 'Investimentos', 'Presentes', 'Outros'],
  payers: ['Isa'],
  colors: {},
  icons: {}
};

export const useFinanceData = (userId: string | null) => {
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [cards, setCards] = useState<CreditCard[]>([]);
  const [accounts, setAccounts] = useState<Account[]>([]);
  const [categories, setCategories] = useState<UserCategories>(DEFAULT_CATEGORIES);
  const [loading, setLoading] = useState(false);

  const fetchData = useCallback(async () => {
    if (!userId) return;
    setLoading(true);

    try {
      const { data: profile } = await supabase
        .from('profiles')
        .select('categories')
        .eq('id', userId)
        .maybeSingle();

      if (profile?.categories) {
        const cats = profile.categories as unknown as UserCategories;
        setCategories({
          ...DEFAULT_CATEGORIES,
          ...cats,
          payers: cats.payers || DEFAULT_CATEGORIES.payers,
          colors: cats.colors || {},
          icons: cats.icons || {}
        });
      }

      const { data: cardsData } = await supabase.from('credit_cards').select('*').eq('user_id', userId);
      setCards(cardsData || []);

      const { data: accountsData } = await supabase.from('accounts').select('*').eq('user_id', userId);
      setAccounts(accountsData || []);

      const { data: transData, error: transError } = await supabase
        .from('transactions')
        .select('*')
        .eq('user_id', userId)
        .order('date', { ascending: false });

      if (transError) throw transError;
      setTransactions(transData || []);
    } catch (err) {
      console.error('Erro ao sincronizar dados:', err);
    } finally {
      setLoading(false);
    }
  }, [userId]);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const addTransaction = useCallback(async (transaction: Omit<Transaction, 'id'>) => {
    if (!userId) return false;
    try {
      const { data, error } = await supabase
        .from('transactions')
        .insert([{ ...transaction, user_id: userId, is_paid: transaction.is_paid ?? true }])
        .select();

      if (error) throw error;
      if (data && data.length > 0) {
        setTransactions(prev => [data[0], ...prev]);
        return true;
      }
      return false;
    } catch (err) { 
      console.error('Erro ao adicionar transação:', err);
      return false;
    }
  }, [userId]);

  const updateTransaction = useCallback(async (id: string, updates: Partial<Transaction>) => {
    if (!userId || !id) return false;
    try {
      const allowedKeys = ['description', 'amount', 'type', 'category', 'date', 'payment_date', 'card_id', 'account_id', 'is_split', 'split_details', 'is_paid'];
      const payload = Object.fromEntries(
        Object.entries(updates).filter(([key]) => allowedKeys.includes(key))
      );

      const { data, error } = await supabase
        .from('transactions')
        .update(payload)
        .eq('id', id)
        .eq('user_id', userId)
        .select();

      if (error) return false;
      if (data && data.length > 0) {
        setTransactions(prev => prev.map(t => t.id === id ? data[0] : t));
        return true;
      }
      return false;
    } catch (err) { 
      console.error('Erro no update:', err);
      return false;
    }
  }, [userId]);

  const togglePaid = useCallback(async (id: string, currentStatus: boolean, paymentDate?: string | null) => {
    if (!userId) return;
    try {
      const updates: any = { is_paid: !currentStatus };
      if (!currentStatus) {
        updates.payment_date = paymentDate || new Date().toISOString();
      } else {
        updates.payment_date = null;
      }

      const { data, error } = await supabase
        .from('transactions')
        .update(updates)
        .eq('id', id)
        .eq('user_id', userId)
        .select();

      if (!error && data && data.length > 0) {
        setTransactions(prev => prev.map(t => t.id === id ? data[0] : t));
      }
    } catch (err) { console.error('Erro ao alternar status:', err); }
  }, [userId]);

  // --- Cards CRUD ---
  const addCard = async (card: Omit<CreditCard, 'id'>) => {
    if (!userId) return;
    const { data, error } = await supabase.from('credit_cards').insert([{ ...card, user_id: userId }]).select();
    if (!error && data && data.length > 0) setCards(prev => [...prev, data[0]]);
  };

  const deleteCard = async (id: string) => {
    if (!userId) return;
    const { error } = await supabase.from('credit_cards').delete().eq('id', id).eq('user_id', userId);
    if (!error) setCards(prev => prev.filter(c => c.id !== id));
  };

  // --- Accounts CRUD ---
  const addAccount = async (account: Omit<Account, 'id'>) => {
    if (!userId) return;
    const { data, error } = await supabase.from('accounts').insert([{ ...account, user_id: userId }]).select();
    if (!error && data && data.length > 0) setAccounts(prev => [...prev, data[0]]);
  };

  const deleteAccount = async (id: string) => {
    if (!userId) return;
    const { error } = await supabase.from('accounts').delete().eq('id', id).eq('user_id', userId);
    if (!error) setAccounts(prev => prev.filter(a => a.id !== id));
  };

  const deleteTransaction = useCallback(async (id: string) => {
    if (!userId) return;
    const { error } = await supabase.from('transactions').delete().eq('id', id).eq('user_id', userId);
    if (!error) setTransactions(prev => prev.filter(t => t.id !== id));
  }, [userId]);

  const persistCategories = async (newCats: UserCategories) => {
    if (!userId) return;
    const { error } = await supabase.from('profiles').update({ categories: newCats }).eq('id', userId);
    if (!error) setCategories(newCats);
  };

  const addCategory = (type: 'income' | 'expense' | 'payers', name: string, color?: string, icon?: string) => {
    const target = type === 'payers' ? 'payers' : type;
    const newColors = { ...categories.colors, [name]: color || '#64748b' };
    const newIcons = { ...categories.icons, [name]: icon || 'other' };

    const newCats = { 
      ...categories, 
      [target]: [...new Set([...categories[target as keyof UserCategories] as string[], name])],
      colors: type !== 'payers' ? newColors : categories.colors,
      icons: type !== 'payers' ? newIcons : categories.icons
    };
    persistCategories(newCats);
  };

  const updateCategory = async (type: 'income' | 'expense', oldName: string, newName: string, newColor: string, newIcon: string) => {
    if (!userId) return;
    const target = type === 'expense' ? 'expense' : 'income';
    const newList = [...categories[target]];
    const index = newList.indexOf(oldName);

    if (index !== -1) {
      newList[index] = newName;
    } else {
      newList.push(newName);
    }

    const newColors = { ...categories.colors };
    const newIcons = { ...categories.icons };

    if (oldName !== newName) {
      delete newColors[oldName];
      delete newIcons[oldName];
    }

    newColors[newName] = newColor;
    newIcons[newName] = newIcon;

    const newCats = {
      ...categories,
      [target]: newList,
      colors: newColors,
      icons: newIcons
    };

    await persistCategories(newCats);
  };

  const deleteCategory = (type: 'income' | 'expense' | 'payers', name: string) => {
    const target = type === 'payers' ? 'payers' : type;
    const newColors = { ...categories.colors };
    const newIcons = { ...categories.icons };
    delete newColors[name];
    delete newIcons[name];

    const newCats = { 
      ...categories, 
      [target]: (categories[target as keyof UserCategories] as string[]).filter(cat => cat !== name),
      colors: type !== 'payers' ? newColors : categories.colors,
      icons: type !== 'payers' ? newIcons : categories.icons
    };
    persistCategories(newCats);
  };

  return {
    transactions, cards, accounts, categories,
    addTransaction, updateTransaction, deleteTransaction, togglePaid,
    addCard, deleteCard,
    addAccount, deleteAccount,
    addCategory, updateCategory, deleteCategory,
    loading
  };
};

import React, { useState, useMemo } from 'react';
import { Account, Transaction } from '../types';

interface AccountManagerProps {
  accounts: Account[];
  transactions: Transaction[];
  onAdd: (account: Omit<Account, 'id'>) => void;
  onDelete: (id: string) => void;
}

const AccountManager: React.FC<AccountManagerProps> = ({ accounts, transactions, onAdd, onDelete }) => {
  const [showAdd, setShowAdd] = useState(false);
  const [name, setName] = useState('');
  const [initialBalance, setInitialBalance] = useState('');
  const [type, setType] = useState<Account['type']>('checking');
  const [color, setColor] = useState('#4f46e5');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onAdd({ 
      name, 
      initial_balance: parseFloat(initialBalance) || 0, 
      type, 
      color 
    });
    setName(''); setInitialBalance(''); setShowAdd(false);
  };

  const formatCurrency = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const calculatedAccounts = useMemo(() => {
    return accounts.map(acc => {
      // Calcula o saldo atual: Saldo Inicial + Entradas - Saídas
      // Apenas transações PAGAS e vinculadas a esta conta entram no cálculo
      const accountTransactions = transactions.filter(t => t.account_id === acc.id && t.is_paid);

      const balanceChange = accountTransactions.reduce((sum, t) => {
        const val = Number(t.amount);
        return t.type === 'income' ? sum + val : sum - val;
      }, 0);

      const currentBalance = Number(acc.initial_balance) + balanceChange;

      return { ...acc, currentBalance };
    });
  }, [accounts, transactions]);

  const totalPatrimony = calculatedAccounts.reduce((sum, acc) => sum + acc.currentBalance, 0);

  const getIcon = (type: string) => {
    switch(type) {
      case 'investment': return <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M12 2v20"/><path d="m17 5-5-3-5 3"/><path d="m17 19-5 3-5-3"/></svg>;
      case 'cash': return <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><rect width="20" height="14" x="2" y="5" rx="2"/><line x1="2" x2="22" y1="10" y2="10"/><line x1="12" x2="12" y1="15" y2="15"/></svg>;
      case 'savings': return <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M19 5c-1.5 0-2.8 1.4-3 2-3.5-1.5-11-.3-11 5 0 1.8 0 3 2 4.5V20h4v-2h3v2h4v-4c1-.5 1.7-1 2-2h2v-4h-2c0-1-.5-1.5-1-2h0V5z"/><path d="M2 9v1"/><path d="M23 9v1"/></svg>;
      default: return <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M3 21h18"/><path d="M5 21V7l8-4 8 4v14"/><path d="M17 21v-8H7v8"/></svg>;
    }
  };

  const getTypeLabel = (type: string) => {
    switch(type) {
      case 'checking': return 'Conta Corrente';
      case 'investment': return 'Investimentos';
      case 'cash': return 'Carteira Física';
      case 'savings': return 'Poupança';
      default: return 'Outros';
    }
  };

  return (
    <div className="max-w-5xl space-y-6 animate-in fade-in duration-500 pb-12">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
        <div>
          <h2 className="text-xl font-bold text-slate-900 tracking-tight">Minhas Contas</h2>
          <div className="flex items-center gap-2 mt-1">
             <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Patrimônio Total Acumulado</p>
          </div>
        </div>

        <div className="flex items-center gap-4 w-full sm:w-auto">
          <div className="bg-indigo-50 px-4 py-2 rounded-xl border border-indigo-100">
             <span className="text-lg font-black text-indigo-700">{formatCurrency(totalPatrimony)}</span>
          </div>
          <button onClick={() => setShowAdd(true)} className="bg-slate-900 text-white px-5 py-3 rounded-xl text-[10px] font-bold uppercase tracking-widest shadow-lg shadow-slate-200 transition-all hover:bg-black active:scale-95">
            Nova Conta
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {calculatedAccounts.map(acc => (
          <div key={acc.id} className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm hover:border-indigo-100 transition-all group relative overflow-hidden">
            <div className="absolute top-0 right-0 w-24 h-24 bg-gradient-to-br from-transparent to-slate-50 rounded-bl-full -mr-4 -mt-4 transition-all group-hover:to-indigo-50"></div>

            <div className="flex justify-between items-start relative z-10">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-xl flex items-center justify-center text-white shadow-md" style={{ backgroundColor: acc.color }}>
                  {getIcon(acc.type)}
                </div>
                <div>
                  <h3 className="font-bold text-slate-900 text-sm">{acc.name}</h3>
                  <p className="text-[9px] font-bold text-slate-400 uppercase tracking-tighter">{getTypeLabel(acc.type)}</p>
                </div>
              </div>
              <button onClick={() => onDelete(acc.id)} className="text-slate-300 hover:text-rose-500 transition-colors p-1">
                <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M3 6h18"/><path d="M19 6v14c0 1-1 2-2 2H7c-1 0-2-1-2-2V6"/></svg>
