-- 1. Permissões básicas
CREATE POLICY "Users can insert own profile" ON public.profiles FOR INSERT WITH CHECK (auth.uid() = id);
CREATE POLICY "Users can insert own transactions" ON public.transactions FOR INSERT WITH CHECK (auth.uid() = user_id);
CREATE POLICY "Users can insert own cards" ON public.credit_cards FOR INSERT WITH CHECK (auth.uid() = user_id);

-- 2. Tabela de Contas (Nova)
CREATE TABLE IF NOT EXISTS accounts (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  type TEXT NOT NULL, -- checking, savings, investment, cash
  initial_balance DECIMAL DEFAULT 0,
  color TEXT,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now())
);

ALTER TABLE accounts ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Users can see own accounts" ON public.accounts FOR SELECT USING (auth.uid() = user_id);
CREATE POLICY "Users can insert own accounts" ON public.accounts FOR INSERT WITH CHECK (auth.uid() = user_id);
CREATE POLICY "Users can update own accounts" ON public.accounts FOR UPDATE USING (auth.uid() = user_id);
CREATE POLICY "Users can delete own accounts" ON public.accounts FOR DELETE USING (auth.uid() = user_id);

-- 3. Atualizar Tabela de Transações para vincular Conta (se ainda não existir)
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='transactions' AND column_name='account_id') THEN
        ALTER TABLE transactions ADD COLUMN account_id UUID REFERENCES accounts(id) ON DELETE SET NULL;
    END IF;
END $$;`;

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    setMessage({ text: 'Script copiado! Agora cole no SQL Editor do Supabase.', type: 'success' });
    setTimeout(() => setMessage(null), 3000);
  };

  const handleExportJSON = async () => {
    try {
      // Buscar contas manualmente pois elas podem não estar na props se não forem passadas
      const { data: accounts } = await supabase.from('accounts').select('*').eq('user_id', userId);

      const dataToExport = {
        version: "1.1",
        exportDate: new Date().toISOString(),
        categories,
        cards,
        accounts: accounts || [],
        transactions
      };

      const blob = new Blob([JSON.stringify(dataToExport, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `backup_financepro_${new Date().toISOString().split('T')[0]}.json`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);

      setMessage({ text: 'Backup JSON exportado com sucesso!', type: 'success' });
    } catch (err) {
      setMessage({ text: 'Erro ao exportar JSON.', type: 'error' });
    }
  };

  const handleExportSQL = async () => {
    try {
      // Buscar contas
      const { data: accounts } = await supabase.from('accounts').select('*').eq('user_id', userId);

      let sql = `-- SCRIPT DE MIGRAÇÃO FINANCEPRO v1.1\n`;
      sql += `-- Gerado em: ${new Date().toLocaleString('pt-BR')}\n\n`;

      sql += `DO $$\n`;
      sql += `DECLARE\n`;
      sql += `    v_user_id UUID;\n`;
      sql += `BEGIN\n`;
      sql += `    SELECT id INTO v_user_id FROM auth.users LIMIT 1;\n\n`;
      sql += `    IF v_user_id IS NULL THEN\n`;
      sql += `        RAISE EXCEPTION 'Nenhum usuário encontrado!';\n`;
      sql += `    END IF;\n\n`;

      const catsJson = JSON.stringify(categories).replace(/'/g, "''");
      sql += `    INSERT INTO profiles (id, categories) VALUES (v_user_id, '${catsJson}'::jsonb) ON CONFLICT (id) DO UPDATE SET categories = EXCLUDED.categories;\n\n`;

      if (cards.length > 0) {
        cards.forEach(card => {
          const name = card.name.replace(/'/g, "''");
          sql += `    INSERT INTO credit_cards (id, user_id, name, color, credit_limit, closing_day, due_day) VALUES ('${card.id}', v_user_id, '${name}', '${card.color}', ${card.credit_limit}, ${card.closing_day}, ${card.due_day}) ON CONFLICT (id) DO NOTHING;\n`;
        });
      }

      if (accounts && accounts.length > 0) {
        accounts.forEach(acc => {
          const name = acc.name.replace(/'/g, "''");
          sql += `    INSERT INTO accounts (id, user_id, name, type, initial_balance, color) VALUES ('${acc.id}', v_user_id, '${name}', '${acc.type}', ${acc.initial_balance}, '${acc.color}') ON CONFLICT (id) DO NOTHING;\n`;
        });
      }

      if (transactions.length > 0) {
        transactions.forEach(t => {
          const desc = t.description.replace(/'/g, "''");
          const cardId = t.card_id ? `'${t.card_id}'` : 'NULL';
          const accId = t.account_id ? `'${t.account_id}'` : 'NULL';
          const pDate = t.payment_date ? `'${t.payment_date}'` : 'NULL';
          const splitDetails = t.split_details ? `'${JSON.stringify(t.split_details).replace(/'/g, "''")}'::jsonb` : 'NULL';

          sql += `    INSERT INTO transactions (id, user_id, description, amount, type, category, date, payment_date, card_id, account_id, is_split, split_details, is_paid) \n`;
          sql += `    VALUES ('${t.id}', v_user_id, '${desc}', ${t.amount}, '${t.type}', '${t.category}', '${t.date}', ${pDate}, ${cardId}, ${accId}, ${t.is_split}, ${splitDetails}, ${t.is_paid}) \n`;
          sql += `    ON CONFLICT (id) DO NOTHING;\n`;
        });
      }

      sql += `END $$;`;

      const blob = new Blob([sql], { type: 'text/plain' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `migracao_full_${new Date().toISOString().split('T')[0]}.sql`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);

      setMessage({ text: 'Script de migração gerado!', type: 'success' });
    } catch (err) {
      setMessage({ text: 'Erro ao gerar script SQL.', type: 'error' });
    }
  };

  const handleImport = async (event: React.ChangeEvent<HTMLInputElement>) => {
    // Mesma lógica anterior, mas adicionando importação de accounts
    const file = event.target.files?.[0];
    if (!file) return;

    if(!window.confirm("Isso adicionará dados ao banco atual. Continuar?")) return;
    setLoading(true);

    try {
      const reader = new FileReader();
      reader.onload = async (e) => {
        try {
          const importedData = JSON.parse(e.target?.result as string);

          // Importar Contas
          const accountIdMap: Record<string, string> = {};
          if (importedData.accounts && Array.isArray(importedData.accounts)) {
             for (const acc of importedData.accounts) {
               const { id: oldId, ...accData } = acc;
               const { data } = await supabase.from('accounts').insert([{ ...accData, user_id: userId }]).select().single();
               if(data) accountIdMap[oldId] = data.id;
             }
          }

          // Importar Cartões (Mantido)
          const cardIdMap: Record<string, string> = {};
          if (importedData.cards) {
             for (const c of importedData.cards) {
               const { id: oldId, ...cData } = c;
               const { data } = await supabase.from('credit_cards').insert([{ ...cData, user_id: userId }]).select().single();
               if(data) cardIdMap[oldId] = data.id;
             }
          }

          // Importar Transações
          if (importedData.transactions) {
            const transactionsToInsert = importedData.transactions.map((t: any) => {
              const { id, ...tData } = t;
              return {
                ...tData,
                user_id: userId,
                card_id: t.card_id ? (cardIdMap[t.card_id] || null) : null,
                account_id: t.account_id ? (accountIdMap[t.account_id] || null) : null
              };
            });

            const batchSize = 50;
            for (let i = 0; i < transactionsToInsert.length; i += batchSize) {
              await supabase.from('transactions').insert(transactionsToInsert.slice(i, i + batchSize));
            }
          }

          setMessage({ text: 'Importação concluída!', type: 'success' });
          setTimeout(() => { onRefresh(); setLoading(false); }, 2000);
        } catch (err: any) {
          setMessage({ text: `Erro: ${err.message}`, type: 'error' });
          setLoading(false);
        }
      };
      reader.readAsText(file);
    } catch (err) { setLoading(false); }
  };

  return (
    <div className="max-w-4xl mx-auto space-y-8 animate-in fade-in duration-500">
      <div className="bg-indigo-900 p-8 rounded-[32px] shadow-2xl shadow-indigo-200 border border-indigo-700 overflow-hidden relative group">
        <div className="relative z-10">
          <div className="flex items-center gap-3 mb-6">
            <h2 className="text-xl font-black text-white tracking-tight uppercase">Atualizar Banco de Dados</h2>
          </div>
          <p className="text-indigo-200 text-xs font-bold uppercase tracking-widest mb-6 leading-relaxed">
            Para ativar a funcionalidade de <span className="text-white">CONTAS BANCÁRIAS</span>, execute este script no Supabase. Ele cria a tabela 'accounts' e adiciona a coluna de ligação.
          </p>
          <div className="bg-slate-900/50 backdrop-blur-md rounded-2xl p-4 border border-indigo-500/30 mb-6">
            <pre className="text-[10px] font-mono text-indigo-300 leading-relaxed overflow-x-auto whitespace-pre">{sqlFixCode}</pre>
          </div>
          <button onClick={() => copyToClipboard(sqlFixCode)} className="bg-white text-indigo-900 px-8 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-indigo-50 transition-all shadow-xl active:scale-95 flex items-center gap-2">
            Copiar Script SQL
          </button>
        </div>
      </div>

      <div className="bg-white p-8 rounded-2xl border border-slate-100 shadow-sm">
        <h2 className="text-xl font-black text-slate-900 tracking-tight uppercase mb-8">Backup & Migração</h2>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="p-6 rounded-2xl border-2 border-slate-50 bg-slate-50/30 flex flex-col items-center text-center">
            <h3 className="text-[10px] font-black text-slate-800 uppercase tracking-widest mb-4">Exportar SQL</h3>
            <button onClick={handleExportSQL} className="w-full py-3 bg-slate-800 text-white rounded-xl text-[9px] font-black uppercase tracking-widest hover:bg-slate-900 transition-all">Gerar Migração</button>
          </div>
          <div className="p-6 rounded-2xl border-2 border-slate-50 bg-slate-50/30 flex flex-col items-center text-center">
            <h3 className="text-[10px] font-black text-slate-800 uppercase tracking-widest mb-4">Backup JSON</h3>
            <button onClick={handleExportJSON} className="w-full py-3 bg-slate-800 text-white rounded-xl text-[9px] font-black uppercase tracking-widest hover:bg-slate-900 transition-all">Baixar Backup</button>
          </div>
          <div className="p-6 rounded-2xl border-2 border-dashed border-slate-200 bg-white flex flex-col items-center text-center">
            <h3 className="text-[10px] font-black text-slate-800 uppercase tracking-widest mb-4">Importar JSON</h3>
            <label className={`w-full py-3 bg-teal-600 text-white rounded-xl text-[9px] font-black uppercase tracking-widest text-center cursor-pointer hover:bg-teal-700 transition-all ${loading ? 'opacity-50' : ''}`}>
              {loading ? 'Lendo...' : 'Selecionar'}
              <input type="file" accept=".json" onChange={handleImport} disabled={loading} className="hidden" />
            </label>
          </div>
        </div>
        {message && <div className={`mt-4 p-3 text-center text-[10px] font-bold uppercase rounded-lg ${message.type === 'success' ? 'bg-teal-50 text-teal-700' : 'bg-rose-50 text-rose-700'}`}>{message.text}</div>}
      </div>
    </div>
  );
};

export default DataManagement;

import React, { useState, useEffect, useMemo } from 'react';
import { supabase } from './services/supabaseClient';
import { useFinanceData } from './hooks/useFinanceData';
import SummaryCards from './components/SummaryCards';
import TransactionForm from './components/TransactionForm';
import Charts from './components/Charts';
import AIInsights from './components/AIInsights';
import Sidebar, { ViewType } from './components/Sidebar';
import Reports from './components/Reports';
import CategoryManager from './components/CategoryManager';
import CardManager from './components/CardManager';
import AccountManager from './components/AccountManager';
import PayerManager from './components/PayerManager';
import PayerReports from './components/PayerReports';
import DataManagement from './components/DataManagement';
import AuthScreen from './components/AuthScreen';
import Logo from './components/Logo';
import { TransactionType, User, Summary, Transaction } from './types';
import { getCategoryIcon, getCategoryStyles } from './utils/icons';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [sessionLoading, setSessionLoading] = useState(true);
  const [dbError, setDbError] = useState<string | null>(null);

  const { 
    transactions, cards, accounts, categories, 
    addTransaction, updateTransaction, deleteTransaction, togglePaid,
    addCard, deleteCard, 
    addAccount, deleteAccount,
    addCategory, updateCategory, deleteCategory, loading: dataLoading
  } = useFinanceData(currentUser?.id || null);

  const [currentView, setCurrentView] = useState<ViewType>('dashboard');
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);

  const [isPaymentModalOpen, setIsPaymentModalOpen] = useState(false);
  const [pendingPaymentId, setPendingPaymentId] = useState<string | null>(null);
  const [selectedPaymentDate, setSelectedPaymentDate] = useState(new Date().toISOString().split('T')[0]);

  const getInitialDates = () => {
    const now = new Date();
    const firstDay = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().split('T')[0];
    const lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0).toISOString().split('T')[0];
    return { firstDay, lastDay };
  };

  const { firstDay: initStart, lastDay: initEnd } = getInitialDates();
  const [startDate, setStartDate] = useState(initStart);
  const [endDate, setEndDate] = useState(initEnd);
  const [selectedCategory, setSelectedCategory] = useState('all');
  const [selectedPayer, setSelectedPayer] = useState('all');
  const [statusFilter, setStatusFilter] = useState<'all' | 'paid' | 'pending'>('all');
  const [isFiltersVisible, setIsFiltersVisible] = useState(false);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session?.user) fetchProfile(session.user);
      else setSessionLoading(false);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((event, session) => {
      if (session?.user) fetchProfile(session.user);
      else { setCurrentUser(null); setSessionLoading(false); }
    });

    return () => subscription.unsubscribe();
  }, []);

  const fetchProfile = async (authUser: any) => {
    try {
      const { data: profile } = await supabase
        .from('profiles')
        .select('name, avatar_color, categories')
        .eq('id', authUser.id)
        .maybeSingle();

      if (profile) {
        setCurrentUser({ id: authUser.id, name: profile.name, avatarColor: profile.avatar_color });
        setDbError(null);
      } else {
        const userName = authUser.user_metadata?.name || authUser.email?.split('@')[0] || 'Usuário';
        const defaultCategories = {
          expense: ['Alimentação', 'Moradia', 'Transporte', 'Lazer', 'Saúde', 'Cartão', 'Outros'],
          income: ['Salário', 'Freelance', 'Investimentos', 'Presentes', 'Outros'],
          payers: [userName.split(' ')[0] || 'Eu'],
          colors: {},
          icons: {}
        };

        const { error: insertError } = await supabase.from('profiles').upsert({
          id: authUser.id,
          name: userName,
          avatar_color: '#4f46e5',
          categories: defaultCategories,
          updated_at: new Date().toISOString()
        });

        if (insertError) {
          setDbError("Atenção: Seu banco está bloqueando a gravação (Regra de INSERT faltando).");
        } else {
          setCurrentUser({ id: authUser.id, name: userName, avatarColor: '#4f46e5' });
          setDbError(null);
        }
      }
    } catch (err) {
      console.error(err);
    } finally {
      setSessionLoading(false);
    }
  };

  const handleLogout = async () => { 
    await supabase.auth.signOut(); 
    setCurrentUser(null); 
    setCurrentView('dashboard'); 
  };

  const formatCurrency = (val: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const handleTogglePaidRequest = (id: string, isPaid: boolean) => {
    if (!isPaid) {
      setPendingPaymentId(id);
      setSelectedPaymentDate(new Date().toISOString().split('T')[0]);
      setIsPaymentModalOpen(true);
    } else {
      if (window.confirm("Deseja marcar este lançamento como Pendente?")) {
        togglePaid(id, true, null);
      }
    }
  };

  const dashboardData = useMemo(() => {
    const filtered = transactions.filter(t => {
      const tDate = t.date.split('T')[0];
      const matchesDate = tDate >= startDate && tDate <= endDate;
      const matchesCategory = selectedCategory === 'all' || t.category === selectedCategory;
      const matchesStatus = statusFilter === 'all' || (statusFilter === 'paid' ? t.is_paid : !t.is_paid);

      let matchesPayer = true;
      if (selectedPayer === 'individual') matchesPayer = true;
      else if (selectedPayer !== 'all') matchesPayer = t.is_split && t.split_details?.partnerName === selectedPayer;

      return matchesDate && matchesCategory && matchesPayer && matchesStatus;
    });

    const summary: Summary = filtered.reduce((acc, t) => {
      let amt = Number(t.amount);
      if (selectedPayer === 'individual' && t.is_split && t.split_details) {
        amt = Number(t.split_details.userPart);
      } else if (selectedPayer !== 'all' && t.is_split && t.split_details) {
        amt = Number(t.split_details.partnerPart);
      }

      if (t.type === 'income') { acc.income += amt; acc.balance += amt; }
      else { acc.expenses += amt; acc.balance -= amt; }
      return acc;
    }, { balance: 0, income: 0, expenses: 0 });

    const groupedByCard = filtered.reduce((acc: any, t) => {
      if (t.type !== 'expense') return acc;
      const cardKey = t.card_id || 'no-card';
      if (!acc[cardKey]) {
        acc[cardKey] = {
          cardId: t.card_id,
          total: 0,
          userPart: 0,
          others: {},
          hasPending: false,
          description: t.card_id ? cards.find(c => c.id === t.card_id)?.name : 'Dinheiro/Pix'
        };
      }
      const amt = Number(t.amount);
      acc[cardKey].total += amt;
      if (!t.is_paid) acc[cardKey].hasPending = true;
      if (t.is_split && t.split_details) {
        acc[cardKey].userPart += Number(t.split_details.userPart);
        const pName = t.split_details.partnerName || 'Indefinido';
        acc[cardKey].others[pName] = (acc[cardKey].others[pName] || 0) + Number(t.split_details.partnerPart);
      } else {
        acc[cardKey].userPart += amt;
      }
      return acc;
    }, {});

    return { filteredTransactions: filtered, summary, cardSummaries: Object.values(groupedByCard) };
  }, [transactions, startDate, endDate, selectedCategory, selectedPayer, statusFilter, cards]);

  const renderFilterBar = () => {
    const allCategories = Array.from(new Set([...categories.expense, ...categories.income])).sort();

    return (
      <div className="bg-white rounded-xl border border-slate-100 shadow-sm mb-6 overflow-hidden">
        {/* Mobile Toggle Button */}
        <button 
          onClick={() => setIsFiltersVisible(!isFiltersVisible)}
          className="w-full px-4 py-3 flex items-center justify-between lg:hidden transition-colors hover:bg-slate-50 border-b border-transparent data-[open=true]:border-slate-100"
          data-open={isFiltersVisible}
        >
          <div className="flex items-center gap-2">
            <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" className="text-indigo-600">
              <path d="M21 4H3"/><path d="M20 8H4"/><path d="M18 12H6"/><path d="M15 16H9"/><path d="M12 20H12"/>
            </svg>
            <span className="text-[10px] font-black uppercase tracking-widest text-slate-700">Filtrar Lançamentos</span>
          </div>
          <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" className={`text-slate-300 transition-transform duration-300 ${isFiltersVisible ? 'rotate-180' : ''}`}>
            <path d="m6 9 6 6 6-6"/>
          </svg>
        </button>

        {/* Filter Content */}
        <div className={`p-4 ${isFiltersVisible ? 'block animate-in slide-in-from-top-2 duration-300' : 'hidden lg:block'}`}>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-6 gap-3 items-end">
            <div>
              <label className="text-[9px] font-bold text-slate-400 uppercase mb-1.5 block">Início</label>
              <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="w-full bg-slate-50 border-none rounded-md px-3 py-2 text-xs font-bold text-indigo-600 outline-none" />
            </div>
            <div>
              <label className="text-[9px] font-bold text-slate-400 uppercase mb-1.5 block">Fim</label>
              <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="w-full bg-slate-50 border-none rounded-md px-3 py-2 text-xs font-bold text-indigo-600 outline-none" />
            </div>
            <div>
              <label className="text-[9px] font-bold text-slate-400 uppercase mb-1.5 block">Pagante</label>
              <select value={selectedPayer} onChange={(e) => setSelectedPayer(e.target.value)} className="w-full bg-slate-50 border-none rounded-md px-4 py-2 text-xs font-bold text-slate-700 outline-none">
                <option value="all">Todos</option>
                <option value="individual">Apenas Eu</option>
                {categories.payers?.map(p => <option key={p} value={p}>{p}</option>)}
              </select>
            </div>
            <div>
              <label className="text-[9px] font-bold text-slate-400 uppercase mb-1.5 block">Status</label>
              <select value={statusFilter} onChange={(e) => setStatusFilter(e.target.value as any)} className="w-full bg-slate-50 border-none rounded-md px-4 py-2 text-xs font-bold text-slate-700 outline-none">
                <option value="all">Todos</option>
                <option value="paid">Pago</option>
                <option value="pending">Pendente</option>
              </select>
            </div>
            <div>
              <label className="text-[9px] font-bold text-slate-400 uppercase mb-1.5 block">Categoria</label>
              <select value={selectedCategory} onChange={(e) => setSelectedCategory(e.target.value)} className="w-full bg-slate-50 border-none rounded-md px-4 py-2 text-xs font-bold text-slate-700 outline-none">
                <option value="all">Todas</option>
                {allCategories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
              </select>
            </div>
            <button 
              onClick={() => { 
                const { firstDay, lastDay } = getInitialDates();
                setStartDate(firstDay); 
                setEndDate(lastDay); 
                setSelectedCategory('all');
                setSelectedPayer('all');
                setStatusFilter('all');
                if (window.innerWidth < 1024) setIsFiltersVisible(false);
              }} 
              className="w-full py-2 text-[10px] font-bold text-slate-400 uppercase hover:text-indigo-600 transition-colors"
            >
              Limpar Filtros
            </button>
          </div>
        </div>
      </div>
    );
  };

  const renderTransactionManagement = (type: TransactionType) => {
    const filtered = transactions
      .filter(t => {
        if (t.type !== type) return false;
        const tDate = t.date.split('T')[0];
        if (tDate < startDate || tDate > endDate) return false;
        if (selectedCategory !== 'all' && t.category !== selectedCategory) return false;
        if (statusFilter === 'paid' && !t.is_paid) return false;
        if (statusFilter === 'pending' && t.is_paid) return false;
        return true;
      })
      .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

