                    <td className={`py-4 px-3 text-right font-bold text-sm ${t.type === 'income' ? 'text-teal-600' : 'text-rose-500'} ${!t.is_paid ? 'opacity-50' : ''} print:opacity-100`}>
                      {formatCurrency(displayVal)}
