import { GoogleGenAI, Type } from "@google/genai";
import { Transaction } from "../types";

export interface AIInsightResponse {
  analysis: string;
  savings: string;
  tip: string;
}

export const getFinancialInsights = async (transactions: Transaction[]): Promise<AIInsightResponse | string> => {
  if (transactions.length < 3) return "Adicione pelo menos 3 transações para que eu possa analisar seus padrões financeiros.";

  const summary = transactions.slice(0, 15).map(t => ({
    t: t.type === 'income' ? 'E' : 'S', // E=Entrada, S=Saída
    v: t.amount,
    c: t.category,
    d: t.description,
    p: t.is_paid ? 'S' : 'N',
    dt: t.date.split('T')[0]
  }));

  const prompt = `Analise este resumo financeiro: ${JSON.stringify(summary)}. 
  Forneça 3 insights curtos e amigáveis em português. Use uma linguagem simples.`;

  try {
    // Inicialização direta conforme diretrizes
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const result = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction: "Você é um consultor financeiro amigável e direto. Retorne sempre um JSON válido com os campos: analysis (sobre o fluxo atual), savings (onde economizar) e tip (conselho pro futuro).",
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            analysis: { type: Type.STRING },
            savings: { type: Type.STRING },
            tip: { type: Type.STRING },
          },
          required: ["analysis", "savings", "tip"],
        },
        temperature: 0.7,
      },
    });

    const text = result.text;
    if (text) {
      return JSON.parse(text) as AIInsightResponse;
    }
    return "A IA não conseguiu processar os dados agora. Tente novamente.";
  } catch (error: any) {
    console.error("Gemini API Error:", error);
    if (error?.message?.includes("API key not found")) {
      return "Chave de API não configurada. Verifique o ambiente.";
    }
    return "Ocorreu um erro na conexão com a IA. Por favor, tente em alguns instantes.";
  }
};

import React, { useState, useEffect } from 'react';
import { Transaction } from '../types';
import { getFinancialInsights, AIInsightResponse } from '../services/geminiService';

interface AIInsightsProps {
  transactions: Transaction[];
}

const AIInsights: React.FC<AIInsightsProps> = ({ transactions }) => {
  const [insight, setInsight] = useState<AIInsightResponse | string | null>(null);
  const [loading, setLoading] = useState(false);

  const fetchInsight = async () => {
    if (transactions.length < 3) {
      setInsight("Lance pelo menos 3 transações para desbloquear a análise personalizada da IA.");
      return;
    }
    setLoading(true);
    const result = await getFinancialInsights(transactions);
    setInsight(result);
    setLoading(false);
  };

  useEffect(() => {
    fetchInsight();
  }, [transactions.length < 3]);

  const isStructured = (data: any): data is AIInsightResponse => {
    return data && typeof data === 'object' && 'analysis' in data;
  };

  return (
    <div className="bg-white rounded-2xl border border-indigo-100 shadow-sm overflow-hidden transition-all hover:border-indigo-200">
      <div className="bg-indigo-600/5 px-5 py-4 flex items-center justify-between border-b border-indigo-50">
        <div className="flex items-center gap-2.5">
          <div className="bg-indigo-600 text-white p-2 rounded-xl shadow-md shadow-indigo-200">
            <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3"><path d="M12 2v8"/><path d="m4.93 4.93 7.07 7.07"/><path d="M2 12h8"/><path d="m4.93 19.07 7.07-7.07"/><path d="M12 22v-8"/><path d="m19.07 19.07-7.07-7.07"/><path d="M22 12h-8"/><path d="m19.07 4.93-7.07 7.07"/></svg>
          </div>
          <h3 className="text-xs font-black text-indigo-900 uppercase tracking-widest">Consultor Estratégico IA</h3>
        </div>

        {transactions.length >= 3 && (
          <button 
            onClick={fetchInsight} 
            disabled={loading}
            className="p-2 text-indigo-400 hover:text-indigo-600 hover:bg-white rounded-lg transition-all disabled:opacity-30"
