            const styles = getCategoryStyles(t.category, categories);
            const inlineStyles = styles.isCustom ? {
              backgroundColor: `${styles.customColor}15`,
              color: styles.customColor,
              borderColor: `${styles.customColor}30`
            } : {};

            return (
