                  { id: 'categories', label: 'Categorias', icon: <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="m16 6 4 14"/><path d="M12 6v14"/></svg> },
