                      <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M3 6h18"/><path d="M19 6v14c0 1-1 2-2 2H7c-1 0-2-1-2-2V6"/></svg>
                    </button>
                  </div>
                </div>
              </div>
            );
          })}
        </div>

        {filtered.length === 0 && (
          <div className="py-20 text-center text-slate-300 font-black text-[10px] uppercase tracking-widest">Nenhum lançamento encontrado</div>
        )}
      </div>
    );
  };

  const renderContent = () => {
    switch (currentView) {
      case 'dashboard':
        return (
          <div className="space-y-6 md:space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-24 md:pb-0">
            {dbError && (
              <div className="p-5 bg-rose-600 rounded-xl shadow-2xl shadow-rose-100 flex flex-col md:flex-row items-center gap-6 border border-rose-500 animate-in zoom-in-95">
                <div className="w-12 h-12 bg-white/20 rounded-lg flex items-center justify-center text-white shrink-0">
                   <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3"><path d="m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3Z"/><line x1="12" x2="12" y1="9" y2="13"/><line x1="12" x2="12.01" y1="17" y2="17"/></svg>
                </div>
                <div className="flex-1 text-center md:text-left">
                  <p className="text-xs font-black text-white uppercase tracking-widest leading-relaxed">{dbError}</p>
                </div>
              </div>
            )}

            <div className="mb-6 text-center md:text-left">
              <h1 className="text-xl md:text-2xl font-bold text-slate-900 tracking-tight">
                Olá, <span className="text-indigo-600">{currentUser?.name.split(' ')[0]}!</span> 👋
              </h1>
              <p className="text-xs font-medium text-slate-400 mt-1">Sua situação financeira hoje</p>
            </div>

            {renderFilterBar()}

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
              <div className="lg:col-span-8 space-y-6">
                <SummaryCards summary={dashboardData.summary} />
                <AIInsights transactions={dashboardData.filteredTransactions} />
                <Charts transactions={dashboardData.filteredTransactions} categories={categories} />
              </div>
              <div className="lg:col-span-4">
                <div className="bg-white p-5 rounded-xl shadow-sm border border-slate-100 h-full">
                  <h2 className="text-[10px] font-black text-slate-900 tracking-tight uppercase mb-6 border-b border-slate-50 pb-3">Extrato por Pagante</h2>
                  <div className="space-y-3">
                    {dashboardData.cardSummaries.map((card: any) => (
                      <div key={card.cardId || 'cash'} className="p-4 bg-slate-50/40 rounded-lg border border-slate-100">
                        <div className="flex justify-between items-start mb-4">
                          <h4 className="font-black text-[10px] text-slate-900 uppercase tracking-widest">{card.description}</h4>
                        </div>
                        <div className="pt-3 border-t border-slate-100/60 space-y-2">
                          <div className="flex justify-between items-baseline"><span className="text-[8px] font-black text-slate-400 uppercase tracking-tighter">VOCÊ</span><span className="text-xs font-black text-slate-900">{formatCurrency(card.userPart)}</span></div>
                          {Object.entries(card.others).map(([name, val]: [any, any]) => (
                            <div key={name} className="flex justify-between items-baseline"><span className="text-[8px] font-black text-indigo-400 uppercase tracking-tighter">{name}</span><span className="text-xs font-black text-indigo-600">{formatCurrency(val as number)}</span></div>
                          ))}
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </div>
          </div>
        );
      case 'add-expense': return renderTransactionManagement('expense');
      case 'add-income': return renderTransactionManagement('income');
      case 'payers': return <PayerManager categories={categories} onAdd={addCategory} onDelete={deleteCategory} />;
      case 'cards': return <CardManager cards={cards} accounts={accounts} transactions={transactions} onAdd={addCard} onUpdate={updateCard} onDelete={deleteCard} />;
      case 'accounts': return <AccountManager accounts={accounts} transactions={transactions} categories={categories} cards={cards} onAdd={addAccount} onDelete={deleteAccount} onTogglePaid={togglePaid} onDeleteTransaction={deleteTransaction} />;
      case 'reports': return <Reports transactions={transactions} categories={categories} />;
      case 'payer-reports': return <PayerReports transactions={transactions} categories={categories} />;
      case 'categories': return <CategoryManager categories={categories} onAdd={addCategory} onUpdate={updateCategory} onDelete={deleteCategory} />;
    }
  };

  if (sessionLoading) return <div className="min-h-screen flex items-center justify-center"><div className="w-8 h-8 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div></div>;
  if (!currentUser) return <AuthScreen onSelectUser={setCurrentUser} />;

  const viewTitles: Record<string, string> = {
    'dashboard': 'Visão Geral', 'cards': 'Meus Cartões', 'accounts': 'Minhas Contas', 'add-expense': 'Despesas', 'add-income': 'Receitas', 'categories': 'Categorias', 'reports': 'Extrato', 'payers': 'Pagantes', 'payer-reports': 'Acerto de Contas'
  };

  const showNewTransactionButton = !['dashboard', 'reports', 'payer-reports', 'cards', 'accounts'].includes(currentView);

  return (
    <div className="flex min-h-screen bg-slate-50/50">
      <Sidebar 
        currentView={currentView} 
        onViewChange={setCurrentView} 
        onAddClick={() => { setEditingTransaction(null); setIsFormOpen(true); }}
        currentUser={currentUser} 
        onLogout={handleLogout} 
      />
      <main className="flex-1 p-4 md:p-8 w-full max-w-7xl mx-auto">
        <header className="mb-6 md:mb-10 flex flex-col items-center text-center">
          <h2 className="text-2xl md:text-3xl font-black text-slate-900 tracking-tight uppercase">{viewTitles[currentView]}</h2>
          {showNewTransactionButton && (
            <button 
              onClick={() => { setEditingTransaction(null); setIsFormOpen(true); }} 
              className="mt-4 bg-indigo-600 text-white px-8 py-3 rounded-lg shadow-xl hover:bg-indigo-700 transition-all font-black text-[10px] uppercase tracking-widest hidden md:flex items-center gap-2 active:scale-95"
            >
              <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4"><path d="M12 5v14M5 12h14"/></svg>
              Novo Lançamento
            </button>
          )}
        </header>

        {isFormOpen && (
          <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[120] overflow-y-auto p-4 md:flex md:justify-center md:items-start py-8 md:py-16">
            <div className="w-full max-w-2xl mx-auto">
              <TransactionForm onAdd={addTransaction} onUpdate={updateTransaction} editingTransaction={editingTransaction} categories={categories} cards={cards} onCancel={() => setIsFormOpen(false)} initialType={currentView === 'add-income' ? 'income' : 'expense'} />
            </div>
          </div>
        )}

        {isPaymentModalOpen && (
          <div className="fixed inset-0 z-[130] bg-slate-900/50 backdrop-blur-sm flex items-center justify-center p-4 animate-in fade-in duration-200">
            <div className="bg-white p-6 rounded-xl shadow-2xl max-w-md w-full animate-in zoom-in-95">
              <h3 className="text-lg font-bold text-slate-900 mb-2">
                {pendingPaymentStatus ? 'Reabrir Lançamento?' : 'Confirmar Pagamento?'}
              </h3>
              <p className="text-xs text-slate-500 mb-6 font-medium">
                {pendingPaymentStatus 
                  ? 'Isso marcará a transação como PENDENTE novamente.' 
                  : 'Informe a data que o pagamento foi realizado.'}
              </p>
              {!pendingPaymentStatus && (
                <div className="mb-6">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1.5 ml-1">Data do Pagamento</label>
                  <input 
                    type="date" 
                    value={selectedPaymentDate} 
                    onChange={e => setSelectedPaymentDate(e.target.value)}
                    className="w-full px-4 py-3 bg-slate-50 rounded-lg text-sm font-bold text-slate-900 outline-none border border-transparent focus:border-indigo-100"
                  />
                </div>
              )}
              <div className="flex gap-3">
                <button onClick={() => setIsPaymentModalOpen(false)} className="flex-1 py-3 text-slate-400 font-bold text-[10px] uppercase tracking-widest hover:text-slate-600 transition-colors">Cancelar</button>
                <button onClick={confirmPaymentStatus} className={`flex-1 ${pendingPaymentStatus ? 'bg-amber-500 hover:bg-amber-600' : 'bg-teal-600 hover:bg-teal-700'} text-white rounded-lg font-bold text-[10px] uppercase tracking-widest shadow-lg transition-all active:scale-95`}>Confirmar</button>
              </div>
            </div>
          </div>
        )}

        {isDeleteModalOpen && (
          <div className="fixed inset-0 z-[130] bg-slate-900/50 backdrop-blur-sm flex items-center justify-center p-4 animate-in fade-in duration-200">
             <div className="bg-white p-6 rounded-xl shadow-2xl max-w-md w-full animate-in zoom-in-95 border border-rose-100">
                <div className="w-12 h-12 bg-rose-50 rounded-full flex items-center justify-center text-rose-500 mb-4 mx-auto">
                   <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M3 6h18"/><path d="M19 6v14c0 1-1 2-2 2H7c-1 0-2-1-2-2V6"/></svg>
                </div>
                <h3 className="text-lg font-bold text-slate-900 mb-2 text-center">Excluir Lançamento?</h3>
                <p className="text-xs text-slate-500 mb-6 font-medium text-center">Tem certeza que deseja remover este item? Esta ação não pode ser desfeita.</p>
                <div className="flex gap-3">
                  <button onClick={() => setIsDeleteModalOpen(false)} className="flex-1 py-3 text-slate-400 font-bold text-[10px] uppercase tracking-widest hover:text-slate-600 transition-colors">Cancelar</button>
                  <button onClick={confirmDelete} className="flex-1 bg-rose-500 hover:bg-rose-600 text-white rounded-lg font-bold text-[10px] uppercase tracking-widest shadow-lg shadow-rose-100 transition-all active:scale-95">Sim, Excluir</button>
                </div>
             </div>
          </div>
        )}

        <div className="w-full max-w-full mx-auto">
          {renderContent()}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Transaction, TransactionType, UserCategories, CreditCard, Account, SplitDetails } from '../types';
import { supabase } from '../services/supabaseClient';

interface TransactionFormProps {
  onAdd: (data: any) => Promise<boolean>;
  onUpdate?: (id: string, data: any) => Promise<boolean>;
  editingTransaction?: Transaction | null;
  categories: UserCategories;
  cards: CreditCard[];
  onCancel?: () => void;
  initialType?: TransactionType;
}

const TransactionForm: React.FC<TransactionFormProps> = ({ 
  onAdd, 
  onUpdate,
  editingTransaction,
  categories, 
  cards, 
  onCancel, 
  initialType = 'expense' 
}) => {
  const [description, setDescription] = useState('');
  const [amount, setAmount] = useState('');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [paymentDate, setPaymentDate] = useState(new Date().toISOString().split('T')[0]);
  const [type, setType] = useState<TransactionType>(initialType);
  const [category, setCategory] = useState('');

  // Seleção de meio de pagamento
  const [selectedCardId, setSelectedCardId] = useState('');
  const [selectedAccountId, setSelectedAccountId] = useState('');
  const [availableAccounts, setAvailableAccounts] = useState<Account[]>([]);

  const [installments, setInstallments] = useState(1);
  const [installmentMode, setInstallmentMode] = useState<'divide' | 'repeat'>('divide');
  const [isSplit, setIsSplit] = useState(false);
  const [isPaid, setIsPaid] = useState(false);
  const [partnerPart, setPartnerPart] = useState('');
  const [partnerName, setPartnerName] = useState(categories.payers?.[0] || 'Isa');
  const [success, setSuccess] = useState(false);
  const [loading, setLoading] = useState(false);

  // Buscar contas ao montar
  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session?.user) {
        supabase.from('accounts').select('*').eq('user_id', session.user.id)
          .then(({ data }) => { if (data) setAvailableAccounts(data); });
      }
    });
  }, []);

  useEffect(() => {
    if (editingTransaction) {
      setDescription(editingTransaction.description);
      setAmount(editingTransaction.amount.toString());
      setDate(editingTransaction.date.split('T')[0]);
      setPaymentDate(editingTransaction.payment_date ? editingTransaction.payment_date.split('T')[0] : new Date().toISOString().split('T')[0]);
      setType(editingTransaction.type);
      setCategory(editingTransaction.category);
      setSelectedCardId(editingTransaction.card_id || '');
      setSelectedAccountId(editingTransaction.account_id || '');
      setIsSplit(!!editingTransaction.is_split);
      setIsPaid(editingTransaction.is_paid);
      if (editingTransaction.split_details) {
        setPartnerPart(editingTransaction.split_details.partnerPart.toString());
        setPartnerName(editingTransaction.split_details.partnerName);
      }
    } else {
      setDescription('');
      setAmount('');
      setDate(new Date().toISOString().split('T')[0]);
      setPaymentDate(new Date().toISOString().split('T')[0]);
      setType(initialType);
      setCategory(categories[initialType][0] || 'Outros');
      setSelectedCardId('');
      setSelectedAccountId('');
      setInstallments(1);
      setInstallmentMode('divide');
      setIsSplit(false);
      setIsPaid(false);
      setPartnerPart('');
      setPartnerName(categories.payers?.[0] || 'Isa');
    }
  }, [editingTransaction, initialType, categories]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!description || !amount || !date || loading) return;
    setLoading(true);

    try {
      const inputValue = parseFloat(amount);
      const getSafeISO = (dateStr: string) => {
        const d = new Date(dateStr + 'T12:00:00');
        return d.toISOString();
      };

      // Define se usa cartão ou conta
      const finalCardId = selectedCardId || null;
      // Permite salvar a conta mesmo se tiver cartão (para manter o vínculo)
      const finalAccountId = selectedAccountId || null;

      if (editingTransaction && onUpdate) {
        const splitInfo: SplitDetails | undefined = isSplit ? {
          userPart: inputValue - (parseFloat(partnerPart) || 0),
          partnerPart: parseFloat(partnerPart) || 0,
          partnerName: partnerName
        } : undefined;

        const res = await onUpdate(editingTransaction.id, {
          description,
          amount: inputValue,
          type,
          category,
          date: getSafeISO(date),
          payment_date: isPaid ? getSafeISO(paymentDate) : null,
          card_id: finalCardId,
          account_id: finalAccountId,
          is_split: isSplit,
          split_details: splitInfo,
          is_paid: isPaid
        });

        if (res) {
          setSuccess(true);
          setTimeout(() => { if (onCancel) onCancel(); }, 800);
        } else {
          setLoading(false);
        }
        return;
      }

      const numInstallments = Math.max(1, installments);
      const amountPerInstallment = installmentMode === 'divide' ? inputValue / numInstallments : inputValue;
      const pPartInput = parseFloat(partnerPart) || 0;
      const pPartPerMonth = installmentMode === 'divide' ? pPartInput / numInstallments : pPartInput;
      const uPartPerMonth = amountPerInstallment - pPartPerMonth;

      const [year, month, day] = date.split('-').map(Number);
      let allSuccess = true;

      for (let i = 0; i < numInstallments; i++) {
        const targetDate = new Date(year, month - 1 + i, day, 12, 0, 0);
        const installmentLabel = numInstallments > 1 ? ` (${i + 1}/${numInstallments})` : '';
        const splitInfo: SplitDetails | undefined = isSplit ? {
          userPart: uPartPerMonth,
          partnerPart: pPartPerMonth,
          partnerName: partnerName
        } : undefined;

        const res = await onAdd({
          description: description + installmentLabel,
          amount: amountPerInstallment,
          type,
          category: category || 'Outros',
          date: targetDate.toISOString(),
          payment_date: isPaid ? targetDate.toISOString() : null,
          card_id: finalCardId,
          account_id: finalAccountId,
          is_split: isSplit,
          split_details: splitInfo,
          is_paid: isPaid
        });
        if (!res) allSuccess = false;
      }

      if (allSuccess) {
        setSuccess(true);
        setTimeout(() => { if (onCancel) onCancel(); }, 1000);
      } else {
        setLoading(false);
      }
    } catch (err) {
      setLoading(false);
    }
  };

  const formatCurrency = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const inputClasses = "w-full h-[38px] px-3 bg-slate-50 border border-transparent focus:border-indigo-100 focus:bg-white rounded-md outline-none text-xs font-bold text-slate-800 placeholder:text-slate-300 transition-all flex items-center";
  const labelClasses = "text-[9px] font-black text-slate-400 uppercase tracking-widest block mb-1 ml-0.5";

  return (
    <div className="bg-white p-4 md:p-7 rounded-xl shadow-2xl border border-slate-100 w-full animate-in fade-in zoom-in duration-300 relative pb-6 md:pb-7">
      <div className="flex justify-between items-center mb-4 md:mb-6">
        <h2 className="text-lg md:text-xl font-black text-slate-900 tracking-tight">
          {editingTransaction ? 'Editar Lançamento' : 'Novo Lançamento'}
        </h2>
        {onCancel && (
          <button onClick={onCancel} className="p-1.5 text-slate-300 hover:text-slate-500 transition-all">
            <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3"><path d="M18 6 6 18"/><path d="m6 6 12 12"/></svg>
          </button>
        )}
      </div>

      <form onSubmit={handleSubmit} className="space-y-3 md:space-y-4">
        {!editingTransaction && (
          <div className="flex p-1 bg-slate-100/50 rounded-lg max-w-xs">
            {(['expense', 'income'] as const).map((t) => (
              <button
                key={t}
                type="button"
                onClick={() => { setType(t); setCategory(categories[t][0] || 'Outros'); }}
                className={`flex-1 py-1 rounded text-[9px] font-black tracking-widest transition-all uppercase flex items-center justify-center gap-2 ${type === t ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}
              >
                {t === 'expense' ? 'DESPESA' : 'RECEITA'}
              </button>
            ))}
          </div>
        )}

        <div className="space-y-3 md:space-y-4">
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-3 md:gap-4">
            <div className="lg:col-span-6">
              <label className={labelClasses}>Descrição</label>
              <input type="text" value={description} onChange={e => setDescription(e.target.value)} className={inputClasses} placeholder="O que você comprou?" required />
            </div>
            <div className="lg:col-span-3">
              <label className={labelClasses}>Data de Vencimento</label>
              <input type="date" value={date} onChange={e => setDate(e.target.value)} className={inputClasses} required />
            </div>
            <div className="lg:col-span-3">
              <div className="flex items-center justify-between mb-1">
                <label className={labelClasses}>Pago?</label>
                <button type="button" onClick={() => setIsPaid(!isPaid)} className={`w-9 h-5 rounded-full transition-all relative ${isPaid ? 'bg-teal-500' : 'bg-slate-200'}`}>
                  <div className={`absolute top-0.5 w-4 h-4 bg-white rounded-full shadow-sm transition-all ${isPaid ? 'left-4.5' : 'left-0.5'}`}></div>
                </button>
              </div>
              {isPaid && (
                <input type="date" value={paymentDate} onChange={e => setPaymentDate(e.target.value)} className={`${inputClasses} bg-teal-50/20 border-teal-50`} required />
              )}
            </div>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-3 md:gap-4">
            <div>
              <label className={labelClasses}>Valor Total</label>
              <input type="number" step="0.01" value={amount} onChange={e => setAmount(e.target.value)} className={`${inputClasses} font-black text-sm`} placeholder="0,00" required />
            </div>
            <div>
              <label className={labelClasses}>Categoria</label>
              <select value={category} onChange={e => setCategory(e.target.value)} className={`${inputClasses} appearance-none pr-8 bg-[url('data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%2212%22%20height%3D%2212%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%23cbd5e1%22%20stroke-width%3D%223%22%3E%3Cpath%20d%3D%22m6%209%206%206%206-6%22%2F%3E%3C%2Fsvg%3E')] bg-[length:12px_12px] bg-[right_0.6rem_center] bg-no-repeat`}>
                {categories[type].map(cat => <option key={cat} value={cat}>{cat}</option>)}
              </select>
            </div>

            {/* Lógica de Seleção de Pagamento */}
            <div className="md:col-span-2 grid grid-cols-2 gap-3">
               <div>
                  <label className={labelClasses}>Cartão de Crédito</label>
                  <select 
                    value={selectedCardId} 
                    onChange={e => { 
                      const newCardId = e.target.value;
                      setSelectedCardId(newCardId);

                      // Auto-vincula a conta se o cartão tiver uma configurada
                      if (newCardId) {
                        const card = cards.find(c => c.id === newCardId);
                        if (card?.account_id) {
                          setSelectedAccountId(card.account_id);
                        } else {
                          setSelectedAccountId('');
                        }
                      } else {
                        setSelectedAccountId(''); 
                      }
                    }} 
                    className={`${inputClasses} appearance-none pr-8 bg-[url('data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%2212%22%20height%3D%2212%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%23cbd5e1%22%20stroke-width%3D%223%22%3E%3Cpath%20d%3D%22m6%209%206%206%206-6%22%2F%3E%3C%2Fsvg%3E')] bg-[length:12px_12px] bg-[right_0.6rem_center] bg-no-repeat`}
                  >
                    <option value="">Não usar cartão</option>
                    {cards.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                  </select>
               </div>
               <div>
                  <label className={labelClasses}>Conta / Carteira</label>
                  <select 
                    value={selectedAccountId} 
                    onChange={e => setSelectedAccountId(e.target.value)} 
                    disabled={!!selectedCardId}
                    className={`${inputClasses} ${!!selectedCardId ? 'opacity-70 bg-slate-100' : ''} appearance-none pr-8 bg-[url('data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%2212%22%20height%3D%2212%22%20viewBox%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%23cbd5e1%22%20stroke-width%3D%223%22%3E%3Cpath%20d%3D%22m6%209%206%206%206-6%22%2F%3E%3C%2Fsvg%3E')] bg-[length:12px_12px] bg-[right_0.6rem_center] bg-no-repeat`}
                  >
                    <option value="">Sem conta vinculada</option>
                    {availableAccounts.map(a => <option key={a.id} value={a.id}>{a.name}</option>)}
                  </select>
               </div>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
             <div className="md:col-start-4">
               <label className={`${labelClasses} text-indigo-500`}>Nº Meses</label>
               <input type="number" min="1" max="99" value={installments} disabled={!!editingTransaction} onChange={e => setInstallments(parseInt(e.target.value) || 1)} className={`${inputClasses} border-indigo-50 bg-indigo-50/20 disabled:opacity-40`} />
             </div>
          </div>

          {!editingTransaction && installments > 1 && (
            <div className="flex flex-col sm:flex-row items-center gap-3 bg-slate-50/50 p-3 rounded-lg border border-slate-100">
              <div className="flex p-0.5 bg-white rounded-md border border-slate-100">
                <button type="button" onClick={() => setInstallmentMode('divide')} className={`px-3 py-1 rounded-sm text-[8px] font-black uppercase tracking-widest ${installmentMode === 'divide' ? 'bg-indigo-600 text-white' : 'text-slate-400'}`}>Ratear</button>
                <button type="button" onClick={() => setInstallmentMode('repeat')} className={`px-3 py-1 rounded-sm text-[8px] font-black uppercase tracking-widest ${installmentMode === 'repeat' ? 'bg-indigo-600 text-white' : 'text-slate-400'}`}>Repetir</button>
              </div>
              {amount && (
                <p className="text-[9px] font-black text-slate-500 uppercase tracking-widest">
                  Plano: <span className="text-indigo-600">{installments}x</span> de <span className="text-indigo-600">{formatCurrency(installmentMode === 'divide' ? parseFloat(amount) / installments : parseFloat(amount))}</span>
                </p>
              )}
            </div>
          )}

          {type === 'expense' && (
            <div className={`p-3 md:p-4 rounded-lg border transition-all ${isSplit ? 'bg-indigo-50/10 border-indigo-100' : 'bg-slate-50/30 border-slate-50'}`}>
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-3">
                   <div className={`w-8 h-8 rounded flex items-center justify-center transition-all ${isSplit ? 'bg-indigo-600 text-white' : 'bg-slate-100 text-slate-300'}`}>
                     <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3"><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/></svg>
                   </div>
                   <div className="leading-none">
                     <span className="text-[10px] font-black text-slate-800 uppercase tracking-widest block mb-0.5">Dividir com Pagante</span>
                     <span className="text-[8px] font-bold text-slate-400 uppercase tracking-tight">Rateio de despesa comum</span>
                   </div>
                </div>
                <button type="button" onClick={() => setIsSplit(!isSplit)} className={`w-9 h-5 rounded-full transition-all relative ${isSplit ? 'bg-indigo-600' : 'bg-slate-200'}`}>
                  <div className={`absolute top-0.5 w-4 h-4 bg-white rounded-full shadow-sm transition-all ${isSplit ? 'left-4.5' : 'left-0.5'}`}></div>
                </button>
              </div>
              {isSplit && (
                <div className="mt-3 pt-3 border-t border-indigo-100/30 grid grid-cols-1 sm:grid-cols-2 gap-3 animate-in fade-in slide-in-from-top-2">
                  <div>
                    <label className="text-[8px] font-black text-indigo-400 uppercase mb-1 block">Quem é o pagante?</label>
                    <select value={partnerName} onChange={e => setPartnerName(e.target.value)} className="w-full h-9 px-3 bg-white rounded-md border border-indigo-50 text-[11px] font-black text-slate-800 outline-none">
                      {categories.payers?.map(p => <option key={p} value={p}>{p}</option>)}
                    </select>
                  </div>
                  <div>
                    <label className="text-[8px] font-black text-indigo-400 uppercase mb-1 block">Parte dele(a)</label>
                    <input type="number" step="0.01" value={partnerPart} onChange={e => setPartnerPart(e.target.value)} placeholder="0,00" className="w-full h-9 px-3 bg-white rounded-md border border-indigo-50 text-[11px] font-black text-indigo-600 outline-none" />
                  </div>
                </div>
              )}
            </div>
          )}
        </div>

        <div className="pt-3 md:pt-4 pb-2 md:pb-0">
          <button type="submit" disabled={success || loading} className={`w-full py-3.5 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all text-white shadow-lg active:scale-[0.98] ${success ? 'bg-teal-500' : 'bg-indigo-600 hover:bg-indigo-700 disabled:opacity-50'}`}>
            {loading ? 'Processando...' : (success ? '✓ Atualizado' : (editingTransaction ? 'Salvar Alterações' : 'Confirmar Lançamento'))}
          </button>
        </div>
      </form>
    </div>
  );
};

export default TransactionForm;

export type TransactionType = 'income' | 'expense';

export interface User {
  id: string;
  name: string;
  avatarColor: string;
}

export interface SplitDetails {
  userPart: number;
  partnerPart: number;
  partnerName: string;
}

export interface Account {
  id: string;
  name: string;
  type: 'checking' | 'investment' | 'cash' | 'savings' | 'other';
  initial_balance: number;
  initial_invested_balance?: number; 
  color: string;
}

export interface Transaction {
  id: string;
  description: string;
  amount: number;
  type: TransactionType;
  category: string;
  date: string;
  payment_date?: string | null;
  card_id?: string | null;
  account_id?: string | null;
  is_split?: boolean;
  split_details?: SplitDetails;
  is_paid: boolean;
  is_reserve_withdrawal?: boolean;
}

export interface CreditCard {
  id: string;
  name: string;
  color: string;
  credit_limit: number;
  closing_day: number;
  due_day: number;
  account_id?: string | null;
}

export interface Summary {
  balance: number;
  income: number;
  expenses: number;
}

export interface UserCategories {
  expense: string[];
  income: string[];
  payers: string[];
  colors?: Record<string, string>;
  icons?: Record<string, string>;
}

import React, { useState, useEffect } from 'react';
import { Transaction, TransactionType, UserCategories, CreditCard, Account, SplitDetails } from '../types';
import { supabase } from '../services/supabaseClient';

interface TransactionFormProps {
  onAdd: (data: any) => Promise<boolean>;
  onUpdate?: (id: string, data: any) => Promise<boolean>;
  editingTransaction?: Transaction | null;
  categories: UserCategories;
  cards: CreditCard[];
  onCancel?: () => void;
  initialType?: TransactionType;
}

const TransactionForm: React.FC<TransactionFormProps> = ({ 
  onAdd, 
  onUpdate,
  editingTransaction,
  categories, 
  cards, 
  onCancel, 
  initialType = 'expense' 
}) => {
  const [description, setDescription] = useState('');
  const [amount, setAmount] = useState('');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [paymentDate, setPaymentDate] = useState(new Date().toISOString().split('T')[0]);
  const [type, setType] = useState<TransactionType>(initialType);
  const [category, setCategory] = useState('');

  const [selectedCardId, setSelectedCardId] = useState('');
  const [selectedAccountId, setSelectedAccountId] = useState('');
  const [availableAccounts, setAvailableAccounts] = useState<Account[]>([]);

  const [installments, setInstallments] = useState(1);
  const [installmentMode, setInstallmentMode] = useState<'divide' | 'repeat'>('divide');
  const [isSplit, setIsSplit] = useState(false);
  const [isPaid, setIsPaid] = useState(false);
  const [isReserveWithdrawal, setIsReserveWithdrawal] = useState(false);
  const [partnerPart, setPartnerPart] = useState('');
  const [partnerName, setPartnerName] = useState(categories.payers?.[0] || 'Isa');
  const [success, setSuccess] = useState(false);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session?.user) {
        supabase.from('accounts').select('*').eq('user_id', session.user.id)
          .then(({ data }) => { if (data) setAvailableAccounts(data); });
      }
    });
  }, []);

  useEffect(() => {
    if (editingTransaction) {
      setDescription(editingTransaction.description);
      setAmount(editingTransaction.amount.toString());
      setDate(editingTransaction.date.split('T')[0]);
      setPaymentDate(editingTransaction.payment_date ? editingTransaction.payment_date.split('T')[0] : new Date().toISOString().split('T')[0]);
      setType(editingTransaction.type);
      setCategory(editingTransaction.category);
      setSelectedCardId(editingTransaction.card_id || '');
      setSelectedAccountId(editingTransaction.account_id || '');
      setIsSplit(!!editingTransaction.is_split);
      setIsPaid(editingTransaction.is_paid);
      setIsReserveWithdrawal(!!editingTransaction.is_reserve_withdrawal);
      if (editingTransaction.split_details) {
        setPartnerPart(editingTransaction.split_details.partnerPart.toString());
        setPartnerName(editingTransaction.split_details.partnerName);
      }
    } else {
      setDescription('');
      setAmount('');
      setDate(new Date().toISOString().split('T')[0]);
      setPaymentDate(new Date().toISOString().split('T')[0]);
      setType(initialType);
      setCategory(categories[initialType][0] || 'Outros');
      setSelectedCardId('');
      setSelectedAccountId('');
      setInstallments(1);
      setInstallmentMode('divide');
      setIsSplit(false);
      setIsPaid(false);
      setIsReserveWithdrawal(false);
      setPartnerPart('');
      setPartnerName(categories.payers?.[0] || 'Isa');
    }
  }, [editingTransaction, initialType, categories]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!description || !amount || !date || loading) return;
    setLoading(true);

    try {
      const inputValue = parseFloat(amount);
      const getSafeISO = (dateStr: string) => new Date(dateStr + 'T12:00:00').toISOString();

      const finalCardId = selectedCardId || null;
      const finalAccountId = selectedAccountId || null;

      if (editingTransaction && onUpdate) {
        const splitInfo: SplitDetails | undefined = isSplit ? {
          userPart: inputValue - (parseFloat(partnerPart) || 0),
          partnerPart: parseFloat(partnerPart) || 0,
          partnerName: partnerName
        } : undefined;

        const res = await onUpdate(editingTransaction.id, {
          description,
          amount: inputValue,
          type,
          category,
          date: getSafeISO(date),
          payment_date: isPaid ? getSafeISO(paymentDate) : null,
          card_id: finalCardId,
          account_id: finalAccountId,
          is_split: isSplit,
          split_details: splitInfo,
          is_paid: isPaid,
          is_reserve_withdrawal: isReserveWithdrawal
        });

        if (res) {
          setSuccess(true);
          setTimeout(() => { if (onCancel) onCancel(); }, 800);
        } else {
          setLoading(false);
        }
        return;
      }

      const numInstallments = Math.max(1, installments);
      const amountPerInstallment = installmentMode === 'divide' ? inputValue / numInstallments : inputValue;
      const pPartInput = parseFloat(partnerPart) || 0;
      const pPartPerMonth = installmentMode === 'divide' ? pPartInput / numInstallments : pPartInput;
      const uPartPerMonth = amountPerInstallment - pPartPerMonth;

      const [year, month, day] = date.split('-').map(Number);
      let allSuccess = true;

      for (let i = 0; i < numInstallments; i++) {
        const targetDate = new Date(year, month - 1 + i, day, 12, 0, 0);
        const installmentLabel = numInstallments > 1 ? ` (${i + 1}/${numInstallments})` : '';
        const splitInfo: SplitDetails | undefined = isSplit ? {
          userPart: uPartPerMonth,
          partnerPart: pPartPerMonth,
          partnerName: partnerName
        } : undefined;

        const res = await onAdd({
          description: description + installmentLabel,
          amount: amountPerInstallment,
          type,
          category: category || 'Outros',
          date: targetDate.toISOString(),
          payment_date: isPaid ? targetDate.toISOString() : null,
          card_id: finalCardId,
          account_id: finalAccountId,
          is_split: isSplit,
          split_details: splitInfo,
          is_paid: isPaid,
          is_reserve_withdrawal: isReserveWithdrawal
        });
        if (!res) allSuccess = false;
      }

      if (allSuccess) {
        setSuccess(true);
        setTimeout(() => { if (onCancel) onCancel(); }, 1000);
      } else {
        setLoading(false);
      }
    } catch (err) {
      setLoading(false);
    }
  };

  const formatCurrency = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const inputClasses = "w-full h-[38px] px-3 bg-slate-50 border border-transparent focus:border-indigo-100 focus:bg-white rounded-md outline-none text-xs font-bold text-slate-800 placeholder:text-slate-300 transition-all flex items-center";
  const labelClasses = "text-[9px] font-black text-slate-400 uppercase tracking-widest block mb-1 ml-0.5";

  return (
    <div className="bg-white p-4 md:p-7 rounded-xl shadow-2xl border border-slate-100 w-full animate-in fade-in zoom-in duration-300 relative pb-6 md:pb-7">
      <div className="flex justify-between items-center mb-4 md:mb-6">
        <h2 className="text-lg md:text-xl font-black text-slate-900 tracking-tight">
          {editingTransaction ? 'Editar Lançamento' : 'Novo Lançamento'}
        </h2>
        {onCancel && (
          <button onClick={onCancel} className="p-1.5 text-slate-300 hover:text-slate-500 transition-all">
            <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3"><path d="M18 6 6 18"/><path d="m6 6 12 12"/></svg>
          </button>
        )}
      </div>

      <form onSubmit={handleSubmit} className="space-y-3 md:space-y-4">
        {!editingTransaction && (
          <div className="flex p-1 bg-slate-100/50 rounded-lg max-w-xs">
            {(['expense', 'income'] as const).map((t) => (
              <button
                key={t}
                type="button"
                onClick={() => { setType(t); setCategory(categories[t][0] || 'Outros'); }}
                className={`flex-1 py-1 rounded text-[9px] font-black tracking-widest transition-all uppercase flex items-center justify-center gap-2 ${type === t ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}
              >
                {t === 'expense' ? 'DESPESA' : 'RECEITA'}
              </button>
            ))}
          </div>
        )}

        <div className="space-y-3 md:space-y-4">
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-3 md:gap-4">
            <div className="lg:col-span-6">
              <label className={labelClasses}>Descrição</label>
              <input type="text" value={description} onChange={e => setDescription(e.target.value)} className={inputClasses} placeholder="O que você comprou?" required />
            </div>
            <div className="lg:col-span-3">
              <label className={labelClasses}>Data de Vencimento</label>
              <input type="date" value={date} onChange={e => setDate(e.target.value)} className={inputClasses} required />
            </div>
            <div className="lg:col-span-3">
              <div className="flex items-center justify-between mb-1">
                <label className={labelClasses}>Pago?</label>
                <button type="button" onClick={() => setIsPaid(!isPaid)} className={`w-9 h-5 rounded-full transition-all relative ${isPaid ? 'bg-teal-500' : 'bg-slate-200'}`}>
                  <div className={`absolute top-0.5 w-4 h-4 bg-white rounded-full shadow-sm transition-all ${isPaid ? 'left-4.5' : 'left-0.5'}`}></div>
                </button>
              </div>
              {isPaid && (
                <input type="date" value={paymentDate} onChange={e => setPaymentDate(e.target.value)} className={`${inputClasses} bg-teal-50/20 border-teal-50`} required />
              )}
            </div>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-3 md:gap-4">
            <div>
              <label className={labelClasses}>Valor Total</label>
              <input type="number" step="0.01" value={amount} onChange={e => setAmount(e.target.value)} className={`${inputClasses} font-black text-sm`} placeholder="0,00" required />
            </div>
            <div>
              <label className={labelClasses}>Categoria</label>
              <select value={category} onChange={e => setCategory(e.target.value)} className={`${inputClasses} appearance-none pr-8 bg-[url('data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%2212%22%20height%3D%2212%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%23cbd5e1%22%20stroke-width%3D%223%22%3E%3Cpath%20d%3D%22m6%209%206%206%206-6%22%2F%3E%3C%2Fsvg%3E')] bg-[length:12px_12px] bg-[right_0.6rem_center] bg-no-repeat`}>
                {categories[type].map(cat => <option key={cat} value={cat}>{cat}</option>)}
              </select>
            </div>

            <div className="md:col-span-2 grid grid-cols-2 gap-3">
               <div>
                  <label className={labelClasses}>Cartão de Crédito</label>
                  <select 
                    value={selectedCardId} 
                    onChange={e => { 
                      const newCardId = e.target.value;
                      setSelectedCardId(newCardId);
                      if (newCardId) {
                        const card = cards.find(c => c.id === newCardId);
                        if (card?.account_id) setSelectedAccountId(card.account_id);
                        else setSelectedAccountId('');
                      } else {
                        setSelectedAccountId(''); 
                      }
                    }} 
                    className={`${inputClasses} appearance-none pr-8 bg-[url('data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%2212%22%20height%3D%2212%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%23cbd5e1%22%20stroke-width%3D%223%22%3E%3Cpath%20d%3D%22m6%209%206%206%206-6%22%2F%3E%3C%2Fsvg%3E')] bg-[length:12px_12px] bg-[right_0.6rem_center] bg-no-repeat`}
                  >
                    <option value="">Não usar cartão</option>
                    {cards.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                  </select>
               </div>
               <div>
                  <label className={labelClasses}>Conta / Carteira</label>
                  <select 
                    value={selectedAccountId} 
                    onChange={e => setSelectedAccountId(e.target.value)} 
                    disabled={!!selectedCardId}
                    className={`${inputClasses} ${!!selectedCardId ? 'opacity-70 bg-slate-100' : ''} appearance-none pr-8 bg-[url('data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%2212%22%20height%3D%2212%22%20viewBox%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%23cbd5e1%22%20stroke-width%3D%223%22%3E%3Cpath%20d%3D%22m6%209%206%206%206-6%22%2F%3E%3C%2Fsvg%3E')] bg-[length:12px_12px] bg-[right_0.6rem_center] bg-no-repeat`}
                  >
                    <option value="">Sem conta vinculada</option>
                    {availableAccounts.map(a => <option key={a.id} value={a.id}>{a.name}</option>)}
                  </select>
               </div>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
             {type === 'expense' && (
                <div className="md:col-span-2">
                  <div className="flex items-center justify-between h-full bg-amber-50/50 border border-amber-100/50 rounded-lg px-4 py-2">
                    <div className="flex items-center gap-2">
                      <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#f59e0b" strokeWidth="2.5"><path d="M12 2v20"/><path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"/></svg>
                      <span className="text-[10px] font-black text-amber-700 uppercase tracking-widest">Usar Reserva?</span>
                    </div>
                    <button type="button" onClick={() => setIsReserveWithdrawal(!isReserveWithdrawal)} className={`w-9 h-5 rounded-full transition-all relative ${isReserveWithdrawal ? 'bg-amber-500' : 'bg-slate-200'}`}>
                      <div className={`absolute top-0.5 w-4 h-4 bg-white rounded-full shadow-sm transition-all ${isReserveWithdrawal ? 'left-4.5' : 'left-0.5'}`}></div>
                    </button>
                  </div>
                </div>
             )}
             <div className="md:col-start-4">
               <label className={`${labelClasses} text-indigo-500`}>Nº Meses</label>
               <input type="number" min="1" max="99" value={installments} disabled={!!editingTransaction} onChange={e => setInstallments(parseInt(e.target.value) || 1)} className={`${inputClasses} border-indigo-50 bg-indigo-50/20 disabled:opacity-40`} />
             </div>
          </div>

          {!editingTransaction && installments > 1 && (
            <div className="flex flex-col sm:flex-row items-center gap-3 bg-slate-50/50 p-3 rounded-lg border border-slate-100">
              <div className="flex p-0.5 bg-white rounded-md border border-slate-100">
                <button type="button" onClick={() => setInstallmentMode('divide')} className={`px-3 py-1 rounded-sm text-[8px] font-black uppercase tracking-widest ${installmentMode === 'divide' ? 'bg-indigo-600 text-white' : 'text-slate-400'}`}>Ratear</button>
                <button type="button" onClick={() => setInstallmentMode('repeat')} className={`px-3 py-1 rounded-sm text-[8px] font-black uppercase tracking-widest ${installmentMode === 'repeat' ? 'bg-indigo-600 text-white' : 'text-slate-400'}`}>Repetir</button>
              </div>
              {amount && (
                <p className="text-[9px] font-black text-slate-500 uppercase tracking-widest">
                  Plano: <span className="text-indigo-600">{installments}x</span> de <span className="text-indigo-600">{formatCurrency(installmentMode === 'divide' ? parseFloat(amount) / installments : parseFloat(amount))}</span>
                </p>
              )}
            </div>
          )}

          {type === 'expense' && (
            <div className={`p-3 md:p-4 rounded-lg border transition-all ${isSplit ? 'bg-indigo-50/10 border-indigo-100' : 'bg-slate-50/30 border-slate-50'}`}>
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-3">
                   <div className={`w-8 h-8 rounded flex items-center justify-center transition-all ${isSplit ? 'bg-indigo-600 text-white' : 'bg-slate-100 text-slate-300'}`}>
                     <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3"><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/></svg>
                   </div>
                   <div className="leading-none">
                     <span className="text-[10px] font-black text-slate-800 uppercase tracking-widest block mb-0.5">Dividir com Pagante</span>
                     <span className="text-[8px] font-bold text-slate-400 uppercase tracking-tight">Rateio de despesa comum</span>
                   </div>
                </div>
                <button type="button" onClick={() => setIsSplit(!isSplit)} className={`w-9 h-5 rounded-full transition-all relative ${isSplit ? 'bg-indigo-600' : 'bg-slate-200'}`}>
                  <div className={`absolute top-0.5 w-4 h-4 bg-white rounded-full shadow-sm transition-all ${isSplit ? 'left-4.5' : 'left-0.5'}`}></div>
                </button>
              </div>
              {isSplit && (
                <div className="mt-3 pt-3 border-t border-indigo-100/30 grid grid-cols-1 sm:grid-cols-2 gap-3 animate-in fade-in slide-in-from-top-2">
                  <div>
                    <label className="text-[8px] font-black text-indigo-400 uppercase mb-1 block">Quem é o pagante?</label>
                    <select value={partnerName} onChange={e => setPartnerName(e.target.value)} className="w-full h-9 px-3 bg-white rounded-md border border-indigo-50 text-[11px] font-black text-slate-800 outline-none">
                      {categories.payers?.map(p => <option key={p} value={p}>{p}</option>)}
                    </select>
                  </div>
                  <div>
                    <label className="text-[8px] font-black text-indigo-400 uppercase mb-1 block">Parte dele(a)</label>
                    <input type="number" step="0.01" value={partnerPart} onChange={e => setPartnerPart(e.target.value)} placeholder="0,00" className="w-full h-9 px-3 bg-white rounded-md border border-indigo-50 text-[11px] font-black text-indigo-600 outline-none" />
                  </div>
                </div>
              )}
            </div>
          )}
        </div>

        <div className="pt-3 md:pt-4 pb-2 md:pb-0">
          <button type="submit" disabled={success || loading} className={`w-full py-3.5 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all text-white shadow-lg active:scale-[0.98] ${success ? 'bg-teal-500' : 'bg-indigo-600 hover:bg-indigo-700 disabled:opacity-50'}`}>
            {loading ? 'Processando...' : (success ? '✓ Atualizado' : (editingTransaction ? 'Salvar Alterações' : 'Confirmar Lançamento'))}
          </button>
        </div>
      </form>
    </div>
  );
};

export default TransactionForm;

import React, { useState, useMemo } from 'react';
import { Account, Transaction, UserCategories, CreditCard } from '../types';
import { getCategoryIcon, getCategoryStyles } from '../utils/icons';

interface AccountManagerProps {
  accounts: Account[];
  transactions: Transaction[];
  categories: UserCategories;
  cards: CreditCard[];
  onAdd: (account: Omit<Account, 'id'>) => Promise<boolean>;
  onDelete: (id: string) => void;
  onTogglePaid: (id: string, currentStatus: boolean, paymentDate?: string | null) => void;
  onDeleteTransaction: (id: string) => void;
}

const AccountManager: React.FC<AccountManagerProps> = ({ accounts, transactions, categories, cards, onAdd, onDelete, onTogglePaid, onDeleteTransaction }) => {
  const [showAdd, setShowAdd] = useState(false);
  const [selectedAccount, setSelectedAccount] = useState<Account | null>(null);

  const getInitialDates = () => {
    const now = new Date();
    const firstDay = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().split('T')[0];
    const lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0).toISOString().split('T')[0];
    return { firstDay, lastDay };
  };

  const { firstDay: initStart, lastDay: initEnd } = getInitialDates();
  const [startDate, setStartDate] = useState(initStart);
  const [endDate, setEndDate] = useState(initEnd);
  const [selectedCategory, setSelectedCategory] = useState('all');
  const [statusFilter, setStatusFilter] = useState<'all' | 'paid' | 'pending'>('all');

  const [name, setName] = useState('');
  const [initialBalance, setInitialBalance] = useState('');
  const [initialInvested, setInitialInvested] = useState('');
  const [type, setType] = useState<Account['type']>('checking');
  const [color, setColor] = useState('#4f46e5');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    const success = await onAdd({ 
      name, 
      initial_balance: parseFloat(initialBalance) || 0, 
      initial_invested_balance: parseFloat(initialInvested) || 0,
      type, 
      color 
    });

    setIsSubmitting(false);
    if (success) {
      setName(''); setInitialBalance(''); setInitialInvested(''); setShowAdd(false);
    }
  };

  const formatCurrency = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const calculatedAccounts = useMemo(() => {
    return accounts.map(acc => {
      const accountTransactions = transactions.filter(t => t.account_id === acc.id && t.is_paid);

      let balanceChange = 0;
      let investmentMovements = 0;

      accountTransactions.forEach(t => {
        const val = Number(t.amount);
        const isInvestmentCategory = t.category.toLowerCase().includes('invest');
        const isReserveWithdrawal = !!t.is_reserve_withdrawal;

        if (t.type === 'income') {
          if (isInvestmentCategory) {
            investmentMovements -= val; 
            balanceChange += val; 
          } else {
            balanceChange += val;
          }
        } else {
          // Despesa
          if (isReserveWithdrawal) {
            // Se for resgate da reserva, abate do investido
            investmentMovements -= val;
          } else if (isInvestmentCategory) {
            // Se for aporte em investimento, tira do líquido e põe no investido
            investmentMovements += val;
            balanceChange -= val;
          } else {
            // Gasto comum tira do líquido
            balanceChange -= val;
          }
        }
      });

      const currentLiquid = Number(acc.initial_balance) + balanceChange;
      const currentInvested = Number(acc.initial_invested_balance || 0) + investmentMovements;
      const totalPatrimony = currentLiquid + currentInvested;

      const linkedCardIds = cards.filter(c => c.account_id === acc.id).map(c => c.id);
      const creditCardDebt = transactions
        .filter(t => t.card_id && linkedCardIds.includes(t.card_id) && !t.is_paid && t.type === 'expense')
        .reduce((sum, t) => sum + Number(t.amount), 0);

      return { ...acc, currentLiquid, currentInvested, totalPatrimony, creditCardDebt, linkedCardsCount: linkedCardIds.length };
    });
  }, [accounts, transactions, cards]);

  const filteredTransactions = useMemo(() => {
    if (!selectedAccount) return [];
    const linkedCardIds = cards.filter(c => c.account_id === selectedAccount.id).map(c => c.id);

    return transactions.filter(t => {
      const isDirect = t.account_id === selectedAccount.id;
      const isLinkedCard = t.card_id && linkedCardIds.includes(t.card_id);
      if (!isDirect && !isLinkedCard) return false;

      const tDate = t.date.split('T')[0];
      return tDate >= startDate && tDate <= endDate && (selectedCategory === 'all' || t.category === selectedCategory) && (statusFilter === 'all' || (statusFilter === 'paid' ? t.is_paid : !t.is_paid));
    }).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [transactions, selectedAccount, startDate, endDate, selectedCategory, statusFilter, cards]);

  return (
    <div className="max-w-5xl space-y-6 pb-12">
      {selectedAccount ? (
        <div className="space-y-6 animate-in slide-in-from-right-4 duration-300">
          <div className="flex items-center gap-4 bg-white p-6 rounded-xl border border-slate-100 shadow-sm">
            <button onClick={() => setSelectedAccount(null)} className="p-2 hover:bg-slate-50 rounded-lg text-slate-400 hover:text-indigo-600 transition-colors">
              <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="m15 18-6-6 6-6"/></svg>
            </button>
            <div className="w-12 h-12 rounded-lg flex items-center justify-center text-white" style={{ backgroundColor: selectedAccount.color }}>
              <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M3 21h18"/><path d="M5 21V7l8-4 8 4v14"/><path d="M17 21v-8H7v8"/></svg>
            </div>
            <div className="flex-1">
              <h2 className="text-xl font-bold text-slate-900 tracking-tight">{selectedAccount.name}</h2>
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Extrato da Conta</p>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
             {(() => {
               const acc = calculatedAccounts.find(a => a.id === selectedAccount.id);
               if (!acc) return null;
               return (
                 <>
                   <div className="bg-white p-5 rounded-xl border border-slate-100 shadow-sm">
                     <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Saldo Disponível (Líquido)</p>
                     <h3 className={`text-xl font-black ${acc.currentLiquid >= 0 ? 'text-slate-900' : 'text-rose-500'}`}>{formatCurrency(acc.currentLiquid)}</h3>
                   </div>
                   <div className="bg-indigo-50/50 p-5 rounded-xl border border-indigo-100">
                     <p className="text-[9px] font-black text-indigo-500 uppercase tracking-widest mb-1">Reserva / Investido</p>
                     <h3 className="text-xl font-black text-indigo-700">{formatCurrency(acc.currentInvested)}</h3>
                   </div>
                   <div className="bg-slate-900 p-5 rounded-xl border border-slate-800 shadow-xl">
                     <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Patrimônio Total</p>
                     <h3 className="text-xl font-black text-white">{formatCurrency(acc.totalPatrimony)}</h3>
                   </div>
                 </>
               )
             })()}
          </div>

          <div className="bg-white rounded-xl border border-slate-100 shadow-sm overflow-hidden p-6">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6">Lançamentos Vinculados</h3>
            <div className="space-y-3">
              {filteredTransactions.map(t => (
                <div key={t.id} className="flex items-center justify-between p-4 bg-slate-50/50 rounded-lg hover:bg-slate-50 transition-all group">
                   <div className="flex items-center gap-3">
                      <div className="w-8 h-8 rounded bg-white border border-slate-100 flex items-center justify-center text-slate-400">
                        {getCategoryIcon(t.category, 16)}
                      </div>
                      <div>
                        <div className="flex items-center gap-2">
                           <p className="text-xs font-bold text-slate-900">{t.description}</p>
                           {t.is_reserve_withdrawal && (
                             <span className="px-1.5 py-0.5 rounded-sm bg-amber-50 text-amber-600 text-[8px] font-black uppercase tracking-tighter border border-amber-100">Via Reserva</span>
                           )}
                        </div>
                        <p className="text-[8px] font-black text-slate-400 uppercase tracking-tighter">{t.category}</p>
                      </div>
                   </div>
                   <div className="text-right">
                      <p className={`text-sm font-black ${t.type === 'income' ? 'text-teal-600' : 'text-rose-500'}`}>{formatCurrency(t.amount)}</p>
                      <p className="text-[9px] font-bold text-slate-300">{new Date(t.date).toLocaleDateString('pt-BR')}</p>
                   </div>
                </div>
              ))}
              {filteredTransactions.length === 0 && <p className="text-center py-10 text-[10px] font-black text-slate-300 uppercase italic">Nenhuma transação encontrada</p>}
            </div>
          </div>
        </div>
      ) : (
        <div className="space-y-6">
          <div className="flex justify-between items-center bg-white p-6 rounded-xl border border-slate-100 shadow-sm">
            <div>
              <h2 className="text-xl font-bold text-slate-900 tracking-tight">Suas Contas</h2>
              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Gestão de Patrimônio Líquido e Reservas</p>
            </div>
            <button onClick={() => setShowAdd(true)} className="bg-indigo-600 text-white px-6 py-3 rounded-lg text-[10px] font-black uppercase tracking-widest shadow-lg shadow-indigo-100 active:scale-95">Nova Conta</button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
            {calculatedAccounts.map(acc => (
              <div key={acc.id} onClick={() => setSelectedAccount(acc)} className="bg-white p-6 rounded-xl border border-slate-100 shadow-sm hover:border-indigo-200 transition-all group cursor-pointer active:scale-[0.98]">
                <div className="flex justify-between items-start mb-6">
                  <div className="w-10 h-10 rounded-lg flex items-center justify-center text-white shadow-md" style={{ backgroundColor: acc.color }}>
                    <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M3 21h18"/><path d="M5 21V7l8-4 8 4v14"/><path d="M17 21v-8H7v8"/></svg>
                  </div>
                  <button onClick={(e) => { e.stopPropagation(); onDelete(acc.id); }} className="text-slate-300 hover:text-rose-500 transition-colors p-1">
                    <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M3 6h18"/><path d="M19 6v14c0 1-1 2-2 2H7c-1 0-2-1-2-2V6"/></svg>
                  </button>
                </div>
                <h3 className="font-black text-slate-900 text-sm mb-4 truncate">{acc.name}</h3>

                <div className="space-y-3">
                   <div className="flex justify-between items-end">
                      <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest">Saldo Disponível</p>
                      <p className={`text-base font-black ${acc.currentLiquid >= 0 ? 'text-slate-900' : 'text-rose-500'}`}>{formatCurrency(acc.currentLiquid)}</p>
                   </div>
                   <div className="flex justify-between items-end">
                      <p className="text-[8px] font-black text-indigo-400 uppercase tracking-widest">Investido / Reserva</p>
                      <p className="text-sm font-black text-indigo-600">{formatCurrency(acc.currentInvested)}</p>
                   </div>
                </div>

                <div className="mt-5 pt-4 border-t border-slate-50 flex justify-between items-center">
                   <p className="text-[9px] font-black text-slate-300 uppercase">Patrimônio Total</p>
                   <p className="text-sm font-black text-slate-900">{formatCurrency(acc.totalPatrimony)}</p>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {showAdd && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[70] flex items-center justify-center p-4">
          <div className="bg-white p-8 rounded-xl shadow-2xl w-full max-w-md animate-in zoom-in-95">
            <h3 className="text-xl font-black text-slate-900 mb-6 uppercase tracking-tight">Criar Nova Conta</h3>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="text-[10px] font-bold text-slate-400 uppercase block mb-1.5 ml-1">Nome</label>
                <input type="text" value={name} onChange={e => setName(e.target.value)} className="w-full px-4 py-3 bg-slate-50 rounded-lg outline-none border-2 border-transparent focus:border-indigo-100 font-medium text-slate-900 text-sm" placeholder="Ex: Nubank" required />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-[10px] font-bold text-slate-400 uppercase block mb-1.5 ml-1">Saldo Líquido Inicial</label>
                  <input type="number" step="0.01" value={initialBalance} onChange={e => setInitialBalance(e.target.value)} className="w-full px-4 py-3 bg-slate-50 rounded-lg outline-none border-2 border-transparent focus:border-indigo-100 font-bold text-slate-900 text-sm" placeholder="0,00" required />
                </div>
                <div>
                  <label className="text-[10px] font-bold text-indigo-400 uppercase block mb-1.5 ml-1">Reserva / Investido</label>
                  <input type="number" step="0.01" value={initialInvested} onChange={e => setInitialInvested(e.target.value)} className="w-full px-4 py-3 bg-indigo-50/30 rounded-lg outline-none border-2 border-transparent focus:border-indigo-100 font-bold text-indigo-700 text-sm" placeholder="0,00" />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-[10px] font-bold text-slate-400 uppercase block mb-1.5 ml-1">Tipo</label>
                  <select value={type} onChange={e => setType(e.target.value as any)} className="w-full px-4 py-3 bg-slate-50 rounded-lg outline-none border-2 border-transparent focus:border-indigo-100 font-bold text-slate-900 text-xs">
                    <option value="checking">Conta Corrente</option>
                    <option value="investment">Investimento</option>
                    <option value="cash">Dinheiro</option>
                  </select>
                </div>
                <div>
                  <label className="text-[10px] font-bold text-slate-400 uppercase block mb-1.5 ml-1">Cor</label>
                  <input type="color" value={color} onChange={e => setColor(e.target.value)} className="w-full h-[48px] p-1 bg-slate-50 rounded-lg cursor-pointer" />
                </div>
              </div>
              <div className="flex gap-3 pt-6">
                <button type="button" onClick={() => setShowAdd(false)} className="flex-1 py-4 text-slate-400 font-bold text-[10px] uppercase tracking-widest hover:text-slate-600 transition-colors">Cancelar</button>
                <button type="submit" disabled={isSubmitting} className="flex-1 bg-indigo-600 text-white rounded-lg font-bold text-[10px] uppercase tracking-widest shadow-lg shadow-indigo-100 hover:bg-indigo-700 transition-all">
                  {isSubmitting ? 'Salvando...' : 'Criar Conta'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default AccountManager;

import React, { useState, useEffect } from 'react';
import { supabase } from '../services/supabaseClient';
import { Transaction, CreditCard, UserCategories, Account } from '../types';

interface DataManagementProps {
  userId: string;
  transactions: Transaction[];
  cards: CreditCard[];
  categories: UserCategories;
  onRefresh: () => void;
}

const DataManagement: React.FC<DataManagementProps> = ({ userId, transactions, cards, categories, onRefresh }) => {
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState<{ text: string, type: 'success' | 'error' } | null>(null);

  const [sbUrl, setSbUrl] = useState('');
  const [sbKey, setSbKey] = useState('');

  useEffect(() => {
    const storedUrl = localStorage.getItem('financepro_sb_url');
    const storedKey = localStorage.getItem('financepro_sb_key');
    if (storedUrl) setSbUrl(storedUrl);
    if (storedKey) setSbKey(storedKey);
  }, []);

  const handleSaveConnection = () => {
    if (!sbUrl || !sbKey) {
      if (confirm('Deseja limpar as configurações e usar o banco de dados de demonstração?')) {
        localStorage.removeItem('financepro_sb_url');
        localStorage.removeItem('financepro_sb_key');
        window.location.reload();
      }
      return;
    }
    localStorage.setItem('financepro_sb_url', sbUrl);
    localStorage.setItem('financepro_sb_key', sbKey);
    alert('Conexão salva! A página será recarregada para aplicar as mudanças.');
    window.location.reload();
  };

  const sqlFixCode = `-- SCRIPT CORRIGIDO E SEGURO (IDEMPOTENTE) v1.2
-- 1. Cria tabelas se não existirem
CREATE TABLE IF NOT EXISTS public.profiles (
  id UUID REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL PRIMARY KEY,
  name TEXT,
  avatar_color TEXT,
  categories JSONB,
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now())
);

CREATE TABLE IF NOT EXISTS public.accounts (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL,
  name TEXT NOT NULL,
  type TEXT NOT NULL,
  initial_balance DECIMAL DEFAULT 0,
  initial_invested_balance DECIMAL DEFAULT 0,
  color TEXT,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now())
);

CREATE TABLE IF NOT EXISTS public.credit_cards (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL,
